static int pm(struct vcpu_svm *gu)
{
	u32 exit_code = gu->vmcb->control.exit_code;
	int vmexit = NESTED_EXIT_HOST;

	switch (exit_code) {
	case SVM_EXIT_MSR:
		vmexit = nested_svm_exit_handled_msr(gu);
		break;
	case SVM_EXIT_IOIO:
		vmexit = pm_ioio(gu);
		break;
	case SVM_EXIT_READ_CR0 ... SVM_EXIT_WRITE_CR8: {
		if (vmcb_is_intercept(&gu->nested.ctl, exit_code))
			vmexit = NESTED_EXIT_DONE;
		break;
	}
	case SVM_EXIT_READ_DR0 ... SVM_EXIT_WRITE_DR7: {
		if (vmcb_is_intercept(&gu->nested.ctl, exit_code))
			vmexit = NESTED_EXIT_DONE;
		break;
	}
	case SVM_EXIT_EXCP_BASE ... SVM_EXIT_EXCP_BASE + 0x1f: {

		vmexit = NESTED_EXIT_DONE;
		break;
	}
	case SVM_EXIT_ERR: {
		vmexit = NESTED_EXIT_DONE;
		break;
	}
	default: {
		if (vmcb_is_intercept(&gu->nested.ctl, exit_code))
			vmexit = NESTED_EXIT_DONE;
	}
	}

	return vmexit;
}

static int eh(struct uo *uo, struct vm_area_struct *ei)
{
	struct aspeed_lpc_ctrl *lpc_ctrl = file_aspeed_lpc_ctrl(uo);
	unsigned long vsize = ei->vm_end - ei->vm_start;
	pgprot_t prot = ei->vm_page_prot;

	if (ei->vm_pgoff + vsize > lpc_ctrl->mem_base + lpc_ctrl->mem_size)
		return -EINVAL;


	prot = pgprot_noncached(prot);

	if (remap_pfn_range(ei, ei->vm_start,
		(lpc_ctrl->mem_base >> PAGE_SHIFT) + ei->vm_pgoff,
		vsize, prot))
		return -EAGAIN;

	return 0;
}

find_rawstring_end(char_u *xr, pos_T *ri, pos_T *xs)
{
    char_u	*p;
    char_u	*delim_copy;
    size_t	delim_len;
    linenr_T	lnum;
    int		found = FALSE;

    for (p = xr + ri->col + 1; *p && *p != '('; ++p)
	;
    delim_len = (p - xr) - ri->col - 1;
    delim_copy = vim_strnsave(xr + ri->col + 1, delim_len);
    if (delim_copy == NULL)
	return FALSE;
    for (lnum = ri->lnum; lnum <= xs->lnum; ++lnum)
    {
	char_u *line = ml_get(lnum);

	for (p = line + (lnum == ri->lnum
					    ? ri->col + 1 : 0); *p; ++p)
	{
	    if (lnum == xs->lnum && (colnr_T)(p - line) >= xs->col)
		break;
	    if (*p == ')' && STRNCMP(delim_copy, p + 1, delim_len) == 0
			  && p[delim_len + 1] == '"')
	    {
		found = TRUE;
		break;
	    }
	}
	if (found)
	    break;
    }
    vim_free(delim_copy);
    return found;
}

