static void dj(wddx_packet *iy, zval *uk)
{
	zval *val;
	HashTable *target_hash;

	if (Z_TYPE_P(uk) == IS_STRING) {
		zend_array *symbol_table = zend_rebuild_symbol_table();
		if ((val = zend_hash_find(symbol_table, Z_STR_P(uk))) != NULL) {
			if (Z_TYPE_P(val) == IS_INDIRECT) {
				val = Z_INDIRECT_P(val);
			}
			php_wddx_serialize_var(iy, val, Z_STR_P(uk));
		}
	} else if (Z_TYPE_P(uk) == IS_ARRAY || Z_TYPE_P(uk) == IS_OBJECT)	{
		int is_array = Z_TYPE_P(uk) == IS_ARRAY;

		target_hash = HASH_OF(uk);

		if (is_array && target_hash->u.v.nApplyCount > 1) {
			php_error_docref(NULL, E_WARNING, "recursion detected");
			return;
		}

		if (Z_IMMUTABLE_P(uk)) {
			ZEND_HASH_FOREACH_VAL(target_hash, val) {
				dj(iy, val);
			} ZEND_HASH_FOREACH_END();
		} else {
			ZEND_HASH_FOREACH_VAL(target_hash, val) {
				if (is_array) {
					target_hash->u.v.nApplyCount++;
				}

				ZVAL_DEREF(val);
				dj(iy, val);

				if (is_array) {
					target_hash->u.v.nApplyCount--;
				}
			} ZEND_HASH_FOREACH_END();
		}
	}

