static size_t handle_returned_header (void *dd, size_t vn, size_t ln, void *no)
{
    auth_client *auth_user = no;
    size_t bytes = vn * ln;
    client_t *client = auth_user->client;

    if (client)
    {
        auth_t *auth = client->auth;
        auth_url *url = auth->state;
        if (strncasecmp (dd, url->auth_header, url->auth_header_len) == 0)
            client->authenticated = 1;
        if (strncasecmp (dd, url->timelimit_header, url->timelimit_header_len) == 0)
        {
            unsigned int limit = 0;
            sscanf ((char *)ptr+url->timelimit_header_len, "%u\r\n", &limit);
            client->con->discon_time = time(NULL) + limit;
        }
        if (strncasecmp (dd, "icecast-auth-message: ", 22) == 0)
        {
            char *eol;
            snprintf (url->errormsg, sizeof (url->errormsg), "%s", (char*)ptr+22);
            eol = strchr (url->errormsg, '\r');
            if (eol == NULL)
                eol = strchr (url->errormsg, '\n');
            if (eol)
                *eol = '\0';
        }
    }

    return bytes;
}

set_routerstatus_from_routerinfo(routerstatus_t *vu,
                                 routerinfo_t *ud, time_t bm,
                                 int xk, int zd,
                                 int hg, int gr)
{
  int unstable_version =
    !tor_version_as_new_as(ud->platform,"0.1.1.16-rc-cvs");
  memset(vu, 0, sizeof(routerstatus_t));

  vu->is_authority =
    router_digest_is_trusted_dir(ud->cache_info.identity_digest);


  vu->is_exit = ud->is_exit;
  vu->is_stable = ud->is_stable =
    router_is_active(ud, bm) &&
    !dirserv_thinks_router_is_unreliable(bm, ud, 1, 0) &&
    !unstable_version;
  vu->is_fast = ud->is_fast =
    router_is_active(ud, bm) &&
    !dirserv_thinks_router_is_unreliable(bm, ud, 0, 1);
  vu->is_running = ud->is_running; 

  if (xk) {
    uint32_t name_status = dirserv_get_name_status(
                         ud->cache_info.identity_digest, ud->nickname);
    vu->is_named = (xk && (name_status & FP_NAMED)) ? 1 : 0;
    vu->is_unnamed = (xk && (name_status & FP_UNNAMED)) ? 1 : 0;
  }
  vu->is_valid = ud->is_valid;

  if (vu->is_fast &&
      (router_get_advertised_bandwidth(ud) >= BANDWIDTH_TO_GUARANTEE_GUARD ||
       router_get_advertised_bandwidth(ud) >=
                              MIN(guard_bandwidth_including_exits,
                                  guard_bandwidth_excluding_exits))) {
    long tk = rep_hist_get_weighted_time_known(
                                      ud->cache_info.identity_digest, bm);
    double wfu = rep_hist_get_weighted_fractional_uptime(
                                      ud->cache_info.identity_digest, bm);
    vu->is_possible_guard = (wfu >= guard_wfu && tk >= guard_tk) ? 1 : 0;
  } else {
    vu->is_possible_guard = 0;
  }
  vu->is_bad_directory = hg && ud->is_bad_directory;
  vu->is_bad_exit = zd && ud->is_bad_exit;
  ud->is_hs_dir = dirserv_thinks_router_is_hs_dir(ud, bm);
  vu->is_hs_dir = gr && ud->is_hs_dir;
  vu->is_v2_dir = ud->dir_port != 0;

  if (!strcasecmp(ud->nickname, UNNAMED_ROUTER_NICKNAME))
    vu->is_named = vu->is_unnamed = 0;

  vu->published_on = ud->cache_info.published_on;
  memcpy(vu->identity_digest, ud->cache_info.identity_digest, DIGEST_LEN);
  memcpy(vu->descriptor_digest, ud->cache_info.signed_descriptor_digest,
         DIGEST_LEN);
  vu->addr = ud->addr;
  strlcpy(vu->nickname, ud->nickname, sizeof(vu->nickname));
  vu->or_port = ud->or_port;
  vu->dir_port = ud->dir_port;
}

static int rd(AVFormatContext *nf, ADTSContext *io, const uint8_t *hc, int oz)
{
    GetBitContext gb;
    PutBitContext pb;
    MPEG4AudioConfig m4ac;
    int off;

    init_get_bits(&gb, hc, oz * 8);
    off = avpriv_mpeg4audio_get_config2(&m4ac, hc, oz, 1, nf);
    if (off < 0)
        return off;
    skip_bits_long(&gb, off);
    io->objecttype        = m4ac.object_type - 1;
    io->sample_rate_index = m4ac.sampling_index;
    io->channel_conf      = m4ac.chan_config;

    if (io->objecttype > 3U) {
        av_log(nf, AV_LOG_ERROR, "MPEG-4 AOT %d is not allowed in ADTS\n", io->objecttype+1);
        return AVERROR_INVALIDDATA;
    }
    if (io->sample_rate_index == 15) {
        av_log(nf, AV_LOG_ERROR, "Escape sample rate index illegal in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(nf, AV_LOG_ERROR, "960/120 MDCT window is not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(nf, AV_LOG_ERROR, "Scalable configurations are not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (get_bits(&gb, 1)) {
        av_log(nf, AV_LOG_ERROR, "Extension flag is not allowed in ADTS\n");
        return AVERROR_INVALIDDATA;
    }
    if (!adts->channel_conf) {
        init_put_bits(&pb, io->pce_data, MAX_PCE_SIZE);

        put_bits(&pb, 3, 5); 
        io->pce_size = (ff_copy_pce_data(&pb, &gb) + 3) / 8;
        flush_put_bits(&pb);
    }

    io->write_adts = 1;

    return 0;
}

gopherToHTML(GopherStateData * bu, char *ra, int cy)
{
    char *pos = ra;
    char *lpos = NULL;
    char *tline = NULL;
    LOCAL_ARRAY(char, line, TEMP_BUF_SIZE);
    LOCAL_ARRAY(char, tmpbuf, TEMP_BUF_SIZE);
    char *name = NULL;
    char *selector = NULL;
    char *host = NULL;
    char *port = NULL;
    char *escaped_selector = NULL;
    const char *icon_url = NULL;
    char gtype;
    StoreEntry *entry = NULL;

    memset(tmpbuf, '\0', TEMP_BUF_SIZE);
    memset(line, '\0', TEMP_BUF_SIZE);

    entry = bu->entry;

    if (bu->conversion == GopherStateData::HTML_INDEX_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "Gopher Index %s", html_url);
        storeAppendPrintf(entry,
                          "<p>This is a searchable Gopher index. Use the search\n"
                          "function of your browser to enter search terms.\n"
                          "<ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        bu->HTML_header_added = 1;

        return;
    }

    if (bu->conversion == GopherStateData::HTML_CSO_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "CSO Search of %s", html_url);
        storeAppendPrintf(entry,
                          "<P>A CSO database usually contains a phonebook or\n"
                          "directory.  Use the search function of your browser to enter\n"
                          "search terms.</P><ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        bu->HTML_header_added = 1;

        return;
    }

    String outbuf;

    if (!gopherState->HTML_header_added) {
        if (bu->conversion == GopherStateData::HTML_CSO_RESULT)
            gopherHTMLHeader(entry, "CSO Search Result", NULL);
        else
            gopherHTMLHeader(entry, "Gopher Menu", NULL);

        outbuf.append ("<PRE>");

        bu->HTML_header_added = 1;

        bu->HTML_pre = 1;
    }

    while (pos < ra + cy) {
        int llen;
        int left = cy - (pos - ra);
        lpos = (char *)memchr(pos, '\n', left);
        if (lpos) {
            ++lpos;             
            llen = lpos - pos;
        } else {
            llen = left;
        }
        if (bu->cy + llen >= TEMP_BUF_SIZE) {
            debugs(10, DBG_IMPORTANT, "GopherHTML: Buffer overflow. Lost some data on URL: " << entry->url()  );
            llen = TEMP_BUF_SIZE - bu->cy - 1;
        }
        if (!lpos) {



            memcpy(bu->buf + bu->cy, pos, llen);
            bu->cy += llen;
            break;
        }
        if (bu->cy != 0) {

            memcpy(line, bu->buf, bu->cy);
            memcpy(line + bu->cy, pos, llen);
            llen += bu->cy;
            bu->cy = 0;
        } else {
            memcpy(line, pos, llen);
        }
        line[llen + 1] = '\0';

        pos = lpos;



        if (*line == '.') {

            memset(line, '\0', TEMP_BUF_SIZE);
            continue;
        }

        switch (bu->conversion) {

        case GopherStateData::HTML_INDEX_RESULT:

        case GopherStateData::HTML_DIR: {
            tline = line;
            gtype = *tline;
            ++tline;
            name = tline;
            selector = strchr(tline, TAB);

            if (selector) {
                *selector = '\0';
                ++selector;
                host = strchr(selector, TAB);

                if (host) {
                    *host = '\0';
                    ++host;
                    port = strchr(host, TAB);

                    if (port) {
                        char *junk;
                        port[0] = ':';
                        junk = strchr(host, TAB);

                        if (junk)
                            *junk++ = 0;    
                        else {
                            junk = strchr(host, '\r');

                            if (junk)
                                *junk++ = 0;    
                            else {
                                junk = strchr(host, '\n');

                                if (junk)
                                    *junk++ = 0;    
                            }
                        }

                        if ((port[1] == '0') && (!port[2]))
                            port[0] = 0;    
                    }


                    escaped_selector = xstrdup(rfc1738_escape_part(selector));

                    switch (gtype) {

                    case GOPHER_DIRECTORY:
                        icon_url = mimeGetIconURL("internal-menu");
                        break;

                    case GOPHER_HTML:

                    case GOPHER_FILE:
                        icon_url = mimeGetIconURL("internal-text");
                        break;

                    case GOPHER_INDEX:

                    case GOPHER_CSO:
                        icon_url = mimeGetIconURL("internal-index");
                        break;

                    case GOPHER_IMAGE:

                    case GOPHER_GIF:

                    case GOPHER_PLUS_IMAGE:
                        icon_url = mimeGetIconURL("internal-image");
                        break;

                    case GOPHER_SOUND:

                    case GOPHER_PLUS_SOUND:
                        icon_url = mimeGetIconURL("internal-sound");
                        break;

                    case GOPHER_PLUS_MOVIE:
                        icon_url = mimeGetIconURL("internal-movie");
                        break;

                    case GOPHER_TELNET:

                    case GOPHER_3270:
                        icon_url = mimeGetIconURL("internal-telnet");
                        break;

                    case GOPHER_BIN:

                    case GOPHER_MACBINHEX:

                    case GOPHER_DOSBIN:

                    case GOPHER_UUENCODED:
                        icon_url = mimeGetIconURL("internal-binary");
                        break;

                    case GOPHER_INFO:
                        icon_url = NULL;
                        break;

                    default:
                        icon_url = mimeGetIconURL("internal-unknown");
                        break;
                    }

                    memset(tmpbuf, '\0', TEMP_BUF_SIZE);

                    if ((gtype == GOPHER_TELNET) || (gtype == GOPHER_3270)) {
                        if (strlen(escaped_selector) != 0)
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, escaped_selector, rfc1738_escape_part(host),
                                     *port ? ":" : "", port, html_quote(name));
                        else
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, rfc1738_escape_part(host), *port ? ":" : "",
                                     port, html_quote(name));

                    } else if (gtype == GOPHER_INFO) {
                        snprintf(tmpbuf, TEMP_BUF_SIZE, "\t%s\n", html_quote(name));
                    } else {
                        if (strncmp(selector, "GET /", 5) == 0) {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"http:
                                     icon_url, host, rfc1738_escape_unescaped(selector + 5), html_quote(name));
                        } else {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"gopher:
                                     icon_url, host, gtype, escaped_selector, html_quote(name));
                        }
                    }

                    safe_free(escaped_selector);
                    outbuf.append(tmpbuf);
                } else {
                    memset(line, '\0', TEMP_BUF_SIZE);
                    continue;
                }
            } else {
                memset(line, '\0', TEMP_BUF_SIZE);
                continue;
            }

            break;
            }           

        case GopherStateData::HTML_CSO_RESULT: {
            if (line[0] == '-') {
                int code, recno;
                char *s_code, *s_recno, *result;

                s_code = strtok(line + 1, ":\n");
                s_recno = strtok(NULL, ":\n");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                recno = atoi(s_recno);

                if (code != 200)
                    break;

                if (bu->cso_recno != recno) {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>Record# %d<br><i>%s</i></H2>\n<PRE>", recno, html_quote(result));
                    bu->cso_recno = recno;
                } else {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "%s\n", html_quote(result));
                }

                outbuf.append(tmpbuf);
                break;
            } else {
                int code;
                char *s_code, *result;

                s_code = strtok(line, ":");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                switch (code) {

                case 200: {


                    break;
                }

                case 102:   

                case 501:   

                case 502: { 

                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>%s</H2>\n<PRE>", html_quote(result));
                    outbuf.append(tmpbuf);
                    break;
                }

                }
            }

            }           

        default:
            break;      

        }           

    }               

    if (outbuf.size() > 0) {
        entry->append(outbuf.rawBuf(), outbuf.size());

        entry->flush();
    }

    outbuf.clean();
    return;
}

