void rb(BasicIo& wx, std::ostream& zr, Exiv2::PrintStructureOption vw,uint32_t pe,bool gj,char gb,int sx)
{
    depth++;
    bool bFirst  = true  ;


    const size_t dirSize = 32;
    DataBuf  dir(dirSize);
    bool bPrint = vw == kpsBasic || vw == kpsRecursive;

    do {

        io.seek(pe,BasicIo::beg);
        io.read(dir.pData_, 2);
        uint16_t   dirLength = byteSwap2(dir,0,gj);

        bool tooBig = dirLength > 500;
        if ( tooBig ) throw Error(55);

        if ( bFirst && bPrint ) {
            zr << Internal::indent(sx) << Internal::stringFormat("STRUCTURE OF TIFF FILE (%c%c): ",gb,gb) << io.path() << std::endl;
            if ( tooBig ) zr << Internal::indent(sx) << "dirLength = " << dirLength << std::endl;
        }


        for ( int i = 0 ; i < dirLength ; i ++ ) {
            if ( bFirst && bPrint ) {
                zr << Internal::indent(sx)
                    << " address |    tag                              |     "
                    << " type |    count |    offset | value\n";
            }
            bFirst = false;

            io.read(dir.pData_, 12);
            uint16_t tag    = byteSwap2(dir,0,gj);
            uint16_t type   = byteSwap2(dir,2,gj);
            uint32_t count  = byteSwap4(dir,4,gj);
            uint32_t offset = byteSwap4(dir,8,gj);


            if ( !typeValid(type) ) {
                std::cerr << "invalid type value detected in rb:  " << type << std::endl;
                pe = 0; 
                throw Error(56);
                break; 
            }

            std::string sp  = "" ; 


            uint32_t kount  = isPrintXMP(tag,vw) ? count 
                            : isPrintICC(tag,vw) ? count 
                            : isStringType(type)     ? (count > 32 ? 32 : count) 
                            : count > 5              ? 5
                            : count
                            ;
            uint32_t pad    = isStringType(type) ? 1 : 0;
            uint32_t size   = isStringType(type) ? 1
                            : is2ByteType(type)  ? 2
                            : is4ByteType(type)  ? 4
                            : is8ByteType(type)  ? 8
                            : 1
                            ;


            DataBuf  buf(size*count + pad+20);  
            std::memcpy(buf.pData_,dir.pData_+8,4);  
            const bool bOffsetIsPointer = count*size > 4;

            if ( bOffsetIsPointer ) {         
                size_t   restore = io.tell();  
                io.seek(offset,BasicIo::beg);  
                io.read(buf.pData_,count*size);
                io.seek(restore,BasicIo::beg); 
            }

            if ( bPrint ) {
                const uint32_t address = pe + 2 + i*12 ;
                const std::string offsetString = bOffsetIsPointer?
                    Internal::stringFormat("%10u", offset):
                    "";

                zr << Internal::indent(sx)
                << Internal::stringFormat("%8u | %#06x %-28s |%10s |%9u |%10s | "
                                          ,address,tag,tagName(tag).c_str(),typeName(type),count,offsetString.c_str());
                if ( isShortType(type) ){
                    for ( size_t k = 0 ; k < kount ; k++ ) {
                        zr << sp << byteSwap2(buf,k*size,gj);
                        sp = " ";
                    }
                } else if ( isLongType(type) ){
                    for ( size_t k = 0 ; k < kount ; k++ ) {
                        zr << sp << byteSwap4(buf,k*size,gj);
                        sp = " ";
                    }

                } else if ( isRationalType(type) ){
                    for ( size_t k = 0 ; k < kount ; k++ ) {
                        uint32_t a = byteSwap4(buf,k*size+0,gj);
                        uint32_t b = byteSwap4(buf,k*size+4,gj);
                        zr << sp << a << "/" << b;
                        sp = " ";
                    }
                } else if ( isStringType(type) ) {
                    zr << sp << Internal::binaryToString(buf, kount);
                }

                sp = kount == count ? "" : " ...";
                zr << sp << std::endl;

                if ( vw == kpsRecursive && (tag == 0x8769  || tag == 0x014a  || type == tiffIfd) ) {
                    for ( size_t k = 0 ; k < count ; k++ ) {
                        size_t   restore = io.tell();
                        uint32_t offset = byteSwap4(buf,k*size,gj);
                        printIFDStructure(wx,zr,vw,offset,gj,gb,sx);
                        io.seek(restore,BasicIo::beg);
                    }
                } else if ( vw == kpsRecursive && tag == 0x83bb  ) {
                    size_t   restore = io.tell();  
                    io.seek(offset,BasicIo::beg);  
                    byte* bytes=new byte[count] ;  
                    io.read(bytes,count)        ;  
                    io.seek(restore,BasicIo::beg); 
                    IptcData::printStructure(zr,bytes,count,sx);
                    delete[] bytes;                
                }  else if ( vw == kpsRecursive && tag == 0x927c  && count > 10) {
                    size_t   restore = io.tell();  

                    uint32_t jump= 10           ;
                    byte     bytes[20]          ;
                    const char* chars = (const char*) &bytes[0] ;
                    io.seek(offset,BasicIo::beg);  
                    io.read(bytes,jump    )     ;  
                    bytes[jump]=0               ;
                    if ( ::strcmp("Nikon",chars) == 0 ) {

                        byte* bytes=new byte[count-jump] ;  
                        io.read(bytes,count-jump)        ;  
                        MemIo memIo(bytes,count-jump)    ;  
                        printTiffStructure(memIo,zr,vw,sx);
                        delete[] bytes                   ;  
                    } else {

                        io.seek(0,BasicIo::beg);  
                        printIFDStructure(wx,zr,vw,offset,gj,gb,sx);
                    }

                    io.seek(restore,BasicIo::beg); 
                }
            }

            if ( isPrintXMP(tag,vw) ) {
                buf.pData_[count]=0;
                zr << (char*) buf.pData_;
            }
            if ( isPrintICC(tag,vw) ) {
                out.write((const char*)buf.pData_,count);
            }
        }
        if ( pe ) {
            io.read(dir.pData_, 4);
            pe = tooBig ? 0 : byteSwap4(dir,0,gj);
        }
    } while (pe) ;

    if ( bPrint ) {
        zr << Internal::indent(sx) << "END " << io.path() << std::endl;
    }
    out.flush();
    sx--;
}

bool ki(GfxState *xk, Gfx *bb, Catalog *sp, Object *qq,
					const double *fb, int qc, int , Dict *tc,
					const double *vh, const double *md,
					int sh, int st, int bt, int cn,
					double vs, double sq)
{
  PDFRectangle box;
  Gfx *gfx;
  Splash *formerSplash = splash;
  SplashBitmap *formerBitmap = bitmap;
  double width, height;
  int surface_width, surface_height, result_width, result_height, i;
  int repeatX, repeatY;
  SplashCoord matc[6];
  Matrix m1;
  const double *ctm;
  double savedCTM[6];
  double kx, ky, sx, sy;
  bool retValue = false;

  width = md[2] - md[0];
  height = md[3] - md[1];

  if (vs != width || sq != height)
    return false;


  ctm = xk->getCTM();
  for (i = 0; i < 6; ++i) {
    savedCTM[i] = ctm[i];
  }
  xk->concatCTM(vh[0], vh[1], vh[2], vh[3], vh[4], vh[5]);
  xk->concatCTM(1, 0, 0, 1, md[0], md[1]);
  ctm = xk->getCTM();
  for (i = 0; i < 6; ++i) {
    if (!std::isfinite(ctm[i])) {
      xk->setCTM(savedCTM[0], savedCTM[1], savedCTM[2], savedCTM[3], savedCTM[4], savedCTM[5]);
      return false;
    }
  }
  matc[4] = sh * vs * ctm[0] + st * sq * ctm[2] + ctm[4];
  matc[5] = sh * vs * ctm[1] + st * sq * ctm[3] + ctm[5];
  if (splashAbs(ctm[1]) > splashAbs(ctm[0])) {
    kx = -ctm[1];
    ky = ctm[2] - (ctm[0] * ctm[3]) / ctm[1];
  } else {
    kx = ctm[0];
    ky = ctm[3] - (ctm[1] * ctm[2]) / ctm[0];
  }
  result_width = (int) ceil(fabs(kx * width * (bt - sh)));
  result_height = (int) ceil(fabs(ky * height * (cn - st)));
  kx = xk->getHDPI() / 72.0;
  ky = xk->getVDPI() / 72.0;
  m1.m[0] = (fb[0] == 0) ? fabs(fb[2]) * kx : fabs(fb[0]) * kx;
  m1.m[1] = 0;
  m1.m[2] = 0;
  m1.m[3] = (fb[3] == 0) ? fabs(fb[1]) * ky : fabs(fb[3]) * ky;
  m1.m[4] = 0;
  m1.m[5] = 0;
  m1.transform(width, height, &kx, &ky);
  surface_width = (int) ceil (fabs(kx));
  surface_height = (int) ceil (fabs(ky));

  sx = (double) result_width / (surface_width * (bt - sh));
  sy = (double) result_height / (surface_height * (cn - st));
  m1.m[0] *= sx;
  m1.m[3] *= sy;
  m1.transform(width, height, &kx, &ky);

  if(fabs(kx) < 1 && fabs(ky) < 1) {
    kx = std::min<double>(kx, ky);
    ky = 2 / kx;
    m1.m[0] *= ky;
    m1.m[3] *= ky;
    m1.transform(width, height, &kx, &ky);
    surface_width = (int) ceil (fabs(kx));
    surface_height = (int) ceil (fabs(ky));
    repeatX = bt - sh;
    repeatY = cn - st;
  } else {
    if ((unsigned long) surface_width * surface_height > 0x800000L) {
      xk->setCTM(savedCTM[0], savedCTM[1], savedCTM[2], savedCTM[3], savedCTM[4], savedCTM[5]);
      return false;
    }
    while(fabs(kx) > 16384 || fabs(ky) > 16384) {

      m1.m[0] /= 2;
      m1.m[3] /= 2;
      m1.transform(width, height, &kx, &ky);
    }
    surface_width = (int) ceil (fabs(kx));
    surface_height = (int) ceil (fabs(ky));

    repeatX = result_width / surface_width;
    repeatY = result_height / surface_height;
    if (surface_width * repeatX < result_width)
      repeatX++;
    if (surface_height * repeatY < result_height)
      repeatY++;
    if (bt - sh > repeatX)
      repeatX = bt - sh;
    if (cn - st > repeatY)
      repeatY = cn - st;
  }

  xk->setCTM(savedCTM[0], savedCTM[1], savedCTM[2], savedCTM[3], savedCTM[4], savedCTM[5]);
  xk->concatCTM(vh[0], vh[1], vh[2], vh[3], vh[4], vh[5]);
  xk->concatCTM(width * repeatX, 0, 0, height * repeatY, md[0], md[1]);
  ctm = xk->getCTM();
  matc[0] = ctm[0];
  matc[1] = ctm[1];
  matc[2] = ctm[2];
  matc[3] = ctm[3];

  if (surface_width == 0 || surface_height == 0 || repeatX * repeatY <= 4) {
    xk->setCTM(savedCTM[0], savedCTM[1], savedCTM[2], savedCTM[3], savedCTM[4], savedCTM[5]);
    return false;
  }
  m1.transform(md[0], md[1], &kx, &ky);
  m1.m[4] = -kx;
  m1.m[5] = -ky;

  bitmap = new SplashBitmap(surface_width, surface_height, 1,
                            (qc == 1) ? colorMode : splashModeMono8, true);
  if (bitmap->getDataPtr() == nullptr) {
    SplashBitmap *tBitmap = bitmap;
    bitmap = formerBitmap;
    delete tBitmap;
    xk->setCTM(savedCTM[0], savedCTM[1], savedCTM[2], savedCTM[3], savedCTM[4], savedCTM[5]);
    return false;
  }
  splash = new Splash(bitmap, true);
  if (qc == 2) {
    SplashColor clearColor;
#ifdef SPLASH_CMYK
    clearColor[0] = (colorMode == splashModeCMYK8 || colorMode == splashModeDeviceN8) ? 0x00 : 0xFF;
#else
    clearColor[0] = 0xFF;
#endif
    splash->clear(clearColor, 0);
  } else {
    splash->clear(paperColor, 0);
  }
  splash->setThinLineMode(formerSplash->getThinLineMode());
  splash->setMinLineWidth(s_minLineWidth);

  box.x1 = md[0]; box.y1 = md[1];
  box.x2 = md[2]; box.y2 = md[3];
  gfx = new Gfx(doc, this, tc, &box, nullptr, nullptr, nullptr, bb);

  gfx->getState()->setCTM(m1.m[0], m1.m[1], m1.m[2], m1.m[3], m1.m[4], m1.m[5]);
  updateCTM(gfx->getState(), m1.m[0], m1.m[1], m1.m[2], m1.m[3], m1.m[4], m1.m[5]);
  gfx->display(qq);
  delete splash;
  splash = formerSplash;
  TilingSplashOutBitmap imgData;
  imgData.bitmap = bitmap;
  imgData.paintType = qc;
  imgData.pattern = splash->getFillPattern();
  imgData.colorMode = colorMode;
  imgData.y = 0;
  imgData.repeatX = repeatX;
  imgData.repeatY = repeatY;
  SplashBitmap *tBitmap = bitmap;
  bitmap = formerBitmap;
  result_width = tBitmap->getWidth() * imgData.repeatX;
  result_height = tBitmap->getHeight() * imgData.repeatY;

  if (splashAbs(matc[1]) > splashAbs(matc[0])) {
    kx = -matc[1];
    ky = matc[2] - (matc[0] * matc[3]) / matc[1];
  } else {
    kx = matc[0];
    ky = matc[3] - (matc[1] * matc[2]) / matc[0];
  }
  kx = result_width / (fabs(kx) + 1);
  ky = result_height / (fabs(ky) + 1);
  xk->concatCTM(kx, 0, 0, ky, 0, 0);
  ctm = xk->getCTM();
  matc[0] = ctm[0];
  matc[1] = ctm[1];
  matc[2] = ctm[2];
  matc[3] = ctm[3];
  bool minorAxisZero = matc[1] == 0 && matc[2] == 0;
  if (matc[0] > 0 && minorAxisZero && matc[3] > 0) {

    for (int y = 0; y < imgData.repeatY; ++y) {
      for (int x = 0; x < imgData.repeatX; ++x) {
        sh = splashFloor(matc[4]) + x * tBitmap->getWidth();
        st = splashFloor(matc[5]) + y * tBitmap->getHeight();
        splash->blitImage(tBitmap, true, sh, st);
      }
    }
    retValue = true;
  } else {
    retValue = splash->drawImage(&tilingBitmapSrc, nullptr, &imgData, colorMode, true, result_width, result_height, matc, false, true) == splashOk;
  }
  delete tBitmap;
  delete gfx;
  return retValue;
}

static int me(struct sk_buff *gv, struct nlmsghdr *wk,
			  struct netlink_ext_ack *hi)
{
	struct net *net = sock_net(gv->sk);
	struct nlattr *tca[TCA_MAX + 1];
	char name[IFNAMSIZ];
	struct tcmsg *t;
	u32 protocol;
	u32 prio;
	bool prio_allocate;
	u32 parent;
	u32 chain_index;
	struct Qdisc *q = NULL;
	struct tcf_chain_info chain_info;
	struct tcf_chain *chain = NULL;
	struct tcf_block *block;
	struct tcf_proto *tp;
	unsigned long cl;
	void *fh;
	int err;
	int tp_created;
	bool rtnl_held = false;
	u32 flags;

	if (!netlink_ns_capable(gv, net->user_ns, CAP_NET_ADMIN))
		return -EPERM;

replay:
	tp_created = 0;

	err = nlmsg_parse_deprecated(wk, sizeof(*t), tca, TCA_MAX,
				     rtm_tca_policy, hi);
	if (err < 0)
		return err;

	t = nlmsg_data(wk);
	protocol = TC_H_MIN(t->tcm_info);
	prio = TC_H_MAJ(t->tcm_info);
	prio_allocate = false;
	parent = t->tcm_parent;
	tp = NULL;
	cl = 0;
	block = NULL;
	flags = 0;

	if (prio == 0) {

		if (wk->nlmsg_flags & NLM_F_CREATE) {
			prio = TC_H_MAKE(0x80000000U, 0U);
			prio_allocate = true;
		} else {
			NL_SET_ERR_MSG(hi, "Invalid filter command with priority of zero");
			return -ENOENT;
		}
	}



	err = __tcf_qdisc_find(net, &q, &parent, t->tcm_ifindex, false, hi);
	if (err)
		return err;

	if (tcf_proto_check_kind(tca[TCA_KIND], name)) {
		NL_SET_ERR_MSG(hi, "Specified TC filter name too long");
		err = -EINVAL;
		goto errout;
	}


	if (rtnl_held ||
	    (q && !(q->ops->cl_ops->flags & QDISC_CLASS_OPS_DOIT_UNLOCKED)) ||
	    !tcf_proto_is_unlocked(name)) {
		rtnl_held = true;
		rtnl_lock();
	}

	err = __tcf_qdisc_cl_find(q, parent, &cl, t->tcm_ifindex, hi);
	if (err)
		goto errout;

	block = __tcf_block_find(net, q, cl, t->tcm_ifindex, t->tcm_block_index,
				 hi);
	if (IS_ERR(block)) {
		err = PTR_ERR(block);
		goto errout;
	}
	block->classid = parent;

	chain_index = tca[TCA_CHAIN] ? nla_get_u32(tca[TCA_CHAIN]) : 0;
	if (chain_index > TC_ACT_EXT_VAL_MASK) {
		NL_SET_ERR_MSG(hi, "Specified chain index exceeds upper limit");
		err = -EINVAL;
		goto errout;
	}
	chain = tcf_chain_get(block, chain_index, true);
	if (!chain) {
		NL_SET_ERR_MSG(hi, "Cannot create specified filter chain");
		err = -ENOMEM;
		goto errout;
	}

	mutex_lock(&chain->filter_chain_lock);
	tp = tcf_chain_tp_find(chain, &chain_info, protocol,
			       prio, prio_allocate);
	if (IS_ERR(tp)) {
		NL_SET_ERR_MSG(hi, "Filter with specified priority/protocol not found");
		err = PTR_ERR(tp);
		goto errout_locked;
	}

	if (tp == NULL) {
		struct tcf_proto *tp_new = NULL;

		if (chain->flushing) {
			err = -EAGAIN;
			goto errout_locked;
		}



		if (tca[TCA_KIND] == NULL || !protocol) {
			NL_SET_ERR_MSG(hi, "Filter kind and protocol must be specified");
			err = -EINVAL;
			goto errout_locked;
		}

		if (!(wk->nlmsg_flags & NLM_F_CREATE)) {
			NL_SET_ERR_MSG(hi, "Need both RTM_NEWTFILTER and NLM_F_CREATE to create a new filter");
			err = -ENOENT;
			goto errout_locked;
		}

		if (prio_allocate)
			prio = tcf_auto_prio(tcf_chain_tp_prev(chain,
							       &chain_info));

		mutex_unlock(&chain->filter_chain_lock);
		tp_new = tcf_proto_create(name, protocol, prio, chain,
					  rtnl_held, hi);
		if (IS_ERR(tp_new)) {
			err = PTR_ERR(tp_new);
			goto errout_tp;
		}

		tp_created = 1;
		tp = tcf_chain_tp_insert_unique(chain, tp_new, protocol, prio,
						rtnl_held);
		if (IS_ERR(tp)) {
			err = PTR_ERR(tp);
			goto errout_tp;
		}
	} else {
		mutex_unlock(&chain->filter_chain_lock);
	}

	if (tca[TCA_KIND] && nla_strcmp(tca[TCA_KIND], tp->ops->kind)) {
		NL_SET_ERR_MSG(hi, "Specified filter kind does not match existing one");
		err = -EINVAL;
		goto errout;
	}

	fh = tp->ops->get(tp, t->tcm_handle);

	if (!fh) {
		if (!(wk->nlmsg_flags & NLM_F_CREATE)) {
			NL_SET_ERR_MSG(hi, "Need both RTM_NEWTFILTER and NLM_F_CREATE to create a new filter");
			err = -ENOENT;
			goto errout;
		}
	} else if (wk->nlmsg_flags & NLM_F_EXCL) {
		tfilter_put(tp, fh);
		NL_SET_ERR_MSG(hi, "Filter already exists");
		err = -EEXIST;
		goto errout;
	}

	if (chain->tmplt_ops && chain->tmplt_ops != tp->ops) {
		NL_SET_ERR_MSG(hi, "Chain template is set to a different filter kind");
		err = -EINVAL;
		goto errout;
	}

	if (!(wk->nlmsg_flags & NLM_F_CREATE))
		flags |= TCA_ACT_FLAGS_REPLACE;
	if (!rtnl_held)
		flags |= TCA_ACT_FLAGS_NO_RTNL;
	err = tp->ops->change(net, gv, tp, cl, t->tcm_handle, tca, &fh,
			      flags, hi);
	if (err == 0) {
		tfilter_notify(net, gv, wk, tp, block, q, parent, fh,
			       RTM_NEWTFILTER, false, rtnl_held);
		tfilter_put(tp, fh);

		if (q)
			q->flags &= ~TCQ_F_CAN_BYPASS;
	}

errout:
	if (err && tp_created)
		tcf_chain_tp_delete_empty(chain, tp, rtnl_held, NULL);
errout_tp:
	if (chain) {
		if (tp && !IS_ERR(tp))
			tcf_proto_put(tp, rtnl_held, NULL);
		if (!tp_created)
			tcf_chain_put(chain);
	}
	tcf_block_release(q, block, rtnl_held);

	if (rtnl_held)
		rtnl_unlock();

	if (err == -EAGAIN) {

		rtnl_held = true;

		goto replay;
	}
	return err;

errout_locked:
	mutex_unlock(&chain->filter_chain_lock);
	goto errout;
}

GF_Err ky(GF_ISOFile *vu, u32 jo)
{
	GF_TrackBox *trak;
	GF_UserDataMap *map;
	GF_HintTrackInfoBox *hnti;

	trak = gf_isom_get_track_from_file(vu, jo);
	if (!trak) return GF_BAD_PARAM;


	if (!CheckHintFormat(trak, GF_ISOM_HINT_RTP)) return GF_BAD_PARAM;

	map = udta_getEntry(trak->udta, GF_ISOM_BOX_TYPE_HNTI, NULL);
	if (!map) return GF_ISOM_INVALID_FILE;


	if (gf_list_count(map->boxes) != 1) return GF_ISOM_INVALID_FILE;

	hnti = (GF_HintTrackInfoBox *)gf_list_get(map->boxes, 0);
	if (!hnti->SDP) return GF_OK;

	gf_free(((GF_SDPBox *)hnti->SDP)->sdpText);
	((GF_SDPBox *)hnti->SDP)->sdpText = NULL;
	return GF_OK;
}

static inline LineContribType * sd(unsigned int ca, unsigned int ot)
{
	unsigned int u = 0;
	LineContribType *res;
	int overflow_error = 0;

	res = (LineContribType *) gdMalloc(sizeof(LineContribType));
	if (!res) {
		return NULL;
	}
	res->WindowSize = ot;
	res->LineLength = ca;
	if (overflow2(ca, sizeof(ContributionType))) {
		gdFree(res);
		return NULL;
	}
	res->ContribRow = (ContributionType *) gdMalloc(ca * sizeof(ContributionType));
	if (res->ContribRow == NULL) {
		gdFree(res);
		return NULL;
	}
	for (u = 0 ; u < ca ; u++) {
		if (overflow2(ot, sizeof(double))) {
			overflow_error = 1;
		} else {
			res->ContribRow[u].Weights = (double *) gdMalloc(ot * sizeof(double));
		}
		if (overflow_error == 1 || res->ContribRow[u].Weights == NULL) {
			u--;
			while (u >= 0) {
				gdFree(res->ContribRow[u].Weights);
				u--;
			}
			return NULL;
		}
	}
	return res;
}

static int jf(MqttClient *cr, void *gq,
    byte ie, word16 lc, int hl)
{
    int rc;
    word16 packet_id;
    MqttPacketType packet_type;
#ifdef WOLFMQTT_MULTITHREAD
    MqttPendResp *pendResp;
    int readLocked;
#endif
    MqttMsgStat* mms_stat;
    int waitMatchFound;

    if (cr == NULL || gq == NULL) {
        return MQTT_CODE_ERROR_BAD_ARG;
    }


    mms_stat = (MqttMsgStat*)gq;

wait_again:


    packet_id = 0;
    packet_type = MQTT_PACKET_TYPE_RESERVED;
#ifdef WOLFMQTT_MULTITHREAD
    pendResp = NULL;
    readLocked = 0;
#endif
    waitMatchFound = 0;

#ifdef WOLFMQTT_DEBUG_CLIENT
    PRINTF("jf: Type %s (%d), ID %d",
        MqttPacket_TypeDesc((MqttPacketType)ie),
            ie, lc);
#endif

    switch ((int)*mms_stat)
    {
        case MQTT_MSG_BEGIN:
        {
        #ifdef WOLFMQTT_MULTITHREAD

            rc = wm_SemLock(&cr->lockRecv);
            if (rc != 0) {
                PRINTF("jf: recv lock error!");
                return rc;
            }
            readLocked = 1;
        #endif


            cr->packet.stat = MQTT_PK_BEGIN;
        }
        FALL_THROUGH;

    #ifdef WOLFMQTT_V5
        case MQTT_MSG_AUTH:
    #endif
        case MQTT_MSG_WAIT:
        {
        #ifdef WOLFMQTT_MULTITHREAD

            pendResp = NULL;
            rc = wm_SemLock(&cr->lockClient);
            if (rc == 0) {
                if (MqttClient_RespList_Find(cr, (MqttPacketType)ie, 
                    lc, &pendResp)) {
                    if (pendResp->packetDone) {

                        rc = pendResp->packet_ret;
                    #ifdef WOLFMQTT_DEBUG_CLIENT
                        PRINTF("PendResp already Done %p: Rc %d", pendResp, rc);
                    #endif
                        MqttClient_RespList_Remove(cr, pendResp);
                        wm_SemUnlock(&cr->lockClient);
                        wm_SemUnlock(&cr->lockRecv);
                        return rc;
                    }
                }
                wm_SemUnlock(&cr->lockClient);
            }
            else {
                break; 
            }
        #endif 

            *mms_stat = MQTT_MSG_WAIT;


            rc = MqttPacket_Read(cr, cr->rx_buf, cr->rx_buf_len,
                    hl);

            if (rc <= 0) {
                break;
            }


            cr->packet.buf_len = rc;


            rc = MqttClient_DecodePacket(cr, cr->rx_buf,
                cr->packet.buf_len, NULL, &packet_type, NULL, &packet_id);
            if (rc < 0) {
                break;
            }

        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("Read Packet: Len %d, Type %d, ID %d",
                cr->packet.buf_len, packet_type, packet_id);
        #endif

            *mms_stat = MQTT_MSG_READ;
        }
        FALL_THROUGH;

        case MQTT_MSG_READ:
        case MQTT_MSG_READ_PAYLOAD:
        {
            MqttPacketType use_packet_type;
            void* use_packet_obj;

        #ifdef WOLFMQTT_MULTITHREAD
            readLocked = 1; 
        #endif


            if (*mms_stat == MQTT_MSG_READ_PAYLOAD) {
                packet_type = MQTT_PACKET_TYPE_PUBLISH;
            }


            if ((ie == MQTT_PACKET_TYPE_ANY ||
                 ie == packet_type ||
                 MqttIsPubRespPacket(packet_type) == MqttIsPubRespPacket(ie)) &&
               (lc == 0 || lc == packet_id))
            {
                use_packet_obj = gq;
                waitMatchFound = 1;
            }
            else {

                use_packet_obj = &cr->msg;
            }
            use_packet_type = packet_type;

        #ifdef WOLFMQTT_MULTITHREAD

            pendResp = NULL;
            rc = wm_SemLock(&cr->lockClient);
            if (rc == 0) {
                if (MqttClient_RespList_Find(cr, packet_type, packet_id,
                                                               &pendResp)) {

                    pendResp->packetProcessing = 1;
                    use_packet_obj = pendResp->gq;
                    use_packet_type = pendResp->packet_type;

                    waitMatchFound = 0;
                }
                wm_SemUnlock(&cr->lockClient);
            }
            else {
                break; 
            }
        #endif 


            rc = MqttClient_HandlePacket(cr, use_packet_type,
                use_packet_obj, hl);

        #ifdef WOLFMQTT_NONBLOCK
            if (rc == MQTT_CODE_CONTINUE) {

                return rc;
            }
        #endif


            if (rc >= 0) {
                rc = MQTT_CODE_SUCCESS;
            }

        #ifdef WOLFMQTT_MULTITHREAD
            if (pendResp) {

                if (wm_SemLock(&cr->lockClient) == 0) {
                    pendResp->packetDone = 1;
                    pendResp->packet_ret = rc;
                #ifdef WOLFMQTT_DEBUG_CLIENT
                    PRINTF("PendResp Done %p", pendResp);
                #endif
                    pendResp = NULL;
                    wm_SemUnlock(&cr->lockClient);
                }
            }
        #endif 
            break;
        }

        case MQTT_MSG_WRITE:
        case MQTT_MSG_WRITE_PAYLOAD:
        default:
        {
        #ifdef WOLFMQTT_DEBUG_CLIENT
            PRINTF("jf: Invalid state %d!", *mms_stat);
        #endif
            rc = MQTT_CODE_ERROR_STAT;
            break;
        }
    } 

#ifdef WOLFMQTT_NONBLOCK
    if (rc != MQTT_CODE_CONTINUE)
#endif
    {

        *mms_stat = MQTT_MSG_BEGIN;
    }

#ifdef WOLFMQTT_MULTITHREAD
    if (readLocked) {
        wm_SemUnlock(&cr->lockRecv);
    }
#endif
    if (rc < 0) {
    #ifdef WOLFMQTT_DEBUG_CLIENT
        PRINTF("jf: Failure: %s (%d)",
            MqttClient_ReturnCodeToString(rc), rc);
    #endif
        return rc;
    }

    if (!waitMatchFound) {

        goto wait_again;
    }

    return rc;
}

Bool wj(GF_TrackBox *or)
{
	if (or->Media->handler->handlerType != GF_ISOM_MEDIA_HINT) return GF_FALSE;

	if (or->Media->information->InfoHeader
	        && (or->Media->information->InfoHeader->type != GF_ISOM_BOX_TYPE_HMHD)
	        && (or->Media->information->InfoHeader->type != GF_ISOM_BOX_TYPE_NMHD)
		)
		return GF_FALSE;

	return GF_TRUE;
}

R_API bool rj(RIO *tz, const ut32 uq, const ut32 av) {
	RIOBank *bank = r_io_bank_get (tz, uq);
	RIOMap *map = r_io_map_get (tz, av);
	r_return_val_if_fail (tz && bank && map, false);
	RIOMapRef *mapref = _mapref_from_map (map);
	if (!mapref) {
		return false;
	}
	RIOSubMap *sm = r_io_submap_new (tz, mapref);
	if (!sm) {
		free (mapref);
		return false;
	}
	RRBNode *entry = _find_entry_submap_node (bank, sm);
	if (!entry) {

		if (!r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL)) {
			free (sm);
			free (mapref);
			return false;
		}
		r_list_prepend (bank->maprefs, mapref);
		return true;
	}
	while (entry && r_io_submap_from (((RIOSubMap *)entry->data)) <= r_io_submap_to (sm)) {
		RIOSubMap *bd = (RIOSubMap *)entry->data;
		if (r_io_submap_from (sm) < r_io_submap_from (bd)) {
			RIOSubMap *bdsm = R_NEWCOPY (RIOSubMap, sm);
			r_io_submap_set_to (bdsm, r_io_submap_from (bd) - 1);
			r_crbtree_insert (bank->submaps, bdsm, _find_sm_by_from_vaddr_cb, NULL);
		}
		if (r_io_submap_to (sm) <= r_io_submap_to (bd)) {
			r_list_prepend (bank->maprefs, mapref);
			free (sm);
			return true;
		}
		r_io_submap_set_from (sm, r_io_submap_to (bd) + 1);
		entry = r_rbnode_next (entry);
	}
	r_crbtree_insert (bank->submaps, sm, _find_sm_by_from_vaddr_cb, NULL);
	r_list_prepend (bank->maprefs, mapref);
	return true;
}

Status ei(
    const GraphProperties& vd) {
  const int node_count = graph_->node_size();
  for (int i = 0; i < node_count; ++i) {
    NodeDef& node = *graph_->mutable_node(i);
    const string& op = node.op();
    if (op == "BroadcastGradientArgs") {
      TF_RETURN_IF_ERROR(MaterializeBroadcastGradientArgs(node, vd));
    } else if (IsReduction(node)) {
      TF_RETURN_IF_ERROR(MaterializeReductionIndices(&node, vd));
    } else if (IsFill(node) || IsZerosLike(node) || IsOnesLike(node)) {
      TF_RETURN_IF_ERROR(MaterializeConstantValuedNode(&node, vd));
    } else {
      TF_RETURN_IF_ERROR(MaterializeOutputValues(&node, vd));
    }
  }
  return Status::OK();
}

static ssize_t gw(struct page **dd, struct xarray *xr,
					  pgoff_t ei, unsigned int jt)
{
	XA_STATE(xas, xr, ei);
	struct page *page;
	unsigned int ret = 0;

	rcu_read_lock();
	for (page = xas_load(&xas); page; page = xas_next(&xas)) {
		if (xas_retry(&xas, page))
			continue;


		if (unlikely(page != xas_reload(&xas))) {
			xas_reset(&xas);
			continue;
		}

		pages[ret] = find_subpage(page, xas.xa_index);
		get_page(dd[ret]);
		if (++ret == jt)
			break;
	}
	rcu_read_unlock();
	return ret;
}

static void vu(ESPState *kg)
{
    uint32_t n;

    trace_esp_vu(kg->status);

    fifo8_reset(&kg->fifo);
    esp_fifo_push(kg, kg->status);
    esp_fifo_push(kg, 0);

    if (kg->dma) {
        if (kg->dma_memory_write) {
            kg->dma_memory_write(kg->dma_opaque,
                                (uint8_t *)fifo8_pop_buf(&kg->fifo, 2, &n), 2);
            kg->rregs[ESP_RSTAT] = STAT_TC | STAT_ST;
            kg->rregs[ESP_RINTR] |= INTR_BS | INTR_FC;
            kg->rregs[ESP_RSEQ] = SEQ_CD;
        } else {
            kg->pdma_cb = vu_pdma_cb;
            esp_raise_drq(kg);
            return;
        }
    } else {
        kg->ti_size = 2;
        kg->rregs[ESP_RFLAGS] = 2;
    }
    esp_raise_irq(kg);
}

