static bool ak(struct torture_context *un,
		       struct smbcli_state *ib)
{
	bool ret = false;
	int fnum = -1;
	struct smbcli_request *req = NULL;
	const char *fname = BASEDIR "\\badwrite.txt";
	bool ok = false;

	if (!torture_setup_dir(ib, BASEDIR)) {
		torture_fail(un, "failed to setup basedir");
	}

	torture_comment(un, "Testing RAW_BAD_WRITE\n");

	fnum = smbcli_open(ib->tree, fname, O_RDWR|O_CREAT, DENY_NONE);
	if (fnum == -1) {
		torture_fail_goto(un,
			done,
			talloc_asprintf(un,
				"Failed to create %s - %s\n",
				fname,
				smbcli_errstr(ib->tree)));
	}

	req = smbcli_request_setup(ib->tree,
				   SMBwrite,
				   5,
				   0);
	if (req == NULL) {
		torture_fail_goto(un,
			done,
			talloc_asprintf(un, "talloc fail\n"));
	}

	SSVAL(req->out.vwv, VWV(0), fnum);
	SSVAL(req->out.vwv, VWV(1), 65535); 
	SIVAL(req->out.vwv, VWV(2), 0); 
	SSVAL(req->out.vwv, VWV(4), 0); 

        if (!smbcli_request_send(req)) {
		torture_fail_goto(un,
			done,
			talloc_asprintf(un, "Send failed\n"));
        }

        if (!smbcli_request_receive(req)) {
		torture_fail_goto(un,
			done,
			talloc_asprintf(un, "Reveive failed\n"));
	}


	ok = (NT_STATUS_EQUAL(req->status, NT_STATUS_INVALID_PARAMETER) ||
	     NT_STATUS_EQUAL(req->status, NT_STATUS_UNSUCCESSFUL));

	if (!ok) {
		torture_fail_goto(un,
			done,
			talloc_asprintf(un,
				"Should have returned "
				"NT_STATUS_INVALID_PARAMETER or "
				"NT_STATUS_UNSUCCESSFUL "
				"got %s\n",
				nt_errstr(req->status)));
        }

	ret = true;

done:
	if (req != NULL) {
		smbcli_request_destroy(req);
	}
	if (fnum != -1) {
		smbcli_close(ib->tree, fnum);
	}
	smb_raw_exit(ib->session);
	smbcli_deltree(ib->tree, BASEDIR);
	return ret;
}

flatpak_dir_ensure_bundle_remote (FlatpakDir         *ye,
                                  GFile              *ui,
                                  GBytes             *fx,
                                  FlatpakDecomposed **or,
                                  char              **wn,
                                  char              **ra,
                                  gboolean           *dc,
                                  GCancellable       *we,
                                  GError            **rb)
{
  g_autoptr(FlatpakDecomposed) ref = NULL;
  gboolean created_remote = FALSE;
  g_autoptr(GBytes) deploy_data = NULL;
  g_autoptr(GVariant) metadata = NULL;
  g_autofree char *origin = NULL;
  g_autofree char *fp_metadata = NULL;
  g_autofree char *basename = NULL;
  g_autoptr(GBytes) included_gpg_data = NULL;
  GBytes *gpg_data = NULL;
  g_autofree char *to_checksum = NULL;
  g_autofree char *remote = NULL;
  g_autofree char *collection_id = NULL;

  if (!flatpak_dir_ensure_repo (ye, we, rb))
    return NULL;

  metadata = flatpak_bundle_load (ui, &to_checksum,
                                  &ref,
                                  &origin,
                                  NULL, &fp_metadata, NULL,
                                  &included_gpg_data,
                                  &collection_id,
                                  rb);
  if (metadata == NULL)
    return NULL;

  gpg_data = fx ? fx : included_gpg_data;

  deploy_data = flatpak_dir_get_deploy_data (ye, ref, FLATPAK_DEPLOY_VERSION_ANY, we, NULL);
  if (deploy_data != NULL)
    {
      remote = g_strdup (flatpak_deploy_data_get_origin (deploy_data));


      if (gpg_data != NULL)
        {
          g_autoptr(GKeyFile) new_config = NULL;

          new_config = ostree_repo_copy_config (flatpak_dir_get_repo (ye));

          if (!flatpak_dir_modify_remote (ye, remote, new_config,
                                          gpg_data, we, rb))
            return NULL;
        }
    }
  else
    {
      g_autofree char *id = flatpak_decomposed_dup_id (ref);

      basename = g_file_get_basename (ui);
      remote = flatpak_dir_create_origin_remote (ye,
                                                 origin,
                                                 id,
                                                 basename,
                                                 flatpak_decomposed_get_ref (ref),
                                                 gpg_data,
                                                 collection_id,
                                                 &created_remote,
                                                 we,
                                                 rb);
      if (remote == NULL)
        return NULL;
    }

  if (dc)
    *dc = created_remote;

  if (or)
    *or = g_steal_pointer (&ref);

  if (wn)
    *wn = g_steal_pointer (&to_checksum);

  if (ra)
    *ra = g_steal_pointer (&fp_metadata);


  return g_steal_pointer (&remote);
}

find_field_in_tables(THD *re, Item_ident *ne,
                     TABLE_LIST *bj, TABLE_LIST *lz,
		     Item **bl, find_item_error_report_type gv,
                     bool hv, bool dl)
{
  Field *found=0;
  const char *db= ne->db_name;
  const char *table_name= ne->table_name;
  const char *name= ne->field_name;
  uint length=(uint) strlen(name);
  char name_buff[SAFE_NAME_LEN+1];
  TABLE_LIST *cur_table= bj;
  TABLE_LIST *actual_table;
  bool allow_rowid;

  if (!table_name || !table_name[0])
  {
    table_name= 0;                              
    db= 0;
  }

  allow_rowid= table_name || (cur_table && !cur_table->next_local);

  if (ne->cached_table)
  {
    DBUG_PRINT("info", ("using cached table"));

    TABLE_LIST *table_ref= ne->cached_table;

    if (table_ref->table && !table_ref->view &&
        (!table_ref->is_merged_derived() ||
         (!table_ref->is_multitable() && table_ref->merged_for_insert)))
    {

      found= find_field_in_table(re, table_ref->table, name, length,
                                 TRUE, &(ne->cached_field_index));
#ifndef NO_EMBEDDED_ACCESS_CHECKS

      if (found && hv && !is_temporary_table(table_ref) &&
          check_column_grant_in_table_ref(re, table_ref, name, length))
        found= WRONG_GRANT;
#endif
    }
    else
      found= find_field_in_table_ref(re, table_ref, name, length, ne->name,
                                     NULL, NULL, bl, hv,
                                     TRUE, &(ne->cached_field_index),
                                     dl,
                                     &actual_table);
    if (found)
    {
      if (found == WRONG_GRANT)
	return (Field*) 0;


      if (!table_ref->belong_to_view &&
          !table_ref->belong_to_derived)
      {
        SELECT_LEX *current_sel= ne->context->select_lex;
        SELECT_LEX *last_select= table_ref->select_lex;
        bool all_merged= TRUE;
        for (SELECT_LEX *sl= current_sel; sl && sl!=last_select;
             sl=sl->outer_select())
        {
          Item *subs= sl->master_unit()->ne;
          if (subs->type() == Item::SUBSELECT_ITEM && 
              ((Item_subselect*)subs)->substype() == Item_subselect::IN_SUBS &&
              ((Item_in_subselect*)subs)->test_strategy(SUBS_SEMI_JOIN))
          {
            continue;
          }
          all_merged= FALSE;
          break;
        }

        if (!all_merged && current_sel != last_select)
        {
          mark_select_range_as_dependent(re, last_select, current_sel,
                                         found, *bl, ne, true);
        }
      }
      return found;
    }
  }
  else
    ne->can_be_depended= TRUE;

  if (db && lower_case_table_names)
  {

    strmake_buf(name_buff, db);
    my_casedn_str(files_charset_info, name_buff);
    db= name_buff;
  }

  if (lz)
    last_table= lz->next_name_resolution_table;

  for (; cur_table != lz ;
       cur_table= cur_table->next_name_resolution_table)
  {
    Field *cur_field= find_field_in_table_ref(re, cur_table, name, length,
                                              ne->name, db, table_name, bl,
                                              (re->lex->sql_command ==
                                               SQLCOM_SHOW_FIELDS)
                                              ? false : hv,
                                              allow_rowid,
                                              &(ne->cached_field_index),
                                              dl,
                                              &actual_table);
    if (cur_field)
    {
      if (cur_field == WRONG_GRANT)
      {
        if (re->lex->sql_command != SQLCOM_SHOW_FIELDS)
          return (Field*) 0;

        re->clear_error();
        cur_field= find_field_in_table_ref(re, cur_table, name, length,
                                           ne->name, db, table_name, bl,
                                           false,
                                           allow_rowid,
                                           &(ne->cached_field_index),
                                           dl,
                                           &actual_table);
        if (cur_field)
        {
          Field *nf=new Field_null(NULL,0,Field::NONE,
                                   cur_field->field_name,
                                   &my_charset_bin);
          nf->init(cur_table->table);
          cur_field= nf;
        }
      }


      ne->cached_table= (!actual_table->cacheable_table || found) ?
                          0 : actual_table;

      DBUG_ASSERT(re->where);

      if (db)
        return cur_field;

      if (found)
      {
        if (gv == REPORT_ALL_ERRORS ||
            gv == IGNORE_EXCEPT_NON_UNIQUE)
          my_error(ER_NON_UNIQ_ERROR, MYF(0),
                   table_name ? ne->full_name() : name, re->where);
        return (Field*) 0;
      }
      found= cur_field;
    }
  }

  if (found)
    return found;


  if (table_name && (cur_table == bj) &&
      (gv == REPORT_ALL_ERRORS ||
       gv == REPORT_EXCEPT_NON_UNIQUE))
  {
    char buff[SAFE_NAME_LEN*2 + 2];
    if (db && db[0])
    {
      strxnmov(buff,sizeof(buff)-1,db,".",table_name,NullS);
      table_name=buff;
    }
    my_error(ER_UNKNOWN_TABLE, MYF(0), table_name, re->where);
  }
  else
  {
    if (gv == REPORT_ALL_ERRORS ||
        gv == REPORT_EXCEPT_NON_UNIQUE)
      my_error(ER_BAD_FIELD_ERROR, MYF(0), ne->full_name(), re->where);
    else
      found= not_found_field;
  }
  return found;
}

int xe(SSL *nt)
{
    int ok, al, ret = 0, ticklen;
    long n;
    const unsigned char *p;
    unsigned char *d;

    n = nt->method->ssl_get_message(nt,
                                   SSL3_ST_CR_SESSION_TICKET_A,
                                   SSL3_ST_CR_SESSION_TICKET_B,
                                   SSL3_MT_NEWSESSION_TICKET, 16384, &ok);

    if (!ok)
        return ((int)n);

    if (n < 6) {

        al = SSL_AD_DECODE_ERROR;
        SSLerr(SSL_F_SSL3_GET_NEW_SESSION_TICKET, SSL_R_LENGTH_MISMATCH);
        goto f_err;
    }

    p = d = (unsigned char *)nt->init_msg;
    n2l(p, nt->session->tlsext_tick_lifetime_hint);
    n2s(p, ticklen);

    if (ticklen + 6 != n) {
        al = SSL_AD_DECODE_ERROR;
        SSLerr(SSL_F_SSL3_GET_NEW_SESSION_TICKET, SSL_R_LENGTH_MISMATCH);
        goto f_err;
    }
    if (nt->session->tlsext_tick) {
        OPENSSL_free(nt->session->tlsext_tick);
        nt->session->tlsext_ticklen = 0;
    }
    nt->session->tlsext_tick = OPENSSL_malloc(ticklen);
    if (!s->session->tlsext_tick) {
        SSLerr(SSL_F_SSL3_GET_NEW_SESSION_TICKET, ERR_R_MALLOC_FAILURE);
        goto err;
    }
    memcpy(nt->session->tlsext_tick, p, ticklen);
    nt->session->tlsext_ticklen = ticklen;

    EVP_Digest(p, ticklen,
               nt->session->session_id, &nt->session->session_id_length,
# ifndef OPENSSL_NO_SHA256
               EVP_sha256(), NULL);
# else
               EVP_sha1(), NULL);
# endif
    ret = 1;
    return (ret);
 f_err:
    ssl3_send_alert(nt, SSL3_AL_FATAL, al);
 err:
    nt->state = SSL_ST_ERR;
    return (-1);
}

void af( pjmedia_rtcp_xr_session *hf,
				 const void *zz,
				 pj_size_t fn)
{
    const pjmedia_rtcp_xr_pkt	      *rtcp_xr = (pjmedia_rtcp_xr_pkt*) zz;
    const pjmedia_rtcp_xr_rb_rr_time  *rb_rr_time = NULL;
    const pjmedia_rtcp_xr_rb_dlrr     *rb_dlrr = NULL;
    const pjmedia_rtcp_xr_rb_stats    *rb_stats = NULL;
    const pjmedia_rtcp_xr_rb_voip_mtc *rb_voip_mtc = NULL;
    const pjmedia_rtcp_xr_rb_header   *rb_hdr = (pjmedia_rtcp_xr_rb_header*) 
						rtcp_xr->buf;
    unsigned pkt_len, rb_len;

    if (rtcp_xr->common.pt != RTCP_XR)
	return;

    pkt_len = pj_ntohs((pj_uint16_t)rtcp_xr->common.length);

    if ((pkt_len + 1) > (fn / 4))
	return;


    while ((pj_int32_t*)rb_hdr < (pj_int32_t*)zz + pkt_len)
    {	
	rb_len = pj_ntohs((pj_uint16_t)rb_hdr->length);


	if (rb_len) {
	    switch (rb_hdr->bt) {
		case BT_RR_TIME:
		    rb_rr_time = (pjmedia_rtcp_xr_rb_rr_time*) rb_hdr;
		    break;
		case BT_DLRR:
		    rb_dlrr = (pjmedia_rtcp_xr_rb_dlrr*) rb_hdr;
		    break;
		case BT_STATS:
		    rb_stats = (pjmedia_rtcp_xr_rb_stats*) rb_hdr;
		    break;
		case BT_VOIP_METRICS:
		    rb_voip_mtc = (pjmedia_rtcp_xr_rb_voip_mtc*) rb_hdr;
		    break;
		default:
		    break;
	    }
	}
	rb_hdr = (pjmedia_rtcp_xr_rb_header*)
		 ((pj_int32_t*)rb_hdr + rb_len + 1);
    }


    if (rb_rr_time) {

	sess->rx_lrr = ((pj_ntohl(rb_rr_time->ntp_sec) & 0x0000FFFF) << 16) | 
		       ((pj_ntohl(rb_rr_time->ntp_frac) >> 16) & 0xFFFF);


	pj_get_timestamp(&hf->rx_lrr_time);

	TRACE_((hf->name, "Rx RTCP SR: ntp_ts=%p", hf->rx_lrr,
	       (pj_uint32_t)(hf->rx_lrr_time.u64*65536/
			     hf->rtcp_session->ts_freq.u64)));
    }


    if (rb_dlrr) {
	pj_uint32_t lrr, now, dlrr;
	pj_uint64_t eedelay;
	pjmedia_rtcp_ntp_rec ntp;


	lrr = pj_ntohl(rb_dlrr->item.lrr);


	dlrr = pj_ntohl(rb_dlrr->item.dlrr);


	pjmedia_rtcp_get_ntp_time(hf->rtcp_session, &ntp);
	now = ((ntp.hi & 0xFFFF) << 16) + (ntp.lo >> 16);


	eedelay = now - lrr - dlrr;


	if (eedelay < 4294) {
	    eedelay = (eedelay * 1000000) >> 16;
	} else {
	    eedelay = (eedelay * 1000) >> 16;
	    eedelay *= 1000;
	}

	TRACE_((hf->name, "Rx RTCP XR DLRR: lrr=%p, dlrr=%p (%d:%03dms), "
			   "now=%p, rtt=%p",
		lrr, dlrr, dlrr/65536, (dlrr%65536)*1000/65536,
		now, (pj_uint32_t)eedelay));


	if (now-dlrr >= lrr) {
	    unsigned rtt = (pj_uint32_t)eedelay;


	    if (eedelay <= 30 * 1000 * 1000UL) {

		if (rtt>((unsigned)hf->stat.rtt.mean*3) && hf->stat.rtt.n!=0)
		{
		    unsigned orig_rtt = rtt;
		    rtt = (unsigned)hf->stat.rtt.mean*3;
		    PJ_LOG(5,(hf->name, 
			      "RTT value %d usec is normalized to %d usec",
			      orig_rtt, rtt));
		}

		TRACE_((hf->name, "RTCP RTT is set to %d usec", rtt));
		pj_math_stat_update(&hf->stat.rtt, rtt);
	    }
	} else {
	    PJ_LOG(5, (hf->name, "Internal RTCP NTP clock skew detected: "
				   "lrr=%p, now=%p, dlrr=%p (%d:%03dms), "
				   "diff=%d",
				   lrr, now, dlrr, dlrr/65536,
				   (dlrr%65536)*1000/65536,
				   dlrr-(now-lrr)));
	}
    }


    if (rb_stats) {
	pj_uint8_t flags = rb_stats->header.specific;

	pj_bzero(&hf->stat.tx.stat_sum, sizeof(hf->stat.tx.stat_sum));


	sess->stat.tx.stat_sum.begin_seq = pj_ntohs(rb_stats->begin_seq);
	sess->stat.tx.stat_sum.end_seq   = pj_ntohs(rb_stats->end_seq);


	sess->stat.tx.stat_sum.l = (flags & (1 << 7)) != 0;
	sess->stat.tx.stat_sum.d = (flags & (1 << 6)) != 0;
	sess->stat.tx.stat_sum.j = (flags & (1 << 5)) != 0;
	sess->stat.tx.stat_sum.t = (flags & (3 << 3)) != 0;


	if (hf->stat.tx.stat_sum.l) {
	    hf->stat.tx.stat_sum.lost = pj_ntohl(rb_stats->lost);
	}

	if (hf->stat.tx.stat_sum.d) {
	    hf->stat.tx.stat_sum.dup = pj_ntohl(rb_stats->dup);
	}

	if (hf->stat.tx.stat_sum.j) {
	    hf->stat.tx.stat_sum.jitter.min = pj_ntohl(rb_stats->jitter_min);
	    hf->stat.tx.stat_sum.jitter.max = pj_ntohl(rb_stats->jitter_max);
	    hf->stat.tx.stat_sum.jitter.mean= pj_ntohl(rb_stats->jitter_mean);
	    pj_math_stat_set_stddev(&hf->stat.tx.stat_sum.jitter, 
				    pj_ntohl(rb_stats->jitter_dev));
	}

	if (hf->stat.tx.stat_sum.t) {
	    hf->stat.tx.stat_sum.toh.min = rb_stats->toh_min;
	    hf->stat.tx.stat_sum.toh.max = rb_stats->toh_max;
	    hf->stat.tx.stat_sum.toh.mean= rb_stats->toh_mean;
	    pj_math_stat_set_stddev(&hf->stat.tx.stat_sum.toh, 
				    pj_ntohl(rb_stats->toh_dev));
	}

	pj_gettimeofday(&hf->stat.tx.stat_sum.update);
    }


    if (rb_voip_mtc) {
	sess->stat.tx.voip_mtc.loss_rate = rb_voip_mtc->loss_rate;
	sess->stat.tx.voip_mtc.discard_rate = rb_voip_mtc->discard_rate;
	sess->stat.tx.voip_mtc.burst_den = rb_voip_mtc->burst_den;
	sess->stat.tx.voip_mtc.gap_den = rb_voip_mtc->gap_den;
	sess->stat.tx.voip_mtc.burst_dur = pj_ntohs(rb_voip_mtc->burst_dur);
	sess->stat.tx.voip_mtc.gap_dur = pj_ntohs(rb_voip_mtc->gap_dur);
	sess->stat.tx.voip_mtc.rnd_trip_delay = 
					pj_ntohs(rb_voip_mtc->rnd_trip_delay);
	sess->stat.tx.voip_mtc.end_sys_delay = 
					pj_ntohs(rb_voip_mtc->end_sys_delay);

	sess->stat.tx.voip_mtc.signal_lvl = (pj_int8_t)
				    ((rb_voip_mtc->signal_lvl > 127)?
				     ((int)rb_voip_mtc->signal_lvl - 256) : 
				     rb_voip_mtc->signal_lvl);
	sess->stat.tx.voip_mtc.noise_lvl  = (pj_int8_t)
				    ((rb_voip_mtc->noise_lvl > 127)?
				     ((int)rb_voip_mtc->noise_lvl - 256) : 
				     rb_voip_mtc->noise_lvl);
	sess->stat.tx.voip_mtc.rerl = rb_voip_mtc->rerl;
	sess->stat.tx.voip_mtc.gmin = rb_voip_mtc->gmin;
	sess->stat.tx.voip_mtc.r_factor = rb_voip_mtc->r_factor;
	sess->stat.tx.voip_mtc.ext_r_factor = rb_voip_mtc->ext_r_factor;
	sess->stat.tx.voip_mtc.mos_lq = rb_voip_mtc->mos_lq;
	sess->stat.tx.voip_mtc.mos_cq = rb_voip_mtc->mos_cq;
	sess->stat.tx.voip_mtc.rx_config = rb_voip_mtc->rx_config;
	sess->stat.tx.voip_mtc.jb_nom = pj_ntohs(rb_voip_mtc->jb_nom);
	sess->stat.tx.voip_mtc.jb_max = pj_ntohs(rb_voip_mtc->jb_max);
	sess->stat.tx.voip_mtc.jb_abs_max = pj_ntohs(rb_voip_mtc->jb_abs_max);

	pj_gettimeofday(&hf->stat.tx.voip_mtc.update);
    }
}

TfLiteStatus zv(TfLiteContext* xk, TfLiteNode* zn) {
  const auto* params = reinterpret_cast<TfLiteSVDFParams*>(zn->builtin_data);
  OpData* op_data = reinterpret_cast<OpData*>(zn->user_data);
  int scratch_tensor_index = op_data->scratch_tensor_index;


  TF_LITE_ENSURE_EQ(xk, zn->outputs->size, 1);
  TF_LITE_ENSURE_EQ(xk, zn->inputs->size, 5);

  const TfLiteTensor* input;
  TF_LITE_ENSURE_OK(xk, GetInputSafe(xk, zn, kInputTensor, &input));
  const TfLiteTensor* weights_feature;
  TF_LITE_ENSURE_OK(xk, GetInputSafe(xk, zn, kWeightsFeatureTensor,
                                          &weights_feature));
  const TfLiteTensor* weights_time;
  TF_LITE_ENSURE_OK(
      xk, GetInputSafe(xk, zn, kWeightsTimeTensor, &weights_time));

  TF_LITE_ENSURE(xk,
                 input->type == kTfLiteFloat32 || input->type == kTfLiteInt8);



  const int rank = params->rank;
  const int batch_size = input->dims->data[0];
  const int num_filters = weights_feature->dims->data[0];
  TF_LITE_ENSURE(xk, rank != 0);
  TF_LITE_ENSURE_EQ(xk, num_filters % rank, 0);
  const int num_units = num_filters / rank;
  const int memory_size = weights_time->dims->data[1];
  TF_LITE_ENSURE_EQ(xk, input->dims->data[1],
                    weights_feature->dims->data[1]);
  TF_LITE_ENSURE_EQ(xk, weights_time->dims->data[0], num_filters);

  const TfLiteTensor* bias = GetOptionalInputTensor(xk, zn, kBiasTensor);
  if (bias) {
    TF_LITE_ENSURE_EQ(xk, bias->dims->data[0], num_units);
  }

  const TfLiteTensor* state;
  TF_LITE_ENSURE_OK(xk, GetInputSafe(xk, zn, kStateTensor, &state));
  TfLiteTensor* output;
  TF_LITE_ENSURE_OK(xk,
                    GetOutputSafe(xk, zn, kOutputTensor, &output));


  TF_LITE_ENSURE_EQ(xk, NumDimensions(state), 2);
  TF_LITE_ENSURE_EQ(xk, SizeOfDimension(state, 0), batch_size);
  TF_LITE_ENSURE_EQ(xk, SizeOfDimension(state, 1),
                    memory_size * num_filters);


  TfLiteIntArray* output_size_array = TfLiteIntArrayCreate(2);
  output_size_array->data[0] = batch_size;
  output_size_array->data[1] = num_units;
  TF_LITE_ENSURE_OK(xk,
                    xk->ResizeTensor(xk, output, output_size_array));


  const bool is_hybrid_op = IsHybridOp(input, weights_feature);
  const bool is_full_integer = input->type == kTfLiteInt8;


  TfLiteIntArrayFree(zn->temporaries);
  if (is_hybrid_op) {
    zn->temporaries = TfLiteIntArrayCreate(6);
  } else if (is_full_integer) {
    zn->temporaries = TfLiteIntArrayCreate(2);
  } else {
    zn->temporaries = TfLiteIntArrayCreate(1);
  }
  zn->temporaries->data[0] = scratch_tensor_index;

  TfLiteIntArray* scratch_size_array = TfLiteIntArrayCreate(2);
  scratch_size_array->data[0] = batch_size;
  scratch_size_array->data[1] = num_filters;

  TfLiteTensor* scratch_tensor;
  TF_LITE_ENSURE_OK(
      xk, GetTemporarySafe(xk, zn, 0, &scratch_tensor));



  if (is_full_integer) {
    scratch_tensor->type = kTfLiteInt32;
  } else {
    scratch_tensor->type = kTfLiteFloat32;
  }
  scratch_tensor->allocation_type = kTfLiteArenaRw;
  TF_LITE_ENSURE_OK(xk, xk->ResizeTensor(xk, scratch_tensor,
                                                   scratch_size_array));

  if (is_hybrid_op) {
    op_data->compute_row_sums = true;


    zn->temporaries->data[1] = scratch_tensor_index + 1;
    TfLiteTensor* input_quantized;
    TF_LITE_ENSURE_OK(xk, GetTemporarySafe(xk, zn, 1,
                                                &input_quantized));
    input_quantized->type = weights_feature->type;
    input_quantized->allocation_type = kTfLiteArenaRw;
    if (!TfLiteIntArrayEqual(input_quantized->dims, input->dims)) {
      TfLiteIntArray* input_quantized_size = TfLiteIntArrayCopy(input->dims);
      TF_LITE_ENSURE_OK(xk, xk->ResizeTensor(xk, input_quantized,
                                                       input_quantized_size));
    }


    zn->temporaries->data[2] = scratch_tensor_index + 2;
    TfLiteTensor* scaling_factors;
    TF_LITE_ENSURE_OK(xk, GetTemporarySafe(xk, zn, 2,
                                                &scaling_factors));
    scaling_factors->type = kTfLiteFloat32;
    scaling_factors->allocation_type = kTfLiteArenaRw;
    int scaling_dims[1] = {batch_size};
    if (!TfLiteIntArrayEqualsArray(scaling_factors->dims, 1, scaling_dims)) {
      TfLiteIntArray* scaling_factors_size = TfLiteIntArrayCreate(1);
      scaling_factors_size->data[0] = batch_size;
      TF_LITE_ENSURE_OK(xk, xk->ResizeTensor(xk, scaling_factors,
                                                       scaling_factors_size));
    }



    zn->temporaries->data[3] = scratch_tensor_index + 3;
    TfLiteTensor* float_weights_time;
    TF_LITE_ENSURE_OK(xk, GetTemporarySafe(xk, zn, 3,
                                                &float_weights_time));
    float_weights_time->type = kTfLiteFloat32;

    float_weights_time->allocation_type = kTfLiteArenaRwPersistent;
    if (!TfLiteIntArrayEqual(float_weights_time->dims, weights_time->dims)) {
      TfLiteIntArray* float_weights_time_size =
          TfLiteIntArrayCopy(weights_time->dims);
      TF_LITE_ENSURE_OK(xk,
                        xk->ResizeTensor(xk, float_weights_time,
                                              float_weights_time_size));
    }

    zn->temporaries->data[4] = scratch_tensor_index + 4;
    TfLiteTensor* zero_points;
    TF_LITE_ENSURE_OK(
        xk, GetTemporarySafe(xk, zn, 4, &zero_points));
    zero_points->type = kTfLiteFloat32;
    zero_points->allocation_type = kTfLiteArenaRw;
    int zero_points_dims[1] = {batch_size};
    if (!TfLiteIntArrayEqualsArray(zero_points->dims, 1, zero_points_dims)) {
      TfLiteIntArray* zero_points_size = TfLiteIntArrayCreate(1);
      zero_points_size->data[0] = zero_points_dims[0];
      TF_LITE_ENSURE_OK(xk, xk->ResizeTensor(xk, zero_points,
                                                       zero_points_size));
    }

    zn->temporaries->data[5] = scratch_tensor_index + 5;
    TfLiteTensor* row_sums;
    TF_LITE_ENSURE_OK(xk,
                      GetTemporarySafe(xk, zn, 5, &row_sums));
    row_sums->type = kTfLiteFloat32;
    row_sums->allocation_type = kTfLiteArenaRwPersistent;
    int row_sums_dims[1] = {num_filters};
    if (!TfLiteIntArrayEqualsArray(row_sums->dims, 1, row_sums_dims)) {
      TfLiteIntArray* row_sums_size = TfLiteIntArrayCreate(1);
      row_sums_size->data[0] = row_sums_dims[0];
      TF_LITE_ENSURE_OK(
          xk, xk->ResizeTensor(xk, row_sums, row_sums_size));
    }
  }
  if (is_full_integer) {

    TfLiteIntArray* output_temp_size_array = TfLiteIntArrayCreate(2);
    output_temp_size_array->data[0] = num_units;
    output_temp_size_array->data[1] = batch_size;
    zn->temporaries->data[1] = scratch_tensor_index + 1;
    TfLiteTensor* output_temp;
    TF_LITE_ENSURE_OK(
        xk, GetTemporarySafe(xk, zn, 1, &output_temp));
    output_temp->type = kTfLiteInt32;
    output_temp->allocation_type = kTfLiteArenaRw;
    TF_LITE_ENSURE_OK(xk, xk->ResizeTensor(xk, output_temp,
                                                     output_temp_size_array));


    auto* input_params =
        reinterpret_cast<TfLiteAffineQuantization*>(input->quantization.params);
    auto* weights_feature_params = reinterpret_cast<TfLiteAffineQuantization*>(
        weights_feature->quantization.params);
    auto* state_params =
        reinterpret_cast<TfLiteAffineQuantization*>(state->quantization.params);
    auto* weight_time_params = reinterpret_cast<TfLiteAffineQuantization*>(
        weights_time->quantization.params);
    auto* output_params = reinterpret_cast<TfLiteAffineQuantization*>(
        output->quantization.params);
    const double effective_scale_1 = input_params->scale->data[0] *
                                     weights_feature_params->scale->data[0] /
                                     state_params->scale->data[0];
    const double effective_scale_2 = state_params->scale->data[0] *
                                     weight_time_params->scale->data[0] /
                                     output_params->scale->data[0];
    QuantizeMultiplier(effective_scale_1, &op_data->effective_scale_1_a,
                       &op_data->effective_scale_1_b);
    QuantizeMultiplier(effective_scale_2, &op_data->effective_scale_2_a,
                       &op_data->effective_scale_2_b);
  }
  return kTfLiteOk;
}

