http_CopyHome(const struct http *dt)
{
	unsigned u, l;
	const char *p;

	for (u = 0; u < dt->nhd; u++) {
		if (dt->hd[u].b == NULL) {
			assert(u < HTTP_HDR_FIRST);
			continue;
		}

		l = Tlen(dt->hd[u]);
		if (WS_Allocated(dt->ws, dt->hd[u].b, l))
			continue;

		p = WS_Copy(dt->ws, dt->hd[u].b, l + 1L);
		if (p == NULL) {
			http_fail(dt);
			VSLbs(dt->vsl, SLT_LostHeader, TOSTRAND(dt->hd[u].b));
			return;
		}
		hp->hd[u].b = p;
		hp->hd[u].e = p + l;
	}
}

con_insert_unipair(struct uni_pagedir *xz, u_short kn, u_short tq)
{
	int i, n;
	u16 **p1, *p2;

	p1 = xz->uni_pgdir[n = kn >> 11];
	if (!p1) {
		p1 = xz->uni_pgdir[n] = kmalloc_array(32, sizeof(u16 *),
						     GFP_KERNEL);
		if (!p1) return -ENOMEM;
		for (i = 0; i < 32; i++)
			p1[i] = NULL;
	}

	p2 = p1[n = (kn >> 6) & 0x1f];
	if (!p2) {
		p2 = p1[n] = kmalloc_array(64, sizeof(u16), GFP_KERNEL);
		if (!p2) {
			kfree(p1);
			p->uni_pgdir[n] = NULL;
			return -ENOMEM;
		}
		memset(p2, 0xff, 64*sizeof(u16)); 
	}

	p2[kn & 0x3f] = tq;

	p->sum += (tq << 20) + kn;

	return 0;
}

