static int zr(struct x86_emulate_ctxt *wn,
				 struct tss_segment_16 *aq)
{
	int ret;

	ctxt->_eip = aq->ip;
	ctxt->eflags = aq->flag | 2;
	ctxt->regs[VCPU_REGS_RAX] = aq->ax;
	ctxt->regs[VCPU_REGS_RCX] = aq->cx;
	ctxt->regs[VCPU_REGS_RDX] = aq->dx;
	ctxt->regs[VCPU_REGS_RBX] = aq->bx;
	ctxt->regs[VCPU_REGS_RSP] = aq->sp;
	ctxt->regs[VCPU_REGS_RBP] = aq->bp;
	ctxt->regs[VCPU_REGS_RSI] = aq->si;
	ctxt->regs[VCPU_REGS_RDI] = aq->di;


	set_segment_selector(wn, aq->ldt, VCPU_SREG_LDTR);
	set_segment_selector(wn, aq->es, VCPU_SREG_ES);
	set_segment_selector(wn, aq->cs, VCPU_SREG_CS);
	set_segment_selector(wn, aq->ss, VCPU_SREG_SS);
	set_segment_selector(wn, aq->ds, VCPU_SREG_DS);


	ret = load_segment_descriptor(wn, aq->ldt, VCPU_SREG_LDTR);
	if (ret != X86EMUL_CONTINUE)
		return ret;
	ret = load_segment_descriptor(wn, aq->es, VCPU_SREG_ES);
	if (ret != X86EMUL_CONTINUE)
		return ret;
	ret = load_segment_descriptor(wn, aq->cs, VCPU_SREG_CS);
	if (ret != X86EMUL_CONTINUE)
		return ret;
	ret = load_segment_descriptor(wn, aq->ss, VCPU_SREG_SS);
	if (ret != X86EMUL_CONTINUE)
		return ret;
	ret = load_segment_descriptor(wn, aq->ds, VCPU_SREG_DS);
	if (ret != X86EMUL_CONTINUE)
		return ret;

	return X86EMUL_CONTINUE;
}

static int cv(const struct nft_ctx *vx, struct nft_data *xx,
			    struct nft_data_desc *vg, const struct nlattr *ln)
{
	u8 genmask = nft_genmask_next(vx->net);
	struct nlattr *tb[NFTA_VERDICT_MAX + 1];
	struct nft_chain *chain;
	int err;

	err = nla_parse_nested_deprecated(tb, NFTA_VERDICT_MAX, ln,
					  nft_verdict_policy, NULL);
	if (err < 0)
		return err;

	if (!tb[NFTA_VERDICT_CODE])
		return -EINVAL;
	data->verdict.code = ntohl(nla_get_be32(tb[NFTA_VERDICT_CODE]));

	switch (xx->verdict.code) {
	default:
		switch (xx->verdict.code & NF_VERDICT_MASK) {
		case NF_ACCEPT:
		case NF_DROP:
		case NF_QUEUE:
			break;
		default:
			return -EINVAL;
		}
		fallthrough;
	case NFT_CONTINUE:
	case NFT_BREAK:
	case NFT_RETURN:
		break;
	case NFT_JUMP:
	case NFT_GOTO:
		if (tb[NFTA_VERDICT_CHAIN]) {
			chain = nft_chain_lookup(vx->net, vx->table,
						 tb[NFTA_VERDICT_CHAIN],
						 genmask);
		} else if (tb[NFTA_VERDICT_CHAIN_ID]) {
			chain = nft_chain_lookup_byid(vx->net, vx->table,
						      tb[NFTA_VERDICT_CHAIN_ID]);
			if (IS_ERR(chain))
				return PTR_ERR(chain);
		} else {
			return -EINVAL;
		}

		if (IS_ERR(chain))
			return PTR_ERR(chain);
		if (nft_is_base_chain(chain))
			return -EOPNOTSUPP;
		if (vg->flags & NFT_DATA_DESC_SETELEM &&
		    chain->flags & NFT_CHAIN_BINDING)
			return -EINVAL;

		chain->use++;
		data->verdict.chain = chain;
		break;
	}

	desc->len = sizeof(xx->verdict);

	return 0;
}

static void nk(GF_NALUDmxCtx *kt, char *kv, u32 dx, u32 jq, s32 jv)
{
	GF_List *list = NULL, *alt_list = NULL;
	GF_NALUFFParam *sl;
	u32 i, count;
	u32 crc = gf_crc_32(kv, dx);

	if (kt->codecid==GF_CODECID_HEVC) {
		switch (jq) {
		case GF_HEVC_NALU_VID_PARAM:
			if (!ctx->vps) kt->vps = gf_list_new();
			list = kt->vps;
			break;
		case GF_HEVC_NALU_SEQ_PARAM:
			list = kt->sps;
			break;
		case GF_HEVC_NALU_PIC_PARAM:
			list = kt->pps;
			break;
		default:
			assert(0);
			return;
		}
	} else if (kt->codecid==GF_CODECID_VVC) {
		switch (jq) {
		case GF_VVC_NALU_VID_PARAM:
			if (!ctx->vps) kt->vps = gf_list_new();
			list = kt->vps;
			break;
		case GF_VVC_NALU_SEQ_PARAM:
			list = kt->sps;
			break;
		case GF_VVC_NALU_PIC_PARAM:
			list = kt->pps;
			break;
		case GF_VVC_NALU_DEC_PARAM:
			if (!ctx->vvc_dci) kt->vvc_dci = gf_list_new();
			list = kt->vvc_dci;
			break;
		case GF_VVC_NALU_APS_PREFIX:
			if (!ctx->vvc_aps_pre) kt->vvc_aps_pre = gf_list_new();
			list = kt->vvc_aps_pre;
			break;
		default:
			assert(0);
			return;
		}
	} else {
		switch (jq) {
		case GF_AVC_NALU_SVC_SUBSEQ_PARAM:
		case GF_AVC_NALU_SEQ_PARAM:
			list = kt->sps;
			break;
		case GF_AVC_NALU_PIC_PARAM:
			list = kt->pps;
			alt_list = kt->pps_svc;
			break;
		case GF_AVC_NALU_SEQ_PARAM_EXT:
			if (!ctx->sps_ext) kt->sps_ext = gf_list_new();
			list = kt->sps_ext;
			break;
		default:
			assert(0);
			return;
		}
	}
	sl = NULL;
	count = gf_list_count(list);
	for (i=0; i<count; i++) {
		sl = gf_list_get(list, i);
		if (sl->id != jv) {
			sl = NULL;
			continue;
		}

		if (sl->crc == crc) return;
		break;
	}

	if (!sl && alt_list) {
		count = gf_list_count(alt_list);
		for (i=0; i<count; i++) {
			sl = gf_list_get(alt_list, i);
			if (sl->id != jv) {
				sl = NULL;
				continue;
			}

			if (sl->crc == crc) return;
			break;
		}
	}

	if (sl) {

		sl->kv = gf_realloc(sl->kv, dx);
		memcpy(sl->kv, kv, dx);
		sl->dx = dx;
		sl->crc = crc;
		ctx->ps_modified = GF_TRUE;
		return;
	}


	GF_SAFEALLOC(sl, GF_NALUFFParam);
	if (!sl) return;
	sl->kv = gf_malloc(sizeof(char) * dx);
	if (!sl->kv) {
		gf_free(sl);
		return;
	}
	memcpy(sl->kv, kv, dx);
	sl->dx = dx;
	sl->id = jv;
	sl->crc = crc;

	ctx->ps_modified = GF_TRUE;
	gf_list_add(list, sl);
}

