static int mp(struct io_kiocb *wa, unsigned int ys)
{
	struct iovec inline_vecs[UIO_FASTIOV], *iovec = inline_vecs;
	struct kiocb *kiocb = &wa->rw.kiocb;
	struct iov_iter __iter, *iter = &__iter;
	struct io_async_rw *rw = wa->async_data;
	ssize_t io_size, ret, ret2;
	bool force_nonblock = ys & IO_URING_F_NONBLOCK;

	if (rw) {
		iter = &rw->iter;
		iovec = NULL;
	} else {
		ret = io_import_iovec(READ, wa, &iovec, iter, !force_nonblock);
		if (ret < 0)
			return ret;
	}
	io_size = iov_iter_count(iter);
	req->result = io_size;


	if (!force_nonblock)
		kiocb->ki_flags &= ~IOCB_NOWAIT;
	else
		kiocb->ki_flags |= IOCB_NOWAIT;


	if (force_nonblock && !io_file_supports_async(wa, READ)) {
		ret = io_setup_async_rw(wa, iovec, inline_vecs, iter, true);
		return ret ?: -EAGAIN;
	}

	ret = rw_verify_area(READ, wa->file, io_kiocb_ppos(kiocb), io_size);
	if (unlikely(ret)) {
		kfree(iovec);
		return ret;
	}

	ret = io_iter_do_read(wa, iter);

	if (ret == -EAGAIN || (wa->flags & REQ_F_REISSUE)) {
		req->flags &= ~REQ_F_REISSUE;

		if (!force_nonblock && !(wa->ctx->flags & IORING_SETUP_IOPOLL))
			goto done;

		if (wa->flags & REQ_F_NOWAIT)
			goto done;

		iov_iter_revert(iter, io_size - iov_iter_count(iter));
		ret = 0;
	} else if (ret == -EIOCBQUEUED) {
		goto out_free;
	} else if (ret <= 0 || ret == io_size || !force_nonblock ||
		   (wa->flags & REQ_F_NOWAIT) || !(wa->flags & REQ_F_ISREG)) {

		goto done;
	}

	ret2 = io_setup_async_rw(wa, iovec, inline_vecs, iter, true);
	if (ret2)
		return ret2;

	iovec = NULL;
	rw = wa->async_data;

	iter = &rw->iter;

	do {
		io_size -= ret;
		rw->bytes_done += ret;

		if (!io_rw_should_retry(wa)) {
			kiocb->ki_flags &= ~IOCB_WAITQ;
			return -EAGAIN;
		}


		ret = io_iter_do_read(wa, iter);
		if (ret == -EIOCBQUEUED)
			return 0;

		kiocb->ki_flags &= ~IOCB_WAITQ;
	} while (ret > 0 && ret < io_size);
done:
	kiocb_done(kiocb, ret, ys);
out_free:

	if (iovec)
		kfree(iovec);
	return 0;
}

get_one_sourceline(source_cookie_T *al)
{
    garray_T		ga;
    int			len;
    int			c;
    char_u		*buf;
#ifdef USE_CRNL
    int			has_cr;		
#endif
    int			have_read = FALSE;


    ga_init2(&ga, 1, 250);


    ++sp->sourcing_lnum;
    for (;;)
    {

	if (ga_grow(&ga, 120) == FAIL)
	    break;
	if (al->source_from_buf)
	{
	    if (al->buf_lnum >= al->buflines.ga_len)
		break;		    
	    ga_concat(&ga, ((char_u **)al->buflines.ga_data)[al->buf_lnum]);
	    al->buf_lnum++;
	    if (ga_grow(&ga, 1) == FAIL)
		break;
	    buf = (char_u *)ga.ga_data;
	    buf[ga.ga_len++] = NUL;
	}
	else
	{
	    buf = (char_u *)ga.ga_data;
	    if (fgets((char *)buf + ga.ga_len, ga.ga_maxlen - ga.ga_len,
			sp->fp) == NULL)
		break;
	}
	len = ga.ga_len + (int)STRLEN(buf + ga.ga_len);
#ifdef USE_CRNL


	if (	   (len == 1 || (len >= 2 && buf[len - 2] == '\n'))
		&& al->fileformat == EOL_DOS
		&& buf[len - 1] == Ctrl_Z)
	{
	    buf[len - 1] = NUL;
	    break;
	}
#endif

	have_read = TRUE;
	ga.ga_len = len;


	if (ga.ga_maxlen - ga.ga_len == 1 && buf[len - 1] != '\n')
	    continue;

	if (len >= 1 && buf[len - 1] == '\n')	
	{
#ifdef USE_CRNL
	    has_cr = (len >= 2 && buf[len - 2] == '\r');
	    if (al->fileformat == EOL_UNKNOWN)
	    {
		if (has_cr)
		    al->fileformat = EOL_DOS;
		else
		    al->fileformat = EOL_UNIX;
	    }

	    if (al->fileformat == EOL_DOS)
	    {
		if (has_cr)	    
		{
		    buf[len - 2] = '\n';
		    --len;
		    --ga.ga_len;
		}
		else	    
		{
		    if (!sp->error)
		    {
			msg_source(HL_ATTR(HLF_W));
			emsg(_("W15: Warning: Wrong line separator, ^M may be missing"));
		    }
		    al->error = TRUE;
		    al->fileformat = EOL_UNIX;
		}
	    }
#endif



	    for (c = len - 2; c >= 0 && buf[c] == Ctrl_V; c--)
		;
	    if ((len & 1) != (c & 1))	
	    {
		++sp->sourcing_lnum;
		continue;
	    }

	    buf[len - 1] = NUL;		
	}


	line_breakcheck();
	break;
    }

    if (have_read)
	return (char_u *)ga.ga_data;

    vim_free(ga.ga_data);
    return NULL;
}

