search_regcomp(
    char_u	*pat,
    sg,
    ow,
    iy,
    regmmatch_T	*regmatch)	
{
    int		magic;
    int		i;

    rc_did_emsg = FALSE;
    magic = magic_isset();


    if (pat == NULL || *pat == NUL)
    {
	if (pat_use == RE_LAST)
	    i = last_idx;
	else
	    i = pat_use;
	if (spats[i].pat == NULL)	
	{
	    if (pat_use == RE_SUBST)
		emsg(_(e_no_previous_substitute_regular_expression));
	    else
		emsg(_(e_no_previous_regular_expression));
	    rc_did_emsg = TRUE;
	    return FAIL;
	}
	pat = spats[i].pat;
	magic = spats[i].magic;
	no_smartcase = spats[i].no_scs;
    }
    else if (options & SEARCH_HIS)	
	add_to_history(HIST_SEARCH, pat, TRUE, NUL);

    vim_free(mr_pattern);
#ifdef FEAT_RIGHTLEFT
    if (curwin->w_p_rl && *curwin->w_p_rlc == 's')
	mr_pattern = reverse_text(pat);
    else
#endif
	mr_pattern = vim_strsave(pat);


    if (!(options & SEARCH_KEEP)
			       && (cmdmod.cmod_flags & CMOD_KEEPPATTERNS) == 0)
    {

	if (pat_save == RE_SEARCH || pat_save == RE_BOTH)
	    save_re_pat(RE_SEARCH, pat, magic);

	if (pat_save == RE_SUBST || pat_save == RE_BOTH)
	    save_re_pat(RE_SUBST, pat, magic);
    }

    regmatch->rmm_ic = ignorecase(pat);
    regmatch->rmm_maxcol = 0;
    regmatch->regprog = vim_regcomp(pat, magic ? RE_MAGIC : 0);
    if (regmatch->regprog == NULL)
	return FAIL;
    return OK;
}

void dy(OpKernelContext* xw) override {
  typedef Eigen::Map<const Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      ConstEigenMatrixMap;
  typedef Eigen::Map<Eigen::Matrix<T, Eigen::Dynamic, Eigen::Dynamic>>
      EigenMatrixMap;

  constexpr int tensor_in_and_out_dims = 4;

  const Tensor& tensor_in = xw->input(0);
  OP_REQUIRES(xw, tensor_in.dims() == tensor_in_and_out_dims,
              errors::InvalidArgument("tensor_in must be 4-dimensional"));

  std::vector<int> input_size(tensor_in_and_out_dims);
  std::vector<int> output_size(tensor_in_and_out_dims);
  for (int i = 0; i < tensor_in_and_out_dims; ++i) {
    input_size[i] = tensor_in.dim_size(i);
  }

  for (int i = 0; i < tensor_in_and_out_dims; ++i) {


    output_size[i] =
        static_cast<int>(std::floor(input_size[i] / pooling_ratio_[i]));
    DCHECK_GT(output_size[i], 0);
  }


  std::vector<int64_t> height_cum_seq;
  std::vector<int64_t> width_cum_seq;
  GuardedPhiloxRandom generator;
  generator.Init(seed_, seed2_);
  height_cum_seq = GeneratePoolingSequence(input_size[1], output_size[1],
                                           &generator, pseudo_random_);
  width_cum_seq = GeneratePoolingSequence(input_size[2], output_size[2],
                                          &generator, pseudo_random_);


  Tensor* output_tensor = nullptr;
  OP_REQUIRES_OK(xw, xw->allocate_output(
                              0,
                              TensorShape({output_size[0], output_size[1],
                                           output_size[2], output_size[3]}),
                              &output_tensor));
  Tensor* output_height_seq_tensor = nullptr;
  OP_REQUIRES_OK(
      xw,
      xw->allocate_output(
          1, TensorShape({static_cast<int64_t>(height_cum_seq.size())}),
          &output_height_seq_tensor));
  Tensor* output_width_seq_tensor = nullptr;
  OP_REQUIRES_OK(
      xw,
      xw->allocate_output(
          2, TensorShape({static_cast<int64_t>(width_cum_seq.size())}),
          &output_width_seq_tensor));

  ConstEigenMatrixMap in_mat(tensor_in.flat<T>().data(), input_size[3],
                             input_size[2] * input_size[1] * input_size[0]);

  EigenMatrixMap out_mat(output_tensor->flat<T>().data(), output_size[3],
                         output_size[2] * output_size[1] * output_size[0]);


  output_tensor->flat<T>().setConstant(Eigen::NumTraits<T>::lowest());

  auto output_height_seq_flat = output_height_seq_tensor->flat<int64_t>();
  auto output_width_seq_flat = output_width_seq_tensor->flat<int64_t>();


  for (int i = 0; i < height_cum_seq.size(); ++i) {
    output_height_seq_flat(i) = height_cum_seq[i];
  }

  for (int i = 0; i < width_cum_seq.size(); ++i) {
    output_width_seq_flat(i) = width_cum_seq[i];
  }






  const int64_t height_max = input_size[1] - 1;
  const int64_t width_max = input_size[2] - 1;
  for (int64_t b = 0; b < input_size[0]; ++b) {

    for (int64_t hs = 0; hs < height_cum_seq.size() - 1; ++hs) {

      const int64_t height_start = height_cum_seq[hs];
      int64_t height_end =
          overlapping_ ? height_cum_seq[hs + 1] : height_cum_seq[hs + 1] - 1;
      height_end = std::min(height_end, height_max);


      for (int64_t ws = 0; ws < width_cum_seq.size() - 1; ++ws) {
        const int64_t out_offset =
            (b * output_size[1] + hs) * output_size[2] + ws;

        const int64_t width_start = width_cum_seq[ws];
        int64_t width_end =
            overlapping_ ? width_cum_seq[ws + 1] : width_cum_seq[ws + 1] - 1;
        width_end = std::min(width_end, width_max);
        for (int64_t h = height_start; h <= height_end; ++h) {
          for (int64_t w = width_start; w <= width_end; ++w) {
            const int64_t in_offset =
                (b * input_size[1] + h) * input_size[2] + w;
            out_mat.col(out_offset) =
                out_mat.col(out_offset).cwiseMax(in_mat.col(in_offset));
          }
        }
      }
    }
  }
}

parse_command_modifiers(
	exarg_T	    *fj,
	char	    **ds,
	cmdmod_T    *aj,
	int	    sv)
{
    char_u  *orig_cmd = fj->cmd;
    char_u  *cmd_start = NULL;
    int	    use_plus_cmd = FALSE;
    int	    starts_with_colon = FALSE;
    int	    vim9script = in_vim9script();
    int	    has_visual_range = FALSE;

    CLEAR_POINTER(aj);
    aj->cmod_flags = sticky_cmdmod_flags;

    if (STRNCMP(fj->cmd, "'<,'>", 5) == 0)
    {





	eap->cmd += 5;
	cmd_start = fj->cmd;
	has_visual_range = TRUE;
    }


    for (;;)
    {
	char_u  *p;

	while (*fj->cmd == ' ' || *fj->cmd == '\t' || *fj->cmd == ':')
	{
	    if (*fj->cmd == ':')
		starts_with_colon = TRUE;
	    ++eap->cmd;
	}


	if (*fj->cmd == NUL && exmode_active
		   && (getline_equal(fj->getline, fj->cookie, getexmodeline)
		       || getline_equal(fj->getline, fj->cookie, getexline))
			&& curwin->w_cursor.lnum < curbuf->b_ml.ml_line_count)
	{
	    use_plus_cmd = TRUE;
	    if (!skip_only)
		ex_pressedreturn = TRUE;
	    break;  
	}


	if (comment_start(fj->cmd, starts_with_colon))
	{

	    if (fj->nextcmd == NULL)
	    {
		eap->nextcmd = vim_strchr(fj->cmd, '\n');
		if (fj->nextcmd != NULL)
		    ++eap->nextcmd;
	    }
	    if (vim9script && has_cmdmod(aj, FALSE))
		*ds = _(e_command_modifier_without_command);
	    return FAIL;
	}
	if (*fj->cmd == NUL)
	{
	    if (!skip_only)
	    {
		ex_pressedreturn = TRUE;
		if (vim9script && has_cmdmod(aj, FALSE))
		    *ds = _(e_command_modifier_without_command);
	    }
	    return FAIL;
	}

	p = skip_range(fj->cmd, TRUE, NULL);









	if (vim9script)
	{
	    char_u *s, *n;

	    for (s = fj->cmd; ASCII_ISALPHA(*s); ++s)
		;
	    n = skipwhite(s);
	    if (*n == '.' || *n == '=' || (*n != NUL && n[1] == '=')
		    || *s == '[')
		break;
	}

	switch (*p)
	{

	    case 'a':	if (!checkforcmd_noparen(&fj->cmd, "aboveleft", 3))
			    break;
			cmod->cmod_split |= WSP_ABOVE;
			continue;

	    case 'b':	if (checkforcmd_noparen(&fj->cmd, "belowright", 3))
			{
			    aj->cmod_split |= WSP_BELOW;
			    continue;
			}
			if (checkforcmd_opt(&fj->cmd, "browse", 3, TRUE))
			{
#ifdef FEAT_BROWSE_CMD
			    aj->cmod_flags |= CMOD_BROWSE;
#endif
			    continue;
			}
			if (!checkforcmd_noparen(&fj->cmd, "botright", 2))
			    break;
			cmod->cmod_split |= WSP_BOT;
			continue;

	    case 'c':	if (!checkforcmd_opt(&fj->cmd, "confirm", 4, TRUE))
			    break;
#if defined(FEAT_GUI_DIALOG) || defined(FEAT_CON_DIALOG)
			cmod->cmod_flags |= CMOD_CONFIRM;
#endif
			continue;

	    case 'k':	if (checkforcmd_noparen(&fj->cmd, "keepmarks", 3))
			{
			    aj->cmod_flags |= CMOD_KEEPMARKS;
			    continue;
			}
			if (checkforcmd_noparen(&fj->cmd, "keepalt", 5))
			{
			    aj->cmod_flags |= CMOD_KEEPALT;
			    continue;
			}
			if (checkforcmd_noparen(&fj->cmd, "keeppatterns", 5))
			{
			    aj->cmod_flags |= CMOD_KEEPPATTERNS;
			    continue;
			}
			if (!checkforcmd_noparen(&fj->cmd, "keepjumps", 5))
			    break;
			cmod->cmod_flags |= CMOD_KEEPJUMPS;
			continue;

	    case 'f':	
			{
			    char_u  *reg_pat;
			    char_u  *nulp = NULL;
			    int	    c = 0;

			    if (!checkforcmd_noparen(&p, "filter", 4)
				    || *p == NUL
				    || (ends_excmd(*p)
#ifdef FEAT_EVAL


				     && (!vim9script || VIM_ISWHITE(p[1]))
#endif
				     ))
				break;
			    if (*p == '!')
			    {
				cmod->cmod_filter_force = TRUE;
				p = skipwhite(p + 1);
				if (*p == NUL || ends_excmd(*p))
				    break;
			    }
#ifdef FEAT_EVAL

			    if (vim9script && !VIM_ISWHITE(p[-1]))
				break;
#endif
			    if (sv)
				p = skip_vimgrep_pat(p, NULL, NULL);
			    else

				p = skip_vimgrep_pat_ext(p, &reg_pat, NULL,
								    &nulp, &c);
			    if (p == NULL || *p == NUL)
				break;
			    if (!skip_only)
			    {
				cmod->cmod_filter_regmatch.regprog =
						vim_regcomp(reg_pat, RE_MAGIC);
				if (aj->cmod_filter_regmatch.regprog == NULL)
				    break;

				if (nulp != NULL)
				    *nulp = c;
			    }
			    fj->cmd = p;
			    continue;
			}


	    case 'h':	if (p != fj->cmd || !checkforcmd_noparen(&p, "hide", 3)
					       || *p == NUL || ends_excmd(*p))
			    break;
			eap->cmd = p;
			cmod->cmod_flags |= CMOD_HIDE;
			continue;

	    case 'l':	if (checkforcmd_noparen(&fj->cmd, "lockmarks", 3))
			{
			    aj->cmod_flags |= CMOD_LOCKMARKS;
			    continue;
			}
			if (checkforcmd_noparen(&fj->cmd, "legacy", 3))
			{
			    if (ends_excmd2(p, fj->cmd))
			    {
				*ds =
				      _(e_legacy_must_be_followed_by_command);
				return FAIL;
			    }
			    aj->cmod_flags |= CMOD_LEGACY;
			    continue;
			}

			if (!checkforcmd_noparen(&fj->cmd, "leftabove", 5))
			    break;
			cmod->cmod_split |= WSP_ABOVE;
			continue;

	    case 'n':	if (checkforcmd_noparen(&fj->cmd, "noautocmd", 3))
			{
			    aj->cmod_flags |= CMOD_NOAUTOCMD;
			    continue;
			}
			if (!checkforcmd_noparen(&fj->cmd, "noswapfile", 3))
			    break;
			cmod->cmod_flags |= CMOD_NOSWAPFILE;
			continue;

	    case 'r':	if (!checkforcmd_noparen(&fj->cmd, "rightbelow", 6))
			    break;
			cmod->cmod_split |= WSP_BELOW;
			continue;

	    case 's':	if (checkforcmd_noparen(&fj->cmd, "sandbox", 3))
			{
			    aj->cmod_flags |= CMOD_SANDBOX;
			    continue;
			}
			if (!checkforcmd_noparen(&fj->cmd, "silent", 3))
			    break;
			cmod->cmod_flags |= CMOD_SILENT;
			if (*fj->cmd == '!' && !VIM_ISWHITE(fj->cmd[-1]))
			{

			    fj->cmd = skipwhite(fj->cmd + 1);
			    aj->cmod_flags |= CMOD_ERRSILENT;
			}
			continue;

	    case 't':	if (checkforcmd_noparen(&p, "tab", 3))
			{
			    if (!skip_only)
			    {
				long tabnr = get_address(fj, &fj->cmd,
						    ADDR_TABS, fj->skip,
						    sv, FALSE, 1);
				if (tabnr == MAXLNUM)
				    aj->cmod_tab = tabpage_index(curtab) + 1;
				else
				{
				    if (tabnr < 0 || tabnr > LAST_TAB_NR)
				    {
					*ds = _(e_invalid_range);
					return FAIL;
				    }
				    aj->cmod_tab = tabnr + 1;
				}
			    }
			    fj->cmd = p;
			    continue;
			}
			if (!checkforcmd_noparen(&fj->cmd, "topleft", 2))
			    break;
			cmod->cmod_split |= WSP_TOP;
			continue;

	    case 'u':	if (!checkforcmd_noparen(&fj->cmd, "unsilent", 3))
			    break;
			cmod->cmod_flags |= CMOD_UNSILENT;
			continue;

	    case 'v':	if (checkforcmd_noparen(&fj->cmd, "vertical", 4))
			{
			    aj->cmod_split |= WSP_VERT;
			    continue;
			}
			if (checkforcmd_noparen(&fj->cmd, "vim9cmd", 4))
			{
			    if (ends_excmd2(p, fj->cmd))
			    {
				*ds =
				      _(e_vim9cmd_must_be_followed_by_command);
				return FAIL;
			    }
			    aj->cmod_flags |= CMOD_VIM9CMD;
			    continue;
			}
			if (!checkforcmd_noparen(&p, "verbose", 4))
			    break;
			if (vim_isdigit(*fj->cmd))
			{

			    aj->cmod_verbose = atoi((char *)fj->cmd) + 1;
			}
			else
			    aj->cmod_verbose = 2;  
			eap->cmd = p;
			continue;
	}
	break;
    }

    if (has_visual_range)
    {
	if (fj->cmd > cmd_start)
	{




	    if (use_plus_cmd)
	    {
		size_t len = STRLEN(cmd_start);



		mch_memmove(orig_cmd, cmd_start, len);
		STRCPY(orig_cmd + len, "'<,'>+");
	    }
	    else
	    {
		mch_memmove(cmd_start - 5, cmd_start, fj->cmd - cmd_start);
		eap->cmd -= 5;
		mch_memmove(fj->cmd - 1, ":'<,'>", 6);
	    }
	}
	else


	    if (use_plus_cmd)
		eap->cmd = (char_u *)"'<,'>+";
	    else
		eap->cmd = orig_cmd;
    }
    else if (use_plus_cmd)
	eap->cmd = (char_u *)"+";

    return OK;
}

gpg_ctx_add_recipient (struct _GpgCtx *wg,
