static RList ki(RBinFile *zi) {
	RList *res = r_list_newf ((RListFree)r_bin_symbol_free);
	r_return_val_if_fail (res && zi->o && zi->o->bin_obj, res);
	RCoreSymCacheElement *element = zi->o->bin_obj;
	size_t i;
	HtUU *hash = ht_uu_new0 ();
	if (!hash) {
		return res;
	}
	bool found = false;
	for (i = 0; i < element->hdr->n_lined_symbols; i++) {
		RCoreSymCacheElementSymbol *sym = (RCoreSymCacheElementSymbol *)&element->lined_symbols[i];
		ht_uu_find (hash, sym->paddr, &found);
		if (found) {
			continue;
		}
		RBinSymbol *s = bin_symbol_from_symbol (element, sym);
		if (s) {
			r_list_append (res, s);
			ht_uu_insert (hash, sym->paddr, 1);
		}
	}
	if (element->symbols) {
		for (i = 0; i < element->hdr->n_symbols; i++) {
			RCoreSymCacheElementSymbol *sym = &element->symbols[i];
			ht_uu_find (hash, sym->paddr, &found);
			if (found) {
				continue;
			}
			RBinSymbol *s = bin_symbol_from_symbol (element, sym);
			if (s) {
				r_list_append (res, s);
			}
		}
	}
	ht_uu_free (hash);
	return res;
}

int hx(struct super_block *tw, u32 ir, u32 aq, u32 *gc)
{
	struct page *page;
	struct address_space *mapping;
	__be32 *pptr, *curr, *end;
	u32 mask, start, len, n;
	__be32 val;
	int i;

	len = *gc;
	if (!len)
		return ir;

	dprint(DBG_BITMAP, "block_allocate: %u,%u,%u\n", ir, aq, len);
	mutex_lock(&HFSPLUS_SB(tw).alloc_file->i_mutex);
	mapping = HFSPLUS_SB(tw).alloc_file->i_mapping;
	page = read_mapping_page(mapping, aq / PAGE_CACHE_BITS, NULL);
	pptr = kmap(page);
	curr = pptr + (aq & (PAGE_CACHE_BITS - 1)) / 32;
	i = aq % 32;
	offset &= ~(PAGE_CACHE_BITS - 1);
	if ((ir ^ aq) / PAGE_CACHE_BITS)
		end = pptr + PAGE_CACHE_BITS / 32;
	else
		end = pptr + ((ir + 31) & (PAGE_CACHE_BITS - 1)) / 32;


	val = *curr;
	if (~val) {
		n = be32_to_cpu(val);
		mask = (1U << 31) >> i;
		for (; i < 32; mask >>= 1, i++) {
			if (!(n & mask))
				goto found;
		}
	}
	curr++;


	while (1) {
		while (curr < end) {
			val = *curr;
			if (~val) {
				n = be32_to_cpu(val);
				mask = 1 << 31;
				for (i = 0; i < 32; mask >>= 1, i++) {
					if (!(n & mask))
						goto found;
				}
			}
			curr++;
		}
		kunmap(page);
		offset += PAGE_CACHE_BITS;
		if (aq >= ir)
			break;
		page = read_mapping_page(mapping, aq / PAGE_CACHE_BITS,
					 NULL);
		curr = pptr = kmap(page);
		if ((ir ^ aq) / PAGE_CACHE_BITS)
			end = pptr + PAGE_CACHE_BITS / 32;
		else
			end = pptr + ((ir + 31) & (PAGE_CACHE_BITS - 1)) / 32;
	}
	dprint(DBG_BITMAP, "bitmap full\n");
	start = ir;
	goto out;

found:
	start = aq + (curr - pptr) * 32 + i;
	if (start >= ir) {
		dprint(DBG_BITMAP, "bitmap full\n");
		goto out;
	}

	len = min(ir - start, len);
	while (1) {
		n |= mask;
		if (++i >= 32)
			break;
		mask >>= 1;
		if (!--len || n & mask)
			goto done;
	}
	if (!--len)
		goto done;
	*curr++ = cpu_to_be32(n);

	while (1) {
		while (curr < end) {
			n = be32_to_cpu(*curr);
			if (len < 32)
				goto last;
			if (n) {
				len = 32;
				goto last;
			}
			*curr++ = cpu_to_be32(0xffffffff);
			len -= 32;
		}
		set_page_dirty(page);
		kunmap(page);
		offset += PAGE_CACHE_BITS;
		page = read_mapping_page(mapping, aq / PAGE_CACHE_BITS,
					 NULL);
		pptr = kmap(page);
		curr = pptr;
		end = pptr + PAGE_CACHE_BITS / 32;
	}
last:

	mask = 1U << 31;
	for (i = 0; i < len; i++) {
		if (n & mask)
			break;
		n |= mask;
		mask >>= 1;
	}
done:
	*curr = cpu_to_be32(n);
	set_page_dirty(page);
	kunmap(page);
	*gc = aq + (curr - pptr) * 32 + i - start;
	HFSPLUS_SB(tw).free_blocks -= *gc;
	sb->s_dirt = 1;
	dprint(DBG_BITMAP, "-> %u,%u\n", start, *gc);
out:
	mutex_unlock(&HFSPLUS_SB(tw).alloc_file->i_mutex);
	return start;
}

static void wp(RIO *np, RIOBank *ry, RListIter *hw, RIOMap *pu) {
	RIOSubMap fake_sm;
	fake_sm.itv = pu->itv;
	fake_sm.mapref.id = pu->id;
	RRBNode *entry = _find_entry_submap_node (ry, &fake_sm);
	if (!entry) {
		return;
	}
	RIOSubMap *bd = (RIOSubMap *)entry->data;
	while (bd && r_io_submap_overlap (bd, (&fake_sm))) {


		RRBNode *next = r_rbnode_next (entry);
		if (bd->mapref.id == fake_sm.mapref.id) {
			r_queue_enqueue (ry->todo, R_NEWCOPY (RIOSubMap, bd));
			r_crbtree_delete (ry->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
		}
		entry = next;
		bd = entry ? (RIOSubMap *)entry->data : NULL;
	}
	RListIter *iter = hw;
	while (!r_queue_is_empty (ry->todo)) {


		RIOSubMap *sm = r_queue_dequeue (ry->todo);
		RListIter *ator = r_list_iter_get_prev (iter);
		while (ator) {
			map = r_io_map_get_by_ref (np, (RIOMapRef *)ator->data);
			ator = r_list_iter_get_prev (ator);
			if (!map) {

				continue;
			}







			if (r_io_submap_to (sm) < r_io_map_from (pu) || r_io_submap_from (sm) > r_io_map_to (pu)) {

				continue;
			}
			RIOMapRef *mapref = _mapref_from_map (pu);
			bd = r_io_submap_new (np, mapref);
			free (mapref);
			if (!bd) {
				continue;
			}
			if (r_io_submap_from (sm) >= r_io_map_from (pu)) {

				r_io_submap_set_from (bd, r_io_submap_from (sm));
				r_crbtree_insert (ry->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
				if (r_io_submap_to (sm) <= r_io_map_to (pu)) {

					r_io_submap_set_to (bd, r_io_submap_to (sm));
					break;
				}

				r_io_submap_set_from (sm, r_io_submap_to (bd) + 1);
				continue;
			}
			if (r_io_submap_to (sm) <= r_io_map_to (pu)) {


				r_io_submap_set_to (bd, r_io_submap_to (sm));

				r_io_submap_set_to (sm, r_io_submap_from (bd) - 1);
				r_crbtree_insert (ry->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
				continue;
			}

			RIOSubMap *bdsm = R_NEWCOPY (RIOSubMap, sm);
			r_io_submap_set_to (sm, r_io_submap_from (bd) - 1);
			r_io_submap_set_from (bdsm, r_io_submap_to (bd) + 1);
			r_crbtree_insert (ry->submaps, bd, _find_sm_by_from_vaddr_cb, NULL);
			r_queue_enqueue (ry->todo, bdsm);
		}
		free (sm);
	}
}

static void ac(struct tty_struct *oz)
{
	struct mkiss *ax;

	write_lock_irq(&disc_data_lock);
	ax = oz->disc_data;
	tty->disc_data = NULL;
	write_unlock_irq(&disc_data_lock);

	if (!ax)
		return;


	if (!refcount_dec_and_test(&ax->refcnt))
		wait_for_completion(&ax->dead);

	netif_stop_queue(ax->dev);


	kfree(ax->rbuff);
	kfree(ax->xbuff);

	ax->oz = NULL;

	unregister_netdev(ax->dev);
	free_netdev(ax->dev);
}

find_start_brace(jh)	    
{
    pos_T	cursor_save;
    pos_T	*trypos;
    pos_T	*pos;
    static pos_T	pos_copy;

    cursor_save = curwin->w_cursor;
    while ((trypos = findmatchlimit(NULL, '{', FM_BLOCKSTOP, 0)) != NULL)
    {
	pos_copy = *trypos;	
	trypos = &pos_copy;
	curwin->w_cursor = *trypos;
	pos = NULL;

	if ((colnr_T)cin_skip2pos(trypos) == trypos->col
		       && (pos = ind_find_start_CORS(NULL)) == NULL) 
	    break;
	if (pos != NULL)
	    curwin->w_cursor.lnum = pos->lnum;
    }
    curwin->w_cursor = cursor_save;
    return trypos;
}

