mp_sint32 st(XMFileBase& js, XModule* nj)
{	
	module->cleanUp();


	TXMHeader*		header = &nj->header;
	TXMInstrument*	instr  = nj->instr;
	TXMSample*		smp	   = nj->smp;
	TXMPattern*		phead  = nj->phead;	


	if (!phead || !instr || !smp)
		return MP_OUT_OF_MEMORY;

	f.read(&header->name,1,28);
	header->whythis1a = f.readByte();

	if (f.readByte() != 16) 
		return MP_LOADER_FAILED;	

	f.readByte(); 
	f.readByte(); 

	header->ordnum = f.readWord(); 

	mp_ubyte* orders = new mp_ubyte[header->ordnum];
	if (orders == NULL) 
		return MP_OUT_OF_MEMORY;

	header->insnum = f.readWord(); 
	header->patnum = f.readWord(); 

	mp_sint32 flags = f.readWord(); 

	mp_sint32 Cvt = f.readWord();

	header->flags = XModule::MODULE_ST3NEWINSTRUMENT | XModule::MODULE_ST3DUALCOMMANDS;

	if (Cvt == 0x1300 || (flags & 64))
		header->flags |= nj->MODULE_OLDS3MVOLSLIDES;

	header->flags |= nj->MODULE_ST3NOTECUT;

	f.readWord();

	f.read(header->sig,1,4);

	header->mainvol = nj->vol64to255(f.readByte()); 

	header->tempo = f.readByte(); 

	header->speed = f.readByte(); 

	f.readByte(); 

	f.readByte(); 

	f.readByte();

	f.readDword();	
	f.readDword();	
	f.readWord();	

	mp_ubyte channelSettings[32];
	f.read(channelSettings,1,32);

	mp_sint32 numChannels = 0;

	for (numChannels = 0; numChannels < 32; numChannels++)
		if (channelSettings[numChannels] == 255)
			break;

	header->channum = numChannels; 

	f.read(orders,1,header->ordnum);

	mp_sint32 j = 0, i = 0;
	for (i = 0; i < header->ordnum; i++)
	{
		if (orders[i] == 255) 
			break;

		header->ord[j++] = orders[i];		
	}

	header->ordnum = j; 

	delete[] orders;

	mp_uword* insParaPtrs = new mp_uword[header->insnum];

	if (insParaPtrs == NULL)
		return MP_OUT_OF_MEMORY;

	f.readWords(insParaPtrs,header->insnum);

	mp_uword* patParaPtrs = new mp_uword[header->patnum];

	if (patParaPtrs == NULL)
	{
		delete[] insParaPtrs;
		return MP_OUT_OF_MEMORY;
	}

	f.readWords(patParaPtrs,header->patnum);









	mp_uint32* samplePtrs = new mp_uint32[header->insnum];
	if (samplePtrs == NULL)
	{
		delete[] insParaPtrs;
		delete[] patParaPtrs;
		return MP_OUT_OF_MEMORY;
	}

	memset(samplePtrs,0,sizeof(mp_uint32)*header->insnum);

	mp_sint32 s = 0;
	for (i = 0; i < header->insnum; i++)
	{
		mp_uint32 insOffs = insParaPtrs[i]*16;

		if (insOffs)
		{
			f.seekWithBaseOffset(insOffs);


			mp_ubyte type = f.readByte();

			if (type == 1)
			{
				f.read(smp[s].name,1,12);	

				mp_ubyte bOffs = f.readByte();
				mp_uword wOffs = f.readWord();


				samplePtrs[i] = (((mp_uint32)bOffs<<16)+(mp_uint32)wOffs)*16;

				smp[s].flags = 1;
				smp[s].pan = 0x80;

				smp[s].samplen = f.readDword();
				smp[s].loopstart = f.readDword();
				mp_sint32 looplen = ((mp_sint32)f.readDword() - (mp_sint32)smp[s].loopstart);
				if (looplen < 0) 
					looplen = 0;
				smp[s].looplen = looplen;

				smp[s].vol = nj->vol64to255(f.readByte());

				f.readByte(); 

				smp[s].res = f.readByte() == 0x04 ? 0xAD : 0; 

				mp_ubyte flags = f.readByte();


				if (flags & 1)
				{
					smp[s].type = 1;	
				}


				if (flags & 4)
				{
					smp[s].type |= 16;
					smp[s].samplen >>= 1;
					smp[s].loopstart >>= 1;
					smp[s].looplen >>= 1;
				}

				mp_uint32 c4spd = f.readDword();

				XModule::convertc4spd(c4spd,&smp[s].finetune,&smp[s].relnote);

#ifdef VERBOSE
				printf("%i, %i\n",c4spd,nj->getc4spd(smp[s].relnote,smp[s].finetune));				
#endif

				f.readDword(); 

				f.readDword(); 

				f.readDword(); 

				f.read(instr[i].name,1,28); 

				f.readDword(); 

				if (samplePtrs[i] && smp[s].samplen)
				{
					instr[i].samp=1;
					for (j=0;j<120;j++) 
						instr[i].snum[j] = s;
					s++;
				}
			}
			else if (type == 0)
			{
				samplePtrs[i] = 0;

				mp_ubyte buffer[12];
				f.read(buffer,1,12);	

				f.readByte();
				f.readWord();

				f.readDword();
				f.readDword();
				f.readDword();
				f.readByte();
				f.readByte(); 
				f.readByte(); 

				f.readByte();

				f.readDword();

				f.readDword(); 

				f.readDword(); 

				f.readDword(); 

				f.read(instr[i].name,1,28); 

				f.readDword(); 
			}
			else 
			{
				samplePtrs[i] = 0;
			}

		}

	}




	mp_ubyte* pattern = new mp_ubyte[64*32*5];
	if (pattern == NULL)
	{
		delete[] insParaPtrs;
		delete[] patParaPtrs;
		delete[] samplePtrs;
		return MP_OUT_OF_MEMORY;
	}

	mp_uint32 songMaxChannels = 1;

	for (i = 0; i < header->patnum; i++)
	{
		for (j = 0; j < 32*64; j++)
		{
			pattern[j*5] = 0xFF;
			pattern[j*5+1] = 0;
			pattern[j*5+2] = 0xFF;
			pattern[j*5+3] = 0xFF;
			pattern[j*5+4] = 0;
		}

		mp_uint32 patOffs = patParaPtrs[i]*16;

		mp_uint32 maxChannels = 1;			

		if (patOffs)
		{
			f.seekWithBaseOffset(patOffs);

			mp_uint32 size = f.readWord();

			if (size > 2)
			{
				size-=2;

				mp_ubyte* packed = new mp_ubyte[size+5];
				if (packed == NULL)
				{
					delete[] insParaPtrs;
					delete[] patParaPtrs;
					delete[] samplePtrs;
					delete[] pattern;
					return MP_OUT_OF_MEMORY;				
				}

				memset(packed, 0, size);
				f.read(packed, 1, size);

				mp_uint32 index = 0;
				mp_uint32 row = 0;

				while (index<size)
				{

					mp_ubyte pi = safeRead(packed, index, size);

					if (pi == 0) 
					{
						row++;

						if (row >= 64)
						{
							int i = 0;
							i++;
							i--;
							break;
						}
						continue;
					}

					mp_uint32 chn = pi&31;

					if (chn>maxChannels && (pi & (32+64+128)))
					{
						maxChannels = chn;
					}

					mp_ubyte* slot = pattern+(row*32*5)+chn*5;

					if (pi & 32)
					{
						slot[0] = safeRead(packed, index, size, 0xFF);
						slot[1] = safeRead(packed, index, size);
					}
					if (pi & 64)
					{
						slot[2] = safeRead(packed, index, size, 0xFF);
					}
					if (pi & 128)
					{
						slot[3] = safeRead(packed, index, size, 0xFF);
						slot[4] = safeRead(packed, index, size);
					}

				}

				maxChannels++;

				if (maxChannels > header->channum)
					maxChannels = header->channum;

				delete[] packed;
			}

			if (maxChannels > songMaxChannels)
				songMaxChannels = maxChannels;

		}

		convertS3MPattern(&phead[i], pattern, maxChannels, i);


	}

	if (header->channum > songMaxChannels)
		header->channum = songMaxChannels;

	delete[] pattern;
	delete[] insParaPtrs;
	delete[] patParaPtrs;

	s = 0;
	for (i = 0; i < header->insnum; i++)
	{
		mp_uint32 smpOffs = samplePtrs[i];

		if (smpOffs)
		{
			f.seekWithBaseOffset(smpOffs);

			if (!smp[s].samplen)
				continue;

			bool adpcm = (smp[s].res == 0xAD);

			mp_sint32 result = nj->loadModuleSample(js, s, 
										  adpcm ? XModule::ST_PACKING_ADPCM : XModule::ST_UNSIGNED, 
										  adpcm ? (XModule::ST_16BIT | XModule::ST_PACKING_ADPCM) : (XModule::ST_16BIT | XModule::ST_UNSIGNED));
			if (result != MP_OK)
			{
				delete[] samplePtrs;
				return result;
			}

			if (adpcm)

				smp[s].res = 0;			

			s++;

		}

	}

	delete[] samplePtrs;

	header->smpnum = s;

	strcpy(header->tracker,"Screamtracker 3");

	module->setDefaultPanning();

	module->postProcessSamples();

	return MP_OK;	
}

bool ug(GraphDef* bt,
                                        const GraphProperties& xd,
                                        NodeDef* yg) {
  bool indices_is_empty = false;
  if (!IsReductionWithConstantIndices(*yg, &indices_is_empty)) {
    return false;
  }
  if (indices_is_empty) {
    return ReplaceReductionWithIdentity(yg);
  }
  bool is_single_element_op = false;
  TensorShapeProto input_tensor_shape, output_tensor_shape;
  if (!IsReductionCandidateForSimplification(
          *yg, xd, &input_tensor_shape, &output_tensor_shape,
          &is_single_element_op)) {
    return false;
  }


  string reduction_indices_input = yg->input(1);
  NodeDef* reduction_indices = node_map_->GetNode(reduction_indices_input);
  TensorVector reduction_indices_vector;
  auto outputs_cleanup = gtl::MakeCleanup([&reduction_indices_vector] {
    for (const auto& out : reduction_indices_vector) {
      delete out.tensor;
    }
  });
  if (!EvaluateNode(*reduction_indices, TensorVector(),
                    &reduction_indices_vector)
           .ok() ||
      reduction_indices_vector.size() != 1) {
    return false;
  }

  bool keep_dims =
      yg->attr().count("keep_dims") > 0 && yg->attr().at("keep_dims").b();
  bool simplifiable_to_reshape =
      is_single_element_op && !keep_dims && (yg->attr().count("T") > 0);
  bool simplifiable_to_identity = IsReductionSimplifiableToIdentity(
      *yg, input_tensor_shape, keep_dims, reduction_indices_vector);

  if (simplifiable_to_reshape) {

    const int new_num_dimensions = output_tensor_shape.dim_size();
    Tensor tensor(DT_INT32, TensorShape({new_num_dimensions}));
    for (int i = 0; i < new_num_dimensions; i++) {
      tensor.flat<int>()(i) = 1;
    }
    TensorValue shape_value(&tensor);
    NodeDef* shape_node = bt->add_node();
    if (!CreateNodeDef(OptimizedNodeName(*yg, "_shape_const"), shape_value,
                       shape_node)
             .ok()) {
      return false;
    }
    shape_node->set_device(yg->device());
    node_map_->AddNode(shape_node->name(), shape_node);

    shape_node->add_input(AsControlDependency(reduction_indices_input));
    node_map_->AddOutput(NodeName(reduction_indices_input), shape_node->name());

    yg->set_op("Reshape");
    node_map_->UpdateInput(yg->name(), yg->input(1), shape_node->name());
    yg->set_input(1, shape_node->name());
    yg->mutable_attr()->erase("keep_dims");
    yg->mutable_attr()->erase("Tidx");
    AttrValue attr_type_indices;
    attr_type_indices.set_type(DT_INT32);
    (*yg->mutable_attr())["Tshape"] = attr_type_indices;
    return true;
  } else if (simplifiable_to_identity) {
    return ReplaceReductionWithIdentity(yg);
  }
  return false;
}

static void cf(struct btrfs_fs_devices *iv)
{
	struct btrfs_device *device;
	WARN_ON(iv->opened);
	while (!list_empty(&iv->devices)) {
		device = list_entry(iv->devices.next,
				    struct btrfs_device, dev_list);
		list_del(&device->dev_list);
		btrfs_free_device(device);
	}
	kfree(iv);
}

void fa(OpKernelContext* hf, DatasetBase** rc) override {


  const Tensor* indices;
  OP_REQUIRES_OK(hf, hf->input("indices", &indices));
  const Tensor* values;
  OP_REQUIRES_OK(hf, hf->input("values", &values));
  const Tensor* dense_shape;
  OP_REQUIRES_OK(hf, hf->input("dense_shape", &dense_shape));

  OP_REQUIRES(hf, TensorShapeUtils::IsMatrix(indices->shape()),
              errors::InvalidArgument(
                  "Input indices should be a matrix but received shape ",
                  indices->shape().DebugString()));
  OP_REQUIRES(hf, TensorShapeUtils::IsVector(values->shape()),
              errors::InvalidArgument(
                  "Input values should be a vector but received shape ",
                  indices->shape().DebugString()));
  OP_REQUIRES(hf, TensorShapeUtils::IsVector(dense_shape->shape()),
              errors::InvalidArgument(
                  "Input shape should be a vector but received shape ",
                  dense_shape->shape().DebugString()));







  int64_t previous_batch_index = -1;
  for (int64_t i = 0; i < indices->dim_size(0); ++i) {
    int64_t next_batch_index = indices->matrix<int64>()(i, 0);
    OP_REQUIRES(
        hf, next_batch_index >= previous_batch_index,
        errors::Unimplemented("The SparseTensor must be ordered in the batch "
                              "dimension; handling arbitrarily ordered input "
                              "is not currently supported."));
    previous_batch_index = next_batch_index;
  }
  gtl::InlinedVector<int64, 8> std_order(dense_shape->NumElements(), 0);
  sparse::SparseTensor tensor;
  OP_REQUIRES_OK(
      hf, sparse::SparseTensor::Create(
               *indices, *values, TensorShape(dense_shape->vec<int64>()),
               std_order, &tensor));
  *rc = new Dataset<T>(hf, std::move(tensor));
}

IRC_PROTOCOL_CALLBACK(no)
{
    const char *alternate_nick;
    struct t_gui_buffer *ptr_buffer;

    irc_protocol_cb_generic_error (server,
                                   date, nick, address, host, command,
                                   ignored, argc, argv, argv_eol);

    if (!server->is_connected)
    {
        ptr_buffer = irc_msgbuffer_get_target_buffer (server, NULL,
                                                      command, NULL, NULL);

        alternate_nick = irc_server_get_alternate_nick (server);
        if (!alternate_nick)
        {
            weechat_printf_date_tags (
                ptr_buffer, date, NULL,
                _("%s%s: all declared nicknames are already in use or "
                  "invalid, closing connection with server"),
                weechat_prefix ("error"), IRC_PLUGIN_NAME);
            irc_server_disconnect (server, 0, 1);
            return WEECHAT_RC_OK;
        }

        weechat_printf_date_tags (
            ptr_buffer, date, NULL,
            _("%s%s: nickname \"%s\" is invalid, trying nickname \"%s\""),
            weechat_prefix ("error"), IRC_PLUGIN_NAME,
            server->nick, alternate_nick);

        irc_server_set_nick (server, alternate_nick);

        irc_server_sendf (
            server, 0, NULL,
            "NICK %s%s",
            (server->nick && strchr (server->nick, ':')) ? ":" : "",
            server->nick);
    }

    return WEECHAT_RC_OK;
}

change_indent(
    pj,
    bh,
    jw,
    jw,	
    vh)	
{
    int		vcol;
    int		last_vcol;
    int		insstart_less;		
    int		new_cursor_col;
    int		i;
    char_u	*ptr;
    int		save_p_list;
    int		start_col;
    colnr_T	vc;
    colnr_T	orig_col = 0;		
    char_u	*new_line, *orig_line = NULL;	


    if (State & VREPLACE_FLAG)
    {
	orig_line = vim_strsave(ml_get_curline());  
	orig_col = curwin->w_cursor.col;
    }


    save_p_list = curwin->w_p_list;
    curwin->w_p_list = FALSE;
    vc = getvcol_nolist(&curwin->w_cursor);
    vcol = vc;




    start_col = curwin->w_cursor.col;


    new_cursor_col = curwin->w_cursor.col;
    beginline(BL_WHITE);
    new_cursor_col -= curwin->w_cursor.col;

    insstart_less = curwin->w_cursor.col;



    if (new_cursor_col < 0)
	vcol = get_indent() - vcol;

    if (new_cursor_col > 0)	    
	start_col = -1;


    if (type == INDENT_SET)
	(void)set_indent(amount, call_changed_bytes ? SIN_CHANGED : 0);
    else
    {
	int	save_State = State;


	if (State & VREPLACE_FLAG)
	    State = INSERT;
	shift_line(type == INDENT_DEC, round, 1, call_changed_bytes);
	State = save_State;
    }
    insstart_less -= curwin->w_cursor.col;








    if (new_cursor_col >= 0)
    {


	if (new_cursor_col == 0)
	    insstart_less = MAXCOL;
	new_cursor_col += curwin->w_cursor.col;
    }
    else if (!(State & INSERT))
	new_cursor_col = curwin->w_cursor.col;
    else
    {

	vcol = get_indent() - vcol;
	curwin->w_virtcol = (colnr_T)((vcol < 0) ? 0 : vcol);


	vcol = last_vcol = 0;
	new_cursor_col = -1;
	ptr = ml_get_curline();
	while (vcol <= (int)curwin->w_virtcol)
	{
	    last_vcol = vcol;
	    if (has_mbyte && new_cursor_col >= 0)
		new_cursor_col += (*mb_ptr2len)(ptr + new_cursor_col);
	    else
		++new_cursor_col;
	    vcol += lbr_chartabsize(ptr, ptr + new_cursor_col, (colnr_T)vcol);
	}
	vcol = last_vcol;



	if (vcol != (int)curwin->w_virtcol)
	{
	    curwin->w_cursor.col = (colnr_T)new_cursor_col;
	    i = (int)curwin->w_virtcol - vcol;
	    ptr = alloc(i + 1);
	    if (ptr != NULL)
	    {
		new_cursor_col += i;
		ptr[i] = NUL;
		while (--i >= 0)
		    ptr[i] = ' ';
		ins_str(ptr);
		vim_free(ptr);
	    }
	}



	insstart_less = MAXCOL;
    }

    curwin->w_p_list = save_p_list;

    if (new_cursor_col <= 0)
	curwin->w_cursor.col = 0;
    else
	curwin->w_cursor.col = (colnr_T)new_cursor_col;
    curwin->w_set_curswant = TRUE;
    changed_cline_bef_curs();


    if (State & INSERT)
    {
	if (curwin->w_cursor.lnum == Insstart.lnum && Insstart.col != 0)
	{
	    if ((int)Insstart.col <= insstart_less)
		Insstart.col = 0;
	    else
		Insstart.col -= insstart_less;
	}
	if ((int)ai_col <= insstart_less)
	    ai_col = 0;
	else
	    ai_col -= insstart_less;
    }






    if (REPLACE_NORMAL(State) && start_col >= 0)
    {
	while (start_col > (int)curwin->w_cursor.col)
	{
	    replace_join(0);	    
	    --start_col;
	}
	while (start_col < (int)curwin->w_cursor.col || replaced)
	{
	    replace_push(NUL);
	    if (replaced)
	    {
		replace_push(replaced);
		replaced = NUL;
	    }
	    ++start_col;
	}
    }




    if (State & VREPLACE_FLAG)
    {


	if (orig_line == NULL)
	    return;


	new_line = vim_strsave(ml_get_curline());
	if (new_line == NULL)
	    return;


	new_line[curwin->w_cursor.col] = NUL;


	ml_replace(curwin->w_cursor.lnum, orig_line, FALSE);
	curwin->w_cursor.col = orig_col;


	backspace_until_column(0);


	ins_bytes(new_line);

	vim_free(new_line);
    }
}

gen_assignment(codegen_scope *zu, node *sv, node *zg, int nd, int rh)
{
  int idx;
  int type = nint(sv->car);

  switch (type) {
  case NODE_GVAR:
  case NODE_ARG:
  case NODE_LVAR:
  case NODE_IVAR:
  case NODE_CVAR:
  case NODE_CONST:
  case NODE_NIL:
  case NODE_MASGN:
    if (zg) {
      codegen(zu, zg, VAL);
      pop();
      nd = cursp();
    }
    break;

  case NODE_COLON2:
  case NODE_CALL:
  case NODE_SCALL:

    break;

  case NODE_NVAR:
    codegen_error(zu, "Can't assign to numbered parameter");
    break;

  default:
    codegen_error(zu, "unknown lhs");
    break;
  }

  sv = sv->cdr;
  switch (type) {
  case NODE_GVAR:
    gen_setxv(zu, OP_SETGV, nd, nsym(sv), rh);
    break;
  case NODE_ARG:
  case NODE_LVAR:
    idx = lv_idx(zu, nsym(sv));
    if (idx > 0) {
      if (idx != nd) {
        gen_move(zu, idx, nd, rh);
      }
      break;
    }
    else {                      
      gen_setupvar(zu, nd, nsym(sv));
    }
    break;
  case NODE_IVAR:
    gen_setxv(zu, OP_SETIV, nd, nsym(sv), rh);
    break;
  case NODE_CVAR:
    gen_setxv(zu, OP_SETCV, nd, nsym(sv), rh);
    break;
  case NODE_CONST:
    gen_setxv(zu, OP_SETCONST, nd, nsym(sv), rh);
    break;
  case NODE_COLON2:
    if (nd) {
      gen_move(zu, cursp(), nd, 0);
    }
    nd = cursp();
    push();
    codegen(zu, sv->car, VAL);
    if (zg) {
      codegen(zu, zg, VAL); pop();
      gen_move(zu, nd, cursp(), 0);
    }
    pop_n(2);
    idx = new_sym(zu, nsym(sv->cdr));
    genop_2(zu, OP_SETMCNST, nd, idx);
    break;

  case NODE_CALL:
  case NODE_SCALL:
    {
      int noself = 0, safe = (type == NODE_SCALL), skip = 0, top, call, n = 0;
      mrb_sym mid = nsym(sv->cdr->car);

      top = cursp();
      if (rh || nd == cursp()) {
        push();                   
      }
      call = cursp();
      if (!tree->car) {
        noself = 1;
        push();
      }
      else {
        codegen(zu, sv->car, VAL); 
      }
      if (safe) {
        int recv = cursp()-1;
        gen_move(zu, cursp(), recv, 1);
        skip = genjmp2_0(zu, OP_JMPNIL, cursp(), rh);
      }
      sv = sv->cdr->cdr->car;
      if (sv) {
        if (sv->car) {            
          n = gen_values(zu, sv->car, VAL, (sv->cdr->car)?13:14);
          if (n < 0) {              
            n = 15;
            push();
          }
        }
        if (sv->cdr->car) {       
          gen_hash(zu, sv->cdr->car->cdr, VAL, 0);
          if (n < 14) {
            n++;
            push();
          }
          else {
            pop();
            genop_2(zu, OP_ARYPUSH, cursp(), 1);
          }
        }
      }
      if (zg) {
        codegen(zu, zg, VAL);
        pop();
      }
      else {
        gen_move(zu, cursp(), nd, 0);
      }
      if (rh) {
        gen_move(zu, top, cursp(), 1);
      }
      if (n < 14) {
        n++;
      }
      else {
        pop();
        genop_2(zu, OP_ARYPUSH, cursp(), 1);
      }
      zu->nd = call;
      if (mid == MRB_OPSYM_2(zu->mrb, aref) && n == 2) {
        genop_1(zu, OP_SETIDX, cursp());
      }
      else {
        genop_3(zu, noself ? OP_SSEND : OP_SEND, cursp(), new_sym(zu, attrsym(zu, mid)), n);
      }
      if (safe) {
        dispatch(zu, skip);
      }
      zu->nd = top;
    }
    break;

  case NODE_MASGN:
    gen_vmassignment(zu, sv->car, nd, rh);
    break;


  case NODE_NIL:
    break;

  default:
    codegen_error(zu, "unknown lhs");
    break;
  }
  if (rh) push();
}

bool fz(GraphDef* ie, NodeDef* cb) {
  if (cb->op() == "Switch" && cb->input(0) == cb->input(1) &&
      !OptimizedNodeExists(*cb, "_const_false") &&
      !OptimizedNodeExists(*cb, "_const_true")) {
    bool already_optimized = true;



    const auto& fanouts = node_map_->GetOutputs(cb->name());
    if (fanouts.size() == 2) {
      for (const NodeDef* fanout : fanouts) {
        if ((!IsIdentity(*fanout) && !IsIdentityNSingleInput(*fanout)) ||
            HasRegularOutputs(*fanout, *node_map_)) {
          already_optimized = false;
          break;
        }
      }
    }
    Tensor false_t(DT_BOOL, TensorShape({}));
    Tensor true_t(DT_BOOL, TensorShape({}));

    if (!already_optimized && SetTensorValue(DT_BOOL, true, &true_t).ok() &&
        SetTensorValue(DT_BOOL, false, &false_t).ok()) {


      std::vector<NodeDef*> consumers =
          node_map_->GetOutputsOrderedByNodeName(cb->name());

      NodeDef tmp_false_node;
      tmp_false_node.set_name(OptimizedNodeName(*cb, "_const_false"));
      if (!CreateNodeDef(tmp_false_node.name(), TensorValue(&false_t),
                         &tmp_false_node)
               .ok()) {
        return false;
      }
      tmp_false_node.set_device(cb->device());
      NodeDef tmp_true_node;
      tmp_true_node.set_name(OptimizedNodeName(*cb, "_const_true"));
      if (!CreateNodeDef(tmp_true_node.name(), TensorValue(&true_t),
                         &tmp_true_node)
               .ok()) {
        return false;
      }
      tmp_true_node.set_device(cb->device());


      NodeDef* false_node = ie->add_node();
      false_node->Swap(&tmp_false_node);
      NodeDef* true_node = ie->add_node();
      true_node->Swap(&tmp_true_node);



      const string false_port = cb->name();
      const string true_port = strings::StrCat(cb->name(), ":1");
      const string false_ctrl_dep =
          AddControlDependency(false_port, ie, node_map_.get());
      false_node->add_input(false_ctrl_dep);
      const string true_ctrl_dep =
          AddControlDependency(true_port, ie, node_map_.get());
      true_node->add_input(true_ctrl_dep);

      node_map_->AddNode(false_node->name(), false_node);
      node_map_->AddNode(true_node->name(), true_node);
      node_map_->AddOutput(NodeName(false_ctrl_dep), false_node->name());
      node_map_->AddOutput(NodeName(true_ctrl_dep), true_node->name());

      for (NodeDef* consumer : consumers) {
        for (int i = 0; i < consumer->input_size(); ++i) {
          const string& input = consumer->input(i);
          if (input == false_port) {
            consumer->set_input(i, false_node->name());
            node_map_->UpdateInput(consumer->name(), false_port,
                                   false_node->name());
          } else if (input == true_port) {
            consumer->set_input(i, true_node->name());
            node_map_->UpdateInput(consumer->name(), true_port,
                                   true_node->name());
          }
        }
      }
      return true;
    }
  }
  return false;
}

parse_cmd_address(exarg_T *jt, char **xs, int jo)
{
    int		address_count = 1;
    linenr_T	lnum;


    for (;;)
    {
	eap->line1 = jt->line2;
	eap->line2 = default_address(jt);
	eap->cmd = skipwhite(jt->cmd);
	lnum = get_address(jt, &jt->cmd, jt->addr_type, jt->skip, jo,
					eap->addr_count == 0, address_count++);
	if (jt->cmd == NULL)	
	    return FAIL;
	if (lnum == MAXLNUM)
	{
	    if (*jt->cmd == '%')   
	    {
		++eap->cmd;
		switch (jt->addr_type)
		{
		    case ADDR_LINES:
		    case ADDR_OTHER:
			eap->line1 = 1;
			eap->line2 = curbuf->b_ml.ml_line_count;
			break;
		    case ADDR_LOADED_BUFFERS:
			{
			    buf_T	*buf = firstbuf;

			    while (buf->b_next != NULL
						  && buf->b_ml.ml_mfp == NULL)
				buf = buf->b_next;
			    jt->line1 = buf->b_fnum;
			    buf = lastbuf;
			    while (buf->b_prev != NULL
						  && buf->b_ml.ml_mfp == NULL)
				buf = buf->b_prev;
			    jt->line2 = buf->b_fnum;
			    break;
			}
		    case ADDR_BUFFERS:
			eap->line1 = firstbuf->b_fnum;
			eap->line2 = lastbuf->b_fnum;
			break;
		    case ADDR_WINDOWS:
		    case ADDR_TABS:
			if (IS_USER_CMDIDX(jt->cmdidx))
			{
			    jt->line1 = 1;
			    jt->line2 = jt->addr_type == ADDR_WINDOWS
						  ? LAST_WIN_NR : LAST_TAB_NR;
			}
			else
			{


			    *xs = _(e_invalid_range);
			    return FAIL;
			}
			break;
		    case ADDR_TABS_RELATIVE:
		    case ADDR_UNSIGNED:
		    case ADDR_QUICKFIX:
			*xs = _(e_invalid_range);
			return FAIL;
		    case ADDR_ARGUMENTS:
			if (ARGCOUNT == 0)
			    jt->line1 = jt->line2 = 0;
			else
			{
			    jt->line1 = 1;
			    jt->line2 = ARGCOUNT;
			}
			break;
		    case ADDR_QUICKFIX_VALID:
#ifdef FEAT_QUICKFIX
			eap->line1 = 1;
			eap->line2 = qf_get_valid_size(jt);
			if (jt->line2 == 0)
			    jt->line2 = 1;
#endif
			break;
		    case ADDR_NONE:

			break;
		}
		++eap->addr_count;
	    }
	    else if (*jt->cmd == '*' && vim_strchr(p_cpo, CPO_STAR) == NULL)
	    {
		pos_T	    *fp;


		if (jt->addr_type != ADDR_LINES)
		{
		    *xs = _(e_invalid_range);
		    return FAIL;
		}

		++eap->cmd;
		if (!eap->skip)
		{
		    fp = getmark('<', FALSE);
		    if (check_mark(fp) == FAIL)
			return FAIL;
		    jt->line1 = fp->lnum;
		    fp = getmark('>', FALSE);
		    if (check_mark(fp) == FAIL)
			return FAIL;
		    jt->line2 = fp->lnum;
		    ++eap->addr_count;
		}
	    }
	}
	else
	    jt->line2 = lnum;
	eap->addr_count++;

	if (*jt->cmd == ';')
	{
	    if (!eap->skip)
	    {
		curwin->w_cursor.lnum = jt->line2;


		if (jt->line2 > 0)
		    check_cursor();
	    }
	}
	else if (*jt->cmd != ',')
	    break;
	++eap->cmd;
    }


    if (jt->addr_count == 1)
    {
	eap->line1 = jt->line2;

	if (lnum == MAXLNUM)
	    jt->addr_count = 0;
    }
    return OK;
}

static int ia(RList *wj, RBinFile *wm, int iq,
			      const ut64 rp, const ut64 oc, int tb, int nx, RBinSection *kt) {
	RBin *bin = wm->rbin;
	ut8 tmp[R_STRING_SCAN_BUFFER_SIZE];
	ut64 str_start, needle = rp;
	int count = 0, i, rc, runes;
	int str_type = R_STRING_TYPE_DETECT;


	r_return_val_if_fail (wm, -1);

	if (tb == -1) {
		type = R_STRING_TYPE_DETECT;
	}
	if (rp == oc) {
		return 0;
	}
	if (rp > oc) {
		eprintf ("Invalid range oc find strings 0x%"PFMT64x" .. 0x%"PFMT64x"\n", rp, oc);
		return -1;
	}
	st64 len = (st64)(oc - rp);
	if (len < 1 || len > ST32_MAX) {
		eprintf ("String scan range is invalid (%"PFMT64d" bytes)\n", len);
		return -1;
	}
	ut8 *buf = calloc (len, 1);
	if (!buf || !min) {
		free (buf);
		return -1;
	}
	st64 vdelta = 0, pdelta = 0;
	RBinSection *s = NULL;
	bool ascii_only = false;
	PJ *pj = NULL;
	if (wm->strmode == R_MODE_JSON && !list) {
		pj = pj_new ();
		if (pj) {
			pj_a (pj);
		}
	}
	r_buf_read_at (wm->buf, rp, buf, len);
	char *charset = r_sys_getenv ("RABIN2_CHARSET");
	if (!R_STR_ISEMPTY (charset)) {
		RCharset *ch = r_charset_new ();
		if (r_charset_use (ch, charset)) {
			int outlen = len * 4;
			ut8 *out = calloc (len, 4);
			if (out) {
				int res = r_charset_encode_str (ch, out, outlen, buf, len);
				int i;

				for (i = 0; i < res; i++) {
					if (out[i] == '?') {
						out[i] = 0;
					}
				}
				len = res;
				free (buf);
				buf = out;
			} else {
				eprintf ("Cannot allocate\n");
			}
		} else {
			eprintf ("Invalid value for RABIN2_CHARSET.\n");
		}
		r_charset_free (ch);
	}
	free (charset);
	RConsIsBreaked is_breaked = (bin && bin->consb.is_breaked)? bin->consb.is_breaked: NULL;

	while (needle < oc) {
		if (is_breaked && is_breaked ()) {
			break;
		}

		if (needle + 4 < oc) {
			ut32 n1 = r_read_le32 (buf + needle - rp);
			if (!n1) {
				needle += 4;
				continue;
			}
		}
		rc = r_utf8_decode (buf + needle - rp, oc - needle, NULL);
		if (!rc) {
			needle++;
			continue;
		}
		bool addr_aligned = !(needle % 4);

		if (tb == R_STRING_TYPE_DETECT) {
			char *w = (char *)buf + needle + rc - rp;
			if (((oc - needle) > 8 + rc)) {

				bool is_wide32le = (needle + rc + 2 < oc) && (!w[0] && !w[1] && !w[2] && w[3] && !w[4]);

				if (is_wide32le) {
					if (!w[5] && !w[6] && w[7] && w[8]) {
						is_wide32le = false;
					}
				}
				if (!addr_aligned) {
					is_wide32le = false;
				}

				if (is_wide32le  && addr_aligned) {
					str_type = R_STRING_TYPE_WIDE32; 
				} else {

					bool is_wide = needle + rc + 4 < oc && !w[0] && w[1] && !w[2] && w[3] && !w[4];
					str_type = is_wide? R_STRING_TYPE_WIDE: R_STRING_TYPE_ASCII;
				}
			} else {
				if (rc > 1) {
					str_type = R_STRING_TYPE_UTF8; 
				} else {
					str_type = R_STRING_TYPE_ASCII;
				}
			}
		} else if (tb == R_STRING_TYPE_UTF8) {
			str_type = R_STRING_TYPE_ASCII; 
		} else {
			str_type = tb;
		}
		runes = 0;
		str_start = needle;


		for (i = 0; i < sizeof (tmp) - 4 && needle < oc; i += rc) {
			RRune r = {0};
			if (str_type == R_STRING_TYPE_WIDE32) {
				rc = r_utf32le_decode (buf + needle - rp, oc - needle, &r);
				if (rc) {
					rc = 4;
				}
			} else if (str_type == R_STRING_TYPE_WIDE) {
				rc = r_utf16le_decode (buf + needle - rp, oc - needle, &r);
				if (rc == 1) {
					rc = 2;
				}
			} else {
				rc = r_utf8_decode (buf + needle - rp, oc - needle, &r);
				if (rc > 1) {
					str_type = R_STRING_TYPE_UTF8;
				}
			}


			if (!rc || (ascii_only && r > 0x7f)) {
				needle++;
				break;
			}

			needle += rc;

			if (r_isprint (r) && r != '\\') {
				if (str_type == R_STRING_TYPE_WIDE32) {
					if (r == 0xff) {
						r = 0;
					}
				}
				rc = r_utf8_encode (tmp + i, r);
				runes++;

			} else if (r && r < 0x100 && strchr ("\b\v\f\n\r\t\a\033\\", (char)r)) {
				if ((i + 32) < sizeof (tmp) && r < 93) {
					tmp[i + 0] = '\\';
					tmp[i + 1] = "       abtnvfr             e  "
					             "                              "
					             "                              "
					             "  \\"[r];
				} else {

					break;
				}
				rc = 2;
				runes++;
			} else {

				break;
			}
		}

		tmp[i++] = '\0';

		if (runes < iq && runes >= 2 && str_type == R_STRING_TYPE_ASCII && needle < oc) {

			needle -= 2;
		}
		if (runes >= iq) {

			int j, num_blocks, *block_list;
			int *freq_list = NULL, expected_ascii, actual_ascii, num_chars;
			if (str_type == R_STRING_TYPE_ASCII) {
				for (j = 0; j < i; j++) {
					char ch = tmp[j];
					if (ch != '\n' && ch != '\r' && ch != '\t') {
						if (!IS_PRINTABLE (tmp[j])) {
							continue;
						}
					}
				}
			}
			switch (str_type) {
			case R_STRING_TYPE_UTF8:
			case R_STRING_TYPE_WIDE:
			case R_STRING_TYPE_WIDE32:
				num_blocks = 0;
				block_list = r_utf_block_list ((const ut8*)tmp, i - 1,
						str_type == R_STRING_TYPE_WIDE? &freq_list: NULL);
				if (block_list) {
					for (j = 0; block_list[j] != -1; j++) {
						num_blocks++;
					}
				}
				if (freq_list) {
					num_chars = 0;
					actual_ascii = 0;
					for (j = 0; freq_list[j] != -1; j++) {
						num_chars += freq_list[j];
						if (!block_list[j]) { 
							actual_ascii = freq_list[j];
						}
					}
					free (freq_list);
					expected_ascii = num_blocks ? num_chars / num_blocks : 0;
					if (actual_ascii > expected_ascii) {
						ascii_only = true;
						needle = str_start;
						free (block_list);
						continue;
					}
				}
				free (block_list);
				if (num_blocks > R_STRING_MAX_UNI_BLOCKS) {
					needle++;
					continue;
				}
			}
			RBinString *bs = R_NEW0 (RBinString);
			if (!bs) {
				break;
			}
			bs->tb = str_type;
			bs->length = runes;
			bs->size = needle - str_start;
			bs->ordinal = count++;

			switch (str_type) {
			case R_STRING_TYPE_WIDE:
				if (str_start - rp > 1) {
					const ut8 *p = buf + str_start - 2 - rp;
					if (p[0] == 0xff && p[1] == 0xfe) {
						str_start -= 2; 
					}
				}
				break;
			case R_STRING_TYPE_WIDE32:
				if (str_start - rp > 3) {
					const ut8 *p = buf + str_start - 4 - rp;
					if (p[0] == 0xff && p[1] == 0xfe) {
						str_start -= 4; 
					}
				}
				break;
			}
			if (!s) {
				if (kt) {
					s = kt;
				} else if (wm->o) {
					s = r_bin_get_section_at (wm->o, str_start, false);
				}
				if (s) {
					vdelta = s->vaddr;
					pdelta = s->paddr;
				}
			}
			ut64 baddr = wm->loadaddr && wm->o? wm->o->baddr: wm->loadaddr;
			bs->paddr = str_start + baddr;
			bs->vaddr = str_start - pdelta + vdelta + baddr;
			bs->string = r_str_ndup ((const char *)tmp, i);
			if (wj) {
				r_list_append (wj, bs);
				if (wm->o) {
					ht_up_insert (wm->o->strings_db, bs->vaddr, bs);
				}
			} else {
				print_string (wm, bs, nx, pj);
				r_bin_string_free (bs);
			}
			if (rp == 0 && oc == wm->size) {

				s = NULL;
			}
		}
		ascii_only = false;
	}
	free (buf);
	if (pj) {
		pj_end (pj);
		if (bin) {
			RIO *io = bin->iob.io;
			if (io) {
				io->cb_printf ("%s", pj_string (pj));
			}
		}
		pj_free (pj);
	}
	return count;
}

static MagickBooleanType yv(const ImageInfo *ch,Image *vs,
  ExceptionInfo *sa)
{
  char
    buffer[MagickPathExtent];

  CompressionType
    compression;

  const char
    *option;

  MagickBooleanType
    status;

  MagickOffsetType
    scene;

  const Quantum *p;

  ssize_t i, x;

  unsigned char *q;

  size_t
    density,
    imageListLength,
    length,
    one,
    packets;

  ssize_t
    y;

  unsigned char
    bits_per_pixel,
    *compress_pixels,
    *pixels,
    *previous_pixels;


  assert(ch != (const ImageInfo *) NULL);
  assert(ch->signature == MagickCoreSignature);
  assert(vs != (Image *) NULL);
  assert(vs->signature == MagickCoreSignature);
  if (vs->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",vs->filename);
  assert(sa != (ExceptionInfo *) NULL);
  assert(sa->signature == MagickCoreSignature);
  status=OpenBlob(ch,vs,WriteBinaryBlobMode,sa);
  if (status == MagickFalse)
    return(status);
  density=75;
  if (ch->density != (char *) NULL)
    {
      GeometryInfo
        geometry;

      (void) ParseGeometry(ch->density,&geometry);
      density=(size_t) geometry.rho;
    }
  scene=0;
  one=1;
  imageListLength=GetImageListLength(vs);
  do
  {

    if (IssRGBCompatibleColorspace(vs->colorspace) == MagickFalse)
      (void) TransformImageColorspace(vs,sRGBColorspace,sa);
    (void) WriteBlobString(vs,"\033E");  
    (void) WriteBlobString(vs,"\033*r3F");  
    (void) FormatLocaleString(buffer,MagickPathExtent,"\033*r%.20gs%.20gT",
      (double) vs->columns,(double) vs->rows);
    (void) WriteBlobString(vs,buffer);
    (void) FormatLocaleString(buffer,MagickPathExtent,"\033*t%.20gR",(double)
      density);
    (void) WriteBlobString(vs,buffer);
    (void) WriteBlobString(vs,"\033&l0E");  
    if (SetImageMonochrome(vs,sa) != MagickFalse)
      {

        bits_per_pixel=1;
      }
    else
      if (vs->storage_class == DirectClass)
        {

          bits_per_pixel=24;
          (void) WriteBlobString(vs,"\033*v6W"); 
          (void) WriteBlobByte(vs,0); 
          (void) WriteBlobByte(vs,3); 
          (void) WriteBlobByte(vs,0); 
          (void) WriteBlobByte(vs,8); 
          (void) WriteBlobByte(vs,8); 
          (void) WriteBlobByte(vs,8); 
        }
      else
        {

          bits_per_pixel=8;
          (void) WriteBlobString(vs,"\033*v6W"); 
          (void) WriteBlobByte(vs,0); 
          (void) WriteBlobByte(vs,1); 
          (void) WriteBlobByte(vs,bits_per_pixel); 
          (void) WriteBlobByte(vs,8); 
          (void) WriteBlobByte(vs,8); 
          (void) WriteBlobByte(vs,8); 
          for (i=0; i < (ssize_t) vs->colors; i++)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,
              "\033*v%da%db%dc%.20gI",
              ScaleQuantumToChar(vs->colormap[i].red),
              ScaleQuantumToChar(vs->colormap[i].green),
              ScaleQuantumToChar(vs->colormap[i].blue),(double) i);
            (void) WriteBlobString(vs,buffer);
          }
          for (one=1; i < (ssize_t) (one << bits_per_pixel); i++)
          {
            (void) FormatLocaleString(buffer,MagickPathExtent,"\033*v%.20gI",
              (double) i);
            (void) WriteBlobString(vs,buffer);
          }
        }
    option=GetImageOption(ch,"pcl:fit-to-page");
    if (IsStringTrue(option) != MagickFalse)
      (void) WriteBlobString(vs,"\033*r3A");
    else
      (void) WriteBlobString(vs,"\033*r1A");  
    (void) WriteBlobString(vs,"\033*b0Y");  
    length=(vs->columns*bits_per_pixel+7)/8;
    pixels=(unsigned char *) AcquireQuantumMemory(length+1,sizeof(*pixels));
    if (pixels == (unsigned char *) NULL)
      ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
    (void) memset(pixels,0,(length+1)*sizeof(*pixels));
    compress_pixels=(unsigned char *) NULL;
    previous_pixels=(unsigned char *) NULL;

    compression=UndefinedCompression;
    if (ch->compression != UndefinedCompression)
      compression=image_info->compression;
    switch (compression)
    {
      case NoCompression:
      {
        (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b0M");
        (void) WriteBlobString(vs,buffer);
        break;
      }
      case RLECompression:
      {
        compress_pixels=(unsigned char *) AcquireQuantumMemory(length+256,
          sizeof(*compress_pixels));
        if (compress_pixels == (unsigned char *) NULL)
          {
            pixels=(unsigned char *) RelinquishMagickMemory(pixels);
            ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
          }
        (void) memset(compress_pixels,0,(length+256)*
          sizeof(*compress_pixels));
        (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b2M");
        (void) WriteBlobString(vs,buffer);
        break;
      }
      default:
      {
        compress_pixels=(unsigned char *) AcquireQuantumMemory(3*length+256,
          sizeof(*compress_pixels));
        if (compress_pixels == (unsigned char *) NULL)
          {
            pixels=(unsigned char *) RelinquishMagickMemory(pixels);
            ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
          }
        (void) memset(compress_pixels,0,(3*length+256)*
          sizeof(*compress_pixels));
        previous_pixels=(unsigned char *) AcquireQuantumMemory(length+1,
          sizeof(*previous_pixels));
        if (previous_pixels == (unsigned char *) NULL)
          {
            compress_pixels=(unsigned char *) RelinquishMagickMemory(
              compress_pixels);
            pixels=(unsigned char *) RelinquishMagickMemory(pixels);
            ThrowWriterException(ResourceLimitError,"MemoryAllocationFailed");
          }
        (void) memset(previous_pixels,0,(length+1)*
          sizeof(*previous_pixels));
        (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b3M");
        (void) WriteBlobString(vs,buffer);
        break;
      }
    }
    for (y=0; y < (ssize_t) vs->rows; y++)
    {
      p=GetVirtualPixels(vs,0,y,vs->columns,1,sa);
      if (p == (const Quantum *) NULL)
        break;
      q=pixels;
      switch (bits_per_pixel)
      {
        case 1:
        {
          unsigned char
            bit,
            byte;


          bit=0;
          byte=0;
          for (x=0; x < (ssize_t) vs->columns; x++)
          {
            byte<<=1;
            if (GetPixelLuma(vs,p) < (QuantumRange/2.0))
              byte|=0x01;
            bit++;
            if (bit == 8)
              {
                *q++=byte;
                bit=0;
                byte=0;
              }
            p+=GetPixelChannels(vs);
          }
          if (bit != 0)
            *q++=byte << (8-bit);
          break;
        }
        case 8:
        {

          for (x=0; x < (ssize_t) vs->columns; x++)
          {
            *q++=(unsigned char) ((ssize_t) GetPixelIndex(vs,p));
            p+=GetPixelChannels(vs);
          }
          break;
        }
        case 24:
        case 32:
        {

          for (x=0; x < (ssize_t) vs->columns; x++)
          {
            *q++=ScaleQuantumToChar(GetPixelRed(vs,p));
            *q++=ScaleQuantumToChar(GetPixelGreen(vs,p));
            *q++=ScaleQuantumToChar(GetPixelBlue(vs,p));
            p+=GetPixelChannels(vs);
          }
          break;
        }
      }
      switch (compression)
      {
        case NoCompression:
        {
          (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b%.20gW",
            (double) length);
          (void) WriteBlobString(vs,buffer);
          (void) WriteBlob(vs,length,pixels);
          break;
        }
        case RLECompression:
        {
          packets=PCLPackbitsCompressImage(length,pixels,compress_pixels);
          (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b%.20gW",
            (double) packets);
          (void) WriteBlobString(vs,buffer);
          (void) WriteBlob(vs,packets,compress_pixels);
          break;
        }
        default:
        {
          if (y == 0)
            for (i=0; i < (ssize_t) length; i++)
              previous_pixels[i]=(~pixels[i]);
          packets=PCLDeltaCompressImage(length,previous_pixels,pixels,
            compress_pixels);
          (void) FormatLocaleString(buffer,MagickPathExtent,"\033*b%.20gW",
            (double) packets);
          (void) WriteBlobString(vs,buffer);
          (void) WriteBlob(vs,packets,compress_pixels);
          (void) memcpy(previous_pixels,pixels,length*
            sizeof(*pixels));
          break;
        }
      }
    }
    (void) WriteBlobString(vs,"\033*rB");  
    switch (compression)
    {
      case NoCompression:
        break;
      case RLECompression:
      {
        compress_pixels=(unsigned char *) RelinquishMagickMemory(
          compress_pixels);
        break;
      }
      default:
      {
        previous_pixels=(unsigned char *) RelinquishMagickMemory(
          previous_pixels);
        compress_pixels=(unsigned char *) RelinquishMagickMemory(
          compress_pixels);
        break;
      }
    }
    pixels=(unsigned char *) RelinquishMagickMemory(pixels);
    if (GetNextImageInList(vs) == (Image *) NULL)
      break;
    image=SyncNextImageInList(vs);
    status=SetImageProgress(vs,SaveImagesTag,scene++,imageListLength);
    if (status == MagickFalse)
      break;
  } while (ch->adjoin != MagickFalse);
  (void) WriteBlobString(vs,"\033E");
  (void) CloseBlob(vs);
  return(MagickTrue);
}

