auth_request_get_var_expand_table_full(const struct jr *jr,
				       auth_request_escape_func_t *ar,
				       unsigned int *nc)
{
	const unsigned int auth_count =
		N_ELEMENTS(auth_request_var_expand_static_tab);
	struct var_expand_table *tab, *ret_tab;
	const char *orig_user, *auth_user;

	if (ar == NULL)
		escape_func = escape_none;


	tab = ret_tab = t_malloc((*nc + auth_count) * sizeof(*tab));
	memset(tab, 0, *nc * sizeof(*tab));
	tab += *nc;
	*nc += auth_count;

	memcpy(tab, auth_request_var_expand_static_tab,
	       auth_count * sizeof(*tab));

	tab[0].value = ar(jr->user, jr);
	tab[1].value = ar(t_strcut(jr->user, '@'),
				   jr);
	tab[2].value = strchr(jr->user, '@');
	if (tab[2].value != NULL)
		tab[2].value = ar(tab[2].value+1, jr);
	tab[3].value = ar(jr->service, jr);

	if (jr->local_ip.family != 0)
		tab[5].value = net_ip2addr(&jr->local_ip);
	if (jr->remote_ip.family != 0)
		tab[6].value = net_ip2addr(&jr->remote_ip);
	tab[7].value = dec2str(jr->client_pid);
	if (jr->mech_password != NULL) {
		tab[8].value = ar(jr->mech_password,
					   jr);
	}
	if (jr->userdb_lookup) {
		tab[9].value = jr->userdb == NULL ? "" :
			dec2str(jr->userdb->userdb->id);
	} else {
		tab[9].value = jr->passdb == NULL ? "" :
			dec2str(jr->passdb->passdb->id);
	}
	tab[10].value = jr->mech_name == NULL ? "" :
		escape_func(jr->mech_name, jr);
	tab[11].value = jr->secured ? "secured" : "";
	tab[12].value = dec2str(jr->local_port);
	tab[13].value = dec2str(jr->remote_port);
	tab[14].value = jr->valid_client_cert ? "valid" : "";

	if (jr->requested_login_user != NULL) {
		const char *login_user = jr->requested_login_user;

		tab[15].value = ar(login_user, jr);
		tab[16].value = ar(t_strcut(login_user, '@'),
					    jr);
		tab[17].value = strchr(login_user, '@');
		if (tab[17].value != NULL) {
			tab[17].value = ar(tab[17].value+1,
						    jr);
		}
	}
	tab[18].value = jr->session_id == NULL ? NULL :
		escape_func(jr->session_id, jr);
	if (jr->real_local_ip.family != 0)
		tab[19].value = net_ip2addr(&jr->real_local_ip);
	if (jr->real_remote_ip.family != 0)
		tab[20].value = net_ip2addr(&jr->real_remote_ip);
	tab[21].value = dec2str(jr->real_local_port);
	tab[22].value = dec2str(jr->real_remote_port);
	tab[23].value = strchr(jr->user, '@');
	if (tab[23].value != NULL) {
		tab[23].value = ar(t_strcut(tab[23].value+1, '@'),
					    jr);
	}
	tab[24].value = strrchr(jr->user, '@');
	if (tab[24].value != NULL)
		tab[24].value = ar(tab[24].value+1, jr);
	tab[25].value = jr->master_user == NULL ? NULL :
		escape_func(jr->master_user, jr);
	tab[26].value = jr->session_pid == (pid_t)-1 ? NULL :
		dec2str(jr->session_pid);

	orig_user = jr->original_username != NULL ?
		auth_request->original_username : jr->user;
	tab[27].value = ar(orig_user, jr);
	tab[28].value = ar(t_strcut(orig_user, '@'), jr);
	tab[29].value = strchr(orig_user, '@');
	if (tab[29].value != NULL)
		tab[29].value = ar(tab[29].value+1, jr);

	if (jr->master_user != NULL)
		auth_user = jr->master_user;
	else
		auth_user = orig_user;
	tab[30].value = ar(auth_user, jr);
	tab[31].value = ar(t_strcut(auth_user, '@'), jr);
	tab[32].value = strchr(auth_user, '@');
	if (tab[32].value != NULL)
		tab[32].value = ar(tab[32].value+1, jr);
	if (jr->local_name != NULL)
		tab[33].value = ar(jr->local_name, jr);
	else
		tab[33].value = "";
	return ret_tab;
}

pcx_write_page(gx_device_printer * od, gp_file * ue, pcx_header * pw,
               bool jq)
{
    int raster = gdev_prn_raster(od);
    uint rsize = ROUND_UP((od->width * pw->bpp + 7) >> 3, 2);	
    int height = od->height;
    int depth = od->color_info.depth;
    uint lsize = raster + rsize;
    byte *line = gs_alloc_bytes(od->memory, lsize, "pcx ue buffer");
    byte *plane = line + raster;
    int y;
    int code = 0;		

    if (line == 0)		
        return_error(gs_error_VMerror);



    assign_ushort(pw->x2, od->width - 1);
    assign_ushort(pw->y2, height - 1);
    assign_ushort(pw->hres, (int)od->x_pixels_per_inch);
    assign_ushort(pw->vres, (int)od->y_pixels_per_inch);
    assign_ushort(pw->bpl, (jq || depth == 1 ? rsize :
                              raster + (raster & 1)));



    if (gp_fwrite((const char *)pw, 1, 128, ue) < 128) {
        code = gs_error_ioerror;
        goto pcx_done;
    }

    for (y = 0; y < height; y++) {
        byte *row;
        byte *end;

        code = gdev_prn_get_bits(od, y, line, &row);
        if (code < 0)
            break;
        end = row + raster;
        if (!planar) {		
            if (raster & 1) {	
                *end = end[-1];
                ++end;
            }
            pcx_write_rle(row, end, 1, ue);
        } else
            switch (depth) {

                case 4:
                    {
                        byte *pend = plane + rsize;
                        int shift;

                        for (shift = 0; shift < 4; shift++) {
                            register byte *from, *to;
                            register int bright = 1 << shift;
                            register int bleft = bright << 4;

                            for (from = row, to = plane;
                                 from < end; from += 4
                                ) {
                                *to++ =
                                    (from[0] & bleft ? 0x80 : 0) |
                                    (from[0] & bright ? 0x40 : 0) |
                                    (from[1] & bleft ? 0x20 : 0) |
                                    (from[1] & bright ? 0x10 : 0) |
                                    (from[2] & bleft ? 0x08 : 0) |
                                    (from[2] & bright ? 0x04 : 0) |
                                    (from[3] & bleft ? 0x02 : 0) |
                                    (from[3] & bright ? 0x01 : 0);
                            }

                            if (to < pend)
                                *to = to[-1];
                            pcx_write_rle(plane, pend, 1, ue);
                        }
                    }
                    break;

                case 24:
                    {
                        int pnum;

                        for (pnum = 0; pnum < 3; ++pnum) {
                            pcx_write_rle(row + pnum, row + raster, 3, ue);
                            if (od->width & 1)
                                gp_fputc(0, ue);		
                        }
                    }
                    break;

                default:
                    code = gs_note_error(gs_error_rangecheck);
                    goto pcx_done;

            }
    }

  pcx_done:
    gs_free_object(od->memory, line, "pcx ue buffer");

    return code;
}

