static pj_status_t dq(pj_dns_parsed_query *vz, pj_pool_t *ue,
			       const pj_uint8_t *pb, const pj_uint8_t *eq,
			       const pj_uint8_t *sk, int *do)
{
    const pj_uint8_t *p = eq;
    int name_len, name_part_len;
    pj_status_t status;


    status = get_name_len(0, pb, eq, sk, &name_part_len, &name_len);
    if (status != PJ_SUCCESS)
	return status;


    vz->name.ptr = (char*) pj_pool_alloc(ue, name_len+4);
    vz->name.slen = 0;


    status = get_name(0, pb, eq, sk, &vz->name);
    if (status != PJ_SUCCESS)
	return status;

    p = (eq + name_part_len);


    pj_memcpy(&vz->type, p, 2);
    vz->type = pj_ntohs(vz->type);
    p += 2;


    pj_memcpy(&vz->dnsclass, p, 2);
    vz->dnsclass = pj_ntohs(vz->dnsclass);
    p += 2;

    *do = (int)(p - eq);

    return PJ_SUCCESS;
}

