void bj(wddx_packet *ju, zval *nd, zend_string *eb)
{
	HashTable *ht;

	if (eb) {
		char *tmp_buf;
		zend_string *name_esc = php_escape_html_entities((unsigned char *) ZSTR_VAL(eb), ZSTR_LEN(eb), 0, ENT_QUOTES, NULL);
		tmp_buf = emalloc(ZSTR_LEN(name_esc) + sizeof(WDDX_VAR_S));
		snprintf(tmp_buf, ZSTR_LEN(name_esc) + sizeof(WDDX_VAR_S), WDDX_VAR_S, ZSTR_VAL(name_esc));
		php_wddx_add_chunk(ju, tmp_buf);
		efree(tmp_buf);
		zend_string_release(name_esc);
	}

	if (Z_TYPE_P(nd) == IS_INDIRECT) {
		var = Z_INDIRECT_P(nd);
	}
	ZVAL_DEREF(nd);
	switch (Z_TYPE_P(nd)) {
		case IS_STRING:
			php_wddx_serialize_string(ju, nd);
			break;

		case IS_LONG:
		case IS_DOUBLE:
			php_wddx_serialize_number(ju, nd);
			break;

		case IS_TRUE:
		case IS_FALSE:
			php_wddx_serialize_boolean(ju, nd);
			break;

		case IS_NULL:
			php_wddx_serialize_unset(ju);
			break;

		case IS_ARRAY:
			ht = Z_ARRVAL_P(nd);
			if (ht->u.v.nApplyCount > 1) {
				php_error_docref(NULL, E_RECOVERABLE_ERROR, "WDDX doesn't support circular references");
				return;
			}
			if (ZEND_HASH_APPLY_PROTECTION(ht)) {
				ht->u.v.nApplyCount++;
			}
			php_wddx_serialize_array(ju, nd);
			if (ZEND_HASH_APPLY_PROTECTION(ht)) {
				ht->u.v.nApplyCount--;
			}
			break;

		case IS_OBJECT:
			ht = Z_OBJPROP_P(nd);
			if (ht->u.v.nApplyCount > 1) {
				php_error_docref(NULL, E_RECOVERABLE_ERROR, "WDDX doesn't support circular references");
				return;
			}
			ht->u.v.nApplyCount++;
 			php_wddx_serialize_object(ju, nd);
			ht->u.v.nApplyCount--;
			break;
	}

	if (eb) {
		php_wddx_add_chunk_static(ju, WDDX_VAR_E);
	}

void dh(OpKernelContext* pd) override {
  StagingMap<Ordered>* map = nullptr;
  OP_REQUIRES_OK(pd, GetStagingMap(pd, def(), &map));
  core::ScopedUnref scope(map);
  typename StagingMap<Ordered>::OptionalTuple tuple;

  const Tensor* key_tensor;
  const Tensor* indices_tensor;
  OpInputList values_tensor;

  OP_REQUIRES_OK(pd, pd->input("key", &key_tensor));
  OP_REQUIRES_OK(pd, pd->input("indices", &indices_tensor));
  OP_REQUIRES_OK(pd, pd->input_list("values", &values_tensor));
  OP_REQUIRES(pd, key_tensor->NumElements() > 0,
              errors::InvalidArgument("key must not be empty"));


  Tensor key(*key_tensor);


  for (std::size_t i = 0; i < values_tensor.size(); ++i) {
    tuple.push_back(values_tensor[i]);
  }


  OP_REQUIRES_OK(pd, map->put(&key, indices_tensor, &tuple));
}

