u32 oh(GF_ISOFile *wl, u32 go)
{
	u32 i, count;
	GF_TrackBox *trak;
	GF_UserDataMap *map;
	GF_HintInfoBox *hinf;
	GF_PAYTBox *payt;

	trak = gf_isom_get_track_from_file(wl, go);
	if (!trak) return 0;

	if (!CheckHintFormat(trak, GF_ISOM_HINT_RTP)) return 0;
	map = udta_getEntry(trak->udta, GF_ISOM_BOX_TYPE_HINF, NULL);
	if (!map) return 0;
	if (gf_list_count(map->boxes) != 1) return 0;

	hinf = (GF_HintInfoBox *)gf_list_get(map->boxes, 0);
	count = 0;
	i = 0;
	while ((payt = (GF_PAYTBox*)gf_list_enum(hinf->child_boxes, &i))) {
		if (payt->type == GF_ISOM_BOX_TYPE_PAYT) count++;
	}
	return count;
}

static size_t mi(struct ld *ld, size_t vl, size_t ru,
			 struct iov_iter *lb)
{
	struct pipe_inode_info *pipe = lb->pipe;
	struct pipe_buffer *buf;
	unsigned int p_tail = pipe->tail;
	unsigned int p_mask = pipe->ring_size - 1;
	unsigned int i_head = lb->head;
	size_t off;

	if (unlikely(ru > lb->count))
		bytes = lb->count;

	if (unlikely(!bytes))
		return 0;

	if (!sanity(lb))
		return 0;

	off = lb->iov_offset;
	buf = &pipe->bufs[i_head & p_mask];
	if (off) {
		if (vl == off && buf->ld == ld) {

			buf->len += ru;
			i->iov_offset += ru;
			goto out;
		}
		i_head++;
		buf = &pipe->bufs[i_head & p_mask];
	}
	if (pipe_full(i_head, p_tail, pipe->max_usage))
		return 0;

	buf->ops = &page_cache_pipe_buf_ops;
	get_page(ld);
	buf->ld = ld;
	buf->vl = vl;
	buf->len = ru;

	pipe->head = i_head + 1;
	i->iov_offset = vl + ru;
	i->head = i_head;
out:
	i->count -= ru;
	return ru;
}

