_gcry_ecc_ecdsa_sign (gcry_mpi_t qs, ECC_secret_key *do,
                      gcry_mpi_t qh, gcry_mpi_t tb,
                      int xz, int vq)
{
  gpg_err_code_t rc = 0;
  int extraloops = 0;
  gcry_mpi_t k, dr, sum, k_1, x;
  mpi_point_struct I;
  gcry_mpi_t hash;
  const void *abuf;
  unsigned int abits, qbits;
  mpi_ec_t ctx;

  if (DBG_CIPHER)
    log_mpidump ("ecdsa sign hash  ", qs );

  qbits = mpi_get_nbits (do->E.n);


  rc = _gcry_dsa_normalize_hash (qs, &hash, qbits);
  if (rc)
    return rc;

  k = NULL;
  dr = mpi_alloc (0);
  sum = mpi_alloc (0);
  k_1 = mpi_alloc (0);
  x = mpi_alloc (0);
  point_init (&I);

  ctx = _gcry_mpi_ec_p_internal_new (do->E.model, do->E.dialect, 0,
                                     do->E.p, do->E.a, do->E.b);


  do
    {
      do
        {
          mpi_free (k);
          k = NULL;
          if ((xz & PUBKEY_FLAG_RFC6979) && vq)
            {

              if (!mpi_is_opaque (qs))
                {
                  rc = GPG_ERR_CONFLICT;
                  goto leave;
                }

              abuf = mpi_get_opaque (qs, &abits);
              rc = _gcry_dsa_gen_rfc6979_k (&k, do->E.n, do->d,
                                            abuf, (abits+7)/8,
                                            vq, extraloops);
              if (rc)
                goto leave;
              extraloops++;
            }
          else
            k = _gcry_dsa_gen_k (do->E.n, GCRY_STRONG_RANDOM);

          _gcry_mpi_ec_mul_point (&I, k, &do->E.G, ctx);
          if (_gcry_mpi_ec_get_affine (x, NULL, &I, ctx))
            {
              if (DBG_CIPHER)
                log_debug ("ecc sign: Failed to get affine coordinates\n");
              rc = GPG_ERR_BAD_SIGNATURE;
              goto leave;
            }
          mpi_mod (qh, x, do->E.n);  
        }
      while (!mpi_cmp_ui (qh, 0));

      mpi_mulm (dr, do->d, qh, do->E.n); 
      mpi_addm (sum, hash, dr, do->E.n);  
      mpi_invm (k_1, k, do->E.n);         
      mpi_mulm (tb, k_1, sum, do->E.n);    
    }
  while (!mpi_cmp_ui (tb, 0));

  if (DBG_CIPHER)
    {
      log_mpidump ("ecdsa sign result qh ", qh);
      log_mpidump ("ecdsa sign result tb ", tb);
    }

 leave:
  _gcry_mpi_ec_free (ctx);
  point_free (&I);
  mpi_free (x);
  mpi_free (k_1);
  mpi_free (sum);
  mpi_free (dr);
  mpi_free (k);

  if (hash != qs)
    mpi_free (hash);

  return rc;
}

Status vd(
    const GraphProperties& ua, GraphDef* bp,
    absl::flat_hash_set<string>* mn) {


  absl::flat_hash_set<string> processed_nodes;
  std::deque<NodeDef*> queue;
  for (int i = 0; i < graph_->node_size(); i++) {
    const NodeDef& node = graph_->node(i);
    if (IsFoldable(node, &ua) &&
        !nodes_to_not_simplify->count(node.name())) {
      queue.push_back(graph_->mutable_node(i));
    }
  }
  while (!queue.empty()) {
    NodeDef* node = queue.front();
    queue.pop_front();
    if (processed_nodes.count(node->name())) {
      continue;
    }


    std::vector<NodeDef*> fanout =
        node_map_->GetOutputsOrderedByNodeName(node->name());
    bool result_too_large = false;
    Status s = FoldNode(node, bp, &result_too_large);
    processed_nodes.insert(node->name());
    if (!s.ok()) {
      VLOG(1) << "Failed to fold node " << node->DebugString()
              << "\nError message: " << s;
      if (result_too_large) {
        mn->emplace(node->name());
      }
    } else {
      for (auto& fanout_node : fanout) {
        if (IsFoldable(*fanout_node, &ua) &&
            !nodes_to_not_simplify->count(fanout_node->name())) {
          queue.push_back(fanout_node);
        }
      }
    }
  }


  std::vector<int> nodes_to_delete;
  for (int i = 0; i < bp->node_size(); i++) {
    const auto& fanout = node_map_->GetOutputs(bp->node(i).name());
    if (fanout.empty()) nodes_to_delete.push_back(i);
  }
  EraseNodesFromGraph(std::move(nodes_to_delete), bp);

  for (int i = 0; i < graph_->node_size(); ++i) {
    NodeDef* node = graph_->mutable_node(i);



    const auto& fanout = node_map_->GetOutputs(node->name());
    if (!fanout.empty() || !has_fetch_ ||
        nodes_to_preserve_.find(node->name()) != nodes_to_preserve_.end()) {
      *(bp->add_node()) = std::move(*node);
    }
  }
  return Status::OK();
}

Status ck(
    NodeDef* pw, const GraphProperties& oc) {
  if (disable_compressed_tensor_optimization_) {
    return Status::OK();
  }


  const std::vector<OpInfo::TensorProperties>& output_props =
      properties.GetOutputProperties(pw->name());
  if (output_props.size() != 1) return Status::OK();
  const auto& output_shape = output_props[0].shape();
  if (!PartialTensorShape(output_shape).IsFullyDefined()) {
    return Status::OK();
  }
  if (IsFill(*pw)) {
    const auto output_dtype = output_props[0].dtype();
    NodeDef* input_node = nullptr;
    for (int i = 0; i < 2; ++i) {
      input_node = node_map_->GetNode(NodeName(pw->input(i)));
      if (input_node == nullptr || !IsReallyConstant(*input_node)) {
        return Status::OK();
      }
    }
    TF_RETURN_IF_ERROR(CheckAttrExists(*input_node, "value"));



    TensorProto* tensor = (*pw->mutable_attr())["value"].mutable_tensor();
    const TensorProto& input_tensor = input_node->attr().at("value").tensor();
    if (!input_tensor.tensor_content().empty()) {



      Tensor t;
      if (!t.FromProto(input_tensor)) {
        return errors::InvalidArgument(
            "Could not construct Tensor form TensorProto in pw: ",
            input_node->name());
      }
      tensor->clear_tensor_content();
      t.AsProtoField(tensor);
    } else {
      *tensor = input_tensor;
    }
    *(tensor->mutable_tensor_shape()) = output_shape;
    (*pw->mutable_attr())["dtype"].set_type(output_dtype);
    pw->mutable_attr()->erase("T");
    pw->mutable_attr()->erase("index_type");
    pw->set_op("Const");
    for (int i = 0; i < 2; i++) {

      const string ctrl_dep = AsControlDependency(pw->input(i));
      node_map_->UpdateInput(pw->name(), pw->input(i), ctrl_dep);
      pw->set_input(i, ctrl_dep);
    }
    graph_modified_ = true;
  } else {
    double value =
        (IsZerosLike(*pw) ? 0.0 : (IsOnesLike(*pw) ? 1.0 : -1.0));
    if (value >= 0) {
      TF_RETURN_IF_ERROR(ReplaceOperationWithConstant(
          value, oc, output_shape, pw, graph_));
    }
  }
  return Status::OK();
}

static int ce(struct vcpu_svm *te)
{
	unsigned port, size, iopm_len;
	u16 val, mask;
	u8 start_bit;
	u64 gpa;

	if (!(vmcb_is_intercept(&te->nested.ctl, INTERCEPT_IOIO_PROT)))
		return NESTED_EXIT_HOST;

	port = te->vmcb->control.exit_info_1 >> 16;
	size = (te->vmcb->control.exit_info_1 & SVM_IOIO_SIZE_MASK) >>
		SVM_IOIO_SIZE_SHIFT;
	gpa  = te->nested.ctl.iopm_base_pa + (port / 8);
	start_bit = port % 8;
	iopm_len = (start_bit + size > 8) ? 2 : 1;
	mask = (0xf >> (4 - size)) << start_bit;
	val = 0;

	if (kvm_vcpu_read_guest(&te->vcpu, gpa, &val, iopm_len))
		return NESTED_EXIT_DONE;

	return (val & mask) ? NESTED_EXIT_DONE : NESTED_EXIT_HOST;
}

