	    if (p >= it && *p == '\n')
		--p;
	    if (p >= it && *p == '\r')
		--p;
	    *(p + 1) = NUL;
	}
	if (km == ACTION_SHOW_ALL)
	{
	    sprintf((char *)IObuff, "%3ld: ", qt);	
	    msg_puts((char *)IObuff);
	    sprintf((char *)IObuff, "%4ld", *jo);	

	    msg_puts_attr((char *)IObuff, HL_ATTR(HLF_N));
	    msg_puts(" ");
	}
	msg_prt_line(it, FALSE);
	out_flush();			


	if (got_int || us != FIND_DEFINE || p < it || *p != '\\')
	    break;

	if (tq != NULL)
	{
	    if (vim_fgets(it, LSIZE, tq)) 
		break;
	    ++*jo;
	}
	else
	{
	    if (++*jo > curbuf->b_ml.ml_line_count)
		break;
	    it = ml_get(*jo);
	}
	msg_putchar('\n');
    }
}

Status gn(const GraphProperties& zw,
                                      bool du,
                                      GraphDef* uy,
                                      NodeDef* rx) {
  if (!use_shape_info || rx->op() != "ReverseV2") return Status::OK();
  Tensor axis;
  if (properties.HasInputProperties(rx->name()) &&
      GetTensorFromConstNode(rx->input(1), &axis)) {
    const auto& shape = properties.GetInputProperties(rx->name())[0].shape();
    if (shape.unknown_rank()) return Status::OK();
    std::set<int> target_axes;
    for (int j = 0; j < axis.NumElements(); ++j) {

      if (axis.dtype() == DT_INT64) {
        target_axes.insert((axis.vec<int64_t>()(j) + shape.dim_size()) %
                           shape.dim_size());
      } else {
        target_axes.insert((axis.vec<int>()(j) + shape.dim_size()) %
                           shape.dim_size());
      }
    }





    bool replaceable = true;
    for (int j = 0; replaceable && j < shape.dim_size(); ++j) {
      replaceable &=
          shape.dim(j).size() == 1 || target_axes.find(j) == target_axes.end();
    }
    if (replaceable) {
      ReplaceOperationWithIdentity(0, zw, rx, uy);
    }
  }
  return Status::OK();
}

GF_Err nx(GF_ISOFile *oh, const char **nk, u32 *om)
{
	GF_UserDataMap *map;
	GF_HintTrackInfoBox *hnti;
	GF_RTPBox *rtp;
	*om = 0;
	*nk = NULL;
	if (!movie || !movie->moov) return GF_BAD_PARAM;

	if (!movie->moov->udta) return GF_OK;


	map = udta_getEntry(oh->moov->udta, GF_ISOM_BOX_TYPE_HNTI, NULL);
	if (!map) return GF_OK;


	if (gf_list_count(map->boxes) != 1) return GF_ISOM_INVALID_FILE;
