  (void) LogMagickEvent(CoderEvent,GetMagickModule(),
     "    read_user_chunk: found %c%c%c%c chunk",
       hz->name[0],hz->name[1],hz->name[2],hz->name[3]);

  if (hz->name[0]  == 101 &&
      (hz->name[1] ==  88 || hz->name[1] == 120 ) &&
      hz->name[2] ==   73 &&
      hz-> name[3] == 102)
    {


      PNGErrorInfo
        *error_info;

      StringInfo
        *profile;

      unsigned char
        *p;

      png_byte
        *s;

      size_t
        i;

      (void) LogMagickEvent(CoderEvent,GetMagickModule(),
        " recognized eXIf|exIf chunk");

      image=(Image *) png_get_user_chunk_ptr(is);

      error_info=(PNGErrorInfo *) png_get_error_ptr(is);

      profile=BlobToStringInfo((const void *) NULL,hz->size+6);

      if (profile == (StringInfo *) NULL)
        {
          (void) ThrowMagickException(error_info->exception,GetMagickModule(),
            ResourceLimitError,"MemoryAllocationFailed","`%s'",
            image->filename);
          return(-1);
        }
      p=GetStringInfoDatum(profile);

      if (*p != 'E')
        {

          *p++ ='E';
          *p++ ='x';
          *p++ ='i';
          *p++ ='f';
          *p++ ='\0';
          *p++ ='\0';
        }
      else
        {
          if (p[1] != 'x' || p[2] != 'i' || p[3] != 'f' ||
              p[4] != '\0' || p[5] != '\0')
            {

              profile=DestroyStringInfo(profile);
              return(-1);
            }
         }


      s=chunk->data;
      for (i=0; i<chunk->size; i++)
        *p++ = *s++;

      error_info=(PNGErrorInfo *) png_get_error_ptr(is);
      (void) SetImageProfile(image,"exif",profile,
        error_info->exception);

      profile=DestroyStringInfo(profile);

      return(1);
    }


  if (hz->name[0] == 118 &&
      hz->name[1] == 112 &&
      hz->name[2] ==  65 &&
      hz->name[3] == 103)
    {


      if (hz->size != 9)
        return(-1); 

      if (hz->data[8] != 0)
        return(0);  

      image=(Image *) png_get_user_chunk_ptr(is);

      image->page.width=(size_t) ((hz->data[0] << 24) |
         (hz->data[1] << 16) | (hz->data[2] << 8) | hz->data[3]);

      image->page.height=(size_t) ((hz->data[4] << 24) |
         (hz->data[5] << 16) | (hz->data[6] << 8) | hz->data[7]);

      return(1);
    }


  if (hz->name[0] ==  99 &&
      hz->name[1] ==  97 &&
      hz->name[2] ==  78 &&
      hz->name[3] == 118)
    {


      if (hz->size != 16)
        return(-1); 

      image=(Image *) png_get_user_chunk_ptr(is);

      image->page.width=(size_t) ((hz->data[0] << 24) |
         (hz->data[1] << 16) | (hz->data[2] << 8) | hz->data[3]);

      image->page.height=(size_t) ((hz->data[4] << 24) |
         (hz->data[5] << 16) | (hz->data[6] << 8) | hz->data[7]);

      image->page.x=(size_t) ((hz->data[8] << 24) |
         (hz->data[9] << 16) | (hz->data[10] << 8) | hz->data[11]);

      image->page.y=(size_t) ((hz->data[12] << 24) |
         (hz->data[13] << 16) | (hz->data[14] << 8) | hz->data[15]);

      return(1);
    }

  return(0); 
}

void tv(OpKernelContext* yt) override {

  OpInputList ragged_nested_splits_in;
  OP_REQUIRES_OK(yt, yt->input_list("rt_nested_splits",
                                              &ragged_nested_splits_in));
  const int ragged_nested_splits_len = ragged_nested_splits_in.size();
  RaggedTensorVariant batched_ragged_input;

  batched_ragged_input.set_values(yt->input(ragged_nested_splits_len));
  batched_ragged_input.mutable_nested_splits()->reserve(
      ragged_nested_splits_len);
  for (int i = 0; i < ragged_nested_splits_len; i++) {
    batched_ragged_input.append_splits(ragged_nested_splits_in[i]);
  }

  if (!batched_input_) {

    Tensor* encoded_scalar;
    OP_REQUIRES_OK(yt, yt->allocate_output(0, TensorShape({}),
                                                     &encoded_scalar));
    encoded_scalar->scalar<Variant>()() = std::move(batched_ragged_input);
    return;
  }


  std::vector<RaggedTensorVariant> unbatched_ragged_input;
  auto batched_splits_top_vec =
      batched_ragged_input.splits(0).vec<SPLIT_TYPE>();
  int num_components = batched_splits_top_vec.size() - 1;
  OP_REQUIRES(yt, num_components >= 0,
              errors::Internal("Invalid split argument."));
  OP_REQUIRES_OK(yt, UnbatchRaggedZerothDim<VALUE_TYPE, SPLIT_TYPE>(
                              batched_ragged_input, &unbatched_ragged_input));


  Tensor* encoded_vector;
  int output_size = unbatched_ragged_input.size();
  OP_REQUIRES_OK(yt,
                 yt->allocate_output(0, TensorShape({output_size}),
                                          &encoded_vector));
  auto encoded_vector_t = encoded_vector->vec<Variant>();
  for (int i = 0; i < output_size; i++) {
    encoded_vector_t(i) = unbatched_ragged_input[i];
  }
}

Status vw(
    const Node* ur, InferenceContext* at) {
  TF_RETURN_IF_ERROR(AddNodeInternal(ur, at));
  InferenceContext* node_context = CHECK_NOTNULL(GetContext(ur));

  if (StringPiece(ur->type_string()) == kArgOp) {




    int index;
    TF_RETURN_IF_ERROR(GetNodeAttr(AttrSlice(ur->def()), "index", &index));

    if (index < 0 || at->num_inputs() <= index) {
      return errors::Internal(
          "Function instantiation included invalid input index: ", index,
          " not in [0, ", at->num_inputs(), ").");
    }



    if (at->input(index).SameHandle(ShapeHandle())) {
      VLOG(1) << "Function instantiation has undefined input shape at "
              << "index: " << index << " in the outer inference context.";
      node_context->set_output(0, node_context->UnknownShape());
    } else {
      node_context->set_output(0, at->input(index));
    }

    auto* resource = at->input_handle_shapes_and_types(index);
    if (resource) {
      node_context->set_output_handle_shapes_and_types(0, *resource);
    }
  } else if (StringPiece(ur->type_string()) == kRetvalOp) {




    int index;
    TF_RETURN_IF_ERROR(GetNodeAttr(AttrSlice(ur->def()), "index", &index));

    if (index < 0 || at->num_outputs() <= index) {
      return errors::Internal(
          "Function instantiation included invalid output index: ", index,
          " not in [0, ", at->num_outputs(), ").");
    }



    ShapeHandle handle;
    TensorShapeProto proto;
    node_context->ShapeHandleToProto(node_context->input(0), &proto);
    TF_RETURN_IF_ERROR(at->MakeShapeFromShapeProto(proto, &handle));
    at->set_output(index, handle);

    auto* resource = node_context->input_handle_shapes_and_types(0);
    if (resource) {
      at->set_output_handle_shapes_and_types(index, *resource);
    }
  }

  return Status::OK();
}

bool jk(GraphProperties* ia,
                                       GraphDef* fi,
                                       NodeDef* wy) {






















  const bool is_add = IsAdd(*wy);
  const bool is_mul = IsMul(*wy);
  const bool is_sub = IsSub(*wy);
  const bool is_div = IsDiv(*wy);
  if (!(is_add || is_sub || is_mul || is_div)) return false;
  const bool is_symmetric = is_add || is_mul;

  ConstantPushDownContext ctx;
  if (!PrepareConstantPushDown(*wy, *ia,
                               false, &ctx)) {
    return false;
  }


  const bool is_child_add = IsAdd(*ctx.op_child);
  const bool is_child_mul = IsMul(*ctx.op_child);
  const bool is_child_sub = IsSub(*ctx.op_child);
  const bool is_child_div = IsDiv(*ctx.op_child);
  const bool is_add_sub = (is_add || is_sub) && (is_child_add || is_child_sub);
  const bool is_mul_div = (is_mul || is_div) && (is_child_mul || is_child_div);
  if (!is_add_sub && !is_mul_div) {
    return false;
  }
  const bool is_child_symmetric = is_child_add || is_child_mul;

  if (!CheckAttrExists(*wy, "T").ok()) return false;
  DataType dtype = wy->attr().at("T").type();
  if (!(is_symmetric && is_child_symmetric) &&
      !(DataTypeIsFloating(dtype) || DataTypeIsComplex(dtype))) {
    return false;
  }

  const NodeDef* y_node =
      ctx.left_leaf_is_const ? ctx.left_leaf : ctx.right_leaf;
  if (!IsReallyConstant(*y_node) && !ctx.parent_input_props->empty() &&
      !ctx.op_child_input_props->empty()) {



    const PartialTensorShape c_shape(
        (*ctx.parent_input_props)[ctx.left_child_is_const ? 0 : 1].shape());
    const PartialTensorShape x_shape(
        (*ctx.op_child_input_props)[ctx.left_leaf_is_const ? 0 : 1].shape());

    if (c_shape.IsFullyDefined() && x_shape.IsFullyDefined() &&
        c_shape.num_elements() > x_shape.num_elements()) {
      return false;
    } else if (!c_shape.unknown_rank() && !x_shape.unknown_rank() &&
               c_shape.dims() > 0) {
      for (int idx = 0; idx < std::min(x_shape.dims(), c_shape.dims()); ++idx) {
        if (x_shape.dim_size(idx) >= 0 &&
            c_shape.dim_size(idx) > x_shape.dim_size(idx)) {
          return false;
        }
      }
    }
  }


  const string input_x =
      ctx.left_leaf_is_const ? ctx.op_child->input(1) : ctx.op_child->input(0);
  const string input_y = input_x == ctx.op_child->input(0)
                             ? ctx.op_child->input(1)
                             : ctx.op_child->input(0);
  const string input_c =
      ctx.left_child_is_const ? wy->input(0) : wy->input(1);
  const string input_op =
      ctx.left_child_is_const ? wy->input(1) : wy->input(0);
  VLOG(1) << "input_c = " << input_c << "\ninput_x = " << input_x;


  node_map_->UpdateInput(wy->name(), input_c, input_x);
  node_map_->AddOutput(input_c, ctx.op_child->name());
  if (input_x != input_y) {
    node_map_->RemoveOutput(input_x, ctx.op_child->name());
  }
  ia->ClearInputProperties(wy->name());
  ia->ClearInputProperties(ctx.op_child->name());

  if (is_symmetric && is_child_symmetric) {






    wy->set_input(0, input_x);
    wy->set_input(1, input_op);
    ctx.op_child->set_input(0, input_c);
    ctx.op_child->set_input(1, input_y);
  } else {

















    auto is_leaf_negated = [&](const bool is_right_leaf) -> bool {
      bool leaf_negated = !is_child_symmetric && is_right_leaf;
      bool child_negated = !is_symmetric && (ctx.left_child_is_const);
      return leaf_negated != child_negated;
    };
    const string symmetric_op = (is_add || is_sub) ? "Add" : "Mul";
    const string nonsymmetric_op = (is_add || is_sub) ? "Sub" : "Div";
    bool neg_c = !is_symmetric && !ctx.left_child_is_const;
    bool neg_x = is_leaf_negated(ctx.left_leaf_is_const);
    bool neg_y = is_leaf_negated(!ctx.left_leaf_is_const);

    wy->set_op((neg_x || (neg_c && neg_y)) ? nonsymmetric_op : symmetric_op);
    wy->set_input(0, neg_x ? input_op : input_x);
    wy->set_input(1, neg_x ? input_x : input_op);

    ctx.op_child->set_op(neg_c != neg_y ? nonsymmetric_op : symmetric_op);
    ctx.op_child->set_input(0, neg_c ? input_y : input_c);
    ctx.op_child->set_input(1, neg_c ? input_c : input_y);
  }
  return true;
}

