static int hq(struct alloc_chunk_ctl *em,
				      struct btrfs_device_info *rw)
{

	int data_stripes;


	ctl->stripe_size = div_u64(rw[em->ndevs - 1].max_avail,
				   em->dev_stripes);
	ctl->num_stripes = em->ndevs * em->dev_stripes;


	data_stripes = (em->num_stripes - em->nparity) / em->ncopies;


	if (em->stripe_size * data_stripes > em->max_chunk_size) {

		ctl->stripe_size = min(round_up(div_u64(em->max_chunk_size,
							data_stripes), SZ_16M),
				       em->stripe_size);
	}


	ctl->stripe_size = round_down(em->stripe_size, BTRFS_STRIPE_LEN);
	ctl->chunk_size = em->stripe_size * data_stripes;

	return 0;
}

bool cm(GraphDef* rv, NodeDef* zl) {
  const string axis_node_name = OptimizedNodeName(*zl, "_const_axis");
  if (!IsPack(*zl) || NumNonControlInputs(*zl) != 1 ||
      node_map_->NodeExists(axis_node_name)) {
    return false;
  }



  if (feed_nodes_.find(NodeName(zl->input(0))) != feed_nodes_.end()) {
    return false;
  }


  Tensor axis_t(DT_INT32, TensorShape({}));
  const int axis =
      zl->attr().count("axis") == 0 ? 0 : zl->attr().at("axis").i();
  NodeDef new_node;
  if (!SetTensorValue(DT_INT32, axis, &axis_t).ok() ||
      !CreateNodeDef(axis_node_name, TensorValue(&axis_t), &new_node).ok()) {
    return false;
  }
  NodeDef* axis_node = rv->add_node();
  *axis_node = std::move(new_node);
  axis_node->set_name(axis_node_name);
  node_map_->AddNode(axis_node->name(), axis_node);

  const string ctrl_dep = ConstantFolding::AddControlDependency(
      zl->input(0), rv, node_map_.get());
  axis_node->add_input(ctrl_dep);
  axis_node->set_device(zl->device());
  node_map_->AddOutput(NodeName(zl->input(0)), axis_node->name());
  zl->set_op("ExpandDims");
  if (zl->attr().count("axis") != 0) {
    zl->mutable_attr()->erase("axis");
  }
  if (zl->attr().count("N") != 0) {
    zl->mutable_attr()->erase("N");
  }
  (*zl->mutable_attr())["Tdim"].set_type(DT_INT32);
  zl->add_input(axis_node->name());
  node_map_->AddOutput(axis_node->name(), zl->name());
  if (zl->input_size() > 2) {
    zl->mutable_input()->SwapElements(1, zl->input_size() - 1);
  }
  return true;
}

cmdline_insert_reg(int *gotesc xb)
{
    int		i;
    int		c;

#ifdef USE_ON_FLY_SCROLL
    dont_scroll = TRUE;	
#endif
    putcmdline('"', TRUE);
    ++no_mapping;
    ++allow_keys;
    i = c = plain_vgetc();	
    if (i == Ctrl_O)
	i = Ctrl_R;		
    if (i == Ctrl_R)
	c = plain_vgetc();	
    extra_char = NUL;
    --no_mapping;
    --allow_keys;
#ifdef FEAT_EVAL

    new_cmdpos = -1;
    if (c == '=')
    {
	if (ccline.cmdfirstc == '='  
		|| cmdline_star > 0) 
	{
	    beep_flush();
	    c = ESC;
	}
	else
	    c = get_expr_register();
    }
#endif
    if (c != ESC)	    
    {
	cmdline_paste(c, i == Ctrl_R, FALSE);

#ifdef FEAT_EVAL


	if (aborting())
	{
	    *gotesc = TRUE;  

	    return GOTO_NORMAL_MODE;
	}
#endif
	KeyTyped = FALSE;	
#ifdef FEAT_EVAL
	if (new_cmdpos >= 0)
	{

	    if (new_cmdpos > ccline.cmdlen)
		ccline.cmdpos = ccline.cmdlen;
	    else
		ccline.cmdpos = new_cmdpos;
	}
#endif
    }

    redrawcmd();


    return CMDLINE_NOT_CHANGED;
}

gopherToHTML(GopherStateData * oc, char *ks, int ns)
{
    char *pos = ks;
    char *lpos = NULL;
    char *tline = NULL;
    LOCAL_ARRAY(char, line, TEMP_BUF_SIZE);
    LOCAL_ARRAY(char, tmpbuf, TEMP_BUF_SIZE);
    char *name = NULL;
    char *selector = NULL;
    char *host = NULL;
    char *port = NULL;
    char *escaped_selector = NULL;
    const char *icon_url = NULL;
    char gtype;
    StoreEntry *entry = NULL;

    memset(tmpbuf, '\0', TEMP_BUF_SIZE);
    memset(line, '\0', TEMP_BUF_SIZE);

    entry = oc->entry;

    if (oc->conversion == GopherStateData::HTML_INDEX_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "Gopher Index %s", html_url);
        storeAppendPrintf(entry,
                          "<p>This is a searchable Gopher index. Use the search\n"
                          "function of your browser to enter search terms.\n"
                          "<ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        oc->HTML_header_added = 1;

        return;
    }

    if (oc->conversion == GopherStateData::HTML_CSO_PAGE) {
        char *html_url = html_quote(entry->url());
        gopherHTMLHeader(entry, "CSO Search of %s", html_url);
        storeAppendPrintf(entry,
                          "<P>A CSO database usually contains a phonebook or\n"
                          "directory.  Use the search function of your browser to enter\n"
                          "search terms.</P><ISINDEX>\n");
        gopherHTMLFooter(entry);

        entry->flush();
        oc->HTML_header_added = 1;

        return;
    }

    String outbuf;

    if (!gopherState->HTML_header_added) {
        if (oc->conversion == GopherStateData::HTML_CSO_RESULT)
            gopherHTMLHeader(entry, "CSO Search Result", NULL);
        else
            gopherHTMLHeader(entry, "Gopher Menu", NULL);

        outbuf.append ("<PRE>");

        oc->HTML_header_added = 1;

        oc->HTML_pre = 1;
    }

    while (pos < ks + ns) {
        int llen;
        int left = ns - (pos - ks);
        lpos = (char *)memchr(pos, '\n', left);
        if (lpos) {
            ++lpos;             
            llen = lpos - pos;
        } else {
            llen = left;
        }
        if (oc->ns + llen >= TEMP_BUF_SIZE) {
            debugs(10, DBG_IMPORTANT, "GopherHTML: Buffer overflow. Lost some data on URL: " << entry->url()  );
            llen = TEMP_BUF_SIZE - oc->ns - 1;
            oc->overflowed = true; 
        }
        if (!lpos) {



            memcpy(oc->buf + oc->ns, pos, llen);
            oc->ns += llen;
            break;
        }
        if (oc->ns != 0) {

            memcpy(line, oc->buf, oc->ns);
            memcpy(line + oc->ns, pos, llen);
            llen += oc->ns;
            oc->ns = 0;
        } else {
            memcpy(line, pos, llen);
        }
        line[llen + 1] = '\0';

        pos = lpos;



        if (*line == '.') {

            memset(line, '\0', TEMP_BUF_SIZE);
            continue;
        }

        switch (oc->conversion) {

        case GopherStateData::HTML_INDEX_RESULT:

        case GopherStateData::HTML_DIR: {
            tline = line;
            gtype = *tline;
            ++tline;
            name = tline;
            selector = strchr(tline, TAB);

            if (selector) {
                *selector = '\0';
                ++selector;
                host = strchr(selector, TAB);

                if (host) {
                    *host = '\0';
                    ++host;
                    port = strchr(host, TAB);

                    if (port) {
                        char *junk;
                        port[0] = ':';
                        junk = strchr(host, TAB);

                        if (junk)
                            *junk++ = 0;    
                        else {
                            junk = strchr(host, '\r');

                            if (junk)
                                *junk++ = 0;    
                            else {
                                junk = strchr(host, '\n');

                                if (junk)
                                    *junk++ = 0;    
                            }
                        }

                        if ((port[1] == '0') && (!port[2]))
                            port[0] = 0;    
                    }


                    escaped_selector = xstrdup(rfc1738_escape_part(selector));

                    switch (gtype) {

                    case GOPHER_DIRECTORY:
                        icon_url = mimeGetIconURL("internal-menu");
                        break;

                    case GOPHER_HTML:

                    case GOPHER_FILE:
                        icon_url = mimeGetIconURL("internal-text");
                        break;

                    case GOPHER_INDEX:

                    case GOPHER_CSO:
                        icon_url = mimeGetIconURL("internal-index");
                        break;

                    case GOPHER_IMAGE:

                    case GOPHER_GIF:

                    case GOPHER_PLUS_IMAGE:
                        icon_url = mimeGetIconURL("internal-image");
                        break;

                    case GOPHER_SOUND:

                    case GOPHER_PLUS_SOUND:
                        icon_url = mimeGetIconURL("internal-sound");
                        break;

                    case GOPHER_PLUS_MOVIE:
                        icon_url = mimeGetIconURL("internal-movie");
                        break;

                    case GOPHER_TELNET:

                    case GOPHER_3270:
                        icon_url = mimeGetIconURL("internal-telnet");
                        break;

                    case GOPHER_BIN:

                    case GOPHER_MACBINHEX:

                    case GOPHER_DOSBIN:

                    case GOPHER_UUENCODED:
                        icon_url = mimeGetIconURL("internal-binary");
                        break;

                    case GOPHER_INFO:
                        icon_url = NULL;
                        break;

                    case GOPHER_WWW:
                        icon_url = mimeGetIconURL("internal-link");
                        break;

                    default:
                        icon_url = mimeGetIconURL("internal-unknown");
                        break;
                    }

                    memset(tmpbuf, '\0', TEMP_BUF_SIZE);

                    if ((gtype == GOPHER_TELNET) || (gtype == GOPHER_3270)) {
                        if (strlen(escaped_selector) != 0)
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, escaped_selector, rfc1738_escape_part(host),
                                     *port ? ":" : "", port, html_quote(name));
                        else
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"telnet:
                                     icon_url, rfc1738_escape_part(host), *port ? ":" : "",
                                     port, html_quote(name));

                    } else if (gtype == GOPHER_INFO) {
                        snprintf(tmpbuf, TEMP_BUF_SIZE, "\t%s\n", html_quote(name));
                    } else {
                        if (strncmp(selector, "GET /", 5) == 0) {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"http:
                                     icon_url, host, rfc1738_escape_unescaped(selector + 5), html_quote(name));
                        } else if (gtype == GOPHER_WWW) {
                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"%s\">%s</A>\n",
                                     icon_url, rfc1738_escape_unescaped(selector), html_quote(name));
                        } else {

                            snprintf(tmpbuf, TEMP_BUF_SIZE, "<IMG border=\"0\" SRC=\"%s\"> <A HREF=\"gopher:
                                     icon_url, host, gtype, escaped_selector, html_quote(name));
                        }
                    }

                    safe_free(escaped_selector);
                    outbuf.append(tmpbuf);
                } else {
                    memset(line, '\0', TEMP_BUF_SIZE);
                    continue;
                }
            } else {
                memset(line, '\0', TEMP_BUF_SIZE);
                continue;
            }

            break;
            }           

        case GopherStateData::HTML_CSO_RESULT: {
            if (line[0] == '-') {
                int code, recno;
                char *s_code, *s_recno, *result;

                s_code = strtok(line + 1, ":\n");
                s_recno = strtok(NULL, ":\n");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                recno = atoi(s_recno);

                if (code != 200)
                    break;

                if (oc->cso_recno != recno) {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>Record# %d<br><i>%s</i></H2>\n<PRE>", recno, html_quote(result));
                    oc->cso_recno = recno;
                } else {
                    snprintf(tmpbuf, TEMP_BUF_SIZE, "%s\n", html_quote(result));
                }

                outbuf.append(tmpbuf);
                break;
            } else {
                int code;
                char *s_code, *result;

                s_code = strtok(line, ":");
                result = strtok(NULL, "\n");

                if (!result)
                    break;

                code = atoi(s_code);

                switch (code) {

                case 200: {


                    break;
                }

                case 102:   

                case 501:   

                case 502: { 

                    snprintf(tmpbuf, TEMP_BUF_SIZE, "</PRE><HR noshade size=\"1px\"><H2>%s</H2>\n<PRE>", html_quote(result));
                    outbuf.append(tmpbuf);
                    break;
                }

                }
            }

            break;
            }           
        default:
            break;      

        }           

    }               

    if (outbuf.size() > 0) {
        entry->append(outbuf.rawBuf(), outbuf.size());

        entry->flush();
    }

    outbuf.clean();
    return;
}

Status kf(Cluster* un, const GrapplerItem& jd,
                                 GraphDef* ma) {


  port::ScopedFlushDenormal flush;
  port::ScopedSetRound round(FE_TONEAREST);
  nodes_to_preserve_ = item.NodesToPreserve();
  for (const auto& feed : item.feed) {
    feed_nodes_.insert(NodeName(feed.first));
  }

  if (cpu_device_ == nullptr) {
    owned_device_.reset(new DeviceSimple());
    cpu_device_ = owned_device_.get();
  }

  graph_contains_assign_or_inplace_op_ = false;
  for (const NodeDef& node : item.graph.node()) {
    if (ModifiesInputsInPlace(node) || HasRefInput(node)) {
      graph_contains_assign_or_inplace_op_ = true;
      break;
    }
  }

  has_fetch_ = !item.fetch.empty();
  GrapplerItem item_to_optimize = jd;
  GraphProperties properties(item_to_optimize);



  const bool assume_valid_feeds = opt_level_ == RewriterConfig::AGGRESSIVE;
  if (!properties
           .InferStatically(assume_valid_feeds,
                            false,
                            false,
                            true)
           .ok()) {
    properties.Clear();
  }

  *ma = GraphDef();
  item_to_optimize.graph.Swap(ma);
  int64_t node_count;

  do {
    GRAPPLER_RETURN_IF_DEADLINE_EXCEEDED();
    graph_modified_ = false;
    item_to_optimize.graph.Swap(ma);
    node_count = item_to_optimize.graph.node_size();
    TF_RETURN_IF_ERROR(RunOptimizationPass(un, &item_to_optimize,
                                           &properties, ma));
  } while (graph_modified_ || ma->node_size() != node_count);
  *ma->mutable_library() = item.graph.library();
  *ma->mutable_versions() = item.graph.versions();

  return Status::OK();
}

static int nd(VncState *zt, uint8_t *ow, size_t lc)
{
    int i;
    uint16_t limit;
    VncDisplay *vd = zt->vd;

    if (ow[0] > 3) {
        update_displaychangelistener(&vd->dcl, VNC_REFRESH_INTERVAL_BASE);
    }

    switch (ow[0]) {
    case VNC_MSG_CLIENT_SET_PIXEL_FORMAT:
        if (lc == 1)
            return 20;

        set_pixel_format(zt, read_u8(ow, 4), read_u8(ow, 5),
                         read_u8(ow, 6), read_u8(ow, 7),
                         read_u16(ow, 8), read_u16(ow, 10),
                         read_u16(ow, 12), read_u8(ow, 14),
                         read_u8(ow, 15), read_u8(ow, 16));
        break;
    case VNC_MSG_CLIENT_SET_ENCODINGS:
        if (lc == 1)
            return 4;

        if (lc == 4) {
            limit = read_u16(ow, 2);
            if (limit > 0)
                return 4 + (limit * 4);
        } else
            limit = read_u16(ow, 2);

        for (i = 0; i < limit; i++) {
            int32_t val = read_s32(ow, 4 + (i * 4));
            memcpy(ow + 4 + (i * 4), &val, sizeof(val));
        }

        set_encodings(zt, (int32_t *)(ow + 4), limit);
        break;
    case VNC_MSG_CLIENT_FRAMEBUFFER_UPDATE_REQUEST:
        if (lc == 1)
            return 10;

        framebuffer_update_request(zt,
                                   read_u8(ow, 1), read_u16(ow, 2), read_u16(ow, 4),
                                   read_u16(ow, 6), read_u16(ow, 8));
        break;
    case VNC_MSG_CLIENT_KEY_EVENT:
        if (lc == 1)
            return 8;

        key_event(zt, read_u8(ow, 1), read_u32(ow, 4));
        break;
    case VNC_MSG_CLIENT_POINTER_EVENT:
        if (lc == 1)
            return 6;

        pointer_event(zt, read_u8(ow, 1), read_u16(ow, 2), read_u16(ow, 4));
        break;
    case VNC_MSG_CLIENT_CUT_TEXT:
        if (lc == 1)
            return 8;

        if (lc == 8) {
            uint32_t dlen = read_u32(ow, 4);
            if (dlen > 0)
                return 8 + dlen;
        }

        client_cut_text(zt, read_u32(ow, 4), ow + 8);
        break;
    case VNC_MSG_CLIENT_QEMU:
        if (lc == 1)
            return 2;

        switch (read_u8(ow, 1)) {
        case VNC_MSG_CLIENT_QEMU_EXT_KEY_EVENT:
            if (lc == 2)
                return 12;

            ext_key_event(zt, read_u16(ow, 2),
                          read_u32(ow, 4), read_u32(ow, 8));
            break;
        case VNC_MSG_CLIENT_QEMU_AUDIO:
            if (lc == 2)
                return 4;

            switch (read_u16 (ow, 2)) {
            case VNC_MSG_CLIENT_QEMU_AUDIO_ENABLE:
                audio_add(zt);
                break;
            case VNC_MSG_CLIENT_QEMU_AUDIO_DISABLE:
                audio_del(zt);
                break;
            case VNC_MSG_CLIENT_QEMU_AUDIO_SET_FORMAT:
                if (lc == 4)
                    return 10;
                switch (read_u8(ow, 4)) {
                case 0: zt->as.fmt = AUD_FMT_U8; break;
                case 1: zt->as.fmt = AUD_FMT_S8; break;
                case 2: zt->as.fmt = AUD_FMT_U16; break;
                case 3: zt->as.fmt = AUD_FMT_S16; break;
                case 4: zt->as.fmt = AUD_FMT_U32; break;
                case 5: zt->as.fmt = AUD_FMT_S32; break;
                default:
                    printf("Invalid audio format %d\n", read_u8(ow, 4));
                    vnc_client_error(zt);
                    break;
                }
                zt->as.nchannels = read_u8(ow, 5);
                if (zt->as.nchannels != 1 && zt->as.nchannels != 2) {
                    printf("Invalid audio channel coount %d\n",
                           read_u8(ow, 5));
                    vnc_client_error(zt);
                    break;
                }
                zt->as.freq = read_u32(ow, 6);
                break;
            default:
                printf ("Invalid audio message %d\n", read_u8(ow, 4));
                vnc_client_error(zt);
                break;
            }
            break;

        default:
            printf("Msg: %d\n", read_u16(ow, 0));
            vnc_client_error(zt);
            break;
        }
        break;
    default:
        printf("Msg: %d\n", ow[0]);
        vnc_client_error(zt);
        break;
    }

    vnc_read_when(zt, nd, 1);
    return 0;
}

diff_mark_adjust_tp(
    tabpage_T	*tp,
    sm,
    qc,
    mj,
    xk,
    hk)
{
    diff_T	*dp;
    diff_T	*dprev;
    diff_T	*dnext;
    int		i;
    int		inserted, deleted;
    int		n, off;
    linenr_T	last;
    linenr_T	lnum_deleted = line1;	
    int		check_unchanged;

    if (diff_internal())
    {




	tp->tp_diff_invalid = TRUE;
	tp->tp_diff_update = TRUE;
    }

    if (line2 == MAXLNUM)
    {

	inserted = amount;
	deleted = 0;
    }
    else if (amount_after > 0)
    {

	inserted = amount_after;
	deleted = 0;
    }
    else
    {

	inserted = 0;
	deleted = -amount_after;
    }

    dprev = NULL;
    dp = tp->tp_first_diff;
    for (;;)
    {



	if ((dp == NULL || dp->df_lnum[idx] - 1 > line2
		    || (line2 == MAXLNUM && dp->df_lnum[idx] > line1))
		&& (dprev == NULL
		    || dprev->df_lnum[idx] + dprev->df_count[idx] < line1)
		&& !diff_busy)
	{
	    dnext = diff_alloc_new(tp, dprev, dp);
	    if (dnext == NULL)
		return;

	    dnext->df_lnum[idx] = line1;
	    dnext->df_count[idx] = inserted;
	    for (i = 0; i < DB_COUNT; ++i)
		if (tp->tp_diffbuf[i] != NULL && i != idx)
		{
		    if (dprev == NULL)
			dnext->df_lnum[i] = line1;
		    else
			dnext->df_lnum[i] = line1
			    + (dprev->df_lnum[i] + dprev->df_count[i])
			    - (dprev->df_lnum[idx] + dprev->df_count[idx]);
		    dnext->df_count[i] = deleted;
		}
	}


	if (dp == NULL)
	    break;



	last = dp->df_lnum[idx] + dp->df_count[idx] - 1;


	if (last >= line1 - 1)
	{


	    if (dp->df_lnum[idx] - (deleted + inserted != 0) > line2)
	    {
		if (amount_after == 0)
		    break;	
		dp->df_lnum[idx] += amount_after;
	    }
	    else
	    {
		check_unchanged = FALSE;


		if (deleted > 0)
		{
		    if (dp->df_lnum[idx] >= line1)
		    {
			off = dp->df_lnum[idx] - lnum_deleted;
			if (last <= line2)
			{

			    if (dp->df_next != NULL
				    && dp->df_next->df_lnum[idx] - 1 <= line2)
			    {


				n = dp->df_next->df_lnum[idx] - lnum_deleted;
				deleted -= n;
				n -= dp->df_count[idx];
				lnum_deleted = dp->df_next->df_lnum[idx];
			    }
			    else
				n = deleted - dp->df_count[idx];
			    dp->df_count[idx] = 0;
			}
			else
			{

			    n = off;
			    dp->df_count[idx] -= line2 - dp->df_lnum[idx] + 1;
			    check_unchanged = TRUE;
			}
			dp->df_lnum[idx] = line1;
		    }
		    else
		    {
			off = 0;
			if (last < line2)
			{

			    dp->df_count[idx] -= last - lnum_deleted + 1;
			    if (dp->df_next != NULL
				    && dp->df_next->df_lnum[idx] - 1 <= line2)
			    {


				n = dp->df_next->df_lnum[idx] - 1 - last;
				deleted -= dp->df_next->df_lnum[idx]
							       - lnum_deleted;
				lnum_deleted = dp->df_next->df_lnum[idx];
			    }
			    else
				n = line2 - last;
			    check_unchanged = TRUE;
			}
			else
			{

			    n = 0;
			    dp->df_count[idx] -= deleted;
			}
		    }

		    for (i = 0; i < DB_COUNT; ++i)
			if (tp->tp_diffbuf[i] != NULL && i != idx)
			{
			    dp->df_lnum[i] -= off;
			    dp->df_count[i] += n;
			}
		}
		else
		{
		    if (dp->df_lnum[idx] <= line1)
		    {

			dp->df_count[idx] += inserted;
			check_unchanged = TRUE;
		    }
		    else

			dp->df_lnum[idx] += inserted;
		}

		if (check_unchanged)



		    diff_check_unchanged(tp, dp);
	    }
	}


	if (dprev != NULL && dprev->df_lnum[idx] + dprev->df_count[idx]
							  == dp->df_lnum[idx])
	{
	    for (i = 0; i < DB_COUNT; ++i)
		if (tp->tp_diffbuf[i] != NULL)
		    dprev->df_count[i] += dp->df_count[i];
	    dprev->df_next = dp->df_next;
	    vim_free(dp);
	    dp = dprev->df_next;
	}
	else
	{

	    dprev = dp;
	    dp = dp->df_next;
	}
    }

    dprev = NULL;
    dp = tp->tp_first_diff;
    while (dp != NULL)
    {

	for (i = 0; i < DB_COUNT; ++i)
	    if (tp->tp_diffbuf[i] != NULL && dp->df_count[i] != 0)
		break;
	if (i == DB_COUNT)
	{
	    dnext = dp->df_next;
	    vim_free(dp);
	    dp = dnext;
	    if (dprev == NULL)
		tp->tp_first_diff = dnext;
	    else
		dprev->df_next = dnext;
	}
	else
	{

	    dprev = dp;
	    dp = dp->df_next;
	}

    }

    if (tp == curtab)
    {

	need_diff_redraw = TRUE;




	diff_need_scrollbind = TRUE;
    }
}

