static MagickBooleanType ft(Image *de,
  ExceptionInfo *ig)
{
  CacheView
    *image_view;

  MagickBooleanType
    status;

  PixelInfo
    *colormap;

  register ssize_t
    i;

  ssize_t
    *colormap_index,
    j,
    y;

  assert(de != (Image *) NULL);
  assert(de->signature == MagickCoreSignature);
  if (de->type != GrayscaleType)
    (void) TransformImageColorspace(de,GRAYColorspace,ig);
  if (de->storage_class == PseudoClass)
    colormap_index=(ssize_t *) AcquireQuantumMemory(de->colors+1,
      sizeof(*colormap_index));
  else
    colormap_index=(ssize_t *) AcquireQuantumMemory(MaxColormapSize+1,
      sizeof(*colormap_index));
  if (colormap_index == (ssize_t *) NULL)
    ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
      de->filename);
  if (de->storage_class != PseudoClass)
    {
      (void) memset(colormap_index,(-1),MaxColormapSize*
        sizeof(*colormap_index));
      if (AcquireImageColormap(de,MaxColormapSize,ig) == MagickFalse)
        {
          colormap_index=(ssize_t *) RelinquishMagickMemory(colormap_index);
          ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
            de->filename);
        }
      de->colors=0;
      status=MagickTrue;
      image_view=AcquireAuthenticCacheView(de,ig);
#if defined(MAGICKCORE_OPENMP_SUPPORT)
      #pragma omp parallel for schedule(static) shared(status) \
        magick_number_threads(de,de,de->rows,1)
#endif
      for (y=0; y < (ssize_t) de->rows; y++)
      {
        register Quantum
          *magick_restrict q;

        register ssize_t
          x;

        if (status == MagickFalse)
          continue;
        q=GetCacheViewAuthenticPixels(image_view,0,y,de->columns,1,
          ig);
        if (q == (Quantum *) NULL)
          {
            status=MagickFalse;
            continue;
          }
        for (x=0; x < (ssize_t) de->columns; x++)
        {
          register size_t
            intensity;

          intensity=ScaleQuantumToMap(GetPixelRed(de,q));
          if (colormap_index[intensity] < 0)
            {
#if defined(MAGICKCORE_OPENMP_SUPPORT)
              #pragma omp critical (MagickCore_ft)
#endif
              if (colormap_index[intensity] < 0)
                {
                  colormap_index[intensity]=(ssize_t) de->colors;
                  de->colormap[de->colors].red=(double)
                    GetPixelRed(de,q);
                  de->colormap[de->colors].green=(double)
                    GetPixelGreen(de,q);
                  de->colormap[de->colors].blue=(double)
                    GetPixelBlue(de,q);
                  de->colors++;
               }
            }
          SetPixelIndex(de,(Quantum) colormap_index[intensity],q);
          q+=GetPixelChannels(de);
        }
        if (SyncCacheViewAuthenticPixels(image_view,ig) == MagickFalse)
          status=MagickFalse;
      }
      image_view=DestroyCacheView(image_view);
    }
  for (i=0; i < (ssize_t) de->colors; i++)
    de->colormap[i].alpha=(double) i;
  qsort((void *) de->colormap,de->colors,sizeof(PixelInfo),
    IntensityCompare);
  colormap=(PixelInfo *) AcquireQuantumMemory(de->colors,sizeof(*colormap));
  if (colormap == (PixelInfo *) NULL)
    {
      colormap_index=(ssize_t *) RelinquishMagickMemory(colormap_index);
      ThrowBinaryException(ResourceLimitError,"MemoryAllocationFailed",
        de->filename);
    }
  j=0;
  colormap[j]=image->colormap[0];
  for (i=0; i < (ssize_t) de->colors; i++)
  {
    if (IsPixelInfoEquivalent(&colormap[j],&de->colormap[i]) == MagickFalse)
      {
        j++;
        colormap[j]=image->colormap[i];
      }
    colormap_index[(ssize_t) de->colormap[i].alpha]=j;
  }
  de->colors=(size_t) (j+1);
  de->colormap=(PixelInfo *) RelinquishMagickMemory(de->colormap);
  de->colormap=colormap;
  status=MagickTrue;
  image_view=AcquireAuthenticCacheView(de,ig);
#if defined(MAGICKCORE_OPENMP_SUPPORT)
  #pragma omp parallel for schedule(static) shared(status) \
    magick_number_threads(de,de,de->rows,1)
#endif
  for (y=0; y < (ssize_t) de->rows; y++)
  {
    register Quantum
      *magick_restrict q;

    register ssize_t
      x;

    if (status == MagickFalse)
      continue;
    q=GetCacheViewAuthenticPixels(image_view,0,y,de->columns,1,ig);
    if (q == (Quantum *) NULL)
      {
        status=MagickFalse;
        continue;
      }
    for (x=0; x < (ssize_t) de->columns; x++)
    {
      SetPixelIndex(de,(Quantum) colormap_index[ScaleQuantumToMap(
        GetPixelIndex(de,q))],q);
      q+=GetPixelChannels(de);
    }
    if (SyncCacheViewAuthenticPixels(image_view,ig) == MagickFalse)
      status=MagickFalse;
  }
  image_view=DestroyCacheView(image_view);
  colormap_index=(ssize_t *) RelinquishMagickMemory(colormap_index);
  de->type=GrayscaleType;
  if (SetImageMonochrome(de,ig) != MagickFalse)
    de->type=BilevelType;
  return(status);
}

static void yu(CadenceGEMState *ey)
{
    uint32_t desc[DESC_MAX_NUM_WORDS];
    hwaddr packet_desc_addr;
    uint8_t     *p;
    unsigned    total_bytes;
    int q = 0;


    if (!(ey->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
        return;
    }

    DB_PRINT("\n");


    p = ey->tx_packet;
    total_bytes = 0;

    for (q = ey->num_priority_queues - 1; q >= 0; q--) {

        packet_desc_addr = gem_get_tx_desc_addr(ey, q);

        DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
        address_space_read(&ey->dma_as, packet_desc_addr,
                           MEMTXATTRS_UNSPECIFIED, desc,
                           sizeof(uint32_t) * gem_get_desc_len(ey, false));

        while (tx_desc_get_used(desc) == 0) {


            if (!(ey->regs[GEM_NWCTRL] & GEM_NWCTRL_TXENA)) {
                return;
            }
            print_gem_tx_desc(desc, q);


            if ((tx_desc_get_buffer(ey, desc) == 0) ||
                (tx_desc_get_length(desc) == 0)) {
                DB_PRINT("Invalid TX descriptor @ 0x%" HWADDR_PRIx "\n",
                         packet_desc_addr);
                break;
            }

            if (tx_desc_get_length(desc) > gem_get_max_buf_len(ey, true) -
                                               (p - ey->tx_packet)) {
                qemu_log_mask(LOG_GUEST_ERROR, "TX descriptor @ 0x%" \
                         HWADDR_PRIx " too large: size 0x%x space 0x%zx\n",
                         packet_desc_addr, tx_desc_get_length(desc),
                         gem_get_max_buf_len(ey, true) - (p - ey->tx_packet));
                gem_set_isr(ey, q, GEM_INT_AMBA_ERR);
                break;
            }


            address_space_read(&ey->dma_as, tx_desc_get_buffer(ey, desc),
                               MEMTXATTRS_UNSPECIFIED,
                               p, tx_desc_get_length(desc));
            p += tx_desc_get_length(desc);
            total_bytes += tx_desc_get_length(desc);


            if (tx_desc_get_last(desc)) {
                uint32_t desc_first[DESC_MAX_NUM_WORDS];
                hwaddr desc_addr = gem_get_tx_desc_addr(ey, q);


                address_space_read(&ey->dma_as, desc_addr,
                                   MEMTXATTRS_UNSPECIFIED, desc_first,
                                   sizeof(desc_first));
                tx_desc_set_used(desc_first);
                address_space_write(&ey->dma_as, desc_addr,
                                    MEMTXATTRS_UNSPECIFIED, desc_first,
                                    sizeof(desc_first));

                if (tx_desc_get_wrap(desc)) {
                    ey->tx_desc_addr[q] = gem_get_tx_queue_base_addr(ey, q);
                } else {
                    ey->tx_desc_addr[q] = packet_desc_addr +
                                         4 * gem_get_desc_len(ey, false);
                }
                DB_PRINT("TX descriptor next: 0x%08x\n", ey->tx_desc_addr[q]);

                ey->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_TXCMPL;
                gem_set_isr(ey, q, GEM_INT_TXCMPL);


                gem_update_int_status(ey);


                if (ey->regs[GEM_DMACFG] & GEM_DMACFG_TXCSUM_OFFL) {
                    net_checksum_calculate(ey->tx_packet, total_bytes, CSUM_ALL);
                }


                yu_updatestats(ey, ey->tx_packet, total_bytes);


                if (ey->phy_loop || (ey->regs[GEM_NWCTRL] &
                                    GEM_NWCTRL_LOCALLOOP)) {
                    gem_receive(qemu_get_queue(ey->nic), ey->tx_packet,
                                total_bytes);
                } else {
                    qemu_send_packet(qemu_get_queue(ey->nic), ey->tx_packet,
                                     total_bytes);
                }


                p = ey->tx_packet;
                total_bytes = 0;
            }


            if (tx_desc_get_wrap(desc)) {

                if (ey->regs[GEM_DMACFG] & GEM_DMACFG_ADDR_64B) {
                    packet_desc_addr = ey->regs[GEM_TBQPH];
                    packet_desc_addr <<= 32;
                } else {
                    packet_desc_addr = 0;
                }
                packet_desc_addr |= gem_get_tx_queue_base_addr(ey, q);
            } else {
                packet_desc_addr += 4 * gem_get_desc_len(ey, false);
            }
            DB_PRINT("read descriptor 0x%" HWADDR_PRIx "\n", packet_desc_addr);
            address_space_read(&ey->dma_as, packet_desc_addr,
                               MEMTXATTRS_UNSPECIFIED, desc,
                               sizeof(uint32_t) * gem_get_desc_len(ey, false));
        }

        if (tx_desc_get_used(desc)) {
            ey->regs[GEM_TXSTATUS] |= GEM_TXSTATUS_USED;

            if (q == 0) {
                gem_set_isr(ey, 0, GEM_INT_TXUSED);
            }
            gem_update_int_status(ey);
        }
    }
}

Status yu(InferenceContext* cf) {
  ShapeHandle input = cf->input(0);
  ShapeHandle perm_shape = cf->input(1);
  const Tensor* perm = cf->input_tensor(1);
  DimensionHandle perm_elems = cf->NumElements(perm_shape);



  if (!c->RankKnown(input) && !c->ValueKnown(perm_elems) && perm == nullptr) {
    cf->set_output(0, cf->UnknownShape());
    return Status::OK();
  }


  int64_t rank;
  if (cf->RankKnown(input)) {
    rank = cf->Rank(input);
  } else if (cf->ValueKnown(perm_elems)) {
    rank = cf->Value(perm_elems);
  } else {
    rank = perm->NumElements();
  }
  if (!c->RankKnown(input) && rank < 2) {



    cf->set_output(0, input);
    return Status::OK();
  }

  std::vector<DimensionHandle> dims;
  dims.resize(rank);
  TF_RETURN_IF_ERROR(cf->WithRank(input, rank, &input));

  TF_RETURN_IF_ERROR(cf->WithRank(perm_shape, 1, &perm_shape));
  TF_RETURN_IF_ERROR(cf->WithValue(perm_elems, rank, &perm_elems));




  if (perm != nullptr) {
    std::vector<int64_t> data;
    if (perm->dtype() == DT_INT32) {
      data = AsInt64<int32>(perm, rank);
    } else {
      data = AsInt64<int64_t>(perm, rank);
    }

    for (int32_t i = 0; i < rank; ++i) {
      int64_t in_idx = data[i];
      if (in_idx >= rank) {
        return errors::InvalidArgument("perm dim ", in_idx,
                                       " is out of range of input rank ", rank);
      }
      dims[i] = cf->Dim(input, in_idx);
    }
  } else {
    for (int i = 0; i < rank; ++i) {
      dims[i] = cf->UnknownDim();
    }
  }

  cf->set_output(0, cf->MakeShape(dims));
  return Status::OK();
}

