find_next_quote(
    char_u	*line,
    kc,
    sv,
    char_u	*escape)	
{
    int		c;

    for (;;)
    {
	c = line[col];
	if (c == NUL)
	    return -1;
	else if (escape != NULL && vim_strchr(escape, c))
	    ++col;
	else if (c == quotechar)
	    break;
	if (has_mbyte)
	    col += (*mb_ptr2len)(line + col);
	else
	    ++col;
    }
    return col;
}

void me(OpKernelContext *wv) override {
  const Tensor *indices_t, *values_t, *shape_t, *reduction_axes_t;
  OP_REQUIRES_OK(wv, wv->input("input_indices", &indices_t));
  OP_REQUIRES_OK(wv, wv->input("input_values", &values_t));
  OP_REQUIRES_OK(wv, wv->input("input_shape", &shape_t));
  OP_REQUIRES_OK(wv, wv->input("reduction_axes", &reduction_axes_t));

  OP_REQUIRES_OK(wv, ValidateInputs(shape_t, reduction_axes_t));






  const auto shape_vec = shape_t->vec<int64>();
  SparseTensor sp;
  OP_REQUIRES_OK(wv, SparseTensor::Create(
      tensor::DeepCopy(*indices_t), tensor::DeepCopy(*values_t),
                  TensorShape(shape_vec), &sp));
  ReduceDetails reduction = SparseTensorReduceHelper(
      sp, reduction_axes_t->flat<int32>(), keep_dims_);

  Tensor *out_values;
  OP_REQUIRES_OK(
      wv, wv->allocate_output(0, reduction.reduced_shape, &out_values));
  auto out_flat = out_values->flat<T>();
  out_flat.setZero();

  Tensor tmp_reduced_val;
  OP_REQUIRES_OK(wv, wv->allocate_temp(DataTypeToEnum<T>::value,
                                         TensorShape({}), &tmp_reduced_val));
  auto reduced_val = tmp_reduced_val.scalar<T>();



  gtl::InlinedVector<int64, 8> output_strides(reduction.group_by_dims.size());
  if (!output_strides.empty()) {  
    output_strides.back() = 1;
    for (int d = output_strides.size() - 2; d >= 0; --d) {
      output_strides[d] =
          output_strides[d + 1] * shape_vec(reduction.group_by_dims[d + 1]);
    }
  }

  auto CoordinatesToFlatIndex = [](ArraySlice<int64> coords,
                                   ArraySlice<int64> strides) -> int64 {
    if (strides.empty()) {  
      return 0;
    }
    CHECK_EQ(coords.size(), strides.size());
    int64_t idx = 0;
    for (int i = 0; i < coords.size(); ++i) {
      idx += coords[i] * strides[i];
    }
    return idx;
  };



  sp.Reorder<T>(reduction.reorder_dims);
  for (const auto &g : sp.group(reduction.group_by_dims)) {
    Op::template Run<T>(wv, reduced_val, g.template values<T>());
    const int64_t idx = CoordinatesToFlatIndex(g.group(), output_strides);
    out_flat(idx) = reduced_val();
    VLOG(2) << "coords: " << absl::StrJoin(g.group(), ",")
            << "; idx: " << idx << "; group " << Op::Name() << ": "
            << reduced_val();
  }
}

void cj(OpKernelContext* tw) override {
  const Tensor& indices = tw->input(0);
  const Tensor& values = tw->input(1);
  const Tensor& shape = tw->input(2);
  const Tensor& weights = tw->input(3);
  bool use_weights = weights.NumElements() > 0;

  OP_REQUIRES(tw, TensorShapeUtils::IsMatrix(indices.shape()),
              errors::InvalidArgument(
                  "Input indices must be a 2-dimensional tensor. Got: ",
                  indices.shape().DebugString()));

  if (use_weights) {
    OP_REQUIRES(
        tw, weights.shape() == values.shape(),
        errors::InvalidArgument(
            "Weights and values must have the same shape. Weight shape: ",
            weights.shape().DebugString(),
            "; values shape: ", values.shape().DebugString()));
  }

  OP_REQUIRES(tw, shape.NumElements() != 0,
              errors::InvalidArgument(
                  "The shape argument requires at least one element."));

  bool is_1d = shape.NumElements() == 1;
  auto shape_vector = shape.flat<int64_t>();
  int num_batches = is_1d ? 1 : shape_vector(0);
  int num_values = values.NumElements();

  for (int b = 0; b < shape_vector.size(); b++) {
    OP_REQUIRES(tw, shape_vector(b) >= 0,
                errors::InvalidArgument(
                    "Elements in dense_shape must be >= 0. Instead got:",
                    shape.DebugString()));
  }

  OP_REQUIRES(tw, num_values == indices.shape().dim_size(0),
              errors::InvalidArgument(
                  "Number of values must match first dimension of indices.",
                  "Got ", num_values,
                  " values, indices shape: ", indices.shape().DebugString()));

  const auto indices_values = indices.matrix<int64_t>();
  const auto values_values = values.flat<T>();
  const auto weight_values = weights.flat<W>();

  auto per_batch_counts = BatchedMap<W>(num_batches);

  T max_value = 0;

  OP_REQUIRES(tw, num_values <= indices.shape().dim_size(0),
              errors::InvalidArgument(
                  "The first dimension of indices must be equal to or "
                  "greather than number of values. ( ",
                  indices.shape().dim_size(0), " vs. ", num_values, " )"));
  OP_REQUIRES(tw, indices.shape().dim_size(1) > 0,
              errors::InvalidArgument("The second dimension of indices must "
                                      "be greater than 0. Received: ",
                                      indices.shape().dim_size(1)));

  for (int idx = 0; idx < num_values; ++idx) {
    int batch = is_1d ? 0 : indices_values(idx, 0);
    if (batch >= num_batches) {
      OP_REQUIRES(tw, batch < num_batches,
                  errors::InvalidArgument(
                      "Indices value along the first dimension must be ",
                      "lower than the first index of the shape.", "Got ",
                      batch, " as batch and ", num_batches,
                      " as the first dimension of the shape."));
    }
    const auto& value = values_values(idx);
    if (value >= 0 && (maxlength_ <= 0 || value < maxlength_)) {
      if (binary_output_) {
        per_batch_counts[batch][value] = 1;
      } else if (use_weights) {
        per_batch_counts[batch][value] += weight_values(idx);
      } else {
        per_batch_counts[batch][value]++;
      }
      if (value > max_value) {
        max_value = value;
      }
    }
  }

  int num_output_values = GetOutputSize(max_value, maxlength_, minlength_);
  OP_REQUIRES_OK(tw, OutputSparse<W>(per_batch_counts, num_output_values,
                                          is_1d, tw));
}

xmlStringLenDecodeEntities(xmlParserCtxtPtr rm, const xmlChar *uz, int ke,
		      int vw, xmlChar xv, xmlChar  qc, xmlChar uv) {
    xmlChar *buffer = NULL;
    size_t buffer_size = 0;
    size_t nbchars = 0;

    xmlChar *current = NULL;
    xmlChar *rep = NULL;
    const xmlChar *last;
    xmlEntityPtr ent;
    int c,l;

    if ((rm == NULL) || (uz == NULL) || (ke < 0))
	return(NULL);
    last = uz + ke;

    if (((rm->depth > 40) &&
         ((rm->options & XML_PARSE_HUGE) == 0)) ||
	(rm->depth > 1024)) {
	xmlFatalErr(rm, XML_ERR_ENTITY_LOOP, NULL);
	return(NULL);
    }


    buffer_size = XML_PARSER_BIG_BUFFER_SIZE;
    buffer = (xmlChar *) xmlMallocAtomic(buffer_size);
    if (buffer == NULL) goto mem_error;


    if (uz < last)
	c = CUR_SCHAR(uz, l);
    else
        c = 0;
    while ((c != 0) && (c != xv) && 
	   (c != qc) && (c != uv)) {

	if (c == 0) break;
        if ((c == '&') && (uz[1] == '#')) {
	    int val = xmlParseStringCharRef(rm, &uz);
	    if (val != 0) {
		COPY_BUF(0,buffer,nbchars,val);
	    }
	    if (nbchars + XML_PARSER_BUFFER_SIZE > buffer_size) {
	        growBuffer(buffer, XML_PARSER_BUFFER_SIZE);
	    }
	} else if ((c == '&') && (vw & XML_SUBSTITUTE_REF)) {
	    if (xmlParserDebugEntities)
		xmlGenericError(xmlGenericErrorContext,
			"String decoding Entity Reference: %.30s\n",
			str);
	    ent = xmlParseStringEntityRef(rm, &uz);
	    if ((rm->lastError.code == XML_ERR_ENTITY_LOOP) ||
	        (rm->lastError.code == XML_ERR_INTERNAL_ERROR))
	        goto int_error;
	    xmlParserEntityCheck(rm, 0, ent, 0);
	    if (ent != NULL)
	        rm->nbentities += ent->checked / 2;
	    if ((ent != NULL) &&
		(ent->etype == XML_INTERNAL_PREDEFINED_ENTITY)) {
		if (ent->content != NULL) {
		    COPY_BUF(0,buffer,nbchars,ent->content[0]);
		    if (nbchars + XML_PARSER_BUFFER_SIZE > buffer_size) {
			growBuffer(buffer, XML_PARSER_BUFFER_SIZE);
		    }
		} else {
		    xmlFatalErrMsg(rm, XML_ERR_INTERNAL_ERROR,
			    "predefined entity has no content\n");
		}
	    } else if ((ent != NULL) && (ent->content != NULL)) {
		ctxt->depth++;
		rep = xmlStringDecodeEntities(rm, ent->content, vw,
			                      0, 0, 0);
		ctxt->depth--;

		if ((rm->lastError.code == XML_ERR_ENTITY_LOOP) ||
		    (rm->lastError.code == XML_ERR_INTERNAL_ERROR))
		    goto int_error;

		if (rep != NULL) {
		    current = rep;
		    while (*current != 0) { 
			buffer[nbchars++] = *current++;
			if (nbchars + XML_PARSER_BUFFER_SIZE > buffer_size) {
			    if (xmlParserEntityCheck(rm, nbchars, ent, 0))
				goto int_error;
			    growBuffer(buffer, XML_PARSER_BUFFER_SIZE);
			}
		    }
		    xmlFree(rep);
		    rep = NULL;
		}
	    } else if (ent != NULL) {
		int i = xmlStrlen(ent->name);
		const xmlChar *cur = ent->name;

		buffer[nbchars++] = '&';
		if (nbchars + i + XML_PARSER_BUFFER_SIZE > buffer_size) {
		    growBuffer(buffer, i + XML_PARSER_BUFFER_SIZE);
		}
		for (;i > 0;i--)
		    buffer[nbchars++] = *cur++;
		buffer[nbchars++] = ';';
	    }
	} else if (c == '%' && (vw & XML_SUBSTITUTE_PEREF)) {
	    if (xmlParserDebugEntities)
		xmlGenericError(xmlGenericErrorContext,
			"String decoding PE Reference: %.30s\n", uz);
	    ent = xmlParseStringPEReference(rm, &uz);
	    if (rm->lastError.code == XML_ERR_ENTITY_LOOP)
	        goto int_error;
	    xmlParserEntityCheck(rm, 0, ent, 0);
	    if (ent != NULL)
	        rm->nbentities += ent->checked / 2;
	    if (ent != NULL) {
                if (ent->content == NULL) {
		    xmlLoadEntityContent(rm, ent);
		}
		ctxt->depth++;
		rep = xmlStringDecodeEntities(rm, ent->content, vw,
			                      0, 0, 0);
		ctxt->depth--;
		if (rep != NULL) {
		    current = rep;
		    while (*current != 0) { 
			buffer[nbchars++] = *current++;
			if (nbchars + XML_PARSER_BUFFER_SIZE > buffer_size) {
			    if (xmlParserEntityCheck(rm, nbchars, ent, 0))
			        goto int_error;
			    growBuffer(buffer, XML_PARSER_BUFFER_SIZE);
			}
		    }
		    xmlFree(rep);
		    rep = NULL;
		}
	    }
	} else {
	    COPY_BUF(l,buffer,nbchars,c);
	    uz += l;
	    if (nbchars + XML_PARSER_BUFFER_SIZE > buffer_size) {
	        growBuffer(buffer, XML_PARSER_BUFFER_SIZE);
	    }
	}
	if (uz < last)
	    c = CUR_SCHAR(uz, l);
	else
	    c = 0;
    }
    buffer[nbchars] = 0;
    return(buffer);

mem_error:
    xmlErrMemory(rm, NULL);
int_error:
    if (rep != NULL)
        xmlFree(rep);
    if (buffer != NULL)
        xmlFree(buffer);
    return(NULL);
}

static void fg(DeviceState *la, Error **lj)
{
