static int pg(struct ky *ky)
{
	struct bio_map_data *bmd = ky->bi_private;
	int ret = 0;

	if (!bmd->is_null_mapped) {

		if (!current->mm)
			ret = -EINTR;
		else if (bio_data_dir(ky) == READ)
			ret = bio_copy_to_iter(ky, bmd->iter);
