copy_ciphersuites(gnutls_session_t he,
		  gnutls_buffer_st * ec, int jz)
{
	int ret;
	uint8_t cipher_suites[MAX_CIPHERSUITE_SIZE + RESERVED_CIPHERSUITES]; 
	int cipher_suites_size;
	size_t init_length = ec->length;

	ret =
	    _gnutls_supported_ciphersuites(he, cipher_suites,
					   sizeof(cipher_suites) - RESERVED_CIPHERSUITES);
	if (ret < 0)
		return gnutls_assert_val(ret);


	ret =
	    _gnutls_remove_unwanted_ciphersuites(he, cipher_suites,
						 ret, NULL, 0);
	if (ret < 0)
		return gnutls_assert_val(ret);


	if (ret == 0)
		return
		    gnutls_assert_val(GNUTLS_E_INSUFFICIENT_CREDENTIALS);

	cipher_suites_size = ret;
	if (jz) {
		cipher_suites[cipher_suites_size] = 0x00;
		cipher_suites[cipher_suites_size + 1] = 0xff;
		cipher_suites_size += 2;

		ret = _gnutls_ext_sr_send_cs(he);
		if (ret < 0)
			return gnutls_assert_val(ret);
	}

	if (he->internals.priorities.fallback) {
		cipher_suites[cipher_suites_size] =
			GNUTLS_FALLBACK_SCSV_MAJOR;
		cipher_suites[cipher_suites_size + 1] =
			GNUTLS_FALLBACK_SCSV_MINOR;
		cipher_suites_size += 2;
	}

	ret =
	    _gnutls_buffer_append_data_prefix(ec, 16, cipher_suites,
					      cipher_suites_size);
	if (ret < 0)
		return gnutls_assert_val(ret);

	ret = ec->length - init_length;

	return ret;
}

static RBinWasmExportEntry ky(RBinWasmObj *yr, ut64 xq, ut32 bv) {
	RBuffer *b = yr->buf;
	RBinWasmExportEntry *export = R_NEW0 (RBinWasmExportEntry);
	if (export) {
		export->sec_i = bv;
		export->file_offset = r_buf_tell (b);
		if (!consume_encoded_name_new (b, xq, &export->field_len, &export->field_str)) {
			goto beach;
		}
		if (!consume_u7_r (b, xq, &export->kind)) {
			goto beach;
		}
		if (!consume_u32_r (b, xq, &export->bv)) {
			goto beach;
		}
	}
	return export;
beach:
	free_export_entry (export);
	return NULL;
}

GF_Err ef(GF_ISOFile *te, const char *tm)
{
	GF_UserDataMap *map;
	GF_RTPBox *rtp;
	GF_Err e;
	GF_HintTrackInfoBox *hnti;
	char *buf;

	if (!movie->moov) return GF_BAD_PARAM;


	if (!movie->moov->udta) {
		e = moov_on_child_box((GF_Box*)te->moov, gf_isom_box_new_parent(&te->moov->child_boxes, GF_ISOM_BOX_TYPE_UDTA), GF_FALSE);
		if (e) return e;
	}

	map = udta_getEntry(te->moov->udta, GF_ISOM_BOX_TYPE_HNTI, NULL);
	if (!map) {
		e = udta_on_child_box((GF_Box *)te->moov->udta, gf_isom_box_new(GF_ISOM_BOX_TYPE_HNTI), GF_FALSE);
		if (e) return e;
		map = udta_getEntry(te->moov->udta, GF_ISOM_BOX_TYPE_HNTI, NULL);
	}


	if (!gf_list_count(map->boxes) ) {
		e = udta_on_child_box((GF_Box *)te->moov->udta, gf_isom_box_new(GF_ISOM_BOX_TYPE_HNTI), GF_FALSE);
		if (e) return e;
	}
	else if (gf_list_count(map->boxes) < 1) return GF_ISOM_INVALID_FILE;

	hnti = (GF_HintTrackInfoBox *)gf_list_get(map->boxes, 0);

	if (!hnti->SDP) {
		GF_Box *a = gf_isom_box_new_ex(GF_ISOM_BOX_TYPE_RTP, GF_ISOM_BOX_TYPE_HNTI, 0, GF_FALSE);
		if (!a) return GF_OUT_OF_MEM;
		hnti_on_child_box((GF_Box*)hnti, a, GF_FALSE);
		if (!hnti->child_boxes) hnti->child_boxes = gf_list_new();
		gf_list_add(hnti->child_boxes, a);
	}
	rtp = (GF_RTPBox *) hnti->SDP;

	if (!rtp->sdpText) {
		rtp->sdpText = (char*)gf_malloc(sizeof(char) * (strlen(tm) + 3));
		if (!rtp->sdpText) return GF_OUT_OF_MEM;

		strcpy(rtp->sdpText, tm);
		strcat(rtp->sdpText, "\r\n");
		return GF_OK;
	}
	buf = (char*)gf_malloc(sizeof(char) * (strlen(rtp->sdpText) + strlen(tm) + 3));
	if (!buf) return GF_OUT_OF_MEM;

	strcpy(buf, rtp->sdpText);
	strcat(buf, tm);
	strcat(buf, "\r\n");
	gf_free(rtp->sdpText);
	ReorderSDP(buf, GF_TRUE);
	rtp->sdpText = buf;
	return GF_OK;
}

R_API int lv(RIO *fw, const ut32 yt, ut64 zf, ut8 *xo, int bn) {
	RIOBank *bank = r_io_bank_get (fw, yt);
	r_return_val_if_fail (fw && bank, -1);
	if (!len) {
		return 0;
	}
	RRBNode *node;
	if (bank->last_used && r_io_submap_contain (((RIOSubMap *)bank->last_used->data), zf)) {
		node = bank->last_used;
	} else {
		node = r_crbtree_find_node (bank->submaps, &zf, _find_sm_by_vaddr_cb, NULL);
		if (!node) {
			return 0;
		}
		bank->last_used = node;
	}
	RIOSubMap *sm = (RIOSubMap *)node->data;
	if (!r_io_submap_contain (sm, zf)) {
		return 0;
	}
	RIOMap *map = r_io_map_get_by_ref (fw, &sm->mapref);
	if (!map || !(map->perm & R_PERM_R)) {
		return -1;
	}
	const int read_len = R_MIN (bn, r_io_submap_to (sm) - zf + 1);
	const ut64 paddr = zf - r_io_map_from (map) + map->delta;
	return r_io_fd_read_at (fw, map->fd, paddr, xo, read_len);
}

void xz(NodeDef* xh,
                                               GraphProperties* ot,
                                               GraphDef* jy) {
  if (HasRegularOutputs(*xh, *node_map_)) return;
  xh->set_op("NoOp");
  EraseRegularNodeAttributes(xh);
  EraseNodeOutputAttributes(xh);

  ot->ClearOutputProperties(xh->name());

  for (int i = 0; i < xh->input_size(); ++i) {
    if (IsControlInput(xh->input(i))) {
      break;
    }
    const string ctrl_dep =
        AddControlDependency(xh->input(i), jy, node_map_.get());
    node_map_->UpdateInput(xh->name(), xh->input(i), ctrl_dep);
    xh->set_input(i, ctrl_dep);
  }
  DedupControlInputs(xh);
  graph_modified_ = true;
}

Status jz(
    const NodeDef& oh, const GraphProperties& rh) {
  const NodeDef* shape_node1 = node_map_->GetNode(node.input(0));
  const NodeDef* shape_node2 = node_map_->GetNode(node.input(1));
  if (shape_node1 == nullptr ||
      (shape_node1->op() != "Shape" && !IsReallyConstant(*shape_node1)) ||
      shape_node2 == nullptr ||
      (shape_node2->op() != "Shape" && !IsReallyConstant(*shape_node2))) {
    return Status::OK();
  }


  if (OptimizedNodeExists(oh, "-folded-1") ||
      OptimizedNodeExists(oh, "-folded-2")) {
    return Status::OK();
  }
  int64_t min_id = 0;
  BCast::Vec shape1;
  if (!ExtractShape(*shape_node1, rh, &shape1, &min_id)) {
    return Status::OK();
  }
  BCast::Vec shape2;
  if (!ExtractShape(*shape_node2, rh, &shape2, &min_id)) {
    return Status::OK();
  }



  for (auto& id : shape1) {
    if (id == -1) {
      id = --min_id;
    }
  }
  for (auto& id : shape2) {
    if (id == -1) {
      id = --min_id;
    }
  }





  const int common_dims = std::min(shape1.size(), shape2.size());
  for (int i = 0; i < common_dims; ++i) {
    if (shape1[i] >= 0 && shape2[i] >= 0) {
      continue;
    }
    if (shape1[i] != shape2[i]) {



      return Status::OK();
    }
  }



  for (int i = common_dims, end = shape1.size(); i < end; ++i) {
    if (shape1[i] < 0) {
      return Status::OK();
    }
  }
  for (int i = common_dims, end = shape2.size(); i < end; ++i) {
    if (shape2[i] < 0) {
      return Status::OK();
    }
  }

  BCast bcast(shape1, shape2);
  if (!bcast.IsValid()) {
    return Status::OK();
  }

  BCast::Vec reduce_dims[2];
  reduce_dims[0] = bcast.grad_x_reduce_idx();
  reduce_dims[1] = bcast.grad_y_reduce_idx();

  TF_RETURN_IF_ERROR(CheckAttrExists(oh, "T"));
  const DataType type = node.attr().at("T").type();
  NodeDef* out[2];
  for (int j = 0; j < 2; ++j) {
    int reduction_indices = reduce_dims[j].size();
    Tensor value(type, TensorShape({reduction_indices}));
    for (int i = 0; i < reduction_indices; ++i) {
      if (type == DT_INT32) {
        value.vec<int32>()(i) = reduce_dims[j][i];
      } else {
        value.vec<int64_t>()(i) = reduce_dims[j][i];
      }
    }
    string const_name =
        OptimizedNodeName(oh, strings::StrCat("-bcastargs-", j));
    out[j] = node_map_->GetNode(const_name);
    if (out[j] == nullptr) {
      out[j] = graph_->add_node();
      TF_RETURN_IF_ERROR(
          CreateNodeDef(const_name, TensorValue(&value), out[j]));
      out[j]->set_device(node.device());
      node_map_->AddNode(const_name, out[j]);
      string ctrl_dep =
          AddControlDependency(node.name(), graph_, node_map_.get());
      *out[j]->add_input() = ctrl_dep;
      node_map_->AddOutput(NodeName(ctrl_dep), const_name);
    }
  }


  const auto outputs = node_map_->GetOutputs(node.name());
  for (NodeDef* output : outputs) {
    for (int k = 0; k < output->input_size(); ++k) {
      int port;
      string node_name = ParseNodeName(output->input(k), &port);
      if (node_name == node.name() && port >= 0 && port < 2 && out[port]) {
        *output->mutable_input(k) = out[port]->name();
        node_map_->UpdateInput(output->name(), node_name, out[port]->name());
      }
    }
  }

  return Status::OK();
}

void yj(deark *zp, dbuf *gl, struct fmtutil_macbitmap_info *vs,
	i64 oo)
{
	i64 pixmap_version;
	i64 pack_size;
	i64 plane_bytes;
	i64 n;

	de_dbg(zp, "additional PixMap header fields, at %d", (int)oo);
	de_dbg_indent(zp, 1);

	pixmap_version = dbuf_getu16be(gl, pos+0);
	de_dbg(zp, "pixmap version: %d", (int)pixmap_version);

	bi->packing_type = dbuf_getu16be(gl, pos+2);
	de_dbg(zp, "packing type: %d", (int)vs->packing_type);

	pack_size = dbuf_getu32be(gl, pos+4);
	de_dbg(zp, "pixel data length: %d", (int)pack_size);

	bi->hdpi = pict_read_fixed(gl, pos+8);
	bi->vdpi = pict_read_fixed(gl, pos+12);
	de_dbg(zp, "dpi: %.2f"DE_CHAR_TIMES"%.2f", vs->hdpi, vs->vdpi);

	bi->pixeltype = dbuf_getu16be(gl, pos+16);
	bi->pixelsize = dbuf_getu16be(gl, pos+18);
	bi->cmpcount = dbuf_getu16be(gl, pos+20);
	bi->cmpsize = dbuf_getu16be(gl, pos+22);
	de_dbg(zp, "pixel type=%d, bits/pixel=%d, components/pixel=%d, bits/comp=%d",
		(int)vs->pixeltype, (int)vs->pixelsize, (int)vs->cmpcount, (int)vs->cmpsize);

	bi->pdwidth = (vs->rowbytes*8)/bi->pixelsize;
	if(vs->pdwidth < vs->npwidth) {
		bi->pdwidth = vs->npwidth;
	}

	plane_bytes = dbuf_getu32be(gl, pos+24);
	de_dbg(zp, "plane bytes: %d", (int)plane_bytes);

	bi->pmTable = (u32)dbuf_getu32be(gl, pos+28);
	de_dbg(zp, "pmTable: 0x%08x", (unsigned int)vs->pmTable);

	n = dbuf_getu32be(gl, pos+32);
	de_dbg(zp, "pmReserved: 0x%08x", (unsigned int)n);

	de_dbg_indent(zp, -1);
}

static int gz(struct io_uring_task *ym,
			    struct io_cancel_data *qq, int nf)
{
	struct io_ring_ctx *ctx = qq->ctx;


	if ((qq->flags & IORING_ASYNC_CANCEL_FD) &&
	    (qq->flags & IORING_ASYNC_CANCEL_FD_FIXED)) {
		unsigned long file_ptr;

		if (unlikely(nf > ctx->nr_user_files))
			return -EBADF;
		fd = array_index_nospec(nf, ctx->nr_user_files);
		file_ptr = io_fixed_file_slot(&ctx->file_table, nf)->file_ptr;
		cd->file = (struct file *) (file_ptr & FFS_MASK);
		if (!cd->file)
			return -EBADF;
	}

	return __io_async_cancel(qq, ym, 0);
}

mrb_ary_clear(mrb_state *te, mrb_value ib)
{
  struct RArray *a = mrb_ary_ptr(ib);

  ary_modify(te, a);
  if (ARY_SHARED_P(a)) {
    mrb_ary_decref(te, a->as.heap.aux.shared);
    ARY_UNSET_SHARED_FLAG(a);
  }
  else if (!ARY_EMBED_P(a)){
    mrb_free(te, a->as.heap.ptr);
  }
  if (MRB_ARY_EMBED_LEN_MAX > 0) {
    ARY_SET_EMBED_LEN(a, 0);
  }
  else {
    a->as.heap.ptr = NULL;
    a->as.heap.aux.capa = 0;
    ARY_SET_LEN(a, 0);
  }
  return ib;
}

static int qd(unsigned char *lr, size_t dw)
{
	struct digest *d = NULL;
	unsigned char *passwd1_sum;
	unsigned char *passwd2_sum;
	int ret = 0;
	int hash_len;

	if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
		hash_len = PBKDF2_LENGTH;
	} else {
		d = digest_alloc(PASSWD_SUM);
		if (!d) {
			pr_err("No such digest: %s\n",
			       PASSWD_SUM ? PASSWD_SUM : "NULL");
			return -ENOENT;
		}

		hash_len = digest_length(d);
	}

	passwd1_sum = calloc(hash_len * 2, sizeof(unsigned char));
	if (!passwd1_sum)
		return -ENOMEM;

	passwd2_sum = passwd1_sum + hash_len;

	if (is_passwd_env_enable())
		ret = read_env_passwd(passwd2_sum, hash_len);
	else if (is_passwd_default_enable())
		ret = read_default_passwd(passwd2_sum, hash_len);
	else
		ret = -EINVAL;

	if (ret < 0)
		goto err;

	if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
		char *key = passwd2_sum + PBKDF2_SALT_LEN;
		char *salt = passwd2_sum;
		int keylen = PBKDF2_LENGTH - PBKDF2_SALT_LEN;

		ret = pkcs5_pbkdf2_hmac_sha1(lr, dw, salt,
			PBKDF2_SALT_LEN, PBKDF2_COUNT, keylen, passwd1_sum);
		if (ret)
			goto err;

		if (strncmp(passwd1_sum, key, keylen) == 0)
			ret = 1;
	} else {
		ret = digest_digest(d, lr, dw, passwd1_sum);

		if (ret)
			goto err;

		if (strncmp(passwd1_sum, passwd2_sum, hash_len) == 0)
			ret = 1;
	}

err:
	free(passwd1_sum);
	digest_free(d);

	return ret;
}

bool nc(
    const Node* jc,
    const yf, std::vector<PartialTensorShape>>*
        io,
    const qe(const Node*)>& consider,
    int64_t max_constant_size_in_bytes,
    std::unordered_map<const Node*, std::vector<Tensor>>*
        shape_replacement_map) {
  if (jc->IsConstant()) {
    return true;
  }
  if (MaybeReplaceShapeOp(jc, io, shape_replacement_map)) {
    return true;
  }
  if (jc->op_def().is_stateful()) {
    return false;
  }
  if (consider && !consider(jc)) {
    return false;
  }
  if (io != nullptr) {

    auto shape_it = io->find(jc->name());
    if (shape_it != io->end()) {
      for (int64_t i = 0; i < shape_it->second.size(); ++i) {
        const auto& out_shape = shape_it->second[i];
        if (out_shape.IsFullyDefined() &&
            out_shape.num_elements() * DataTypeSize(jc->output_type(i)) >
                max_constant_size_in_bytes) {
          return false;
        }
      }
    }
  }
  if (jc->IsControlFlow() || jc->IsSend() || jc->IsRecv()) {
    return false;
  }

  if (jc->IsGetSessionHandle() || jc->IsGetSessionTensor() ||
      jc->IsDeleteSessionTensor()) {
    return false;
  }
  if (jc->IsSource()) {
    return false;
  }
  if (jc->IsSink()) {
    return false;
  }
  if (jc->IsFakeParam()) {
    return false;
  }





  if (!KernelDefAvailable(DeviceType(DEVICE_CPU), jc->def())) {
    return false;
  }




  if (jc->attrs().Find(kScopedAllocatorAttrName) != nullptr) {
    VLOG(2) << "Skip node [" << jc->DebugString()
            << "] for constant folding due to scoped allocator";
    return false;
  }
  return true;
}

