  DCMStreamInfo *yo,LinkedListInfo *bj,unsigned char *gb)
{
  if (ze->scale != (Quantum *) NULL)
    ze->scale=(Quantum *) RelinquishMagickMemory(ze->scale);
  if (cw->gray != (int *) NULL)
    cw->gray=(int *) RelinquishMagickMemory(cw->gray);
  if (cw->blue != (int *) NULL)
