fuzzy_match_item_compare(const void *cs, const void *eq)
{
    int		v1 = ((fuzzyItem_T *)cs)->score;
    int		v2 = ((fuzzyItem_T *)eq)->score;
    int		idx1 = ((fuzzyItem_T *)cs)->idx;
    int		idx2 = ((fuzzyItem_T *)eq)->idx;

    return v1 == v2 ? (idx1 - idx2) : v1 > v2 ? -1 : 1;
}

