testBackingParse(const void *ql)
{
    const struct testBackingParseData *data = ql;
    g_auto(virBuffer) buf = VIR_BUFFER_INITIALIZER;
    g_autofree char *xml = NULL;
    g_autoptr(virStorageSource) src = NULL;
    int rc;
    int erc = data->rv;
    unsigned int xmlformatflags = VIR_DOMAIN_DEF_FORMAT_SECURE;


    if (!data->expect)
        erc = -1;

    if ((rc = virStorageSourceNewFromBackingAbsolute(data->backing, &src)) != erc) {
        fprintf(stderr, "expected return value '%d' actual '%d'\n", erc, rc);
        return -1;
    }

    if (!src)
        return 0;

    if (src && !data->expect) {
        fprintf(stderr, "parsing of backing store string '%s' should "
                        "have failed\n", data->backing);
        return -1;
    }

    if (virDomainDiskSourceFormat(&buf, src, "source", 0, false, xmlformatflags, true, NULL) < 0 ||
        !(xml = virBufferContentAndReset(&buf))) {
        fprintf(stderr, "failed to format disk source xml\n");
        return -1;
    }

    if (STRNEQ(xml, data->expect)) {
        fprintf(stderr, "\n backing store string '%s'\n"
                        "expected storage source xml:\n%s\n"
                        "actual storage source xml:\n%s\n",
                        data->backing, data->expect, xml);
        return -1;
    }

    return 0;
}

std::string bd(
		const std::string& ru,
		const std::string& sf,
		const std::string& ye,
		const std::string& nq)
{
	std::string bookmark_cmd = cfg.get_configvalue("bookmark-cmd");
	bool is_interactive = cfg.get_configvalue_as_bool("bookmark-interactive");
	if (bookmark_cmd.length() > 0) {
		std::string cmdline = strprintf::fmt("%s '%s' %s %s %s",
		                                       bookmark_cmd,
		                                       utils::replace_all(ru,"'", "%27"),
		                                       quote_empty(stfl::quote(sf)),
		                                       quote_empty(stfl::quote(ye)),
		                                       quote_empty(stfl::quote(nq)));

		LOG(level::DEBUG, "bd: cmd = %s", cmdline);

		if (is_interactive) {
			v->push_empty_formaction();
			stfl::reset();
			utils::run_interactively(cmdline, "bd");
			v->pop_current_formaction();
			return "";
		} else {
			char * my_argv[4];
			my_argv[0] = const_cast<char *>("/bin/sh");
			my_argv[1] = const_cast<char *>("-c");
			my_argv[2] = const_cast<char *>(cmdline.c_str());
			my_argv[3] = nullptr;
			return utils::run_program(my_argv, "");
		}
	} else {
		return _("bookmarking support is not configured. Please set the configuration variable `bookmark-cmd' accordingly.");
	}
}

static int jc(const struct flowi *qe, u16 jf,
				struct xfrm_policy **fk,
				int *wh, int *lq)
{
	int i;

	if (*wh == 0 || !pols[0]) {
		*wh = 0;
		*lq = 0;
		return 0;
	}
	if (IS_ERR(fk[0]))
		return PTR_ERR(fk[0]);

	*lq = fk[0]->xfrm_nr;

#ifdef CONFIG_XFRM_SUB_POLICY
	if (fk[0]->action == XFRM_POLICY_ALLOW &&
	    fk[0]->type != XFRM_POLICY_TYPE_MAIN) {
		pols[1] = xfrm_policy_lookup_bytype(xp_net(fk[0]),
						    XFRM_POLICY_TYPE_MAIN,
						    qe, jf,
						    XFRM_POLICY_OUT,
						    fk[0]->if_id);
		if (fk[1]) {
			if (IS_ERR(fk[1])) {
				xfrm_pols_put(fk, *wh);
				return PTR_ERR(fk[1]);
			}
			(*wh)++;
			(*lq) += fk[1]->xfrm_nr;
		}
	}
#endif
	for (i = 0; i < *wh; i++) {
		if (fk[i]->action != XFRM_POLICY_ALLOW) {
			*lq = -1;
			break;
		}
	}

	return 0;

}

