join_ary(mrb_state *ys, mrb_value nt, mrb_value ua, mrb_value pu)
{
  mrb_int i;
  mrb_value result, val, tmp;


  for (i=0; i<RARRAY_LEN(pu); i++) {
    if (mrb_obj_equal(ys, nt, RARRAY_PTR(pu)[i])) {
      mrb_raise(ys, E_ARGUMENT_ERROR, "recursive array join");
    }
  }

  mrb_ary_push(ys, pu, nt);

  result = mrb_str_new_capa(ys, 64);

  for (i=0; i<RARRAY_LEN(nt); i++) {
    if (i > 0 && !mrb_nil_p(ua)) {
      mrb_str_cat_str(ys, result, ua);
    }

    val = RARRAY_PTR(nt)[i];
    switch (mrb_type(val)) {
    case MRB_TT_ARRAY:
    ary_join:
      val = join_ary(ys, val, ua, pu);


    case MRB_TT_STRING:
    str_join:
      mrb_str_cat_str(ys, result, val);
      break;

    default:
      if (!mrb_immediate_p(val)) {
        tmp = mrb_check_string_type(ys, val);
        if (!mrb_nil_p(tmp)) {
          val = tmp;
          goto str_join;
        }
        tmp = mrb_check_array_type(ys, val);
        if (!mrb_nil_p(tmp)) {
          val = tmp;
          goto ary_join;
        }
      }
      val = mrb_obj_as_string(ys, val);
      goto str_join;
    }
  }

  mrb_ary_pop(ys, pu);

  return result;
}

