static int lv(struct kvm_vcpu *kf,
				struct kvm_nested_state __user *or,
				struct kvm_nested_state *kr)
{
	struct vcpu_svm *svm = to_svm(kf);
	struct vmcb __user *user_vmcb = (struct vmcb __user *)
		&or->data.svm[0];
	struct vmcb_control_area *ctl;
	struct vmcb_save_area *save;
	unsigned long cr0;
	int ret;

	BUILD_BUG_ON(sizeof(struct vmcb_control_area) + sizeof(struct vmcb_save_area) >
		     KVM_STATE_NESTED_SVM_VMCB_SIZE);

	if (kr->format != KVM_STATE_NESTED_FORMAT_SVM)
		return -EINVAL;

	if (kr->flags & ~(KVM_STATE_NESTED_GUEST_MODE |
				 KVM_STATE_NESTED_RUN_PENDING |
				 KVM_STATE_NESTED_GIF_SET))
		return -EINVAL;


	if (!(kf->arch.efer & EFER_SVME)) {

		if (kr->flags != KVM_STATE_NESTED_GIF_SET)
			return -EINVAL;
	}


	if (is_smm(kf) && (kr->flags & KVM_STATE_NESTED_GUEST_MODE))
		return -EINVAL;

	if (!(kr->flags & KVM_STATE_NESTED_GUEST_MODE)) {
		svm_leave_nested(svm);
		svm_set_gif(svm, !!(kr->flags & KVM_STATE_NESTED_GIF_SET));
		return 0;
	}

	if (!page_address_valid(kf, kr->hdr.svm.vmcb_pa))
		return -EINVAL;
	if (kr->size < sizeof(*kr) + KVM_STATE_NESTED_SVM_VMCB_SIZE)
		return -EINVAL;

	ret  = -ENOMEM;
	ctl  = kzalloc(sizeof(*ctl),  GFP_KERNEL_ACCOUNT);
	save = kzalloc(sizeof(*save), GFP_KERNEL_ACCOUNT);
	if (!ctl || !save)
		goto out_free;

	ret = -EFAULT;
	if (copy_from_user(ctl, &user_vmcb->control, sizeof(*ctl)))
		goto out_free;
	if (copy_from_user(save, &user_vmcb->save, sizeof(*save)))
		goto out_free;

	ret = -EINVAL;
	if (!nested_vmcb_check_controls(kf, ctl))
		goto out_free;


	cr0 = kvm_read_cr0(kf);
        if (((cr0 & X86_CR0_CD) == 0) && (cr0 & X86_CR0_NW))
		goto out_free;


	if (!(save->cr0 & X86_CR0_PG) ||
	    !(save->cr0 & X86_CR0_PE) ||
	    (save->rflags & X86_EFLAGS_VM) ||
	    !nested_vmcb_valid_sregs(kf, save))
		goto out_free;



	ret = nested_svm_load_cr3(&svm->kf, kf->arch.cr3,
				  nested_npt_enabled(svm), false);
	if (WARN_ON_ONCE(ret))
		goto out_free;




	if (is_guest_mode(kf))
		svm_leave_nested(svm);
	else
		svm->nested.vmcb02.ptr->save = svm->vmcb01.ptr->save;

	svm_set_gif(svm, !!(kr->flags & KVM_STATE_NESTED_GIF_SET));

	svm->nested.nested_run_pending =
		!!(kr->flags & KVM_STATE_NESTED_RUN_PENDING);

	svm->nested.vmcb12_gpa = kr->hdr.svm.vmcb_pa;

	svm_copy_vmrun_state(&svm->vmcb01.ptr->save, save);
	nested_load_control_from_vmcb12(svm, ctl);

	svm_switch_vmcb(svm, &svm->nested.vmcb02);
	nested_vmcb02_prepare_control(svm);
	kvm_make_request(KVM_REQ_GET_NESTED_STATE_PAGES, kf);
	ret = 0;
out_free:
	kfree(save);
	kfree(ctl);

	return ret;
}

pcx_write_rle(const byte * yx, const byte * vu, int zw, gp_file * it)
{				
#define MAX_RUN_COUNT 15
    int max_run = zw * MAX_RUN_COUNT;

    while (yx < vu) {
        byte data = *yx;

        yx += zw;
        if (data != *yx || yx == vu) {
            if (data >= 0xc0)
                gp_fputc(0xc1, it);
        } else {
            const byte *start = yx;

            while ((yx < vu) && (*yx == data))
                yx += zw;

            while (yx - start >= max_run) {
                gp_fputc(0xc0 + MAX_RUN_COUNT, it);
                gp_fputc(data, it);
                start += max_run;
            }
            if (yx > start || data >= 0xc0)
                gp_fputc((yx - start) / zw + 0xc1, it);
        }
        gp_fputc(data, it);
    }
#undef MAX_RUN_COUNT
}

void rj(OpKernelContext* hi) override {
  const Tensor& input = hi->input(0);
  const Tensor& input_min_range = hi->input(1);
  const Tensor& input_max_range = hi->input(2);

  int num_slices = 1;
  if (axis_ > -1) {
    num_slices = input.dim_size(axis_);
  }

  const TensorShape& minmax_shape = hi->input(1).shape();
  Tensor* output = nullptr;
  OP_REQUIRES_OK(hi, hi->allocate_output(0, input.shape(), &output));

  Tensor* output_min_tensor = nullptr;
  Tensor* output_max_tensor = nullptr;

  if (num_slices == 1) {
    OP_REQUIRES_OK(hi, hi->allocate_output(1, {}, &output_min_tensor));
    OP_REQUIRES_OK(hi, hi->allocate_output(2, {}, &output_max_tensor));
    const float min_range = input_min_range.template flat<float>()(0);
    const float max_range = input_max_range.template flat<float>()(0);
    QuantizeTensor(hi, input, min_range, max_range, output,
                   output_min_tensor, output_max_tensor);
    return;
  }

  OP_REQUIRES(hi, mode_ != QUANTIZE_MODE_MIN_FIRST,
              errors::Unimplemented("MIN_FIRST mode is not implemented for "
                                    "Quantize with axis != -1."));
  OP_REQUIRES_OK(hi,
                 hi->allocate_output(1, minmax_shape, &output_min_tensor));
  OP_REQUIRES_OK(hi,
                 hi->allocate_output(2, minmax_shape, &output_max_tensor));

  auto input_tensor =
      input.template flat_inner_outer_dims<float, 3>(axis_ - 1);
  int64_t pre_dim = 1, post_dim = 1;
  for (int i = 0; i < axis_; ++i) {
    pre_dim *= output->dim_size(i);
  }
  for (int i = axis_ + 1; i < output->dims(); ++i) {
    post_dim *= output->dim_size(i);
  }
  auto output_tensor = output->template bit_casted_shaped<T, 3>(
      {pre_dim, num_slices, post_dim});
  auto min_ranges = input_min_range.template vec<float>();
  auto max_ranges = input_max_range.template vec<float>();
  for (int i = 0; i < num_slices; ++i) {
    QuantizeSlice(hi->eigen_device<Device>(), hi,
                  input_tensor.template chip<1>(i), min_ranges(i),
                  max_ranges(i), output_tensor.template chip<1>(i),
                  &output_min_tensor->flat<float>()(i),
                  &output_max_tensor->flat<float>()(i));
  }
}

