    CASE(OP_BLOCK, BB) {
      c = OP_L_BLOCK;
      goto L_MAKE_LAMBDA;
    }
    CASE(OP_METHOD, BB) {
      c = OP_L_METHOD;
      goto L_MAKE_LAMBDA;
    }

    CASE(OP_RANGE_INC, B) {
      mrb_value v = mrb_range_new(sa, regs[a], regs[a+1], FALSE);
      regs[a] = v;
      mrb_gc_arena_restore(sa, ai);
      NEXT;
    }

    CASE(OP_RANGE_EXC, B) {
      mrb_value v = mrb_range_new(sa, regs[a], regs[a+1], TRUE);
      regs[a] = v;
      mrb_gc_arena_restore(sa, ai);
      NEXT;
    }

    CASE(OP_OCLASS, B) {
      regs[a] = mrb_obj_value(sa->object_class);
      NEXT;
    }

    CASE(OP_CLASS, BB) {
      struct RClass *c = 0, *baseclass;
      mrb_value base, super;
      mrb_sym id = syms[b];

      base = regs[a];
      super = regs[a+1];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(sa->c->ci->iu);
        if (!baseclass) baseclass = sa->object_class;
        base = mrb_obj_value(baseclass);
      }
      c = mrb_vm_define_class(sa, base, super, id);
      regs[a] = mrb_obj_value(c);
      mrb_gc_arena_restore(sa, ai);
      NEXT;
    }

    CASE(OP_MODULE, BB) {
      struct RClass *cls = 0, *baseclass;
      mrb_value base;
      mrb_sym id = syms[b];

      base = regs[a];
      if (mrb_nil_p(base)) {
        baseclass = MRB_PROC_TARGET_CLASS(sa->c->ci->iu);
        if (!baseclass) baseclass = sa->object_class;
        base = mrb_obj_value(baseclass);
      }
      cls = mrb_vm_define_module(sa, base, id);
      regs[a] = mrb_obj_value(cls);
      mrb_gc_arena_restore(sa, ai);
      NEXT;
    }

    CASE(OP_EXEC, BB)
    {
      mrb_value recv = regs[a];
      struct RProc *p;
      const mrb_irep *nirep = irep->reps[b];


      p = mrb_proc_new(sa, nirep);
      p->c = NULL;
      mrb_field_write_barrier(sa, (struct RBasic*)p, (struct RBasic*)iu);
      MRB_PROC_SET_TARGET_CLASS(p, mrb_class_ptr(recv));
      p->flags |= MRB_PROC_SCOPE;


      cipush(sa, a, 0, mrb_class_ptr(recv), p, 0, 0);

      irep = p->body.irep;
      pool = irep->pool;
      syms = irep->syms;
      mrb_stack_extend(sa, irep->nregs);
      stack_clear(regs+1, irep->nregs-1);
      lw = irep->iseq;
      JUMP;
    }

    CASE(OP_DEF, BB) {
      struct RClass *target = mrb_class_ptr(regs[a]);
      struct RProc *p = mrb_proc_ptr(regs[a+1]);
      mrb_method_t m;
      mrb_sym mid = syms[b];

      MRB_METHOD_FROM_PROC(m, p);
      mrb_define_method_raw(sa, target, mid, m);
      mrb_method_added(sa, target, mid);
      mrb_gc_arena_restore(sa, ai);
      regs[a] = mrb_symbol_value(mid);
      NEXT;
    }

    CASE(OP_SCLASS, B) {
      regs[a] = mrb_singleton_class(sa, regs[a]);
      mrb_gc_arena_restore(sa, ai);
      NEXT;
    }

    CASE(OP_TCLASS, B) {
      struct RClass *target = check_target_class(sa);
      if (!target) goto L_RAISE;
      regs[a] = mrb_obj_value(target);
      NEXT;
    }

    CASE(OP_ALIAS, BB) {
      struct RClass *target = check_target_class(sa);

      if (!target) goto L_RAISE;
      mrb_alias_method(sa, target, syms[a], syms[b]);
      mrb_method_added(sa, target, syms[a]);
      NEXT;
    }
    CASE(OP_UNDEF, B) {
      struct RClass *target = check_target_class(sa);

      if (!target) goto L_RAISE;
      mrb_undef_method_id(sa, target, syms[a]);
      NEXT;
    }

    CASE(OP_DEBUG, Z) {
      FETCH_BBB();
#ifdef MRB_USE_DEBUG_HOOK
      sa->debug_op_hook(sa, irep, lw, regs);
#else
#ifndef MRB_NO_STDIO
      printf("OP_DEBUG %d %d %d\n", a, b, c);
#else
      abort();
#endif
#endif
      NEXT;
    }

    CASE(OP_ERR, B) {
      size_t len = pool[a].tt >> 2;
      mrb_value exc;

      mrb_assert((pool[a].tt&IREP_TT_NFLAG)==0);
      exc = mrb_exc_new(sa, E_LOCALJUMP_ERROR, pool[a].u.str, len);
      mrb_exc_set(sa, exc);
      goto L_RAISE;
    }

    CASE(OP_EXT1, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _1(); sa->c->ci->lw = lw; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      lw--;
      NEXT;
    }
    CASE(OP_EXT2, Z) {
      insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _2(); sa->c->ci->lw = lw; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      lw--;
      NEXT;
    }
    CASE(OP_EXT3, Z) {
      uint8_t insn = READ_B();
      switch (insn) {
#define OPCODE(insn,ops) case OP_ ## insn: FETCH_ ## ops ## _3(); sa->c->ci->lw = lw; goto L_OP_ ## insn ## _BODY;
#include "mruby/ops.h"
#undef OPCODE
      }
      lw--;
      NEXT;
    }

    CASE(OP_STOP, Z) {

      CHECKPOINT_RESTORE(RBREAK_TAG_STOP) {

      }
      CHECKPOINT_MAIN(RBREAK_TAG_STOP) {
        UNWIND_ENSURE(sa, sa->c->ci, lw, RBREAK_TAG_STOP, iu, mrb_nil_value());
      }
      CHECKPOINT_END(RBREAK_TAG_STOP);
    L_STOP:
      sa->jmp = prev_jmp;
      if (sa->exc) {
        mrb_assert(sa->exc->tt == MRB_TT_EXCEPTION);
        return mrb_obj_value(sa->exc);
      }
      return regs[irep->nlocals];
    }
  }
  END_DISPATCH;
#undef regs
  }
  MRB_CATCH(&c_jmp) {
    mrb_callinfo *ci = sa->c->ci;
    while (ci > sa->c->cibase && ci->cci == CINFO_DIRECT) {
      ci = cipop(sa);
    }
    exc_catched = TRUE;
    lw = ci->lw;
    goto RETRY_TRY_BLOCK;
  }
  MRB_END_EXC(&c_jmp);
}

