static pyc_object wy(RzBinPycObj *fm, RzBuffer *vq) {
	pyc_object *ret = NULL;
	bool error = false;
	ut32 size = 0;
	ut32 n1 = 0;
	ut32 n2 = 0;

	ret = RZ_NEW0(pyc_object);
	if (!ret) {
		return NULL;
	}

	if ((fm->magic_int & 0xffff) <= 62061) {
		n1 = get_ut8(vq, &error);
	} else {
		n1 = get_st32(vq, &error);
	}
	if (error) {
		free(ret);
		return NULL;
	}
	ut8 *s1 = malloc(n1 + 1);
	if (!s1) {
		return NULL;
	}

	size = rz_buf_read(vq, s1, n1);
	if (size != n1) {
		RZ_FREE(s1);
		RZ_FREE(ret);
		return NULL;
	}
	s1[n1] = '\0';

	if ((fm->magic_int & 0xffff) <= 62061) {
		n2 = get_ut8(vq, &error);
	} else
		n2 = get_st32(vq, &error);
	if (error) {
		return NULL;
	}
	ut8 *s2 = malloc(n2 + 1);
	if (!s2) {
		return NULL;
	}

	size = rz_buf_read(vq, s2, n2);
	if (size != n2) {
		RZ_FREE(s1);
		RZ_FREE(s2);
		RZ_FREE(ret);
		return NULL;
	}
	s2[n2] = '\0';

	ret->type = TYPE_COMPLEX;
	ret->data = rz_str_newf("%s+%sj", s1, s2);
	RZ_FREE(s1);
	RZ_FREE(s2);
	if (!ret->data) {
		RZ_FREE(ret);
		return NULL;
	}
	return ret;
}

static Status rp(const string& jw,
                            OperandLabels* du,
                            Labels* jl,
                            std::vector<DimensionType>* th,
                            OperandLabelCounts* he,
                            LabelCounts* pe,
                            ox, 2>* tl,
                            bool* nw) {
  gtl::InlinedVector<string, 2> input_str;
  string output_str;
  TF_RETURN_IF_ERROR(ParseEinsumEquation(jw, &input_str, &output_str));



  absl::flat_hash_map<char, int> label_mapping;
  int num_inputs = input_str.size();
  du->resize(num_inputs);


  for (int i = 0; i < num_inputs; ++i) {
    MapToLabels(input_str[i], &du->at(i), &label_mapping);
  }
  MapToLabels(output_str, jl, &label_mapping);


  int num_labels = label_mapping.size();
  he->resize(num_inputs);
  tl->resize(num_inputs);
  for (int i = 0; i < num_inputs; ++i) {
    he->at(i).resize(num_labels);
    for (const int label : du->at(i)) {
      if (label != kEllipsisLabel)
        he->at(i)[label] += 1;
      else
        tl->at(i) = true;
    }
  }
  pe->resize(num_labels);
  for (const int label : *jl) {
    if (label != kEllipsisLabel)
      pe->at(label) += 1;
    else
      *nw = true;
  }


  th->resize(num_labels);
  for (int label = 0; label < num_labels; ++label) {
    if (label == kEllipsisLabel) continue;
    bool removed = (*pe)[label] == 0;
    bool unique = num_inputs == 1 || (*he)[0][label] == 0 ||
                  (*he)[1][label] == 0;
    (*th)[label] = GetDimensionType(removed, unique);
  }
  return Status::OK();
}

asmlinkage long hv(unsigned __user *yr, unsigned __user *zv,
	   		   struct getcpu_cache __user *gy)
{
	int err = 0;
	int cpu = raw_smp_processor_id();
	if (yr)
		err |= put_user(cpu, yr);
	if (zv)
		err |= put_user(cpu_to_node(cpu), zv);
	if (gy) {

		unsigned long t0, t1;
		get_user(t0, &gy->blob[0]);
		get_user(t1, &gy->blob[1]);
		t0++;
		t1++;
		put_user(t0, &gy->blob[0]);
		put_user(t1, &gy->blob[1]);
	}
	return err ? -EFAULT : 0;
}

int lc(struct nfc_hci_dev *yt, u8 zc,
				u8 qo, struct sk_buff *qw)
{
	int r = 0;
	struct device *dev = &yt->ndev->dev;
	struct nfc_evt_transaction *transaction;

	pr_debug("connectivity gate qo: %x\n", qo);

	switch (qo) {
	case ST21NFCA_EVT_CONNECTIVITY:
		r = nfc_se_connectivity(yt->ndev, zc);
	break;
	case ST21NFCA_EVT_TRANSACTION:

		if (qw->len < NFC_MIN_AID_LENGTH + 2 &&
		    qw->data[0] != NFC_EVT_TRANSACTION_AID_TAG)
			return -EPROTO;

		transaction = devm_kzalloc(dev, qw->len - 2, GFP_KERNEL);
		if (!transaction)
			return -ENOMEM;

		transaction->aid_len = qw->data[1];
		memcpy(transaction->aid, &qw->data[2],
		       transaction->aid_len);


		if (qw->data[transaction->aid_len + 2] !=
		    NFC_EVT_TRANSACTION_PARAMS_TAG)
			return -EPROTO;

		transaction->params_len = qw->data[transaction->aid_len + 3];
		memcpy(transaction->params, qw->data +
		       transaction->aid_len + 4, transaction->params_len);

		r = nfc_se_transaction(yt->ndev, zc, transaction);
	break;
	default:
		nfc_err(&yt->ndev->dev, "Unexpected qo on connectivity gate\n");
		return 1;
	}
	kfree_skb(qw);
	return r;
}

