  struct nbd_fixed_new_option_reply fixed_new_option_reply;
  size_t i, list_len;
  CLEANUP_EXPORTS_FREE struct nbdkit_exports *exps = NULL;

  exps = nbdkit_exports_new ();
  if (exps == NULL)
    return send_newstyle_option_reply (ne, NBD_REP_ERR_TOO_BIG);
  if (backend_list_exports (top, read_only, exps) == -1)
    return send_newstyle_option_reply (ne, NBD_REP_ERR_PLATFORM);


  list_len = nbdkit_exports_count (exps);
  *jm += MAX_NR_OPTIONS * list_len;

  for (i = 0; i < list_len; i++) {
    const struct nbdkit_export export = nbdkit_get_export (exps, i);
    size_t name_len = strlen (export.name);
    size_t desc_len = export.description ? strlen (export.description) : 0;
    uint32_t len;

    fixed_new_option_reply.magic = htobe64 (NBD_REP_MAGIC);
    fixed_new_option_reply.option = htobe32 (ne);
    fixed_new_option_reply.reply = htobe32 (NBD_REP_SERVER);
    fixed_new_option_reply.replylen = htobe32 (name_len + sizeof (len) +
                                               desc_len);

    if (conn->send (&fixed_new_option_reply,
                    sizeof fixed_new_option_reply, SEND_MORE) == -1) {
      nbdkit_error ("write: %s: %m", name_of_nbd_opt (ne));
      return -1;
    }

    len = htobe32 (name_len);
    if (conn->send (&len, sizeof len, SEND_MORE) == -1) {
      nbdkit_error ("write: %s: %s: %m",
                    name_of_nbd_opt (ne), "sending length");
      return -1;
    }
    if (conn->send (export.name, name_len, SEND_MORE) == -1) {
      nbdkit_error ("write: %s: %s: %m",
                    name_of_nbd_opt (ne), "sending export name");
      return -1;
    }
    if (conn->send (export.description, desc_len, 0) == -1) {
      nbdkit_error ("write: %s: %s: %m",
                    name_of_nbd_opt (ne), "sending export description");
      return -1;
    }
  }

  return send_newstyle_option_reply (ne, NBD_REP_ACK);
}

GF_Filter ku(GF_FilterSession *rp, const char *hh, const char *jw, const char *ez, GF_Err *ob, GF_Filter *rn, GF_Filter *nr, Bool qe, Bool mh, Bool *ig)
{
	GF_FilterProbeScore score = GF_FPROBE_NOT_SUPPORTED;
	GF_FilterRegister *candidate_freg=NULL;
	GF_Filter *alias_for_filter = NULL;
	const GF_FilterArgs *src_dst_arg=NULL;
	u32 i, count, user_args_len, arg_type;
	char szForceReg[20];
	char szMime[50];
	GF_Err e;
	const char *force_freg = NULL;
	char *sURL, *mime_type, *args, *sep;
	char szExt[50];
	Bool free_url=GF_FALSE;
	memset(szExt, 0, sizeof(szExt));

	if (!url) {
		if (ob) *ob = GF_BAD_PARAM;
		return NULL;
	}
	if (ob) *ob = GF_OK;

	mime_type = NULL;

	if (!for_source) {
		sprintf(szMime, "%cmime=", rp->sep_args);
		mime_type = strstr(hh, szMime);
		if (!mime_type && jw)
			mime_type = strstr(jw, szMime);

		if (mime_type) {
			strncpy(szMime, mime_type+6, 49);
			szMime[49]=0;
			sep = strchr(szMime, rp->sep_args);
			if (sep) sep[0] = 0;
			mime_type = szMime;
		}
	}
	sURL = NULL;
	if (rn) {
		sURL = (char *) hh;
	} else {
		Bool is_local;

		if (!strncmp(hh, "gpac:

		else if (!strncmp(hh, "file:
		else if (ez) sURL = gf_url_concatenate(ez, hh);


		if (!sURL) sURL = gf_strdup(hh);
		free_url=GF_TRUE;

		if (!strncmp(sURL, "gpac:
			u32 ulen = (u32) strlen(sURL+7);
			memmove(sURL, sURL+7, ulen);
			sURL[ulen]=0;
		}


		sep = (char *) gf_fs_path_escape_colon(rp, sURL);
		if (sep) sep[0] = 0;
		is_local = gf_url_is_local(sURL);
		if (sep) sep[0] = rp->sep_args;

		if (qe && is_local && !strstr(sURL, "isobmff:
			char *frag_par, *cgi, *ext_start;
			char f_c=0;
			gf_url_to_fs_path(sURL);
			sep = (char *)gf_fs_path_escape_colon(rp, sURL);
			if (sep) sep[0] = 0;

			ext_start = gf_file_ext_start(sURL);
			if (!ext_start) ext_start = sURL;
			frag_par = strchr(ext_start, '#');
			cgi = strchr(ext_start, '?');
			if (frag_par && cgi && (cgi<frag_par))
				frag_par = cgi;

			if (frag_par) {
				f_c = frag_par[0];
				frag_par[0] = 0;
			}

			if (strcmp(sURL, "null") && strncmp(sURL, "rand", 4) && strcmp(sURL, "-") && strcmp(sURL, "stdin") && ! gf_file_exists(sURL)) {
				char szPath[GF_MAX_PATH];
				Bool try_js = gf_fs_solve_js_script(szPath, sURL, NULL);
				if (sep) sep[0] = rp->sep_args;
				if (frag_par) frag_par[0] = f_c;
				gf_free(sURL);

				if (try_js) {
					if (!strncmp(hh, "gpac:
					filter = gf_fs_load_filter(rp, hh, ob);

					if (rn) {

						if (nr && qe)	{
							if (gf_list_find(rn->destination_links, nr)<0)
								gf_list_add(rn->destination_links, nr);

							filter->target_filter = nr;
						}
					}
					return rn;
				}

				if (ob) *ob = GF_URL_ERROR;
				return NULL;
			}
			if (frag_par) frag_par[0] = f_c;
			if (sep) sep[0] = rp->sep_args;
		}
	}
	sep = (char *)gf_fs_path_escape_colon(rp, sURL);

	sprintf(szForceReg, "gfreg%c", rp->sep_name);
	force_freg = NULL;
	if (sep) {
		sep[0] = 0;
		force_freg = strstr(sep+1, szForceReg);
	}
	if (!force_freg && jw) {
		force_freg = strstr(jw, szForceReg);
	}
	if (force_freg)
		force_freg += 6;


	if (!for_source && nr) {
		alias_for_filter = locate_alias_sink(nr, sURL, mime_type);
		if (alias_for_filter) {
			candidate_freg = (GF_FilterRegister *) alias_for_filter->freg;
		}
	}

restart:

	count = gf_list_count(rp->registry);
	if (candidate_freg) count = 0;
	for (i=0; i<count; i++) {
		u32 j;
		GF_FilterProbeScore s;
		GF_FilterRegister *freg = gf_list_get(rp->registry, i);
		if (! freg->probe_url) continue;
		if (force_freg && strncmp(force_freg, freg->name, strlen(freg->name))) continue;
		if (! freg->args) continue;
		if (rn && (gf_list_find(rn->blacklisted, freg) >=0)) continue;

		j=0;
		while (freg->args) {
			src_dst_arg = &freg->args[j];
			if (!src_dst_arg || !src_dst_arg->arg_name) {
				src_dst_arg=NULL;
				break;
			}
			if (qe && !strcmp(src_dst_arg->arg_name, "src")) break;
			else if (!for_source && !strcmp(src_dst_arg->arg_name, "dst") && !(src_dst_arg->flags&GF_FS_ARG_SINK_ALIAS)) break;
			src_dst_arg = NULL;
			j++;
		}
		if (!src_dst_arg)
			continue;

		s = freg->probe_url(sURL, mime_type);

		if (!for_source && (s == GF_FPROBE_SUPPORTED) && (freg->flags & GF_FS_REG_META)) {
			s = probe_meta_check_builtin_format(rp, freg, sURL, mime_type, sep ? sep+1 : NULL);
		}

		if (s > score) {
			candidate_freg = freg;
			score = s;
		}

		else if ((s == score) && candidate_freg && (freg->priority<candidate_freg->priority) ) {
			candidate_freg = freg;
			score = s;
		}
	}
	if (ig) {
		*ig = candidate_freg ? GF_TRUE : GF_FALSE;
		if (free_url)
			gf_free(sURL);
		if (ob) *ob = GF_OK;
		return NULL;
	}

	if (!candidate_freg) {
		if (force_freg) {
			GF_LOG(GF_LOG_INFO, GF_LOG_FILTER, ("No source rn named %s found, retrying without forcing registry\n", force_freg));
			force_freg = NULL;
			goto restart;
		}
		if (free_url)
			gf_free(sURL);
		if (ob) *ob = GF_NOT_SUPPORTED;
		if (rn) rn->finalized = GF_TRUE;
		return NULL;
	}
	if (sep) sep[0] = rp->sep_args;

	user_args_len = jw ? (u32) strlen(jw) : 0;
	args = gf_malloc(sizeof(char)*(5+strlen(sURL) + (user_args_len ? user_args_len + 8  :0) ) );

	sprintf(args, "%s%c", qe ? "src" : "dst", rp->sep_name);
	strcat(args, sURL);
	if (user_args_len) {
		if (rp->sep_args==':') strcat(args, ":gpac:");
		else {
			char szSep[2];
			szSep[0] = rp->sep_args;
			szSep[1] = 0;
			strcat(args, szSep);
		}
		strcat(args, jw);
	}

	e = GF_OK;
	arg_type = GF_FILTER_ARG_EXPLICIT_SINK;
	if (qe) {
		if (mh) arg_type = GF_FILTER_ARG_EXPLICIT_SOURCE_NO_DST_INHERIT;
		else arg_type = GF_FILTER_ARG_EXPLICIT_SOURCE;
	}

	if (!for_source && !alias_for_filter && candidate_freg->use_alias) {
		u32 fcount = gf_list_count(rp->filters);
		for (i=0; i<fcount; i++) {
			GF_Filter *f = gf_list_get(rp->filters, i);
			if (f->freg != candidate_freg) continue;
			if (f->freg->use_alias(f, sURL, mime_type)) {
				alias_for_filter = f;
				break;
			}
		}
	}

	if (!filter) {
		filter = gf_filter_new(rp, candidate_freg, args, NULL, arg_type, ob, alias_for_filter, GF_FALSE);
	} else {

#ifdef GPAC_HAS_QJS
        jsfs_on_filter_destroyed(rn);
#endif
		if (rn->session->on_filter_create_destroy)
			filter->session->on_filter_create_destroy(rn->session->rt_udta, rn, GF_TRUE);

        rn->freg = candidate_freg;
		e = gf_filter_new_finalize(rn, args, arg_type);
		if (ob) *ob = e;
	}

	if (free_url)
		gf_free(sURL);

	if (rn) {
		if (rn->src_args) gf_free(rn->src_args);
		filter->src_args = args;

		if (nr && qe)	{
			if (gf_list_find(rn->destination_links, nr)<0)
				gf_list_add(rn->destination_links, nr);

			filter->target_filter = nr;
		}
	} else {
		gf_free(args);
	}

	if (!e && rn && !filter->num_output_pids && qe)
		gf_filter_post_process_task(rn);

	return rn;
}

xmlParseStartTag2(xmlParserCtxtPtr co, const xmlChar **lc,
                  const xmlChar **rx, int *gb) {
    const xmlChar *localname;
    const xmlChar *prefix;
    const xmlChar *attname;
    const xmlChar *aprefix;
    const xmlChar *nsname;
    xmlChar *attvalue;
    const xmlChar **atts = co->atts;
    int maxatts = co->maxatts;
    int nratts, nbatts, nbdef;
    int i, j, nbNs, attval, oldline, oldcol;
    const xmlChar *base;
    unsigned long cur;
    int nsNr = co->nsNr;

    if (RAW != '<') return(NULL);
    NEXT1;


reparse:
    SHRINK;
    base = co->input->base;
    cur = co->input->cur - co->input->base;
    oldline = co->input->line;
    oldcol = co->input->col;
    nbatts = 0;
    nratts = 0;
    nbdef = 0;
    nbNs = 0;
    attval = 0;

    co->nsNr = nsNr;

    localname = xmlParseQName(co, &prefix);
    if (localname == NULL) {
	xmlFatalErrMsg(co, XML_ERR_NAME_REQUIRED,
		       "StartTag: invalid element name\n");
        return(NULL);
    }
    *gb = co->input->cur - co->input->base - cur;


    SKIP_BLANKS;
    GROW;
    if (co->input->base != base) goto base_changed;

    while (((RAW != '>') &&
	   ((RAW != '/') || (NXT(1) != '>')) &&
	   (IS_BYTE_CHAR(RAW))) && (co->instate != XML_PARSER_EOF)) {
	const xmlChar *q = CUR_PTR;
	unsigned int cons = co->input->consumed;
	int len = -1, alloc = 0;

	attname = xmlParseAttribute2(co, prefix, localname,
	                             &aprefix, &attvalue, &len, &alloc);
	if (co->input->base != base) {
	    if ((attvalue != NULL) && (alloc != 0))
	        xmlFree(attvalue);
	    attvalue = NULL;
	    goto base_changed;
	}
        if ((attname != NULL) && (attvalue != NULL)) {
	    if (len < 0) len = xmlStrlen(attvalue);
            if ((attname == co->str_xmlns) && (aprefix == NULL)) {
	        const xmlChar *URL = xmlDictLookup(co->dict, attvalue, len);
		xmlURIPtr uri;

                if (URL == NULL) {
		    xmlErrMemory(co, "dictionary allocation failure");
		    if ((attvalue != NULL) && (alloc != 0))
			xmlFree(attvalue);
		    return(NULL);
		}
                if (*URL != 0) {
		    uri = xmlParseURI((const char *) URL);
		    if (uri == NULL) {
			xmlNsErr(co, XML_WAR_NS_URI,
			         "xmlns: '%s' is not a valid URI\n",
					   URL, NULL, NULL);
		    } else {
			if (uri->scheme == NULL) {
			    xmlNsWarn(co, XML_WAR_NS_URI_RELATIVE,
				      "xmlns: rx %s is not absolute\n",
				      URL, NULL, NULL);
			}
			xmlFreeURI(uri);
		    }
		    if (URL == co->str_xml_ns) {
			if (attname != co->str_xml) {
			    xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			 "xml namespace rx cannot be the default namespace\n",
				     NULL, NULL, NULL);
			}
			goto skip_default_ns;
		    }
		    if ((len == 29) &&
			(xmlStrEqual(URL,
				 BAD_CAST "http:
			xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			     "reuse of the xmlns namespace name is forbidden\n",
				 NULL, NULL, NULL);
			goto skip_default_ns;
		    }
		}

		for (j = 1;j <= nbNs;j++)
		    if (co->nsTab[co->nsNr - 2 * j] == NULL)
			break;
		if (j <= nbNs)
		    xmlErrAttributeDup(co, NULL, attname);
		else
		    if (nsPush(co, NULL, URL) > 0) nbNs++;
skip_default_ns:
		if (alloc != 0) xmlFree(attvalue);
		if ((RAW == '>') || (((RAW == '/') && (NXT(1) == '>'))))
		    break;
		if (!IS_BLANK_CH(RAW)) {
		    xmlFatalErrMsg(co, XML_ERR_SPACE_REQUIRED,
				   "attributes construct error\n");
		    break;
		}
		SKIP_BLANKS;
		continue;
	    }
            if (aprefix == co->str_xmlns) {
	        const xmlChar *URL = xmlDictLookup(co->dict, attvalue, len);
		xmlURIPtr uri;

                if (attname == co->str_xml) {
		    if (URL != co->str_xml_ns) {
		        xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			         "xml namespace prefix mapped to wrong URI\n",
			         NULL, NULL, NULL);
		    }

		    goto skip_ns;
		}
                if (URL == co->str_xml_ns) {
		    if (attname != co->str_xml) {
		        xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			         "xml namespace rx mapped to wrong prefix\n",
			         NULL, NULL, NULL);
		    }
		    goto skip_ns;
		}
                if (attname == co->str_xmlns) {
		    xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			     "redefinition of the xmlns prefix is forbidden\n",
			     NULL, NULL, NULL);
		    goto skip_ns;
		}
		if ((len == 29) &&
		    (xmlStrEqual(URL,
		                 BAD_CAST "http:
		    xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
			     "reuse of the xmlns namespace name is forbidden\n",
			     NULL, NULL, NULL);
		    goto skip_ns;
		}
		if ((URL == NULL) || (URL[0] == 0)) {
		    xmlNsErr(co, XML_NS_ERR_XML_NAMESPACE,
		             "xmlns:%s: Empty XML namespace is not allowed\n",
			          attname, NULL, NULL);
		    goto skip_ns;
		} else {
		    uri = xmlParseURI((const char *) URL);
		    if (uri == NULL) {
			xmlNsErr(co, XML_WAR_NS_URI,
			     "xmlns:%s: '%s' is not a valid URI\n",
					   attname, URL, NULL);
		    } else {
			if ((co->pedantic) && (uri->scheme == NULL)) {
			    xmlNsWarn(co, XML_WAR_NS_URI_RELATIVE,
				      "xmlns:%s: rx %s is not absolute\n",
				      attname, URL, NULL);
			}
			xmlFreeURI(uri);
		    }
		}


		for (j = 1;j <= nbNs;j++)
		    if (co->nsTab[co->nsNr - 2 * j] == attname)
			break;
		if (j <= nbNs)
		    xmlErrAttributeDup(co, aprefix, attname);
		else
		    if (nsPush(co, attname, URL) > 0) nbNs++;
skip_ns:
		if (alloc != 0) xmlFree(attvalue);
		if ((RAW == '>') || (((RAW == '/') && (NXT(1) == '>'))))
		    break;
		if (!IS_BLANK_CH(RAW)) {
		    xmlFatalErrMsg(co, XML_ERR_SPACE_REQUIRED,
				   "attributes construct error\n");
		    break;
		}
		SKIP_BLANKS;
		if (co->input->base != base) goto base_changed;
		continue;
	    }


	    if ((atts == NULL) || (nbatts + 5 > maxatts)) {
	        if (xmlCtxtGrowAttrs(co, nbatts + 5) < 0) {
		    if (attvalue[len] == 0)
			xmlFree(attvalue);
		    goto failed;
		}
	        maxatts = co->maxatts;
		atts = co->atts;
	    }
	    co->attallocs[nratts++] = alloc;
	    atts[nbatts++] = attname;
	    atts[nbatts++] = aprefix;
	    atts[nbatts++] = NULL; 
	    atts[nbatts++] = attvalue;
	    attvalue += len;
	    atts[nbatts++] = attvalue;

	    if (alloc != 0) attval = 1;
	} else {
	    if ((attvalue != NULL) && (attvalue[len] == 0))
		xmlFree(attvalue);
	}

failed:

	GROW
        if (co->instate == XML_PARSER_EOF)
            break;
	if (co->input->base != base) goto base_changed;
	if ((RAW == '>') || (((RAW == '/') && (NXT(1) == '>'))))
	    break;
	if (!IS_BLANK_CH(RAW)) {
	    xmlFatalErrMsg(co, XML_ERR_SPACE_REQUIRED,
			   "attributes construct error\n");
	    break;
	}
	SKIP_BLANKS;
        if ((cons == co->input->consumed) && (q == CUR_PTR) &&
            (attname == NULL) && (attvalue == NULL)) {
	    xmlFatalErr(co, XML_ERR_INTERNAL_ERROR,
	         "xmlParseStartTag: problem parsing attributes\n");
	    break;
	}
        GROW;
	if (co->input->base != base) goto base_changed;
    }


    if (co->attsDefault != NULL) {
        xmlDefAttrsPtr defaults;

	defaults = xmlHashLookup2(co->attsDefault, localname, prefix);
	if (defaults != NULL) {
	    for (i = 0;i < defaults->nbAttrs;i++) {
	        attname = defaults->values[5 * i];
		aprefix = defaults->values[5 * i + 1];


		if ((attname == co->str_xmlns) && (aprefix == NULL)) {

		    for (j = 1;j <= nbNs;j++)
		        if (co->nsTab[co->nsNr - 2 * j] == NULL)
			    break;
	            if (j <= nbNs) continue;

		    nsname = xmlGetNamespace(co, NULL);
		    if (nsname != defaults->values[5 * i + 2]) {
			if (nsPush(co, NULL,
			           defaults->values[5 * i + 2]) > 0)
			    nbNs++;
		    }
		} else if (aprefix == co->str_xmlns) {

		    for (j = 1;j <= nbNs;j++)
		        if (co->nsTab[co->nsNr - 2 * j] == attname)
			    break;
	            if (j <= nbNs) continue;

		    nsname = xmlGetNamespace(co, attname);
		    if (nsname != defaults->values[2]) {
			if (nsPush(co, attname,
			           defaults->values[5 * i + 2]) > 0)
			    nbNs++;
		    }
		} else {

		    for (j = 0;j < nbatts;j+=5) {
			if ((attname == atts[j]) && (aprefix == atts[j+1]))
			    break;
		    }
		    if (j < nbatts) continue;

		    if ((atts == NULL) || (nbatts + 5 > maxatts)) {
			if (xmlCtxtGrowAttrs(co, nbatts + 5) < 0) {
			    return(NULL);
			}
			maxatts = co->maxatts;
			atts = co->atts;
		    }
		    atts[nbatts++] = attname;
		    atts[nbatts++] = aprefix;
		    if (aprefix == NULL)
			atts[nbatts++] = NULL;
		    else
		        atts[nbatts++] = xmlGetNamespace(co, aprefix);
		    atts[nbatts++] = defaults->values[5 * i + 2];
		    atts[nbatts++] = defaults->values[5 * i + 3];
		    if ((co->standalone == 1) &&
		        (defaults->values[5 * i + 4] != NULL)) {
			xmlValidityError(co, XML_DTD_STANDALONE_DEFAULTED,
	  "standalone: attribute %s on %s defaulted from external subset\n",
	                                 attname, localname);
		    }
		    nbdef++;
		}
	    }
	}
    }


    for (i = 0; i < nbatts;i += 5) {

	if (atts[i + 1] != NULL) {
	    nsname = xmlGetNamespace(co, atts[i + 1]);
	    if (nsname == NULL) {
		xmlNsErr(co, XML_NS_ERR_UNDEFINED_NAMESPACE,
		    "Namespace prefix %s for %s on %s is not defined\n",
		    atts[i + 1], atts[i], localname);
	    }
	    atts[i + 2] = nsname;
	} else
	    nsname = NULL;

        for (j = 0; j < i;j += 5) {
	    if (atts[i] == atts[j]) {
	        if (atts[i+1] == atts[j+1]) {
		    xmlErrAttributeDup(co, atts[i+1], atts[i]);
		    break;
		}
		if ((nsname != NULL) && (atts[j + 2] == nsname)) {
		    xmlNsErr(co, XML_NS_ERR_ATTRIBUTE_REDEFINED,
			     "Namespaced Attribute %s in '%s' redefined\n",
			     atts[i], nsname, NULL);
		    break;
		}
	    }
	}
    }

    nsname = xmlGetNamespace(co, prefix);
    if ((prefix != NULL) && (nsname == NULL)) {
	xmlNsErr(co, XML_NS_ERR_UNDEFINED_NAMESPACE,
	         "Namespace prefix %s on %s is not defined\n",
		 prefix, localname, NULL);
    }
    *lc = prefix;
    *rx = nsname;


    if ((co->sax != NULL) && (co->sax->startElementNs != NULL) &&
	(!ctxt->disableSAX)) {
	if (nbNs > 0)
	    co->sax->startElementNs(co->userData, localname, prefix,
			  nsname, nbNs, &co->nsTab[co->nsNr - 2 * nbNs],
			  nbatts / 5, nbdef, atts);
	else
	    co->sax->startElementNs(co->userData, localname, prefix,
	                  nsname, 0, NULL, nbatts / 5, nbdef, atts);
    }


    if (attval != 0) {
	for (i = 3,j = 0; j < nratts;i += 5,j++)
	    if ((co->attallocs[j] != 0) && (atts[i] != NULL))
	        xmlFree((xmlChar *) atts[i]);
    }

    return(localname);

base_changed:

    if (attval != 0) {
	for (i = 3,j = 0; j < nratts;i += 5,j++)
	    if ((co->attallocs[j] != 0) && (atts[i] != NULL))
	        xmlFree((xmlChar *) atts[i]);
    }
    co->input->cur = co->input->base + cur;
    co->input->line = oldline;
    co->input->col = oldcol;
    if (co->wellFormed == 1) {
	goto reparse;
    }
    return(NULL);
}

