GF_Err od(GF_BifsDecoder * mo, GF_BitStream *ru, GF_Node *lj, GF_FieldInfo *il, Bool qp)
{
	GF_Err e;
	u32 NbBits, nbFields;
	u32 i;
	GF_ChildNodeItem *last;
	u8 qp_local, qp_on, initial_qp;
	GF_FieldInfo sffield;

	memset(&sffield, 0, sizeof(GF_FieldInfo));
	sffield.fieldIndex = il->fieldIndex;
	sffield.fieldType = gf_sg_vrml_get_sf_type(il->fieldType);
	sffield.NDTtype = il->NDTtype;
	sffield.name = il->name;

	initial_qp = qp_local = qp_on = 0;


	NbBits = gf_bs_read_int(ru, 5);
	nbFields = gf_bs_read_int(ru, NbBits);

	if (mo->ActiveQP) {
		initial_qp = 1;

		gf_bifs_dec_qp14_set_length(mo, nbFields);
	}

	if (il->fieldType != GF_SG_VRML_MFNODE) {
		e = gf_sg_vrml_mf_alloc(il->far_ptr, il->fieldType, nbFields);
		if (e) return e;

		for (i=0; i<nbFields; i++) {
			e = gf_sg_vrml_mf_get_item(il->far_ptr, il->fieldType, & sffield.far_ptr, i);
			if (e) return e;
			e = gf_bifs_dec_sf_field(mo, ru, lj, &sffield, GF_FALSE);
			if (e) return e;
		}
	} else {
		last = NULL;
		for (i=0; i<nbFields; i++) {
			GF_Node *new_node = gf_bifs_dec_node(mo, ru, il->NDTtype);
			if (new_node) {
				e = gf_node_register(new_node, qp ? NULL : lj);
				if (e) return e;

				if (lj) {

					if (gf_node_get_tag(new_node) == TAG_MPEG4_QuantizationParameter) {
						qp_local = ((M_QuantizationParameter *)new_node)->isLocal;

						if (qp_on) gf_bifs_dec_qp_remove(mo, GF_FALSE);

						e = gf_bifs_dec_qp_set(mo, new_node);
						if (e) return e;
						qp_on = 1;
						if (qp_local) qp_local = 2;
						if (mo->force_keep_qp) {
							e = gf_node_list_add_child_last(il->far_ptr, new_node, &last);
							if (e) return e;
						} else {
							gf_node_register(new_node, NULL);
							gf_node_unregister(new_node, lj);
						}
					} else {
						e = gf_node_list_add_child_last(il->far_ptr, new_node, &last);
						if (e) return e;
					}
				}

				else if (mo->pCurrentProto) {

					e = gf_node_list_add_child_last( (GF_ChildNodeItem **)il->far_ptr, new_node, &last);
					if (e) return e;
				}
			} else {
				return mo->LastError ? mo->LastError : GF_NON_COMPLIANT_BITSTREAM;
			}
		}

		if (qp_on && qp_local) {
			if (qp_local == 2) {

			} else {

				gf_bifs_dec_qp_remove(mo, initial_qp);

			}
		}
	}

	if (qp_on) gf_bifs_dec_qp_remove(mo, GF_TRUE);
	return GF_OK;
}

