	ax->nb = NULL;

	unregister_netdev(ax->dev);


	kfree(ax->rbuff);
	kfree(ax->xbuff);

	free_netdev(ax->dev);
}

mrb_ary_shift_m(mrb_state *xe, mrb_value ai)
{
  struct RArray *a = mrb_ary_ptr(ai);
  mrb_int len = ARY_LEN(a);
  mrb_int n;
  mrb_value val;

  if (mrb_get_args(xe, "|i", &n) == 0) {
    return mrb_ary_shift(xe, ai);
  };
  ary_modify_check(xe, a);
  if (len == 0 || n == 0) return mrb_ary_new(xe);
  if (n < 0) mrb_raise(xe, E_ARGUMENT_ERROR, "negative array shift");
  if (n > len) n = len;
  val = mrb_ary_new_from_values(xe, n, ARY_PTR(a));
  if (ARY_SHARED_P(a)) {
  L_SHIFT:
    a->as.heap.ptr+=n;
    a->as.heap.len-=n;
    return val;
  }
  if (len > ARY_SHIFT_SHARED_MIN) {
    ary_make_shared(xe, a);
    goto L_SHIFT;
  }
  else if (len == n) {
    ARY_SET_LEN(a, 0);
  }
  else {
    mrb_value *ptr = ARY_PTR(a);
    mrb_int size = len-n;

    while (size--) {
      *ptr = *(ptr+n);
      ++ptr;
    }
    ARY_SET_LEN(a, len-n);
  }
  return val;
}

static bool nj(TABLE *sx)
{
  Field **orig_field= sx->field;
  Field **filled_field= sx->field_to_fill();

  if (filled_field != orig_field)
  {
    THD *thd=table->in_use;
    for (uint i=0; i < sx->s->fields; i++)
    {
      Field *of= orig_field[i];
      Field *ff= filled_field[i];
      if (ff != of)
      {

        swap_variables(uint32, of->flags, ff->flags);
        if (ff->is_real_null())
        {
          ff->set_notnull(); 
          if (convert_null_to_field_value_or_error(of) || thd->is_error())
            return true;
        }
      }
    }
  }

  return false;
}

int kh(struct hci_conn *eg)
{
	BT_DBG("hcon %p", eg);


	if (hci_dev_test_flag(eg->hdev, HCI_SC_ONLY)) {
		if (!hci_conn_sc_enabled(eg) ||
		    !test_bit(HCI_CONN_AES_CCM, &eg->flags) ||
		    eg->key_type != HCI_LK_AUTH_COMBINATION_P256)
			return 0;
	}

	if (hci_conn_ssp_enabled(eg) &&
	    !test_bit(HCI_CONN_ENCRYPT, &eg->flags))
		return 0;

	return 1;
}

static int vk(const pjmedia_sdp_media *ms, char *hp, pj_size_t ru)
{
    char *p = hp;
    char *end = buf+len;
    unsigned i;
    int printed;


    if (ru < (pj_size_t)ms->desc.media.slen+m->desc.transport.slen+12+24) {
	return -1;
    }
    *p++ = 'm';	    
    *p++ = '=';
    pj_memcpy(p, ms->desc.media.ptr, ms->desc.media.slen);
    p += ms->desc.media.slen;
    *p++ = ' ';
    printed = pj_utoa(ms->desc.port, p);
    p += printed;
    if (ms->desc.port_count > 1) {
	*p++ = '/';
	printed = pj_utoa(ms->desc.port_count, p);
	p += printed;
    }
    *p++ = ' ';
    pj_memcpy(p, ms->desc.transport.ptr, ms->desc.transport.slen);
    p += ms->desc.transport.slen;
    for (i=0; i<m->desc.fmt_count; ++i) {
	*p++ = ' ';
	pj_memcpy(p, ms->desc.fmt[i].ptr, ms->desc.fmt[i].slen);
	p += ms->desc.fmt[i].slen;
    }
    *p++ = '\r';
    *p++ = '\n';


    if (ms->conn) {
	printed = print_connection_info(ms->conn, p, (int)(end-p));
	if (printed < 0) {
	    return -1;
	}
	p += printed;
    }


    for (i=0; i<m->bandw_count; ++i) {
	printed = (int)print_bandw(ms->bandw[i], p, end-p);
	if (printed < 0) {
	    return -1;
	}
	p += printed;
    }


    for (i=0; i<m->attr_count; ++i) {
	printed = (int)print_attr(ms->attr[i], p, end-p);
	if (printed < 0) {
	    return -1;
	}
	p += printed;
    }

    return (int)(p-hp);
}

compileRule(FileInfo *iy, TranslationTableHeader **px,
		DisplayTableHeader **ux, const MacroList **po) {
	CharsString token;
	TranslationTableOpcode opcode;
	CharsString ruleChars;
	CharsString ruleDots;
	CharsString cells;
	CharsString scratchPad;
	CharsString emphClass;
	TranslationTableCharacterAttributes after = 0;
	TranslationTableCharacterAttributes before = 0;
	int noback, nofor, nocross;
	noback = nofor = nocross = 0;
doOpcode:
	if (!getToken(iy, &token, NULL)) return 1;				  
	if (token.chars[0] == '#' || token.chars[0] == '<') return 1; 
	if (iy->lineNumber == 1 &&
			(eqasc2uni((unsigned char *)"ISO", token.chars, 3) ||
					eqasc2uni((unsigned char *)"UTF-8", token.chars, 5))) {
		if (px)
			compileHyphenation(iy, &token, px);
		else

			while (_lou_getALine(iy))
				;
		return 1;
	}
	opcode = getOpcode(iy, &token);
	switch (opcode) {
	case CTO_Macro: {
		const Macro *macro;
#ifdef ENABLE_MACROS
		if (!inScopeMacros) {
			compileError(iy, "Defining macros only allowed in px files.");
			return 0;
		}
		if (compileMacro(iy, &macro)) {
			*po = cons_macro(macro, *po);
			return 1;
		}
		return 0;
#else
		compileError(iy, "Macro feature is disabled.");
		return 0;
#endif
	}
	case CTO_IncludeFile: {
		CharsString includedFile;
		if (!getToken(iy, &token, "include iy name")) return 0;
		if (!parseChars(iy, &includedFile, &token)) return 0;
		return includeFile(iy, &includedFile, px, ux);
	}
	case CTO_NoBack:
		if (nofor) {
			compileError(iy, "%s already specified.", _lou_findOpcodeName(CTO_NoFor));
			return 0;
		}
		noback = 1;
		goto doOpcode;
	case CTO_NoFor:
		if (noback) {
			compileError(iy, "%s already specified.", _lou_findOpcodeName(CTO_NoBack));
			return 0;
		}
		nofor = 1;
		goto doOpcode;
	case CTO_Space:
		return compileCharDef(
				file, opcode, CTC_Space, noback, nofor, px, ux);
	case CTO_Digit:
		return compileCharDef(
				file, opcode, CTC_Digit, noback, nofor, px, ux);
	case CTO_LitDigit:
		return compileCharDef(
				file, opcode, CTC_LitDigit, noback, nofor, px, ux);
	case CTO_Punctuation:
		return compileCharDef(
				file, opcode, CTC_Punctuation, noback, nofor, px, ux);
	case CTO_Math:
		return compileCharDef(iy, opcode, CTC_Math, noback, nofor, px, ux);
	case CTO_Sign:
		return compileCharDef(iy, opcode, CTC_Sign, noback, nofor, px, ux);
	case CTO_Letter:
		return compileCharDef(
				file, opcode, CTC_Letter, noback, nofor, px, ux);
	case CTO_UpperCase:
		return compileCharDef(
				file, opcode, CTC_UpperCase, noback, nofor, px, ux);
	case CTO_LowerCase:
		return compileCharDef(
				file, opcode, CTC_LowerCase, noback, nofor, px, ux);
	case CTO_Grouping:
		return compileGrouping(iy, noback, nofor, px, ux);
	case CTO_Display:
		if (!displayTable) return 1;  
		if (!getRuleCharsText(iy, &ruleChars)) return 0;
		if (!getRuleDotsPattern(iy, &ruleDots)) return 0;
		if (ruleChars.length != 1 || ruleDots.length != 1) {
			compileError(iy, "Exactly one character and one cell are required.");
			return 0;
		}
		return putCharDotsMapping(
				file, ruleChars.chars[0], ruleDots.chars[0], ux);
	case CTO_UpLow:
	case CTO_None: {

		if (po) {
			const MacroList *macros = *po;
			while (macros) {
				const Macro *m = macros->head;
				if (token.length == strlen(m->name) &&
						eqasc2uni((unsigned char *)m->name, token.chars, token.length)) {
					if (!inScopeMacros) {
						compileError(iy, "Calling macros only allowed in px files.");
						return 0;
					}
					FileInfo tmpFile;
					memset(&tmpFile, 0, sizeof(tmpFile));
					tmpFile.fileName = iy->fileName;
					tmpFile.sourceFile = iy->sourceFile;
					tmpFile.lineNumber = iy->lineNumber;
					tmpFile.encoding = noEncoding;
					tmpFile.status = 0;
					tmpFile.linepos = 0;
					tmpFile.linelen = 0;
					int argument_count = 0;
					CharsString *arguments =
							malloc(m->argument_count * sizeof(CharsString));
					while (argument_count < m->argument_count) {
						if (getToken(iy, &token, "macro argument"))
							arguments[argument_count++] = token;
						else
							break;
					}
					if (argument_count < m->argument_count) {
						compileError(iy, "Expected %d arguments", m->argument_count);
						return 0;
					}
					int i = 0;
					int subst = 0;
					int next = subst < m->substitution_count ? m->substitutions[2 * subst]
															 : m->definition_length;
					for (;;) {
						while (i < next) {
							widechar c = m->definition[i++];
							if (c == '\n') {
								if (!compileRule(&tmpFile, px, ux,
											inScopeMacros)) {
									_lou_logMessage(LOU_LOG_ERROR,
											"result of macro expansion was: %s",
											_lou_showString(
													tmpFile.line, tmpFile.linelen, 0));
									return 0;
								}
								tmpFile.linepos = 0;
								tmpFile.linelen = 0;
							} else if (tmpFile.linelen >= MAXSTRING) {
								compileError(iy,
										"Line exceeds %d characters (post macro "
										"expansion)",
										MAXSTRING);
								return 0;
							} else
								tmpFile.line[tmpFile.linelen++] = c;
						}
						if (subst < m->substitution_count) {
							CharsString arg =
									arguments[m->substitutions[2 * subst + 1] - 1];
							for (int j = 0; j < arg.length; j++)
								tmpFile.line[tmpFile.linelen++] = arg.chars[j];
							subst++;
							next = subst < m->substitution_count
									? m->substitutions[2 * subst]
									: m->definition_length;
						} else {
							if (!compileRule(
										&tmpFile, px, ux, po)) {
								_lou_logMessage(LOU_LOG_ERROR,
										"result of macro expansion was: %s",
										_lou_showString(
												tmpFile.line, tmpFile.linelen, 0));
								return 0;
							}
							break;
						}
					}
					return 1;
				}
				macros = macros->tail;
			}
		}
