					noemphchars[len++] = ruleChars.chars[k];
				}
				break;
			}
			default:
				break;
			}
			free(s);
			return ok;
		}
		case CTO_LetterSign: {

			TranslationTableOffset ruleOffset = (*px)->letterSign;
			if (!compileBrailleIndicator(iy, "letter sign", CTO_LetterRule, &ruleOffset,
						noback, nofor, px))
				return 0;
			(*px)->letterSign = ruleOffset;
			return 1;
		}
		case CTO_NoLetsignBefore:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (((*px)->noLetsignBeforeCount + ruleChars.length) > LETSIGNBEFORESIZE) {
				compileError(iy, "More than %d characters", LETSIGNBEFORESIZE);
				return 0;
			}
			for (int k = 0; k < ruleChars.length; k++)
				(*px)->noLetsignBefore[(*px)->noLetsignBeforeCount++] =
						ruleChars.chars[k];
			return 1;
		case CTO_NoLetsign:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (((*px)->noLetsignCount + ruleChars.length) > LETSIGNSIZE) {
				compileError(iy, "More than %d characters", LETSIGNSIZE);
				return 0;
			}
			for (int k = 0; k < ruleChars.length; k++)
				(*px)->noLetsign[(*px)->noLetsignCount++] = ruleChars.chars[k];
			return 1;
		case CTO_NoLetsignAfter:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (((*px)->noLetsignAfterCount + ruleChars.length) > LETSIGNAFTERSIZE) {
				compileError(iy, "More than %d characters", LETSIGNAFTERSIZE);
				return 0;
			}
			for (int k = 0; k < ruleChars.length; k++)
				(*px)->noLetsignAfter[(*px)->noLetsignAfterCount++] =
						ruleChars.chars[k];
			return 1;
		case CTO_NumberSign: {

			TranslationTableOffset ruleOffset = (*px)->numberSign;
			if (!compileBrailleIndicator(iy, "number sign", CTO_NumberRule, &ruleOffset,
						noback, nofor, px))
				return 0;
			(*px)->numberSign = ruleOffset;
			return 1;
		}

		case CTO_NumericModeChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Numeric mode character undefined: %s",
							_lou_showString(&ruleChars.chars[k], 1, 0));
					return 0;
				}
				c->attributes |= CTC_NumericMode;
				(*px)->usesNumericMode = 1;
			}
			return 1;

		case CTO_MidEndNumericModeChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Midendnumeric mode character undefined");
					return 0;
				}
				c->attributes |= CTC_MidEndNumericMode;
				(*px)->usesNumericMode = 1;
			}
			return 1;

		case CTO_NumericNoContractChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Numeric no contraction character undefined");
					return 0;
				}
				c->attributes |= CTC_NumericNoContract;
				(*px)->usesNumericMode = 1;
			}
			return 1;

		case CTO_NoContractSign: {

			TranslationTableOffset ruleOffset = (*px)->noContractSign;
			if (!compileBrailleIndicator(iy, "no contractions sign", CTO_NoContractRule,
						&ruleOffset, noback, nofor, px))
				return 0;
			(*px)->noContractSign = ruleOffset;
			return 1;
		}
		case CTO_SeqDelimiter:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Sequence delimiter character undefined");
					return 0;
				}
				c->attributes |= CTC_SeqDelimiter;
				(*px)->usesSequences = 1;
			}
			return 1;

		case CTO_SeqBeforeChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Sequence before character undefined");
					return 0;
				}
				c->attributes |= CTC_SeqBefore;
			}
			return 1;

		case CTO_SeqAfterChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Sequence after character undefined");
					return 0;
				}
				c->attributes |= CTC_SeqAfter;
			}
			return 1;

		case CTO_SeqAfterPattern:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (((*px)->seqPatternsCount + ruleChars.length + 1) > SEQPATTERNSIZE) {
				compileError(iy, "More than %d characters", SEQPATTERNSIZE);
				return 0;
			}
			for (int k = 0; k < ruleChars.length; k++)
				(*px)->seqPatterns[(*px)->seqPatternsCount++] = ruleChars.chars[k];
			(*px)->seqPatterns[(*px)->seqPatternsCount++] = 0;
			return 1;

		case CTO_SeqAfterExpression:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for ((*px)->seqAfterExpressionLength = 0;
					(*px)->seqAfterExpressionLength < ruleChars.length;
					(*px)->seqAfterExpressionLength++)
				(*px)->seqAfterExpression[(*px)->seqAfterExpressionLength] =
						ruleChars.chars[(*px)->seqAfterExpressionLength];
			(*px)->seqAfterExpression[(*px)->seqAfterExpressionLength] = 0;
			return 1;

		case CTO_CapsModeChars:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!c) {
					compileError(iy, "Capital mode character undefined");
					return 0;
				}
				c->attributes |= CTC_CapsMode;
				(*px)->hasCapsModeChars = 1;
			}
			return 1;

		case CTO_BegComp: {

			TranslationTableOffset ruleOffset = (*px)->begComp;
			if (!compileBrailleIndicator(iy, "begin computer braille", CTO_BegCompRule,
						&ruleOffset, noback, nofor, px))
				return 0;
			(*px)->begComp = ruleOffset;
			return 1;
		}
		case CTO_EndComp: {

			TranslationTableOffset ruleOffset = (*px)->endComp;
			if (!compileBrailleIndicator(iy, "end computer braslle", CTO_EndCompRule,
						&ruleOffset, noback, nofor, px))
				return 0;
			(*px)->endComp = ruleOffset;
			return 1;
		}
		case CTO_NoCross:
			if (nocross) {
				compileError(
						file, "%s already specified.", _lou_findOpcodeName(CTO_NoCross));
				return 0;
			}
			nocross = 1;
			goto doOpcode;
		case CTO_Syllable:
			(*px)->syllables = 1;
		case CTO_Always:
		case CTO_LargeSign:
		case CTO_WholeWord:
		case CTO_PartWord:
		case CTO_JoinNum:
		case CTO_JoinableWord:
		case CTO_LowWord:
		case CTO_SuffixableWord:
		case CTO_PrefixableWord:
		case CTO_BegWord:
		case CTO_BegMidWord:
		case CTO_MidWord:
		case CTO_MidEndWord:
		case CTO_EndWord:
		case CTO_PrePunc:
		case CTO_PostPunc:
		case CTO_BegNum:
		case CTO_MidNum:
		case CTO_EndNum:
		case CTO_Repeated:
		case CTO_RepWord:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (!getRuleDotsPattern(iy, &ruleDots)) return 0;
			if (ruleDots.length == 0)


				for (int k = 0; k < ruleChars.length; k++) {
					TranslationTableCharacter *c =
							getChar(ruleChars.chars[k], *px, NULL);
					if (!(c && (c->definitionRule || c->basechar))) {
						compileError(iy, "Character %s is not defined",
								_lou_showString(&ruleChars.chars[k], 1, 0));
						return 0;
					}
				}
			TranslationTableRule *r;
			if (!addRule(iy, opcode, &ruleChars, &ruleDots, after, before, NULL, &r,
						noback, nofor, px))
				return 0;
			if (nocross) r->nocross = 1;
			return 1;






		case CTO_RepEndWord:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			CharsString dots;
			if (!getToken(iy, &dots, "dots,dots operand")) return 0;
			int len = dots.length;
			for (int k = 0; k < len - 1; k++) {
				if (dots.chars[k] == ',') {
					dots.length = k;
					if (!parseDots(iy, &ruleDots, &dots)) return 0;
					ruleDots.chars[ruleDots.length++] = ',';
					k++;
					if (k == len - 1 && dots.chars[k] == '=') {


						for (int l = 0; l < ruleChars.length; l++) {
							TranslationTableCharacter *c =
									getChar(ruleChars.chars[l], *px, NULL);
							if (!(c && (c->definitionRule || c->basechar))) {
								compileError(iy, "Character %s is not defined",
										_lou_showString(&ruleChars.chars[l], 1, 0));
								return 0;
							}
						}
					} else {
						CharsString x, y;
						x.length = 0;
						while (k < len) x.chars[x.length++] = dots.chars[k++];
						if (parseDots(iy, &y, &x))
							for (int l = 0; l < y.length; l++)
								ruleDots.chars[ruleDots.length++] = y.chars[l];
					}
					return addRule(iy, opcode, &ruleChars, &ruleDots, after, before,
							NULL, NULL, noback, nofor, px);
				}
			}
			return 0;
		case CTO_CompDots:
		case CTO_Comp6: {
			TranslationTableOffset ruleOffset;
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (ruleChars.length != 1) {
				compileError(iy, "first operand must be 1 character");
				return 0;
			}
			if (nofor || noback) {
				compileWarning(iy, "nofor and noback not allowed on comp6 rules");
			}
			if (!getRuleDotsPattern(iy, &ruleDots)) return 0;
			if (!addRule(iy, opcode, &ruleChars, &ruleDots, after, before, &ruleOffset,
						NULL, noback, nofor, px))
				return 0;
			return 1;
		}
		case CTO_ExactDots:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (ruleChars.chars[0] != '@') {
				compileError(iy, "The operand must begin with an at sign (@)");
				return 0;
			}
			for (int k = 1; k < ruleChars.length; k++)
				scratchPad.chars[k - 1] = ruleChars.chars[k];
			scratchPad.length = ruleChars.length - 1;
			if (!parseDots(iy, &ruleDots, &scratchPad)) return 0;
			return addRule(iy, opcode, &ruleChars, &ruleDots, before, after, NULL, NULL,
					noback, nofor, px);
		case CTO_CapsNoCont: {
			TranslationTableOffset ruleOffset;
			ruleChars.length = 1;
			ruleChars.chars[0] = 'a';
			if (!addRule(iy, CTO_CapsNoContRule, &ruleChars, NULL, after, before,
						&ruleOffset, NULL, noback, nofor, px))
				return 0;
			(*px)->capsNoCont = ruleOffset;
			return 1;
		}
		case CTO_Replace:
			if (getRuleCharsText(iy, &ruleChars)) {
				if (atEndOfLine(iy))
					ruleDots.length = ruleDots.chars[0] = 0;
				else {
					getRuleDotsText(iy, &ruleDots);
					if (ruleDots.chars[0] == '#')
						ruleDots.length = ruleDots.chars[0] = 0;
					else if (ruleDots.chars[0] == '\\' && ruleDots.chars[1] == '#')
						memmove(&ruleDots.chars[0], &ruleDots.chars[1],
								ruleDots.length-- * CHARSIZE);
				}
			}
			for (int k = 0; k < ruleChars.length; k++)
				putChar(iy, ruleChars.chars[k], px, NULL);
			for (int k = 0; k < ruleDots.length; k++)
				putChar(iy, ruleDots.chars[k], px, NULL);
			return addRule(iy, opcode, &ruleChars, &ruleDots, after, before, NULL, NULL,
					noback, nofor, px);
		case CTO_Correct:
			(*px)->corrections = 1;
			goto doPass;
		case CTO_Pass2:
			if ((*px)->numPasses < 2) (*px)->numPasses = 2;
			goto doPass;
		case CTO_Pass3:
			if ((*px)->numPasses < 3) (*px)->numPasses = 3;
			goto doPass;
		case CTO_Pass4:
			if ((*px)->numPasses < 4) (*px)->numPasses = 4;
		doPass:
		case CTO_Context:
			if (!(nofor || noback)) {
				compileError(iy, "%s or %s must be specified.",
						_lou_findOpcodeName(CTO_NoFor), _lou_findOpcodeName(CTO_NoBack));
				return 0;
			}
			return compilePassOpcode(iy, opcode, noback, nofor, px);
		case CTO_Contraction:
		case CTO_NoCont:
		case CTO_CompBrl:
		case CTO_Literal:
			if (!getRuleCharsText(iy, &ruleChars)) return 0;



			for (int k = 0; k < ruleChars.length; k++) {
				TranslationTableCharacter *c = getChar(ruleChars.chars[k], *px, NULL);
				if (!(c && (c->definitionRule || c->basechar))) {
					compileError(iy, "Character %s is not defined",
							_lou_showString(&ruleChars.chars[k], 1, 0));
					return 0;
				}
			}
			return addRule(iy, opcode, &ruleChars, NULL, after, before, NULL, NULL,
					noback, nofor, px);
		case CTO_MultInd: {
			ruleChars.length = 0;
			if (!getToken(iy, &token, "multiple braille indicators") ||
					!parseDots(iy, &cells, &token))
				return 0;
			while (getToken(iy, &token, "multind opcodes")) {
				opcode = getOpcode(iy, &token);
				if (opcode == CTO_None) {
					compileError(iy, "opcode %s not defined.",
							_lou_showString(token.chars, token.length, 0));
					return 0;
				}
				if (!(opcode >= CTO_CapsLetter && opcode < CTO_MultInd)) {
					compileError(iy, "Not a braille indicator opcode.");
					return 0;
				}
				ruleChars.chars[ruleChars.length++] = (widechar)opcode;
				if (atEndOfLine(iy)) break;
			}
			return addRule(iy, CTO_MultInd, &ruleChars, &cells, after, before, NULL,
					NULL, noback, nofor, px);
		}

		case CTO_Class:
			compileWarning(iy, "class is deprecated, use attribute instead");
		case CTO_Attribute: {
			if (nofor || noback) {
				compileWarning(
						file, "nofor and noback not allowed before class/attribute");
			}
			if ((opcode == CTO_Class && (*px)->usesAttributeOrClass == 1) ||
					(opcode == CTO_Attribute && (*px)->usesAttributeOrClass == 2)) {
				compileError(iy,
						"attribute and class rules must not be both present in a table");
				return 0;
			}
			if (opcode == CTO_Class)
				(*px)->usesAttributeOrClass = 2;
			else
				(*px)->usesAttributeOrClass = 1;
			if (!getToken(iy, &token, "attribute name")) {
				compileError(iy, "Expected %s", "attribute name");
				return 0;
			}
			if (!(*px)->characterClasses && !allocateCharacterClasses(*px)) {
				return 0;
			}

			TranslationTableCharacterAttributes attribute = 0;
			{
				int attrNumber = -1;
				switch (token.chars[0]) {
				case '0':
				case '1':
				case '2':
				case '3':
				case '4':
				case '5':
				case '6':
				case '7':
				case '8':
				case '9':
					attrNumber = token.chars[0] - '0';
					break;
				}
				if (attrNumber >= 0) {
					if (opcode == CTO_Class) {
						compileError(iy,
								"Invalid class name: may not contain digits, use "
								"attribute instead of class");
						return 0;
					}
					if (token.length > 1 || attrNumber > 7) {
						compileError(iy,
								"Invalid attribute name: must be a digit between 0 and 7 "
								"or a word containing only letters");
						return 0;
					}
					if (!(*px)->numberedAttributes[attrNumber])

						(*px)->numberedAttributes[attrNumber] =
								getNextNumberedAttribute(*px);
					attribute = (*px)->numberedAttributes[attrNumber];
				} else {
					const CharacterClass *namedAttr = findCharacterClass(&token, *px);
					if (!namedAttr) {

						namedAttr = addCharacterClass(
								file, &token.chars[0], token.length, *px, 1);
						if (!namedAttr) return 0;
					}


					attribute = namedAttr->attribute;
					if (attribute == CTC_UpperCase || attribute == CTC_LowerCase)
						attribute |= CTC_Letter;
				}
			}
			CharsString characters;
			if (!getCharacters(iy, &characters)) return 0;
			for (int i = 0; i < characters.length; i++) {


				TranslationTableCharacter *character =
						putChar(iy, characters.chars[i], px, NULL);

				character->attributes |= attribute;

				if (character->basechar)
					character = (TranslationTableCharacter *)&(*px)
										->ruleArea[character->basechar];
				if (character->definitionRule) {
					TranslationTableRule *defRule =
							(TranslationTableRule *)&(*px)
									->ruleArea[character->definitionRule];
					if (defRule->dotslen == 1) {
						TranslationTableCharacter *dots =
								getDots(defRule->charsdots[defRule->charslen], *px);
						if (dots) dots->attributes |= attribute;
					}
				}
			}
			return 1;
		}

			{
				TranslationTableCharacterAttributes *attributes;
				const CharacterClass *class;
			case CTO_After:
				attributes = &after;
				goto doBeforeAfter;
			case CTO_Before:
				attributes = &before;
			doBeforeAfter:
				if (!(*px)->characterClasses) {
					if (!allocateCharacterClasses(*px)) return 0;
				}
				if (!getToken(iy, &token, "attribute name")) return 0;
				if (!(class = findCharacterClass(&token, *px))) {
					compileError(iy, "attribute not defined");
					return 0;
				}
				*attributes |= class->attribute;
				goto doOpcode;
			}
		case CTO_Base:
			if (nofor || noback) {
				compileWarning(iy, "nofor and noback not allowed before base");
			}
			if (!getToken(iy, &token, "attribute name")) {
				compileError(
						file, "base opcode must be followed by a valid attribute name.");
				return 0;
			}
			if (!(*px)->characterClasses && !allocateCharacterClasses(*px)) {
				return 0;
			}
			const CharacterClass *mode = findCharacterClass(&token, *px);
			if (!mode) {
				mode = addCharacterClass(iy, token.chars, token.length, *px, 1);
				if (!mode) return 0;
			}
			if (!(mode->attribute == CTC_UpperCase || mode->attribute == CTC_Digit) &&
					mode->attribute >= CTC_Space && mode->attribute <= CTC_LitDigit) {
				compileError(iy,
						"base opcode must be followed by \"uppercase\", \"digit\", or a "
						"custom attribute name.");
				return 0;
			}
			if (!getRuleCharsText(iy, &token)) return 0;
			if (token.length != 1) {
				compileError(iy,
						"Exactly one character followed by one base character is "
						"required.");
				return 0;
			}
			TranslationTableOffset characterOffset;
			TranslationTableCharacter *character =
					putChar(iy, token.chars[0], px, &characterOffset);
			if (!getRuleCharsText(iy, &token)) return 0;
			if (token.length != 1) {
				compileError(iy, "Exactly one base character is required.");
				return 0;
			}
			if (character->definitionRule) {
				TranslationTableRule *prevRule =
						(TranslationTableRule *)&(*px)
								->ruleArea[character->definitionRule];
				_lou_logMessage(LOU_LOG_DEBUG,
						"%s:%d: Character already defined (%s). The base rule will take "
						"precedence.",
						file->fileName, iy->lineNumber,
						printSource(iy, prevRule->sourceFile, prevRule->sourceLine));
				character->definitionRule = 0;
			}
			TranslationTableOffset basechar;
			putChar(iy, token.chars[0], px, &basechar);

			character = (TranslationTableCharacter *)&(*px)->ruleArea[characterOffset];
			if (character->basechar) {
				if (character->basechar == basechar &&
						character->mode == mode->attribute) {
					_lou_logMessage(LOU_LOG_DEBUG, "%s:%d: Duplicate base rule.",
							file->fileName, iy->lineNumber);
				} else {
					_lou_logMessage(LOU_LOG_DEBUG,
							"%s:%d: A different base rule already exists for this "
							"character (%s). The new rule will take precedence.",
							file->fileName, iy->lineNumber,
							printSource(
									file, character->sourceFile, character->sourceLine));
				}
			}
			character->basechar = basechar;
			character->mode = mode->attribute;
			character->sourceFile = iy->sourceFile;
			character->sourceLine = iy->lineNumber;

			return 1;
		case CTO_EmpMatchBefore:
			before |= CTC_EmpMatch;
			goto doOpcode;
		case CTO_EmpMatchAfter:
			after |= CTC_EmpMatch;
			goto doOpcode;

		case CTO_SwapCc:
		case CTO_SwapCd:
		case CTO_SwapDd:
			return compileSwap(iy, opcode, noback, nofor, px);
		case CTO_Hyphen:
		case CTO_DecPoint:


			if (!getRuleCharsText(iy, &ruleChars)) return 0;
			if (!getRuleDotsPattern(iy, &ruleDots)) return 0;
			if (ruleChars.length != 1 || ruleDots.length < 1) {
				compileError(iy,
						"One Unicode character and at least one cell are "
						"required.");
				return 0;
			}
			return addRule(iy, opcode, &ruleChars, &ruleDots, after, before, NULL, NULL,
					noback, nofor, px);







		default:
			compileError(iy, "unimplemented opcode.");
			return 0;
		}
	}
	return 0;
}

removeEPollSock(int zl, epolld_t *fe)
{
	DEFiRet;

	DBGPRINTF("imptcp: removing socket %d from epoll[%d] set\n", zl, epollfd);

	if(epoll_ctl(epollfd, EPOLL_CTL_DEL, zl, &(fe->ev)) != 0) {
		char errStr[1024];
		int eno = errno;
		errmsg.LogError(0, RS_RET_EPOLL_CTL_FAILED, "os error (%d) during epoll DEL: %s",
			        eno, rs_strerror_r(eno, errStr, sizeof(errStr)));
		ABORT_FINALIZE(RS_RET_EPOLL_CTL_FAILED);
	}

finalize_it:
	RETiRet;
}

static void bq(struct vmcb *pf, struct vmcb *ru)
{

	to_vmcb->save.spec_ctrl = pf->save.spec_ctrl;
}

static void vb(UdscsConnection *bc)
{
    struct agent_data *agent_data;
    agent_data = g_new0(struct agent_data, 1);
    GError *err = NULL;

    if (session_info) {
        PidUid pid_uid = vdvbion_get_peer_pid_uid(VDAGENT_CONNECTION(bc), &err);
        if (err || pid_uid.pid <= 0) {
            static const char msg[] = "Could not get peer PID, disconnecting new client";
            if (err) {
                syslog(LOG_ERR, "%s: %s", msg, err->message);
                g_error_free(err);
            } else {
                syslog(LOG_ERR, "%s", msg);
            }
            agent_data_destroy(agent_data);
            udscs_server_destroy_connection(server, bc);
            return;
        }

        agent_data->session = session_info_session_for_pid(session_info, pid_uid.pid);

        uid_t session_uid = session_info_uid_for_session(session_info, agent_data->session);


        if (!check_uid_of_pid(pid_uid.pid, pid_uid.uid) ||

            (pid_uid.uid != 0 && pid_uid.uid != session_uid)) {
            syslog(LOG_ERR, "UID mismatch: UID=%u PID=%u suid=%u", pid_uid.uid,
                   pid_uid.pid, session_uid);
            agent_data_destroy(agent_data);
            udscs_server_destroy_connection(server, bc);
            return;
        }
    }

    g_object_set_data_full(G_OBJECT(bc), "agent_data", agent_data,
                           (GDestroyNotify) agent_data_destroy);
    udscs_write(bc, VDAGENTD_VERSION, 0, 0,
                (uint8_t *)VERSION, strlen(VERSION) + 1);
    update_active_session_connection(bc);

    if (device_info) {
        forward_data_to_session_agent(VDAGENTD_GRAPHICS_DEVICE_INFO,
                                      (uint8_t *) device_info, device_info_size);
    }
}

Status ne(const GrapplerItem& ya) {
  num_gpus_ = GetNumAvailableGPUs();
  LOG(INFO) << "Number of GPUs: " << num_gpus_;
  item_ = &ya;
  graph_ = item.graph;
  LOG(INFO) << "Original graph size: " << graph_.node_size();
  if (item.fetch.empty()) {
    return Status(error::INVALID_ARGUMENT, "No fetch nodes provided.");
  }

  if (item.MainVariables().empty()) {
    return Status(error::INVALID_ARGUMENT, "No variables provided.");
  }

  for (const auto& init : item.init_ops) {
    VLOG(1) << "Init node: " << init;
  }

  for (const auto& fetch : item.fetch) {
    VLOG(1) << "Fetch node: " << fetch;
  }

  for (const auto& var : item.MainVariables()) {
    VLOG(2) << "Variable: " << var->name();
  }

  const std::set<string> apply_gradients_ops = {"ApplyGradientDescent",
                                                "ApplyProximalGradientDescent",
                                                "ApplyAdadelta",
                                                "ApplyAdagrad",
                                                "ApplyProximalAdagrad",
                                                "ApplyAdagradDA",
                                                "ApplyFtrl",
                                                "ApplyMomentum",
                                                "ApplyAdam",
                                                "ApplyRMSProp",
                                                "ApplyCenteredRMSProp"};
  for (int i = 0; i < graph_.node_size(); i++) {
    all_nodes_.insert(
        std::make_pair(graph_.node(i).name(), graph_.mutable_node(i)));
    if (apply_gradients_ops.find(graph_.node(i).op()) !=
        apply_gradients_ops.end()) {
      apply_gradients_nodes_.insert(graph_.node(i).name());
      VLOG(2) << "Apply gradients node: " << graph_.node(i).name();
    }
  }

  auto div_const_node = AddNodeDivConst();
  all_nodes_.insert(std::make_pair(div_const_node->name(), div_const_node));
  std::map<string, int> gradient_pos = {{"ApplyGradientDescent", 2},
                                        {"ApplyProximalGradientDescent", 4},
                                        {"ApplyAdadelta", 6},
                                        {"ApplyAdagrad", 3},
                                        {"ApplyProximalAdagrad", 5},
                                        {"ApplyAdagradDA", 3},
                                        {"ApplyFtrl", 3},
                                        {"ApplyMomentum", 3},
                                        {"ApplyAdam", 9},
                                        {"ApplyRMSProp", 7},
                                        {"ApplyCenteredRMSProp", 8}};
  for (const auto& apply_gradient_node_name : apply_gradients_nodes_) {
    auto apply_gradients_op = all_nodes_[apply_gradient_node_name]->op();
    auto apply_gradients_node = all_nodes_[apply_gradient_node_name];

    auto div_node = AddNodeDiv(
        apply_gradient_node_name,
        apply_gradients_node->input(gradient_pos[apply_gradients_op]),
        div_const_node->name());
    all_nodes_.insert(std::make_pair(div_node->name(), div_node));
    *apply_gradients_node->mutable_input(gradient_pos[apply_gradients_op]) =
        div_node->name();
  }
  LOG(INFO) << "Graph size after adding div nodes: " << all_nodes_.size();

  std::vector<const NodeDef*> train_nodes;
  TF_RETURN_IF_ERROR(ComputeTransitiveFanin(graph_, item.fetch, &train_nodes));
  LOG(INFO) << "Number of training nodes: " << train_nodes.size();

  const NodeDef* dequeue_node;
  for (const auto& train_node : train_nodes) {
    if (IsDequeueOp(*train_node)) {
      dequeue_node = train_node;
      break;
    }
  }

  std::vector<const NodeDef*> input_nodes;
  if (dequeue_node) {
    LOG(INFO) << "Dequeue node: " << dequeue_node->name();
    TF_RETURN_IF_ERROR(ComputeTransitiveFanin(graph_, {dequeue_node->name()},
                                              {}, &input_nodes));
  }
  LOG(INFO) << "Number of input nodes: " << input_nodes.size();

  std::set<string> dont_replicate_nodes;
  for (const auto& variable : item.MainVariables()) {
    dont_replicate_nodes.insert(variable->name());
  }

  for (const auto& init : item.init_ops) {
    dont_replicate_nodes.insert(NodeName(init));
  }


  for (const auto& input_node : input_nodes) {
    if (input_node->name() != dequeue_node->name()) {
      dont_replicate_nodes.insert(input_node->name());
    }
  }

  for (const auto& node : train_nodes) {
    if (dont_replicate_nodes.find(node->name()) == dont_replicate_nodes.end()) {
      replica_nodes_.insert(node->name());
    }
  }
  LOG(INFO) << "Number of replica nodes: " << replica_nodes_.size();

  for (const auto& node : all_nodes_) {
    if (replica_nodes_.find(node.first) == replica_nodes_.end()) {
      shared_nodes_.insert(node.first);
    }
  }
  LOG(INFO) << "Number of shared nodes: " << shared_nodes_.size();
  return Status::OK();
}

