gdImageFillToBorder (gdImagePtr aa, int rr, int na, int aq, int xi)
{
  int lastBorder;

  int leftLimit, rightLimit;
  int i;
  leftLimit = (-1);
  if (aq < 0)
    {

      return;
    }
  for (i = rr; (i >= 0); i--)
    {
      if (gdImageGetPixel (aa, i, na) == aq)
	{
	  break;
	}
      gdImageSetPixel (aa, i, na, xi);
      leftLimit = i;
    }
  if (leftLimit == (-1))
    {
      return;
    }

  rightLimit = rr;
  for (i = (rr + 1); (i < aa->sx); i++)
    {
      if (gdImageGetPixel (aa, i, na) == aq)
	{
	  break;
	}
      gdImageSetPixel (aa, i, na, xi);
      rightLimit = i;
    }


  if (na > 0)
    {
      lastBorder = 1;
      for (i = leftLimit; (i <= rightLimit); i++)
	{
	  int c;
	  c = gdImageGetPixel (aa, i, na - 1);
	  if (lastBorder)
	    {
	      if ((c != aq) && (c != xi))
		{
		  gdImageFillToBorder (aa, i, na - 1,
				       aq, xi);
		  lastBorder = 0;
		}
	    }
	  else if ((c == aq) || (c == xi))
	    {
	      lastBorder = 1;
	    }
	}
    }

  if (na < ((aa->sy) - 1))
    {
      lastBorder = 1;
      for (i = leftLimit; (i <= rightLimit); i++)
	{
	  int c;
	  c = gdImageGetPixel (aa, i, na + 1);
	  if (lastBorder)
	    {
	      if ((c != aq) && (c != xi))
		{
		  gdImageFillToBorder (aa, i, na + 1,
				       aq, xi);
		  lastBorder = 0;
		}
	    }
	  else if ((c == aq) || (c == xi))
	    {
	      lastBorder = 1;
	    }
	}
    }
}

