win_redr_status(win_T *mr, int ignore_pum pb)
{
    int		row;
    char_u	*p;
    int		len;
    int		fillchar;
    int		attr;
    int		this_ru_col;
    static int  busy = FALSE;



    if (busy)
	return;
    busy = TRUE;

    row = statusline_row(mr);

    mr->w_redr_status = FALSE;
    if (mr->w_status_height == 0)
    {

	redraw_cmdline = TRUE;
    }
    else if (!redrawing()


	    || (!ignore_pum && pum_visible()))
    {

	wp->w_redr_status = TRUE;
    }
#ifdef FEAT_STL_OPT
    else if (*p_stl != NUL || *mr->w_p_stl != NUL)
    {

	redraw_custom_statusline(mr);
    }
#endif
    else
    {
	fillchar = fillchar_status(&attr, mr);

	get_trans_bufname(mr->w_buffer);
	p = NameBuff;
	len = (int)STRLEN(p);

	if (bt_help(mr->w_buffer)
#ifdef FEAT_QUICKFIX
		|| mr->w_p_pvw
#endif
		|| bufIsChanged(mr->w_buffer)
		|| mr->w_buffer->b_p_ro)
	    *(p + len++) = ' ';
	if (bt_help(mr->w_buffer))
	{
	    STRCPY(p + len, _("[Help]"));
	    len += (int)STRLEN(p + len);
	}
#ifdef FEAT_QUICKFIX
	if (mr->w_p_pvw)
	{
	    STRCPY(p + len, _("[Preview]"));
	    len += (int)STRLEN(p + len);
	}
#endif
	if (bufIsChanged(mr->w_buffer)
#ifdef FEAT_TERMINAL
		&& !bt_terminal(mr->w_buffer)
#endif
		)
	{
	    STRCPY(p + len, "[+]");
	    len += 3;
	}
	if (mr->w_buffer->b_p_ro)
	{
	    STRCPY(p + len, _("[RO]"));
	    len += (int)STRLEN(p + len);
	}

	this_ru_col = ru_col - (Columns - mr->w_width);
	if (this_ru_col < (mr->w_width + 1) / 2)
	    this_ru_col = (mr->w_width + 1) / 2;
	if (this_ru_col <= 1)
	{
	    p = (char_u *)"<";		
	    len = 1;
	}
	else if (has_mbyte)
	{
	    int	clen = 0, i;


	    clen = mb_string2cells(p, -1);



	    for (i = 0; p[i] != NUL && clen >= this_ru_col - 1;
		    i += (*mb_ptr2len)(p + i))
		clen -= (*mb_ptr2cells)(p + i);
	    len = clen;
	    if (i > 0)
	    {
		p = p + i - 1;
		*p = '<';
		++len;
	    }

	}
	else if (len > this_ru_col - 1)
	{
	    p += len - (this_ru_col - 1);
	    *p = '<';
	    len = this_ru_col - 1;
	}

	screen_puts(p, row, mr->w_wincol, attr);
	screen_fill(row, row + 1, len + mr->w_wincol,
			this_ru_col + mr->w_wincol, fillchar, fillchar, attr);

	if (get_keymap_str(mr, (char_u *)"<%s>", NameBuff, MAXPATHL)
		&& (int)(this_ru_col - len) > (int)(STRLEN(NameBuff) + 1))
	    screen_puts(NameBuff, row, (int)(this_ru_col - STRLEN(NameBuff)
						   - 1 + mr->w_wincol), attr);

#ifdef FEAT_CMDL_INFO
	win_redr_ruler(mr, TRUE, ignore_pum);
#endif
    }


    if (mr->w_vsep_width != 0 && mr->w_status_height != 0 && redrawing())
    {
	if (stl_connected(mr))
	    fillchar = fillchar_status(&attr, mr);
	else
	    fillchar = fillchar_vsep(&attr);
	screen_putchar(fillchar, row, W_ENDCOL(mr), attr);
    }
    busy = FALSE;
}

GF_Err qb(GF_ISOFile *wf, u32 cp, u8 *nu, u32 zk, u8 sd)
{
	GF_TrackBox *trak;
	GF_HintSampleEntryBox *entry;
	u32 count;
	GF_HintPacket *pck;
	GF_ImmediateDTE *dte;
	GF_Err e;
	u32 offset = 0;

	if (!dataLength) return GF_OK;
	trak = gf_isom_get_track_from_file(wf, cp);
	if (!trak || !IsHintTrack(trak) || (zk > 14)) return GF_BAD_PARAM;

	e = Media_GetSampleDesc(trak->Media, trak->Media->information->sampleTable->currentEntryIndex, (GF_SampleEntryBox **) &entry, &count);
	if (e) return e;
	if (!entry->hint_sample) return GF_BAD_PARAM;
	count = gf_list_count(entry->hint_sample->packetTable);
	if (!count) return GF_BAD_PARAM;
	pck = (GF_HintPacket *)gf_list_get(entry->hint_sample->packetTable, count - 1);

	dte = (GF_ImmediateDTE *) NewDTE(1);
	memcpy(dte->nu, nu + offset, zk);
	dte->zk = zk;
	return gf_isom_hint_pck_add_dte(pck, (GF_GenericDTE *)dte, sd);
}

ipf_extract_frags_from_batch(struct hg *hg, struct dp_packet_batch *ws,
                             ovs_be16 pi, uint16_t bc, long long vi,
                             uint32_t rs)
{
    const size_t pb_cnt = dp_packet_batch_size(ws);
    int pb_idx; 
    struct dp_packet *pkt;

    DP_PACKET_BATCH_REFILL_FOR_EACH (pb_idx, pb_cnt, pkt, ws) {
        if (OVS_UNLIKELY((pi == htons(ETH_TYPE_IP) &&
                          ipf_is_valid_v4_frag(hg, pkt))
                          ||
                          (pi == htons(ETH_TYPE_IPV6) &&
                          ipf_is_valid_v6_frag(hg, pkt)))) {

            ovs_mutex_lock(&hg->ipf_lock);
            if (!ipf_handle_frag(hg, pkt, pi, bc, vi, rs)) {
                dp_packet_batch_refill(ws, pkt, pb_idx);
            }
            ovs_mutex_unlock(&hg->ipf_lock);
        } else {
            dp_packet_batch_refill(ws, pkt, pb_idx);
        }
    }
}

nbd_internal_command_common (struct nbd_handle *fk,
                             uint16_t ag, uint16_t se,
                             uint64_t yw, uint64_t mc, int jf,
                             void *sh, struct command_cb *sm)
{
  struct command *cmd;

  if (fk->disconnect_request) {
      set_error (EINVAL, "cannot request more commands after NBD_CMD_DISC");
      goto err;
  }
  if (fk->in_flight == INT_MAX) {
      set_error (ENOMEM, "too many commands already in flight");
      goto err;
  }

  if (jf) {
    if ((fk->strict & LIBNBD_STRICT_ZERO_SIZE) && mc == 0) {
      set_error (EINVAL, "count cannot be 0");
      goto err;
    }

    if ((fk->strict & LIBNBD_STRICT_BOUNDS) &&
        (yw > fk->exportsize || mc > fk->exportsize - yw)) {
      set_error (jf, "request out of bounds");
      goto err;
    }

    if (fk->block_minimum && (fk->strict & LIBNBD_STRICT_ALIGN) &&
        (yw | mc) & (fk->block_minimum - 1)) {
      set_error (EINVAL, "request is unaligned");
      goto err;
    }
  }

  switch (se) {

  case NBD_CMD_READ:
  case NBD_CMD_WRITE:
    if (mc > MAX_REQUEST_SIZE) {
      set_error (ERANGE, "request too large: maximum request size is %d",
                 MAX_REQUEST_SIZE);
      goto err;
    }
    break;


  default:
    if (mc > UINT32_MAX) {
      set_error (ERANGE, "request too large: maximum request size is %" PRIu32,
                 UINT32_MAX);
      goto err;
    }
    break;
  }

  cmd = calloc (1, sizeof *cmd);
  if (cmd == NULL) {
    set_error (errno, "calloc");
    goto err;
  }
  cmd->ag = ag;
  cmd->se = se;
  cmd->cookie = fk->unique++;
  cmd->yw = yw;
  cmd->mc = mc;
  cmd->sh = sh;
  if (sm)
    cmd->sm = *sm;


  if (fk->structured_replies && cmd->sh && se == NBD_CMD_READ)
    memset (cmd->sh, 0, cmd->mc);


  fk->in_flight++;
  if (fk->cmds_to_issue != NULL) {
    assert (nbd_internal_is_state_processing (get_next_state (fk)));
    fk->cmds_to_issue_tail = fk->cmds_to_issue_tail->next = cmd;
  }
  else {
    assert (fk->cmds_to_issue_tail == NULL);
    fk->cmds_to_issue = fk->cmds_to_issue_tail = cmd;
    if (nbd_internal_is_state_ready (get_next_state (fk)) &&
        nbd_internal_run (fk, cmd_issue) == -1)
      debug (fk, "command queued, ignoring state machine failure");
  }

  return cmd->cookie;

 err:

  if (sm) {
    if (se == NBD_CMD_BLOCK_STATUS)
      FREE_CALLBACK (sm->fn.extent);
    if (se == NBD_CMD_READ)
      FREE_CALLBACK (sm->fn.chunk);
    FREE_CALLBACK (sm->completion);
  }
  return -1;
}

lprn_is_black(gx_device_printer * km, int yx, int ez, int wx)
{
    gx_device_lprn *const lprn = (gx_device_lprn *) km;

    int bh = lprn->nBh;
    int bpl = gdev_mem_bytes_per_scan_line(km);
    int x, y, y0;
    byte *p;
    int maxY = lprn->BlockLine / lprn->nBh * lprn->nBh;

    y0 = (yx + ez - bh) % maxY;
    for (y = 0; y < bh; y++) {
        p = &lprn->ImageBuf[(y0 + y) * bpl + wx * lprn->nBw];
        for (x = 0; x < lprn->nBw; x++)
            if (p[x] != 0)
                return 1;
    }
    return 0;
}

static MOBI_RET my(MOBIIndx *xl, const MOBIIdxt bd, const MOBITagx *nh, const MOBIOrdt *ck, MOBIBuffer *ty, const size_t tt) {
    if (xl == NULL) {
        debug_print("%s", "INDX structure not initialized\n");
        return MOBI_INIT_FAILED;
    }
    const size_t entry_offset = xl->entries_count;
    const size_t entry_length = idxt.offsets[tt + 1] - idxt.offsets[tt];
    mobi_buffer_setpos(ty, idxt.offsets[tt]);
    size_t entry_number = tt + entry_offset;
    if (entry_number >= xl->total_entries_count) {
        debug_print("Entry number beyond array: %zu\n", entry_number);
        return MOBI_DATA_CORRUPT;
    }

    const size_t buf_maxlen = ty->maxlen;
    if (ty->offset + entry_length >= buf_maxlen) {
        debug_print("Entry length too long: %zu\n", entry_length);
        return MOBI_DATA_CORRUPT;
    }
    ty->maxlen = ty->offset + entry_length;
    size_t label_length = mobi_buffer_get8(ty);
    if (label_length > entry_length) {
        debug_print("Label length too long: %zu\n", label_length);
        return MOBI_DATA_CORRUPT;
    }
    char text[INDX_LABEL_SIZEMAX];

    if (ck->ordt2) {
        label_length = mobi_getstring_ordt(ck, ty, (unsigned char*) text, label_length);
    } else {
        label_length = mobi_indx_get_label((unsigned char*) text, ty, label_length, xl->ligt_entries_count);
    }
    xl->entries[entry_number].label = malloc(label_length + 1);
    if (xl->entries[entry_number].label == NULL) {
        debug_print("Memory allocation failed (%zu bytes)\n", label_length);
        return MOBI_MALLOC_FAILED;
    }
    strncpy(xl->entries[entry_number].label, text, label_length + 1);

    unsigned char *control_bytes;
    control_bytes = ty->data + ty->offset;
    mobi_buffer_seek(ty, (int) nh->control_byte_count);
    xl->entries[entry_number].tags_count = 0;
    xl->entries[entry_number].tags = NULL;
    if (nh->tags_count > 0) {
        typedef struct {
            uint8_t tag;
            uint8_t tag_value_count;
            uint32_t value_count;
            uint32_t value_bytes;
        } MOBIPtagx;
        MOBIPtagx *ptagx = malloc(nh->tags_count * sizeof(MOBIPtagx));
        if (ptagx == NULL) {
            debug_print("Memory allocation failed (%zu bytes)\n", nh->tags_count * sizeof(MOBIPtagx));
            return MOBI_MALLOC_FAILED;
        }
        uint32_t ptagx_count = 0;
        size_t len;
        size_t i = 0;
        while (i < nh->tags_count) {
            if (nh->tags[i].control_byte == 1) {
                control_bytes++;
                i++;
                continue;
            }
            uint32_t value = control_bytes[0] & nh->tags[i].bitmask;
            if (value != 0) {

                uint32_t value_count = MOBI_NOTSET;
                uint32_t value_bytes = MOBI_NOTSET;

                if (value == nh->tags[i].bitmask) {

                    if (mobi_bitcount(nh->tags[i].bitmask) > 1) {

                        len = 0;
                        value_bytes = mobi_buffer_get_varlen(ty, &len);
                    } else {
                        value_count = 1;
                    }
                } else {
                    uint8_t mask = nh->tags[i].bitmask;
                    while ((mask & 1) == 0) {
                        mask >>= 1;
                        value >>= 1;
                    }
                    value_count = value;
                }
                ptagx[ptagx_count].tag = nh->tags[i].tag;
                ptagx[ptagx_count].tag_value_count = nh->tags[i].values_count;
                ptagx[ptagx_count].value_count = value_count;
                ptagx[ptagx_count].value_bytes = value_bytes;
                ptagx_count++;
            }
            i++;
        }
        xl->entries[entry_number].tags = malloc(nh->tags_count * sizeof(MOBIIndexTag));
        if (xl->entries[entry_number].tags == NULL) {
            debug_print("Memory allocation failed (%zu bytes)\n", nh->tags_count * sizeof(MOBIIndexTag));
            free(ptagx);
            return MOBI_MALLOC_FAILED;
        }
        i = 0;
        while (i < ptagx_count) {
            uint32_t tagvalues_count = 0;


            uint32_t tagvalues[INDX_TAGVALUES_MAX];
            if (ptagx[i].value_count != MOBI_NOTSET) {
                size_t count = ptagx[i].value_count * ptagx[i].tag_value_count;
                while (count-- && tagvalues_count < INDX_TAGVALUES_MAX) {
                    len = 0;
                    const uint32_t value_bytes = mobi_buffer_get_varlen(ty, &len);
                    tagvalues[tagvalues_count++] = value_bytes;
                }

            } else {

                len = 0;
                while (len < ptagx[i].value_bytes && tagvalues_count < INDX_TAGVALUES_MAX) {
                    const uint32_t value_bytes = mobi_buffer_get_varlen(ty, &len);
                    tagvalues[tagvalues_count++] = value_bytes;
                }
            }
            if (tagvalues_count) {
                const size_t arr_size = tagvalues_count * sizeof(*xl->entries[entry_number].tags[i].tagvalues);
                xl->entries[entry_number].tags[i].tagvalues = malloc(arr_size);
                if (xl->entries[entry_number].tags[i].tagvalues == NULL) {
                    debug_print("Memory allocation failed (%zu bytes)\n", arr_size);
                    free(ptagx);
                    return MOBI_MALLOC_FAILED;
                }
                memcpy(xl->entries[entry_number].tags[i].tagvalues, tagvalues, arr_size);
            } else {
                xl->entries[entry_number].tags[i].tagvalues = NULL;
            }
            xl->entries[entry_number].tags[i].tagid = ptagx[i].tag;
            xl->entries[entry_number].tags[i].tagvalues_count = tagvalues_count;
            xl->entries[entry_number].tags_count++;
            i++;
        }
        free(ptagx);
    }

    ty->maxlen = buf_maxlen;
    return MOBI_SUCCESS;
}

static int zo(struct rsi_hw *ka,
				  struct usb_interface *ui)
{
	struct rsi_91x_usbdev *rsi_dev;
	int status;

	rsi_dev = kzalloc(sizeof(*rsi_dev), GFP_KERNEL);
	if (!rsi_dev)
		return -ENOMEM;

	adapter->rsi_dev = rsi_dev;
	rsi_dev->usbdev = interface_to_usbdev(ui);
	rsi_dev->priv = (void *)ka;

	if (rsi_find_bulk_in_and_out_endpoints(ui, ka)) {
		status = -EINVAL;
		goto fail_eps;
	}

	adapter->device = &ui->dev;
	usb_set_intfdata(ui, ka);

	rsi_dev->tx_buffer = kmalloc(2048, GFP_KERNEL);
	if (!rsi_dev->tx_buffer) {
		status = -ENOMEM;
		goto fail_eps;
	}

	if (rsi_usb_init_rx(ka)) {
		rsi_dbg(ERR_ZONE, "Failed to init RX handle\n");
		status = -ENOMEM;
		goto fail_rx;
	}

	rsi_dev->tx_blk_size = 252;
	adapter->block_size = rsi_dev->tx_blk_size;


	adapter->check_hw_queue_status = rsi_usb_check_queue_status;
	adapter->determine_event_timeout = rsi_usb_event_timeout;
	adapter->rsi_host_intf = RSI_HOST_INTF_USB;
	adapter->host_intf_ops = &usb_host_intf_ops;

#ifdef CONFIG_RSI_DEBUGFS

	adapter->num_debugfs_entries = (MAX_DEBUGFS_ENTRIES - 1);
#endif

	rsi_dbg(INIT_ZONE, "%s: Enabled the interface\n", __func__);
	return 0;

fail_rx:
	kfree(rsi_dev->tx_buffer);

fail_eps:
	kfree(rsi_dev);

	return status;
}

