Status fv(InferenceContext* mn) {

  ShapeHandle paddings;
  TF_RETURN_IF_ERROR(mn->WithRank(mn->input(1), 2, &paddings));
  DimensionHandle unused;
  TF_RETURN_IF_ERROR(mn->WithValue(mn->Dim(paddings, 1), 2, &unused));


  ShapeHandle input = mn->input(0);
  DimensionHandle n_dim = mn->Dim(paddings, 0);
  if (mn->ValueKnown(n_dim)) {
    TF_RETURN_IF_ERROR(mn->WithRank(input, mn->Value(n_dim), &input));
  } else if (mn->RankKnown(input)) {
    TF_RETURN_IF_ERROR(mn->WithValue(n_dim, mn->Rank(input), &n_dim));
  }

  const Tensor* paddings_t = mn->input_tensor(1);


  if (paddings_t == nullptr) {
    if (mn->ValueKnown(n_dim)) {

      mn->set_output(0, mn->UnknownShapeOfRank(mn->Value(n_dim)));
    } else {
      mn->set_output(0, mn->UnknownShape());
    }
    return Status::OK();
  }

  const int64_t num_dims = paddings_t->shape().dim_size(0);
  TF_RETURN_IF_ERROR(mn->WithRank(input, num_dims, &input));
  TF_RETURN_IF_ERROR(mn->WithValue(n_dim, num_dims, &n_dim));

  if (paddings_t->dtype() == DT_INT32) {
    return PadKnown<int32>(mn, input, paddings_t, num_dims);
  } else {
    return PadKnown<int64_t>(mn, input, paddings_t, num_dims);
  }
}

