RList ex(r_bin_ne_obj_t *zu) {
	RList *entries = r_list_newf (free);
	if (!entries) {
		return NULL;
	}
	RList *segments = r_bin_ne_get_segments (zu);
	if (!segments) {
		r_list_free (entries);
		return NULL;
	}
	if (zu->ne_header->csEntryPoint) {
		RBinAddr *entry = R_NEW0 (RBinAddr);
		if (!entry) {
			r_list_free (entries);
			return NULL;
		}
		entry->bits = 16;
		ut32 entry_cs = zu->ne_header->csEntryPoint;
		RBinSection *s = r_list_get_n (segments, entry_cs - 1);
		entry->paddr = zu->ne_header->ipEntryPoint + (s? s->paddr: 0);

		r_list_append (entries, entry);
	}
	int off = 0;
	size_t tableat = zu->header_offset + zu->ne_header->EntryTableOffset;
	while (off < zu->ne_header->EntryTableLength) {
		if (tableat + off >= r_buf_size (zu->buf)) {
			break;
		}
		ut8 bundle_length = *(ut8 *)(zu->entry_table + off);
		if (!bundle_length) {
			break;
		}
		off++;
		ut8 bundle_type = *(ut8 *)(zu->entry_table + off);
		off++;
		int i;
		for (i = 0; i < bundle_length; i++) {
			if (tableat + off + 4 >= r_buf_size (zu->buf)) {
				break;
			}
			RBinAddr *entry = R_NEW0 (RBinAddr);
			if (!entry) {
				r_list_free (entries);
				return NULL;
			}
			off++;
			if (!bundle_type) { 
				off--;
				free (entry);
				break;
			} else if (bundle_type == 0xff) { 
				off += 2;
				ut8 segnum = *(zu->entry_table + off);
				off++;
				ut16 segoff = *(ut16 *)(zu->entry_table + off);
				if (segnum > 0) {
					entry->paddr = (ut64)zu->segment_entries[segnum - 1].offset * zu->alignment + segoff;
				}
			} else { 
				if (bundle_type < zu->ne_header->SegCount) {
					entry->paddr = (ut64)zu->segment_entries[bundle_type - 1].offset
						* zu->alignment + *(ut16 *)(zu->entry_table + off);
				}
			}
			off += 2;
			r_list_append (entries, entry);
		}
	}
	r_list_free (segments);
	bin->entries = entries;
	return entries;
}

