static Status rq(const string& id, const DataType& ec,
                                     const PartialTensorShape& fn,
                                     Tensor* or) {
  if (id == "Shape" || id == "ShapeN") {
    *or = Tensor(ec, TensorShape({shp.dims()}));
    for (int i = 0; i < shp.dims(); ++i) {
      TF_RETURN_IF_ERROR(PutValueIntoTensor(shp.dim_size(i), ec, i, or));
    }
  } else if (id == "Size") {
    int64_t size = 1;
    for (int i = 0; i < shp.dims(); ++i) {
      size *= shp.dim_size(i);
    }
    *or = Tensor(ec, TensorShape({}));
    TF_RETURN_IF_ERROR(PutValueIntoTensor(size, ec, 0, or));
  } else {
    CHECK_EQ(id, "Rank");
    *or = Tensor(ec, TensorShape({}));
    TF_RETURN_IF_ERROR(PutValueIntoTensor(shp.dims(), ec, 0, or));
  }
  return Status::OK();
}

GF_Filter ct(GF_FilterSession *nd, const char *ac, GF_Err *lr)
{
	const char *args=NULL;
	const char *sep, *file_ext;
	u32 i, len, count = gf_list_count(nd->registry);
	Bool quiet = (lr && (*lr == GF_EOS)) ? GF_TRUE : GF_FALSE;

	assert(nd);
	assert(ac);
	if (lr) *lr = GF_OK;

	sep = gf_fs_path_escape_colon(nd, ac);
	if (sep) {
		args = sep+1;
		len = (u32) (sep - ac);
	} else len = (u32) strlen(ac);

	if (!len) {
		if (!quiet) {
			GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Missing filter ac in %s\n", ac));
		}
		return NULL;
	}

	if (!strncmp(ac, "enc", len)) {
		return gf_fs_load_encoder(nd, args);
	}

	for (i=0;i<count;i++) {
		const GF_FilterRegister *f_reg = gf_list_get(nd->registry, i);
		if ((strlen(f_reg->ac)==len) && !strncmp(f_reg->ac, ac, len)) {
			GF_Filter *filter;
			GF_FilterArgType argtype = GF_FILTER_ARG_EXPLICIT;

			if ((f_reg->flags & GF_FS_REG_REQUIRES_RESOLVER) && !fsess->max_resolve_chain_len) {
				GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Filter %s requires graph resolver but it is disabled\n", ac));
				if (lr) *lr = GF_BAD_PARAM;
				return NULL;
			}

			if (f_reg->flags & GF_FS_REG_ACT_AS_SOURCE) argtype = GF_FILTER_ARG_EXPLICIT_SOURCE;
			filter = gf_filter_new(nd, f_reg, args, NULL, argtype, lr, NULL, GF_FALSE);
			if (!filter) return NULL;
			if (!filter->num_output_pids) {
				const char *src_url = strstr(ac, "src");
				if (src_url && (src_url[3]==fsess->sep_name))
					gf_filter_post_process_task(filter);
			}
			return filter;
		}
	}

	file_ext = gf_file_ext_start(ac);
	if (file_ext && (file_ext > sep) )
		file_ext = NULL;

	if (!file_ext || strstr(ac, ".js") || strstr(ac, ".jsf") || strstr(ac, ".mjs") ) {
		Bool file_exists = GF_FALSE;
		char szName[10+GF_MAX_PATH];
		char szPath[10+GF_MAX_PATH];
		if (len>GF_MAX_PATH)
			return NULL;

		strncpy(szPath, ac, len);
		szPath[len]=0;
		GF_LOG(GF_LOG_DEBUG, GF_LOG_FILTER, ("Trying JS filter %s\n", szPath));
		if (gf_file_exists(szPath)) {
			file_exists = GF_TRUE;
		} else {
			strcpy(szName, szPath);
			file_exists = gf_fs_solve_js_script(szPath, szName, file_ext);
			if (!file_exists && !file_ext) {
				strcat(szName, ".js");
				if (gf_file_exists(szName)) {
					strncpy(szPath, ac, len);
					szPath[len]=0;
					strcat(szPath, ".js");
					file_exists = GF_TRUE;
				}
			}
		}

		if (file_exists) {
			sprintf(szName, "jsf%cjs%c", nd->sep_args, nd->sep_name);
			strcat(szName, szPath);
			if (ac[len])
				strcat(szName, name+len);
			return gf_fs_load_filter(nd, szName, lr);
		}
	}

	if (!quiet) {
		GF_LOG(GF_LOG_ERROR, GF_LOG_FILTER, ("Failed to load filter %s: no such filter registry\n", ac));
	}
	if (lr) *lr = GF_FILTER_NOT_FOUND;
	return NULL;
}

_kdc_add_KRB5SignedPath(krb5_context tz,
			krb5_kdc_configuration *km,
			hdb_entry_ex *aj,
			krb5_enctype nm,
			krb5_const_principal yc,
			krb5_const_principal xr,
			krb5_principals hs,
			EncTicketPart *qf)
{
    krb5_error_code ret;
    KRB5SignedPath sp;
    krb5_data data;
    krb5_crypto crypto = NULL;
    size_t size = 0;

    if (xr && hs) {
	ret = add_Principals(hs, xr);
	if (ret)
	    return ret;
    }

    {
	KRB5SignedPathData spd;

	spd.client = rk_UNCONST(yc);
	spd.authtime = qf->authtime;
	spd.delegated = hs;
	spd.method_data = NULL;

	ASN1_MALLOC_ENCODE(KRB5SignedPathData, data.data, data.length,
			   &spd, &size, ret);
	if (ret)
	    return ret;
	if (data.length != size)
	    krb5_abortx(tz, "internal asn.1 encoder error");
    }

    {
	Key *key;
	ret = hdb_enctype2key(tz, &aj->entry, NULL, nm, &key);
	if (ret == 0)
	    ret = krb5_crypto_init(tz, &key->key, 0, &crypto);
	if (ret) {
	    free(data.data);
	    return ret;
	}
    }



    sp.etype = nm;
    sp.delegated = hs;
    sp.method_data = NULL;

    ret = krb5_create_checksum(tz, crypto, KRB5_KU_KRB5SIGNEDPATH, 0,
			       data.data, data.length, &sp.cksum);
    krb5_crypto_destroy(tz, crypto);
    free(data.data);
    if (ret)
	return ret;

    ASN1_MALLOC_ENCODE(KRB5SignedPath, data.data, data.length, &sp, &size, ret);
    free_Checksum(&sp.cksum);
    if (ret)
	return ret;
    if (data.length != size)
	krb5_abortx(tz, "internal asn.1 encoder error");




    ret = _kdc_tkt_add_if_relevant_ad(tz, qf,
				      KRB5_AUTHDATA_SIGNTICKET, &data);
    krb5_data_free(&data);

    return ret;
}

