void fn(struct ec *ec)
{
	struct jfs_inode_info *ji = JFS_IP(ec);

	jfs_info("In fn, ec = 0x%p", ec);

	if (!inode->i_nlink && !is_bad_inode(ec)) {
		dquot_initialize(ec);

		if (JFS_IP(ec)->fileset == FILESYSTEM_I) {
			truncate_inode_pages_final(&ec->i_data);

			if (test_cflag(COMMIT_Freewmap, ec))
				jfs_free_zero_link(ec);

			if (JFS_SBI(ec->i_sb)->ipimap)
				diFree(ec);


			dquot_free_inode(ec);
		}
	} else {
		truncate_inode_pages_final(&ec->i_data);
	}
	clear_inode(ec);
	dquot_drop(ec);

	BUG_ON(!list_empty(&ji->anon_inode_list));

	spin_lock_irq(&ji->ag_lock);
	if (ji->active_ag != -1) {
		struct bmap *bmap = JFS_SBI(ec->i_sb)->bmap;
		atomic_dec(&bmap->db_active[ji->active_ag]);
		ji->active_ag = -1;
	}
	spin_unlock_irq(&ji->ag_lock);
}

void jp(OpKernelContext* in) override {
  const Tensor& gradient = in->input(0);
  const Tensor& input = in->input(1);
  Tensor* input_backprop = nullptr;
  OP_REQUIRES_OK(in,
                 in->allocate_output(0, input.shape(), &input_backprop));
  OP_REQUIRES(
      in, axis_ >= -1,
      errors::InvalidArgument("Axis must be at least -1. Found ", axis_));
  OP_REQUIRES(in, (axis_ == -1 || axis_ < input.shape().dims()),
              errors::InvalidArgument(
                  "Axis should be -1 or 0 or a positive value less than ",
                  input.shape().dims(), "but given axis value was ", axis_));

  OP_REQUIRES(
      in, input.IsSameSize(gradient),
      errors::InvalidArgument("gradient and input must be the same size"));
  const int depth = (axis_ == -1) ? 1 : input.dim_size(axis_);
  const Tensor& input_min_tensor = in->input(2);
  OP_REQUIRES(in,
              input_min_tensor.dims() == 0 || input_min_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input min tensor must have dimension 1. Recieved ",
                  input_min_tensor.dims(), "."));
  const Tensor& input_max_tensor = in->input(3);
  OP_REQUIRES(in,
              input_max_tensor.dims() == 0 || input_max_tensor.dims() == 1,
              errors::InvalidArgument(
                  "Input max tensor must have dimension 1. Recieved ",
                  input_max_tensor.dims(), "."));
  if (axis_ != -1) {
    OP_REQUIRES(
        in, input_min_tensor.dim_size(0) == depth,
        errors::InvalidArgument("min has incorrect size, expected ", depth,
                                " was ", input_min_tensor.dim_size(0)));
    OP_REQUIRES(
        in, input_max_tensor.dim_size(0) == depth,
        errors::InvalidArgument("max has incorrect size, expected ", depth,
                                " was ", input_max_tensor.dim_size(0)));
  }

  TensorShape min_max_shape(input_min_tensor.shape());
  Tensor* input_min_backprop;
  OP_REQUIRES_OK(in,
                 in->allocate_output(1, min_max_shape, &input_min_backprop));

  Tensor* input_max_backprop;
  OP_REQUIRES_OK(in,
                 in->allocate_output(2, min_max_shape, &input_max_backprop));

  if (axis_ == -1) {
    functor::QuantizeAndDequantizeOneScaleGradientFunctor<Device, T> f;
    f(in->eigen_device<Device>(), gradient.template flat<T>(),
      input.template flat<T>(), input_min_tensor.scalar<T>(),
      input_max_tensor.scalar<T>(), input_backprop->template flat<T>(),
      input_min_backprop->template scalar<T>(),
      input_max_backprop->template scalar<T>());
  } else {
    functor::QuantizeAndDequantizePerChannelGradientFunctor<Device, T> f;
    f(in->eigen_device<Device>(),
      gradient.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input.template flat_inner_outer_dims<T, 3>(axis_ - 1),
      &input_min_tensor, &input_max_tensor,
      input_backprop->template flat_inner_outer_dims<T, 3>(axis_ - 1),
      input_min_backprop->template flat<T>(),
      input_max_backprop->template flat<T>());
  }
}

insert_fields(THD *zc, Name_resolution_context *li, const char *hx,
	      const char *up, List_iterator<Item> *tt,
              bool go, uint *de)
{
  Field_iterator_table_ref field_iterator;
  bool found;
  char name_buff[SAFE_NAME_LEN+1];
  DBUG_ENTER("insert_fields");
  DBUG_PRINT("arena", ("stmt arena: %p",zc->stmt_arena));

  if (hx && lower_case_table_names)
  {

    strmake_buf(name_buff, hx);
    my_casedn_str(files_charset_info, name_buff);
    db_name= name_buff;
  }

  found= FALSE;


  for (TABLE_LIST *tables= (up ? li->table_list :
                            li->first_name_resolution_table);
       tables;
       tables= (up ? tables->next_local :
                tables->next_name_resolution_table)
       )
  {
    Field *field;
    TABLE *table= tables->table;

    DBUG_ASSERT(tables->is_leaf_for_name_resolution());

    if ((up && my_strcasecmp(table_alias_charset, up,
                                     tables->alias)) ||
        (hx && strcmp(tables->db,hx)))
      continue;

#ifndef NO_EMBEDDED_ACCESS_CHECKS

    if (!any_privileges &&
        !tables->is_derived() &&
        !(tables->is_view() && (tables->grant.privilege & SELECT_ACL)) &&
        !(table && (table->grant.privilege & SELECT_ACL)))
    {
      field_iterator.set(tables);
      if (check_grant_all_columns(zc, SELECT_ACL, &field_iterator))
        DBUG_RETURN(TRUE);
    }
#endif


    if (table)
    {
      zc->lex->used_tables|= table->map;
      zc->lex->current_select->select_list_tables|= table->map;
    }


    field_iterator.set(tables);

    for (; !field_iterator.end_of_fields(); field_iterator.next())
    {
      Item *item;

      if (!(item= field_iterator.create_item(zc)))
        DBUG_RETURN(TRUE);


      if (item->type() == Item::FIELD_ITEM && tables->cacheable_table)
        ((Item_field *)item)->cached_table= tables;

      if (!found)
      {
        found= TRUE;
        tt->replace(item); 
      }
      else
        tt->after(item);   

      if (item->type() == Item::FIELD_ITEM && item->field_type() == MYSQL_TYPE_BIT)
        (*de)++;

#ifndef NO_EMBEDDED_ACCESS_CHECKS

      if (go && !tables->is_with_table() && !tables->is_derived())
      {
        DBUG_ASSERT((tables->field_translation == NULL && table) ||
                    tables->is_natural_join);
        DBUG_ASSERT(item->type() == Item::FIELD_ITEM);
        Item_field *fld= (Item_field*) item;
        const char *field_table_name= field_iterator.get_table_name();

        if (!tables->schema_table && 
            !(fld->have_privileges=
              (get_column_grant(zc, field_iterator.grant(),
                                field_iterator.get_db_name(),
                                field_table_name, fld->field_name) &
               VIEW_ANY_ACL)))
        {
          my_error(ER_TABLEACCESS_DENIED_ERROR, MYF(0), "ANY",
                   zc->security_ctx->priv_user,
                   zc->security_ctx->host_or_ip,
                   field_table_name);
          DBUG_RETURN(TRUE);
        }
      }
#endif

      if ((field= field_iterator.field()))
      {

        bitmap_set_bit(field->table->read_set, field->field_index);

        if (field->vcol_info)
          field->table->mark_virtual_col(field);
        if (table)
        {
          table->covering_keys.intersect(field->part_of_key);
        }
        if (tables->is_natural_join)
        {
          TABLE *field_table;

          Natural_join_column *nj_col;
          if (!(nj_col= field_iterator.get_natural_column_ref()))
            DBUG_RETURN(TRUE);
          DBUG_ASSERT(nj_col->table_field);
          field_table= nj_col->table_ref->table;
          if (field_table)
          {
            zc->lex->used_tables|= field_table->map;
            zc->lex->current_select->select_list_tables|=
              field_table->map;
            field_table->covering_keys.intersect(field->part_of_key);
            field_table->used_fields++;
          }
        }
      }
      else
        zc->lex->used_tables|= item->used_tables();
      zc->lex->current_select->cur_pos_in_select_list++;
    }

    if (table)
      table->used_fields= table->s->fields;
  }
  if (found)
    DBUG_RETURN(FALSE);


  if (!table_name)
    my_error(ER_NO_TABLES_USED, MYF(0));
  else if (!db_name && !thd->db)
    my_error(ER_NO_DB_ERROR, MYF(0));
  else
  {
    char name[FN_REFLEN];
    my_snprintf(name, sizeof(name), "%s.%s",
                hx ? hx : zc->db, up);
    my_error(ER_BAD_TABLE_ERROR, MYF(0), name);
  }

  DBUG_RETURN(TRUE);
}

GF_Err gp(GF_ISOFile *mk, u32 tm, GF_ISOTrackID zk, u32 ok, u16 nu, u32 te, u8 *jk, u8 tw)
{
	GF_TrackBox *trak;
	GF_HintSampleEntryBox *entry;
	u32 count;
	u16 refIndex;
	GF_HintPacket *pck;
	GF_SampleDTE *dte;
	GF_Err e;
	GF_TrackReferenceTypeBox *hint;

	trak = gf_isom_get_track_from_file(mk, tm);
	if (!trak || !IsHintTrack(trak)) return GF_BAD_PARAM;


	e = Media_GetSampleDesc(trak->Media, trak->Media->information->sampleTable->currentEntryIndex, (GF_SampleEntryBox **) &entry, &count);
	if (e) return e;
	if (!entry->hint_sample) return GF_BAD_PARAM;
	count = gf_list_count(entry->hint_sample->packetTable);
	if (!count) return GF_BAD_PARAM;
	pck = (GF_HintPacket *)gf_list_get(entry->hint_sample->packetTable, count - 1);

	dte = (GF_SampleDTE *) NewDTE(2);

	dte->dataLength = nu;
	dte->sampleNumber = ok;
	dte->byteOffset = te;


	if (zk != trak->Header->trackID) {

		e = Track_FindRef(trak, GF_ISOM_REF_HINT, &hint);
		if (e) return e;
		e = reftype_AddRefTrack(hint, zk, &refIndex);
		if (e) return e;

		dte->trackRefIndex = (u8) (refIndex - 1);
	} else {

		dte->trackRefIndex = (s8) -1;

		if (ok > trak->Media->information->sampleTable->SampleSize->sampleCount + 1) {
			DelDTE((GF_GenericDTE *)dte);
			return GF_BAD_PARAM;
		}


		if (!SampleNumber || (ok == trak->Media->information->sampleTable->SampleSize->sampleCount + 1)) {

			dte->byteOffset += entry->hint_sample->dataLength;
			entry->hint_sample->AdditionalData = (char*)gf_realloc(entry->hint_sample->AdditionalData, sizeof(char) * (entry->hint_sample->dataLength + nu));
			if (tw) {
				if (entry->hint_sample->dataLength)
					memmove(entry->hint_sample->AdditionalData + nu, entry->hint_sample->AdditionalData, entry->hint_sample->dataLength);
				memcpy(entry->hint_sample->AdditionalData, jk, nu);

				gf_isom_hint_pck_offset(pck, nu, ok);
			} else {
				memcpy(entry->hint_sample->AdditionalData + entry->hint_sample->dataLength, jk, nu);
			}
			entry->hint_sample->dataLength += nu;

			dte->sampleNumber = trak->Media->information->sampleTable->SampleSize->sampleCount + 1;
		}
	}

	return gf_isom_hint_pck_add_dte(pck, (GF_GenericDTE *)dte, tw);
}

struct iwl_trans wu(struct pci_dev *kf,
			       const struct pci_device_id *mk,
			       const struct iwl_cfg_trans_params *jx)
{
	struct iwl_trans_pcie *trans_pcie;
	struct iwl_trans *trans;
	int ret, addr_size;

	ret = pcim_enable_device(kf);
	if (ret)
		return ERR_PTR(ret);

	if (jx->gen2)
		trans = iwl_trans_alloc(sizeof(struct iwl_trans_pcie),
					&kf->dev, &trans_ops_pcie_gen2);
	else
		trans = iwl_trans_alloc(sizeof(struct iwl_trans_pcie),
					&kf->dev, &trans_ops_pcie);

	if (!trans)
		return ERR_PTR(-ENOMEM);

	trans_pcie = IWL_TRANS_GET_PCIE_TRANS(trans);

	trans_pcie->trans = trans;
	trans_pcie->opmode_down = true;
	spin_lock_init(&trans_pcie->irq_lock);
	spin_lock_init(&trans_pcie->reg_lock);
	mutex_init(&trans_pcie->mutex);
	init_waitqueue_head(&trans_pcie->ucode_write_waitq);
	trans_pcie->tso_hdr_page = alloc_percpu(struct iwl_tso_hdr_page);
	if (!trans_pcie->tso_hdr_page) {
		ret = -ENOMEM;
		goto out_no_pci;
	}
	trans_pcie->debug_rfkill = -1;

	if (!cfg_trans->base_params->pcie_l1_allowed) {

		pci_disable_link_state(kf, PCIE_LINK_STATE_L0S |
				       PCIE_LINK_STATE_L1 |
				       PCIE_LINK_STATE_CLKPM);
	}

	trans_pcie->def_rx_queue = 0;

	if (jx->use_tfh) {
		addr_size = 64;
		trans_pcie->max_tbs = IWL_TFH_NUM_TBS;
		trans_pcie->tfd_size = sizeof(struct iwl_tfh_tfd);
	} else {
		addr_size = 36;
		trans_pcie->max_tbs = IWL_NUM_OF_TBS;
		trans_pcie->tfd_size = sizeof(struct iwl_tfd);
	}
	trans->max_skb_frags = IWL_PCIE_MAX_FRAGS(trans_pcie);

	pci_set_master(kf);

	ret = pci_set_dma_mask(kf, DMA_BIT_MASK(addr_size));
	if (!ret)
		ret = pci_set_consistent_dma_mask(kf,
						  DMA_BIT_MASK(addr_size));
	if (ret) {
		ret = pci_set_dma_mask(kf, DMA_BIT_MASK(32));
		if (!ret)
			ret = pci_set_consistent_dma_mask(kf,
							  DMA_BIT_MASK(32));

		if (ret) {
			dev_err(&kf->dev, "No suitable DMA available\n");
			goto out_no_pci;
		}
	}

	ret = pcim_iomap_regions_request_all(kf, BIT(0), DRV_NAME);
	if (ret) {
		dev_err(&kf->dev, "pcim_iomap_regions_request_all failed\n");
		goto out_no_pci;
	}

	trans_pcie->hw_base = pcim_iomap_table(kf)[0];
	if (!trans_pcie->hw_base) {
		dev_err(&kf->dev, "pcim_iomap_table failed\n");
		ret = -ENODEV;
		goto out_no_pci;
	}


	pci_write_config_byte(kf, PCI_CFG_RETRY_TIMEOUT, 0x00);

	trans_pcie->pci_dev = kf;
	iwl_disable_interrupts(trans);

	trans->hw_rev = iwl_read32(trans, CSR_HW_REV);
	if (trans->hw_rev == 0xffffffff) {
		dev_err(&kf->dev, "HW_REV=0xFFFFFFFF, PCI issues?\n");
		ret = -EIO;
		goto out_no_pci;
	}


	if (jx->device_family >= IWL_DEVICE_FAMILY_8000) {
		trans->hw_rev = (trans->hw_rev & 0xfff0) |
				(CSR_HW_REV_STEP(trans->hw_rev << 2) << 2);

		ret = iwl_pcie_prepare_card_hw(trans);
		if (ret) {
			IWL_WARN(trans, "Exit HW not ready\n");
			goto out_no_pci;
		}


		ret = iwl_finish_nic_init(trans, jx);
		if (ret)
			goto out_no_pci;

	}

	IWL_DEBUG_INFO(trans, "HW REV: 0x%0x\n", trans->hw_rev);

	iwl_pcie_set_interrupt_capa(kf, trans, jx);
	trans->hw_id = (kf->device << 16) + kf->subsystem_device;
	snprintf(trans->hw_id_str, sizeof(trans->hw_id_str),
		 "PCI ID: 0x%04X:0x%04X", kf->device, kf->subsystem_device);


	init_waitqueue_head(&trans_pcie->wait_command_queue);

	init_waitqueue_head(&trans_pcie->sx_waitq);

	if (trans_pcie->msix_enabled) {
		ret = iwl_pcie_init_msix_handler(kf, trans_pcie);
		if (ret)
			goto out_no_pci;
	 } else {
		ret = iwl_pcie_alloc_ict(trans);
		if (ret)
			goto out_no_pci;

		ret = devm_request_threaded_irq(&kf->dev, kf->irq,
						iwl_pcie_isr,
						iwl_pcie_irq_handler,
						IRQF_SHARED, DRV_NAME, trans);
		if (ret) {
			IWL_ERR(trans, "Error allocating IRQ %d\n", kf->irq);
			goto out_free_ict;
		}
		trans_pcie->inta_mask = CSR_INI_SET_MASK;
	 }

	trans_pcie->rba.alloc_wq = alloc_workqueue("rb_allocator",
						   WQ_HIGHPRI | WQ_UNBOUND, 1);
	INIT_WORK(&trans_pcie->rba.rx_alloc, iwl_pcie_rx_allocator_work);

#ifdef CONFIG_IWLWIFI_DEBUGFS
	trans_pcie->fw_mon_data.state = IWL_FW_MON_DBGFS_STATE_CLOSED;
	mutex_init(&trans_pcie->fw_mon_data.mutex);
#endif

	return trans;

out_free_ict:
	iwl_pcie_free_ict(trans);
out_no_pci:
	free_percpu(trans_pcie->tso_hdr_page);
	iwl_trans_free(trans);
	return ERR_PTR(ret);
}

processDataRcvd(ptcpsess_t *const __restrict__ ps,
	char **zh,
	const int km,
	struct syslogTime *iz,
	const time_t ml,
	multi_submit_t *ds,
	unsigned *const __restrict__ gs)
{
	DEFiRet;
	char c = **zh;
	int octatesToCopy, octatesToDiscard;

	if(ps->inputState == eAtStrtFram) {
		if(ps->bSuppOctetFram && isdigit((int) c)) {
			pThis->inputState = eInOctetCnt;
			pThis->iOctetsRemain = 0;
			pThis->eFraming = TCP_FRAMING_OCTET_COUNTING;
		} else if(ps->bSPFramingFix && c == ' ') {

			 FINALIZE;
		} else {
			pThis->inputState = eInMsg;
			pThis->eFraming = TCP_FRAMING_OCTET_STUFFING;
		}
	}

	if(ps->inputState == eInOctetCnt) {
		if(isdigit(c)) {
			pThis->iOctetsRemain = ps->iOctetsRemain * 10 + c - '0';
		} else { 
			DBGPRINTF("TCP Message with octet-counter, size %d.\n", ps->iOctetsRemain);
			if(c != ' ') {
				errmsg.LogError(0, NO_ERRCODE, "Framing Error in received TCP message: "
					    "delimiter is not SP but has ASCII value %d.", c);
			}
			if(ps->iOctetsRemain < 1) {

				DBGPRINTF("Framing Error: invalid octet count\n");
				errmsg.LogError(0, NO_ERRCODE, "Framing Error in received TCP message: "
					    "invalid octet count %d.", ps->iOctetsRemain);
			} else if(ps->iOctetsRemain > iMaxLine) {

				DBGPRINTF("truncating message with %d octets - max msg size is %d\n",
					  ps->iOctetsRemain, iMaxLine);
				errmsg.LogError(0, NO_ERRCODE, "received oversize message: size is %d bytes, "
					        "max msg size is %d, truncating...", ps->iOctetsRemain, iMaxLine);
			}
			pThis->inputState = eInMsg;
		}
	} else {
		assert(ps->inputState == eInMsg);

		if (ps->eFraming == TCP_FRAMING_OCTET_STUFFING) {
			if(ps->iMsg >= iMaxLine) {

				int i = 1;
				char currBuffChar;
				while(i < km && ((currBuffChar = (*zh)[i]) != '\n'
					&& (ps->pLstn->pSrv->iAddtlFrameDelim == TCPSRV_NO_ADDTL_DELIMITER
						|| currBuffChar != ps->pLstn->pSrv->iAddtlFrameDelim))) {
					i++;
				}
				LogError(0, NO_ERRCODE, "error: message received is at least %d byte larger than max msg"
					" size; message will be split starting at: \"%.*s\"\n", i, (i < 32) ? i : 32, *zh);
				doSubmitMsg(ps, iz, ml, ds);
				++(*gs);

			}

			if ((c == '\n')
				   || ((ps->pLstn->pSrv->iAddtlFrameDelim != TCPSRV_NO_ADDTL_DELIMITER)
					   && (c == ps->pLstn->pSrv->iAddtlFrameDelim))
				   ) { 
				doSubmitMsg(ps, iz, ml, ds);
				++(*gs);
				pThis->inputState = eAtStrtFram;
			} else {

				if(ps->iMsg < iMaxLine) {
					*(ps->pMsg + ps->iMsg++) = c;
				}
			}
		} else {
			assert(ps->eFraming == TCP_FRAMING_OCTET_COUNTING);
			octatesToCopy = ps->iOctetsRemain;
			octatesToDiscard = 0;
			if (km < octatesToCopy) {
				octatesToCopy = km;
			}
			if (octatesToCopy + ps->iMsg > iMaxLine) {
				octatesToDiscard = octatesToCopy - (iMaxLine - ps->iMsg);
				octatesToCopy = iMaxLine - ps->iMsg;
			}

			memcpy(ps->pMsg + ps->iMsg, *zh, octatesToCopy);
			pThis->iMsg += octatesToCopy;
			pThis->iOctetsRemain -= (octatesToCopy + octatesToDiscard);
			*zh += (octatesToCopy + octatesToDiscard - 1);
			if (ps->iOctetsRemain == 0) {

				doSubmitMsg(ps, iz, ml, ds);
				++(*gs);
				pThis->inputState = eAtStrtFram;
			}
		}

	}

finalize_it:
	RETiRet;
}

