MagickExport MagickBooleanType ku(Image *jb,
  const char *zw,const char *da)
{
  ExceptionInfo
    *exception;

  MagickBooleanType
    status;

  MagickStatusType
    flags;

  size_t
    property_length;


  assert(jb != (Image *) NULL);
  assert(jb->signature == MagickCoreSignature);
  if (jb->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",
      jb->filename);
  if (jb->properties == (void *) NULL)
    jb->properties=NewSplayTree(CompareSplayTreeString,
      RelinquishMagickMemory,RelinquishMagickMemory);  
  if (da == (const char *) NULL)
    return(DeleteImageProperty(jb,zw));  
  exception=(&jb->exception);
  property_length=strlen(zw);
  if ((property_length > 2) && (*(property+(property_length-2)) == ':') &&
      (*(property+(property_length-1)) == '*'))
    {
      (void) ThrowMagickException(exception,GetMagickModule(),
        OptionWarning,"SetReadOnlyProperty","`%s'",zw);
      return(MagickFalse);
    }

  status=MagickTrue;
  switch (*zw)
  {
    case 'B':
    case 'b':
    {
      if (LocaleCompare("background",zw) == 0)
        {
          (void) QueryColorDatabase(da,&jb->background_color,exception);
          break;
        }
      if (LocaleCompare("bias",zw) == 0)
        {
          jb->bias=StringToDoubleInterval(da,(double) QuantumRange+1.0);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'C':
    case 'c':
    {
      if (LocaleCompare("colorspace",zw) == 0)
        {
          ssize_t
            colorspace;

          colorspace=ParseCommandOption(MagickColorspaceOptions,MagickFalse,
            da);
          if (colorspace < 0)
            break;
          status=SetImageColorspace(jb,(ColorspaceType) colorspace);
          break;
        }
      if (LocaleCompare("compose",zw) == 0)
        {
          ssize_t
            compose;

          compose=ParseCommandOption(MagickComposeOptions,MagickFalse,da);
          if (compose < 0)
            break;
          jb->compose=(CompositeOperator) compose;
          break;
        }
      if (LocaleCompare("compress",zw) == 0)
        {
          ssize_t
            compression;

          compression=ParseCommandOption(MagickCompressOptions,MagickFalse,
            da);
          if (compression < 0)
            break;
          jb->compression=(CompressionType) compression;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'D':
    case 'd':
    {
      if (LocaleCompare("delay",zw) == 0)
        {
          GeometryInfo
            geometry_info;

          flags=ParseGeometry(da,&geometry_info);
          if ((flags & GreaterValue) != 0)
            {
              if (jb->delay > (size_t) floor(geometry_info.rho+0.5))
                jb->delay=(size_t) floor(geometry_info.rho+0.5);
            }
          else
            if ((flags & LessValue) != 0)
              {
                if ((double) jb->delay < floor(geometry_info.rho+0.5))
                  jb->ticks_per_second=CastDoubleToLong(
                    floor(geometry_info.sigma+0.5));
              }
            else
              jb->delay=(size_t) floor(geometry_info.rho+0.5);
          if ((flags & SigmaValue) != 0)
            jb->ticks_per_second=CastDoubleToLong(floor(
              geometry_info.sigma+0.5));
          break;
        }
      if (LocaleCompare("density",zw) == 0)
        {
          GeometryInfo
            geometry_info;

          flags=ParseGeometry(da,&geometry_info);
          if ((flags & RhoValue) != 0)
            jb->x_resolution=geometry_info.rho;
          jb->y_resolution=image->x_resolution;
          if ((flags & SigmaValue) != 0)
            jb->y_resolution=geometry_info.sigma;
        }
      if (LocaleCompare("depth",zw) == 0)
        {
          jb->depth=StringToUnsignedLong(da);
          break;
        }
      if (LocaleCompare("dispose",zw) == 0)
        {
          ssize_t
            dispose;

          dispose=ParseCommandOption(MagickDisposeOptions,MagickFalse,da);
          if (dispose < 0)
            break;
          jb->dispose=(DisposeType) dispose;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'G':
    case 'g':
    {
      if (LocaleCompare("gamma",zw) == 0)
        {
          jb->gamma=StringToDouble(da,(char **) NULL);
          break;
        }
      if (LocaleCompare("gravity",zw) == 0)
        {
          ssize_t
            gravity;

          gravity=ParseCommandOption(MagickGravityOptions,MagickFalse,da);
          if (gravity < 0)
            break;
          jb->gravity=(GravityType) gravity;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'I':
    case 'i':
    {
      if (LocaleCompare("intensity",zw) == 0)
        {
          ssize_t
            intensity;

          intensity=ParseCommandOption(MagickPixelIntensityOptions,MagickFalse,
            da);
          if (intensity < 0)
            break;
          jb->intensity=(PixelIntensityMethod) intensity;
          break;
        }
      if (LocaleCompare("interpolate",zw) == 0)
        {
          ssize_t
            interpolate;

          interpolate=ParseCommandOption(MagickInterpolateOptions,MagickFalse,
            da);
          if (interpolate < 0)
            break;
          jb->interpolate=(InterpolatePixelMethod) interpolate;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'L':
    case 'l':
    {
      if (LocaleCompare("loop",zw) == 0)
        {
          jb->iterations=StringToUnsignedLong(da);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'P':
    case 'p':
    {
      if (LocaleCompare("page",zw) == 0)
        {
          char
            *geometry;

          geometry=GetPageGeometry(da);
          flags=ParseAbsoluteGeometry(geometry,&jb->page);
          geometry=DestroyString(geometry);
          break;
        }
      if (LocaleCompare("profile",zw) == 0)
        {
          ImageInfo
            *image_info;

          StringInfo
            *profile;

          image_info=AcquireImageInfo();
          (void) CopyMagickString(image_info->filename,da,MaxTextExtent);
          (void) SetImageInfo(image_info,1,exception);
          profile=FileToStringInfo(image_info->filename,~0UL,exception);
          if (profile != (StringInfo *) NULL)
            {
              status=SetImageProfile(jb,image_info->magick,profile);
              profile=DestroyStringInfo(profile);
            }
          image_info=DestroyImageInfo(image_info);
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'R':
    case 'r':
    {
      if (LocaleCompare("rendering-intent",zw) == 0)
        {
          ssize_t
            rendering_intent;

          rendering_intent=ParseCommandOption(MagickIntentOptions,MagickFalse,
            da);
          if (rendering_intent < 0)
            break;
          jb->rendering_intent=(RenderingIntent) rendering_intent;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'T':
    case 't':
    {
      if (LocaleCompare("tile-offset",zw) == 0)
        {
          char
            *geometry;

          geometry=GetPageGeometry(da);
          flags=ParseAbsoluteGeometry(geometry,&jb->tile_offset);
          geometry=DestroyString(geometry);
          break;
        }
     if (LocaleCompare("type",zw) == 0)
        {
          ssize_t
            type;

          type=ParseCommandOption(MagickTypeOptions,MagickFalse,da);
          if (type < 0)
            return(MagickFalse);
          jb->type=(ImageType) type;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    case 'U':
    case 'u':
    {
      if (LocaleCompare("units",zw) == 0)
        {
          ssize_t
            units;

          units=ParseCommandOption(MagickResolutionOptions,MagickFalse,da);
          if (units < 0)
            break;
          jb->units=(ResolutionType) units;
          break;
        }
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
    default:
    {
      status=AddValueToSplayTree((SplayTreeInfo *) jb->properties,
        ConstantString(zw),ConstantString(da));
      break;
    }
  }
  return(status);
}

void zf(OpKernelContext* dv) override {

  OpInputList params_nested_splits_in;
  OP_REQUIRES_OK(dv, dv->input_list("params_nested_splits",
                                              &params_nested_splits_in));
  const Tensor& params_dense_values_in =
      dv->input(params_nested_splits_in.size());
  const Tensor& indices_in =
      dv->input(params_nested_splits_in.size() + 1);

  DCHECK_GT(params_nested_splits_in.size(), 0);  
  SPLITS_TYPE num_params = params_nested_splits_in[0].dim_size(0) - 1;
  OP_REQUIRES_OK(dv, ValidateIndices(indices_in, num_params));

  OP_REQUIRES(dv, params_dense_values_in.dims() > 0,
              errors::InvalidArgument("params.rank must be nonzero"));
  SPLITS_TYPE num_params_dense_values = params_dense_values_in.dim_size(0);



  std::vector<std::pair<SPLITS_TYPE, SPLITS_TYPE>> value_slices;
  SPLITS_TYPE num_values = 0;
  std::vector<std::vector<SPLITS_TYPE>> out_splits;
  OP_REQUIRES_OK(dv, MakeSplits(indices_in, params_nested_splits_in,
                                     num_params_dense_values, &out_splits,
                                     &value_slices, &num_values));


  OP_REQUIRES_OK(dv, WriteSplits(out_splits, dv));
  OP_REQUIRES_OK(dv,
                 WriteValues(params_dense_values_in, value_slices,
                             out_splits.size(), num_values, dv));
}

