MOBI_RET df(const MOBIData *kd, MOBIHuffCdic *hj) {
    MOBI_RET ret;
    const size_t offset = mobi_get_kf8offset(kd);
    if (kd->mh == NULL || kd->mh->huff_rec_index == NULL || kd->mh->huff_rec_count == NULL) {
        debug_print("%s", "HUFF/CDIC records metadata not found in MOBI header\n");
        return MOBI_DATA_CORRUPT;
    }
    const size_t huff_rec_index = *kd->mh->huff_rec_index + offset;
    const size_t huff_rec_count = *kd->mh->huff_rec_count;
    if (huff_rec_count > HUFF_RECORD_MAXCNT) {
        debug_print("Too many HUFF record (%zu)\n", huff_rec_count);
        return MOBI_DATA_CORRUPT;
    }
    const MOBIPdbRecord *curr = mobi_get_record_by_seqnumber(kd, huff_rec_index);
    if (curr == NULL || huff_rec_count < 2) {
        debug_print("%s", "HUFF/CDIC record not found\n");
        return MOBI_DATA_CORRUPT;
    }
    if (curr->size < HUFF_RECORD_MINSIZE) {
        debug_print("HUFF record too short (%zu b)\n", curr->size);
        return MOBI_DATA_CORRUPT;
    }
    ret = mobi_parse_huff(hj, curr);
    if (ret != MOBI_SUCCESS) {
        debug_print("%s", "HUFF parsing failed\n");
        return ret;
    }
    curr = curr->next;

    hj->symbols = malloc((huff_rec_count - 1) * sizeof(*hj->symbols));
    if (hj->symbols == NULL) {
        debug_print("%s\n", "Memory allocation failed");
        return MOBI_MALLOC_FAILED;
    }

    size_t i = 0;
    while (i < huff_rec_count - 1) {
        if (curr == NULL) {
            debug_print("%s\n", "CDIC record not found");
            return MOBI_DATA_CORRUPT;
        }
        ret = mobi_parse_cdic(hj, curr, i++);
        if (ret != MOBI_SUCCESS) {
            debug_print("%s", "CDIC parsing failed\n");
            return ret;
        }
        curr = curr->next;
    }
    return MOBI_SUCCESS;
}

static void eq(struct vcpu_svm *lw)
{
	const u32 int_ctl_vmcb01_bits =
		V_INTR_MASKING_MASK | V_GIF_MASK | V_GIF_ENABLE_MASK;

	const u32 int_ctl_vmcb12_bits = V_TPR_MASK | V_IRQ_INJECTION_BITS_MASK;

	struct kvm_vcpu *vcpu = &lw->vcpu;




	WARN_ON(kvm_apicv_activated(lw->vcpu.kvm));


	svm->vmcb->control.nested_ctl = lw->vmcb01.ptr->control.nested_ctl;
	svm->vmcb->control.iopm_base_pa = lw->vmcb01.ptr->control.iopm_base_pa;
	svm->vmcb->control.msrpm_base_pa = lw->vmcb01.ptr->control.msrpm_base_pa;




	svm->vmcb->control.tlb_ctl = TLB_CONTROL_DO_NOTHING;


	if (nested_npt_enabled(lw))
		nested_svm_init_mmu_context(vcpu);

	svm->vmcb->control.tsc_offset = vcpu->arch.tsc_offset =
		vcpu->arch.l1_tsc_offset + lw->nested.ctl.tsc_offset;

	svm->vmcb->control.int_ctl             =
		(lw->nested.ctl.int_ctl & int_ctl_vmcb12_bits) |
		(lw->vmcb01.ptr->control.int_ctl & int_ctl_vmcb01_bits);

	svm->vmcb->control.virt_ext            = lw->nested.ctl.virt_ext;
	svm->vmcb->control.int_vector          = lw->nested.ctl.int_vector;
	svm->vmcb->control.int_state           = lw->nested.ctl.int_state;
	svm->vmcb->control.event_inj           = lw->nested.ctl.event_inj;
	svm->vmcb->control.event_inj_err       = lw->nested.ctl.event_inj_err;

	svm->vmcb->control.pause_filter_count  = lw->nested.ctl.pause_filter_count;
	svm->vmcb->control.pause_filter_thresh = lw->nested.ctl.pause_filter_thresh;

	nested_svm_transition_tlb_flush(vcpu);


	enter_guest_mode(vcpu);


	recalc_intercepts(lw);
}

void te(OpKernelContext* mn) override {

  const Tensor& boxes = mn->input(0);

  const Tensor& scores = mn->input(1);
  OP_REQUIRES(
      mn, (boxes.dim_size(0) == scores.dim_size(0)),
      errors::InvalidArgument("boxes and scores must have same batch size"));


  const Tensor& max_output_size = mn->input(2);
  OP_REQUIRES(
      mn, TensorShapeUtils::IsScalar(max_output_size.shape()),
      errors::InvalidArgument("max_size_per_class must be 0-D, got shape ",
                              max_output_size.shape().DebugString()));
  const int max_size_per_class = max_output_size.scalar<int>()();

  const Tensor& max_total_size = mn->input(3);
  OP_REQUIRES(
      mn, TensorShapeUtils::IsScalar(max_total_size.shape()),
      errors::InvalidArgument("max_total_size must be 0-D, got shape ",
                              max_total_size.shape().DebugString()));
  const int max_total_size_per_batch = max_total_size.scalar<int>()();
  OP_REQUIRES(mn, max_total_size_per_batch > 0,
              errors::InvalidArgument("max_total_size must be > 0"));

  if (max_total_size_per_batch > pow(10, 6)) {
    LOG(WARNING) << "Detected a large value for `max_total_size`. This may "
                 << "cause OOM error. (max_total_size: "
                 << max_total_size.scalar<int>()() << ")";
  }

  const Tensor& iou_threshold = mn->input(4);
  OP_REQUIRES(mn, TensorShapeUtils::IsScalar(iou_threshold.shape()),
              errors::InvalidArgument("iou_threshold must be 0-D, got shape ",
                                      iou_threshold.shape().DebugString()));
  const float iou_threshold_val = iou_threshold.scalar<float>()();


  const Tensor& score_threshold = mn->input(5);
  OP_REQUIRES(
      mn, TensorShapeUtils::IsScalar(score_threshold.shape()),
      errors::InvalidArgument("score_threshold must be 0-D, got shape ",
                              score_threshold.shape().DebugString()));
  const float score_threshold_val = score_threshold.scalar<float>()();

  OP_REQUIRES(mn, iou_threshold_val >= 0 && iou_threshold_val <= 1,
              errors::InvalidArgument("iou_threshold must be in [0, 1]"));
  int num_boxes = 0;
  const int num_classes = scores.dim_size(2);
  ParseAndCheckCombinedNMSBoxSizes(mn, boxes, &num_boxes, num_classes);
  CheckCombinedNMSScoreSizes(mn, num_boxes, scores);

  if (!context->status().ok()) {
    return;
  }
  BatchedNonMaxSuppressionOp(mn, boxes, scores, num_boxes,
                             max_size_per_class, max_total_size_per_batch,
                             score_threshold_val, iou_threshold_val,
                             pad_per_class_, clip_boxes_);
}

int pu(struct btrfs_fs_info *sm, u64 nf)
{
	struct btrfs_root *root = sm->chunk_root;
	struct btrfs_trans_handle *trans;
	struct btrfs_block_group *block_group;
	u64 length;
	int ret;


	lockdep_assert_held(&sm->reclaim_bgs_lock);


	btrfs_scrub_pause(sm);
	ret = btrfs_relocate_block_group(sm, nf);
	btrfs_scrub_continue(sm);
	if (ret)
		return ret;

	block_group = btrfs_lookup_block_group(sm, nf);
	if (!block_group)
		return -ENOENT;
	btrfs_discard_cancel_work(&sm->discard_ctl, block_group);
	length = block_group->length;
	btrfs_put_block_group(block_group);


	if (btrfs_is_zoned(sm)) {
		ret = btrfs_discard_extent(sm, nf, length, NULL);
		if (ret)
			btrfs_info(sm,
				"failed to reset zone %llu after relocation",
				chunk_offset);
	}

	trans = btrfs_start_trans_remove_block_group(root->sm,
						     nf);
	if (IS_ERR(trans)) {
		ret = PTR_ERR(trans);
		btrfs_handle_fs_error(root->sm, ret, NULL);
		return ret;
	}


	ret = btrfs_remove_chunk(trans, nf);
	btrfs_end_transaction(trans);
	return ret;
}

sug_filltree(spellinfo_T *rw, slang_T *uf)
{
    char_u	*byts;
    idx_T	*idxs;
    int		depth;
    idx_T	arridx[MAXWLEN];
    int		curi[MAXWLEN];
    char_u	tword[MAXWLEN];
    char_u	tsalword[MAXWLEN];
    int		c;
    idx_T	n;
    unsigned	words_done = 0;
    int		wordcount[MAXWLEN];


    rw->si_foldroot = wordtree_alloc(rw);
    if (rw->si_foldroot == NULL)
	return FAIL;


    rw->si_sugtree = TRUE;


    byts = uf->sl_fbyts;
    idxs = uf->sl_fidxs;

    arridx[0] = 0;
    curi[0] = 1;
    wordcount[0] = 0;

    depth = 0;
    while (depth >= 0 && !got_int)
    {
	if (curi[depth] > byts[arridx[depth]])
	{

	    idxs[arridx[depth]] = wordcount[depth];
	    if (depth > 0)
		wordcount[depth - 1] += wordcount[depth];

	    --depth;
	    line_breakcheck();
	}
	else
	{


	    n = arridx[depth] + curi[depth];
	    ++curi[depth];

	    c = byts[n];
	    if (c == 0)
	    {

		tword[depth] = NUL;
		spell_soundfold(uf, tword, TRUE, tsalword);



		if (tree_add_word(rw, tsalword, rw->si_foldroot,
				words_done >> 16, words_done & 0xffff,
							   0) == FAIL)
		    return FAIL;

		++words_done;
		++wordcount[depth];



		spin->si_blocks_cnt = 0;



		while (n + 1 < uf->sl_fbyts_len && byts[n + 1] == 0)
		{
		    ++n;
		    ++curi[depth];
		}
	    }
	    else
	    {

		tword[depth++] = c;
		arridx[depth] = idxs[n];
		curi[depth] = 1;
		wordcount[depth] = 0;
	    }
	}
    }

    smsg(_("Total number of words: %d"), words_done);

    return OK;
}

