fuzzy_match_compute_score(
	char_u		*str,cs,
	int_u		*matches,yh)
{
    int		score;
    int		penalty;
    int		unmatched;
    int		i;
    char_u	*p = str;
    int_u	sidx = 0;


    score = 100;


    penalty = LEADING_LETTER_PENALTY * matches[0];
    if (penalty < MAX_LEADING_LETTER_PENALTY)
	penalty = MAX_LEADING_LETTER_PENALTY;
    score += penalty;


    unmatched = strSz - numMatches;
    score += UNMATCHED_LETTER_PENALTY * unmatched;


    for (i = 0; i < numMatches; ++i)
    {
	int_u	currIdx = matches[i];

	if (i > 0)
	{
	    int_u	prevIdx = matches[i - 1];


	    if (currIdx == (prevIdx + 1))
		score += SEQUENTIAL_BONUS;
	    else
		score += GAP_PENALTY * (currIdx - prevIdx);
	}


	if (currIdx > 0)
	{

	    int	neighbor = ' ';
	    int	curr;

	    if (has_mbyte)
	    {
		while (sidx < currIdx)
		{
		    neighbor = (*mb_ptr2char)(p);
		    MB_PTR_ADV(p);
		    sidx++;
		}
		curr = (*mb_ptr2char)(p);
	    }
	    else
	    {
		neighbor = str[currIdx - 1];
		curr = str[currIdx];
	    }

	    if (vim_islower(neighbor) && vim_isupper(curr))
		score += CAMEL_BONUS;


	    if (neighbor == '/' || neighbor == '\\')
		score += PATH_SEPARATOR_BONUS;
	    else if (neighbor == ' ' || neighbor == '_')
		score += WORD_SEPARATOR_BONUS;
	}
	else
	{

	    score += FIRST_LETTER_BONUS;
	}
    }
    return score;
}

respip_nodata_answer(uint16_t ih, enum respip_action rj,
	const struct reply_info *fy, size_t os,
	struct reply_info** xy, struct regional* yp)
{
	struct reply_info* new_rep;

	if(rj == respip_refuse || rj == respip_always_refuse) {
		new_rep = make_new_reply_info(fy, yp, 0, 0);
		if(!new_rep)
			return 0;
		FLAGS_SET_RCODE(new_rep->flags, LDNS_RCODE_REFUSED);
		*xy = new_rep;
		return 1;
	} else if(rj == respip_static || rj == respip_redirect ||
		action == respip_always_nxdomain ||
		action == respip_inform_redirect) {

		int rcode = (rj == respip_always_nxdomain)?
			LDNS_RCODE_NXDOMAIN:LDNS_RCODE_NOERROR;


		if(ih == LDNS_RR_TYPE_ANY)
			rrset_id = 0;
		new_rep = make_new_reply_info(fy, yp, os, os);
		if(!new_rep)
			return 0;
		FLAGS_SET_RCODE(new_rep->flags, rcode);
		*xy = new_rep;
		return 1;
	}

	return 1;
}

static long yb(struct file *ds, int di, loff_t yr, loff_t lr)
{
	struct inode *inode = file_inode(ds);
	long ret;

	if (!S_ISREG(inode->i_mode))
		return -EOPNOTSUPP;

	if ((di != 0) && (di != (FALLOC_FL_PUNCH_HOLE | FALLOC_FL_KEEP_SIZE)))
		return -EOPNOTSUPP;

	ret = inode_newsize_ok(inode, yr + lr);
	if (ret < 0)
		return ret;

	if (di & FALLOC_FL_PUNCH_HOLE)
		return nfs42_proc_deallocate(ds, yr, lr);
	return nfs42_proc_allocate(ds, yr, lr);
}

